window.RB_SHARDS=window.RB_SHARDS||{};window.RB_SHARDS[5]=[{"i":16400,"n":"ואגנה, אריה ליבש מאמשטרדם","f":"אלכסנדר","bt":"תרטו","b":"רב הכולל בלעוארדן וגליל פריסלנד-תרמח, נדרלנד-הולנד-תרנו וישב בארנהיים. פרסם מאמרים ב\"ישורון\" - ברלין תרף."},{"i":16401,"n":"ואגנה, חיים מאמשטרדם","k":"בעל תולדות יעב\"ץ","b":"אספן ספרים מחכמי אמשטרדם."},{"i":16402,"n":"ואגנוורט, מוריץ","b":"ביקר בשלוניקי-תרסד, ותיאר את הקהלה היהודית."},{"i":16403,"n":"ואגענפרידן, קלמן מפרשבורג","f":"אהרן","b":"מראשי קהלת פרשבורג-תקסז, אחד מאנשי המשלחת אל החת\"ס במטרסדורף להציע לו את רבנות פרשבורג."},{"i":16404,"n":"ואדעי, אפרים","bt":"תרלו","bp":"צנעא","dt":"תשא - יח אלול","dp":"ירושלים","b":"מגדולי חכמי תימן בצנעא, עלה לירושלים"},{"i":16405,"n":"ואהלגעמוט, ישעיה מהמבורג","bt":"תקפ","dt":"תרנט - יח טבת","dp":"המבורג","b":"רב בממל-תר, ר\"מ בקלויז \"ר ליב בר שאול\" בהמבורג-תרם. נסמך מאת: ר צבי הירש ברוידא-סלנט."},{"i":16406,"n":"ואהלשטין, יוסף ממאלמא","f":"משלם","bt":"תרכד","b":"תלמיד השב\"ס, ור מרדכי ברודא מיאווע. חתן ר שלמה ליפמן ולדלר משלאנק. נסמך מאת: ר צבי דוד מפריישטט, ר נחום ארנפלד מפרג, ר אריה שורץ בביהמ\"ד לרבנים בוינה. רב בשוטענהפען(=שוטען-האפען)-בוהמיה-תרנד, מאלמא-שבדיה-תרס. חיבר ערכים באנציקלופדיה \"אוצר ישראל\", ומאמרים בגרמנית ושבדית?"},{"i":16407,"n":"ואהרמס, גרשון מזאלא-לעווא","dt":"תקע - יא אב","dp":"צעהלים","b":"תלמיד החת\"ס. רב בזאלא-לעווא-תקסד. תשובה אליו ב\"חתם סופר\"."},{"i":16408,"n":"ואזאן, אברהם","dt":"תרנג","b":"עלה לטבריה תרלו, בשנת תקמח בשליחות למצרים ותימן"},{"i":16409,"n":"ואזאן, חיים שמואל","bp":"סורא (תונס)","dt":"תריז או אחריה","dp":"תימן","b":"עלה לטבריה בשנת תקפה וחתם על מסמכים רבים. בשנת תריז בשליחות לערי סוריה ותימן ושם נפטר."},{"i":16410,"n":"ואזאנה, אברהם","bp":"סכורה(מרוקו)","dp":"איית בוציאל(מרוקו)","b":"חכם במרוקו"},{"i":16411,"n":"ואזאנה, דוד","b":"מלוב\"ן מדוויה(מרוקו)"},{"i":16412,"n":"ואזאנה, יוסף ממכנאס - הזקן","b":"מחכמי מכנאס-שנות ה-ת'."},{"i":16413,"n":"ואזאנה, יוסף ממכנאס - הנכד","b":"מחכמי מכנאס-תקיג."},{"i":16414,"n":"ואזאנה, מרדכי ממכנאס","b":"מחכמי מכנאס. בנו - ר יוסף."},{"i":16415,"n":"ואזאנה, מרדכי ממכנאס","f":"יוסף","b":"מחכמי מכנאס-שנות ה-תק'."},{"i":16416,"n":"ואזדיאס, אהרן מהאג","b":"רב בהאג-תר\"מ"},{"i":16417,"n":"ואטולין, יעקב","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":16418,"n":"ואטיץ, יוסף מפרשבורג","b":"בעל בית מסחר ספרים ואמנות בפרשבורג."},{"i":16419,"n":"ואטיץ, ישראל מפרשבורג","b":"חתנו - ר אהרן חיים ליכט מפרשבורג."},{"i":16420,"n":"ואינסון, שמריהו","b":"פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":16421,"n":"ואלאברינה, ישראל ברנרד מצרפת","b":"סופר, מתורגמן מלך צרפת-תקל, הסכים בצורת שיר על \"גמול עתליה\" לר דוד פרנקו מינדיס - אמשטרדם תקל."},{"i":16422,"n":"ואלאוויץ, בנימין","dt":"תשג","b":"רב בסקאלעט"},{"i":16423,"n":"ואלאנסי, אברהם - הזקן","b":"רב בספרד. מוזכר ב\"בית יוסף\" - עם בנו ר שמואל כגדולי הדור עם ר יצחק אבוהב."},{"i":16424,"n":"ואלאנסי, אברהם - הנכד","b":"מגולי ספרד והתישב בפאס, והיה סופר בי\"ד. מוזכר ב\"בית יוסף\" - עם בנו ר שמואל כגדולי הדור עם ר יצחק אבואב."},{"i":16425,"n":"ואלאנסי, גבריאל מירושלים","dp":"ירושלים?","b":"מחכמי ירושלים - תס, נזכר בשות ר יהודה חביליו, נשא ונתן עם ר יצחק קופינו ועוד מגדולי הדור"},{"i":16426,"n":"ואלאנסי, חיים דוד מתונס","b":"אב\"ד בתונס-תקפ\"א"},{"i":16427,"n":"ואלאנסי, חיים משלוניקי","dt":"תל","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":16428,"n":"ואלאנסי, יהודה משלוניקי","b":"מראשי קהלת גרוש ספרד בשלוניקי-רן-ש'."},{"i":16429,"n":"ואלאנסי, יעקב מאזמיר","f":"שמואל","b":"מדפיס באזמיר-תקטו."},{"i":16430,"n":"ואלאנסי, משה הלוי מאלגיר","f":"אברהם","dt":"תריג - כד תשרי","dp":"ירושלים","b":"מחכמי אלגיר, עלה לירושלים."},{"i":16431,"n":"ואלאנסי, שם טוב מאיפסולה","b":"רב באיפסולה(-ליד אדרינופול)-ת' יחד עם ר משה בכ\"ר שאול הלוי."},{"i":16432,"n":"ואלאנסי, שמואל","b":"מגדולי חכמי קאסטיליאה-ר\"מ"},{"i":16433,"n":"ואלאנסי, שמואל מספרד","f":"אברהם","b":"מחכמי ספרד, תלמיד ר יצחק קנפנטון. ראש ישיבה בסמורה. נזכר בשו\"ע יחד עם ר יצחק אבוהב כגדולי הדור. מתלמידיו מהר\"ם אלאשקר. רוב חיבוריו אבדו, ונשארו שני חיבורים על כללי הקל וחומר."},{"i":16434,"n":"ואלאס, ג'יולא מבודפשט","k":"בעל חיי רש\"י - הונגר","b":"רב בבודפשט. חיבר \"חיי רש\"י\" בהונגרית. פרסם בכתבי עת שונים."},{"i":16435,"n":"ואלאס, יהודה מצ'ורגוי","b":"רב בקהילה הניאולוגית בצ'ורגוי-1907. חיבר מחקרים ביהדות."},{"i":16436,"n":"ואלהויזן, בנימין וולף מאלטונא","f":"שלמה","dt":"תקעב - ד כסלו","dp":"אלטונא","b":"מחכמי אלטונא, גבאי הח\"ק."},{"i":16437,"n":"ואלהנדלר, יצחק מואלברום","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר, ר\"מ בקראקא. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא, \"נהור שרגא\" - אלכסנדר תרצט."},{"i":16438,"n":"ואלון, צבי הירש","dt":"תשג","b":"רב בגולדינגן"},{"i":16439,"n":"ואלופסקי, צבי הירש ממונטריאול","b":"עורך \"קאנאדער אדלער\" במונטריאול. פרסם מאמרים ב\"מרכז התורה\" - מונטריאול תשב."},{"i":16440,"n":"ואלט, אליהו ברוך מסן פאולו","b":"חתן ר מרדכי יפה-שלזינגר מאיזנשטט - תל אביב."},{"i":16441,"n":"ואלטוך, איצק פישל מהוסיאטין","b":"תשובה אליו - ובחרת בחיים."},{"i":16442,"n":"ואלטוך, יוסף מטרנופול","dt":"תשמג","dp":"ירושלים","b":"נכד המגיד מזלוטשוב. עלה לארץ ונחשב לצדיק נסתר - עבר כפועל נקיון בשעות הלילה בתל אביב."},{"i":16443,"n":"ואלטוך, יוסף מפרשבורג","b":"מעורכי השבועון היהודי בגרמנית ביזמת ר שמעון סופר מקראקא - \"יידישעס וועלטבלאט\" - פרשבורג תרלח - מיועד ליהודי גליציה."},{"i":16444,"n":"ואלטוך, שמעון מברוד","dt":"תרעח","b":"תלמיד המנחת חינוך. אב\"ד אזאראניץ-רוסיה עד שגורש מרוסיה וחזר לברודי. רב יוצאי מזרח אירופה בלייפציג."},{"i":16445,"n":"ואלטיך, איצק פישל מסניאטין","b":"מחכמי סניאטין, תשובה אליו \"ובחרת בחיים\"."},{"i":16446,"n":"ואלי, אליעזר מפפד\"מ","f":"חיים","bt":"תקב","dt":"תקפא - א ניסן","dp":"פפד\"מ","b":"דיין ור\"מ בפפד\"מ. נספד מאת ר שלמה זלמן טריר ור משה שורצשילד."},{"i":16447,"n":"ואלי, יצחק הלוי ממודנא","k":"בעל לחם הפנים","dt":"תם - אייר","dp":"מודנא","b":"רב במודנא בזמן הרמ\"ז. היה רב גם בוירונה ומנטובה. מתורתו ב\"עפר יעקב\". חיבר \"לחם הפנים\" ונפטר באמצע כתיבתו. נדפס ב\"גבול בנימין\". ?? לא באוצר ??"},{"i":16448,"n":"ואלי, ליזר מפפד\"מ","f":"חיים","bt":"תקב","dt":"תקפא - א ניסן","dp":"פפד\"מ","b":"תלמיד ר נתן אדלר, בהחלטת ראשי הקהילה-תקלז נאסר עליו כמו על רבו לקיים מנין בביתו. בהמשך כיהן כדיין בפפד\"מ-תקנה - אצל ר מאיר שיף. חתנו - ר מיכאל לזרוס גייגר, ונכדו ר שלמה גייגר בעל \"דברי קהלת\"."},{"i":16449,"n":"ואלי, משה דוד מאיטליה","k":"בעל פירוש לתנך","r":"מתלמידי הרמח\"ל","bt":"תנו","dt":"תקלז","b":"תלמיד הרמח\"ל. רב בפאדובה ורופא בזמן ר יעקב חזק. חיבר פירוש לתנך בדרך פרד\"ס, ספר לקוטים ועוד. ויצאו לאור בירושלים כל ספר בשם מיוחד לו - תשמט-תשסג.","bk":[["מגלה עמוקות - נ\"ך",""],["אור עולם",""],["ברית עולם",""]]},{"i":16450,"n":"ואליד ן, אברהם מירושלים","b":"מחכמי ירושלים, בשנת תרכב חתם על כתב שליחות ר אברהם חרוש, ובשנת תרלד חתם ב\"כנסיה לשם שמים\"."},{"i":16451,"n":"ואליד ן, אליהו","f":"חיים","b":"שד\"ר"},{"i":16452,"n":"ואליד ן, חיים מירושלים","b":"רב בירושלים, בשליחות ירושלים וחברון בתוניס-תרלז, פורטוגל, מרוקו וברזיל-תרנג."},{"i":16453,"n":"ואליד ן, יהודה מגיברלטר","f":"יצחק בעל ויאמר יצחק","b":"הוא או אביו מחכמי גיברלטר."},{"i":16454,"n":"ואליד ן, יהודה משלוניקי","dt":"ש - ה טבת","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":16455,"n":"ואליד ן, יוסף ממרוקו ואלגיר","f":"יצחק מטיטואן","k":"בעל ושמו יוסף - תרסז","bp":"טיטואן-מרוקו","dt":"תרסו","b":"מחכמי טיטואן הגיע לווהראן-אלגיר ועסק במסחר. נפטר ללא ילדים, ואלמנתו הדפיסה את ספרו \"ושמו יוסף\" בירושלים."},{"i":16456,"n":"ואליד ן, יצחק מטיטואן הזקן","b":"בן למשפחה ממגורשי ספרד. מחכמי טיטואן. ש\"ץ ושו\"ב בגיברלטר. פסק דין בענינו-תקכג בענין פטור ממס לת\"ח."},{"i":16457,"n":"ואליד ן, יצחק מטיטואן הנכד","f":"שם טוב","k":"בעל ויאמר יצחק","r":"ראב\"ד טיטואן שבמרוקו וראש ישיבת מדרש שלמה שם","bt":"תקלח","bp":"טיטואן","dt":"תרל - ח אדר","dp":"טיטואן","b":"נכד ר יצחק ן ואליד ממשפחה ממגורשי ספרד. תלמיד ר מנחם נהון, ור משה הלוי אב\"ד טיטואן. בזיוו\"ש חתן ר וידאל ביבאס מטיטואן. רב בטיטואן-תקפד (מרוקו הספרדית) על מקום רבו משה הלוי, דיין יחד עם ר משה ן צור ור וידאל ישראל ור משה הלוי. עלה לארץ-תרכב והתישב בחיפה והקים בה ישיבת \"בית הלוי\", חזר לטיטואן. תשובות ממנו ב\"משפטים צדיקים\". בניו ר וידאל, ר יעקב, ר יוסי ור שלמה, וכנראה גם ר יהודה החותם שהוא או אביו מגיברלטר.","bk":[["ויאמר יצחק [שו\"ת]",""],["דרושים לכל חפציהם - דרוש (כת\"י?)",""],["ויאמר יצחק",""]]},{"i":16458,"n":"ואליד ן, משה ממרוקו","f":"יעקב","dp":"רבאט","b":"מחכמי וצדיקי מרוקו."},{"i":16459,"n":"ואליד, שם טוב מטיטואן - א","b":"תלמיד ר אפרים מונסונייגו, מחכמי טיטואן-מרוקו-תקמח, וחתם אז עם ר מנחם נהון, ר אברהם מונסונייגו, ועוד."},{"i":16460,"n":"ואליד, שם טוב מטיטואן - ב","f":"יצחק","b":"רב בטיטואן-מרוקו-תרמא, וחתם אז עם ר יצחק נהון, ר שמואל נהון, ור שמואל ישראל."},{"i":16461,"n":"ואליך, אברהם הרופא מפפד\"מ","k":"בעל דמיון הרפואות","b":"רופא בפפד\"מ ובן למשפחת רופאים. חיבר \"דמיון הרפואות\" - פפד\"מ תס, ובנו ר ליב הו\"ל את ספר אביו עם הוספות ממנו. חתם-תטז על תקנון הרופאים בזמן ר מנדל בס מפפד\"מ."},{"i":16462,"n":"ואליך, יחיאל מהמבורג","f":"שלמה זלמן מאלטונא","k":"בעל בית הלוי - כת\"י","dt":"תקמט - טז ניסן","dp":"אלטונא","b":"תלמיד ר יונתן איבשיץ, ועמד לצדו בזמן המחלוקת. גביר ופרנס מחכמי המבורג, מוהל, שתדלן. עמד בראש משלחת אצל המלך לאוידיענץ יחד עם ר חיים בערגל ור הירש ברעסלא. היה נציג קהלת אלטונא בועידת אה\"ו-תקל. הקים בימ\"ד ובו 3 לומדים והם: ר יצחק אב\"ד וארניק, ר יצחק איצחק אב\"ד וארט, ר יעקב מו\"ץ מרענזיבורג."},{"i":16463,"n":"ואליך, יצחק איזיק הרופא מדסאו","f":"שמעון מדסאו","b":"רופא מחכמי דסאו. תלמיד ר יעקב פופרש מפפד\"מ."},{"i":16464,"n":"ואליך, שמעון הרופא מדסאו","b":"רופא בקובלנץ-תס בערך. בן למשפחת רופאים."},{"i":16465,"n":"ואלינר, יהונתן","b":"רב בלובאטש"},{"i":16466,"n":"ואלנו (וולקו), שבתי מירושלים","b":"מחכמי ישיבת \"בית אל\" בירושלים-שנות התק'."},{"i":16467,"n":"ואלענר, וולף מפוזנא","b":"מחכמי פוזנא. חתנו - ר ישכר בער בעל באר טוב."},{"i":16468,"n":"ואלפע, אליהו מראסיין","f":"ראובן זקש מקידאן","dt":"תרמח - יח אייר","dp":"ראסיין","b":"גביר מחכמי ראסיין. אחיו - ר דוד מראסיין."},{"i":16469,"n":"ואלפע, דוד מראסיין","f":"ראובן זקש מקידאן","dt":"תרנט - יז חשון","dp":"ראסיין","b":"גביר מחכמי ראסיין. אחיו - ר אליהו מראסיין. מצאצאיו הגביר ר אברהם ואלפע מראסיין."},{"i":16470,"n":"ואלק, אליעזר ליפמן מדרוייה","f":"עזריאל הכהן","k":"בעל עין אליעזר","b":"רב בפידברז(=פאדבערעזע)-פלך וילנא-תרנ, דרויע. אחיו של ר צבי הירש. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה תרנג."},{"i":16471,"n":"ואלק, אליעזר מדמטשעווא","f":"משה יעקב","bt":"תרכב","b":"רב בדמשטווה(=דאמאטשעווע)-פלך גרודנא-תרסח."},{"i":16472,"n":"ואלק, אלכסנדר סנדר הקטן מוילנא","f":"פיבל מוילנא","dt":"תרמד - ט אב","dp":"וילנא","b":"תלמיד ר ישראל סלנטר. מחכמי וילנא. נפטר ללא ילדים."},{"i":16473,"n":"ואלק, אלכסנדר סנדר מוילנא","f":"יעקב חלפן","bt":"תקפה","dt":"תרנא - ה שבט","dp":"וילנא","b":"נכד ר אלכסנדר סנדר משניפישוק, ומצאצאי ר יהושע בעל הסמ\"ע (שאחד מבניו נקרא גם הוא ר אלכסנדר סנדר). תלמיד קרובו ר ליבלי שפירא מקובנא. חתן אחיו הגביר ר פיבל ואלק. גביר מחכמי וילנא, גבאי צ\"ג ביחד עם ר ישראל יוסף פינס. פעל לשחרור 24 בני עיר שוינצאן שנאסרו בעלילה. דרוש שנשא שם בפני גנרלים רוסים תורגם לרוסית בידי הסופר לעוואנדא ונשלח אל הממשלה."},{"i":16474,"n":"ואלק, אלכסנדר סנדר מוילנא","f":"יהושע משניפישוק","dt":"תקעב - ט אד\"א","dp":"וילנא","b":"חתן ר נח מדעסוי. גבאי בדעסוי ובנה שם ביכ\"נ. חתם שם כמה פעמים."},{"i":16475,"n":"ואלק, חיים מואדלקא","dt":"תשג","b":"רב בוואדלקה"},{"i":16476,"n":"ואלק, י. ה.","f":"צבי הירש מפינסק","b":"נכד(-אבי אמו) ר מרדכי גימפל יפה מרוז'ינוי. מכתב ממנו-תרנז בשם אביו."},{"i":16477,"n":"ואלק, יעקב חלפן מוילקומיר וילנ","f":"אלכסנדר סנדר מדסוי","b":"חתן ר מיכל בן פיבש מסמרגון."},{"i":16478,"n":"ואלק, מנחם מנדל מוילקוביסק","f":"עזריאל הכהן","k":"בעל שקל הקדש","b":"רב בוילקוביסק-תרנד. אחיו של ר צבי הירש. חיבר \"שקל הקודש - נר מצוה\"."},{"i":16479,"n":"ואלק, מרדכי גימפל הכהן","b":"רב בישיבת חכמי לובלין."},{"i":16480,"n":"ואלק, עזריאל הכהן","b":"חכם-שנת תרל. בניו: ר אברהם יפה (שינה שמו בגלל הצבא), ר צבי הירש מפינסק בעל \"כתר כהונה\", ר אליעזר ליפמן בעל \"עין אליעזר\", ר מנחם מנדל בעל \"שקל הקודש\", ר משה יפה."},{"i":16481,"n":"ואלק, פיבל מוילנא","f":"אלכסנדר סנדר מדסוי","dt":"תרלב - טו חשון","b":"מחכמי וילנא ומגיד שיעור. בניו ר סנדר אברהם (הקטן). חתנו-בן אחיו ר אלכסנדר סנדר בן ר יעקב חלפן מוילנא."},{"i":16482,"n":"ואלק, צבי הירש מפינסק","f":"עזריאל הכהן","k":"בעל כתר כהונה-תשנ..","bt":"תרטו-ז","bp":"וילקומיר","dt":"תרסא-ז - ד טבת","dp":"פינסק?","b":"תלמיד ר יוסף דב בר סולוביציק בסלוצק. חתן ר דב בער יפה מטוריץ (ולפי אווצינסקי-קורלנד חתן ר מרדכי גימפל יפה). מגדולי חכמי דורו, רב בגרוזד, קוסובה (בהמלצת ידידו ר ראבן לוין בעל \"ראש לראובני\"), פפלן(=פופיליאן), קפולה, פלצק, פינסק-תרנה על מקום ר אליעזר משה הורביץ. חיבר פירוש \"כתר כהונא\" ל\"ספרי\" עם הגהות הגר\"א, \"טהרת הקודש\", ועוד. אחיו: ר אליעזר ליפמן מדרוייה, ר מנחם מנדל מוילקוביסק. פרסם מאמרים ב\"בית ועד לחכמים\" - נ\"י תרסג. גיסו (היו נשואים לשתי אחיות) - ר יוסף זכריה שטרן."},{"i":16483,"n":"ואלק, שמואל אלעזר","b":"פרסם מאמרים ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה, \"תלפיות\" - נ\"י תשד."},{"i":16484,"n":"ואלקוביסקי, יחיאל דובער מביאלי","b":"גביר בביאליסטוק-תר, בבית מדרשו למד ר אליעזר הבבלי בעל ספר הצבא."},{"i":16485,"n":"ואלקובישק, אשר מהורדנא","bt":"תקא","dt":"תקפב - כא סיון","b":"דיין בהורדנא"},{"i":16486,"n":"ואן לעאן, אברהם מאמשטרדם","b":"רב לאשכנזים באמשטרדם, מידלבורג."},{"i":16487,"n":"ואנדרבר, ראובן ממיטאוי","f":"יוסף","k":"בעל תולדות היהודים","bt":"תקעג","bp":"מיטאוי","dt":"תרכח - כח אלול","b":"מורה בביה\"ס העברי בריגא-תרב, מורה בבית ספר הממשלה במיטאוי, וממלא מקום הרב מטעם הממשלה במיטאוי על מקום ר ישראל פרידמן-תרטו. חיבר \"תולדות היהודים בפלך ליפלנד וקורלנד\", ועוד. פרסם מאמרים בכתבי עת."},{"i":16488,"n":"ואני, יצחק משלוניקי","b":"תלמיד ר מרדכי קלעי. מחכמי שלוניקי-שנות ה-ת'."},{"i":16489,"n":"ואנציאגר, לאיוש מבודפשט","b":"רב ניאולוגי בבודפשט, סגן יו\"ר הארגון הארצי של הרבנים המתקדמים, מרצה בסמינר לרבנים בבודפשט. חיבר מסות היסטוריות, ספר היסטוריה של יהדות הונגריה - בודפשט 1922."},{"i":16490,"n":"ואנציגר, ל מצ'ורגוי ואויפעשט","b":"רב בקהילה הניאולוגית בצ'ורגוי, אויפעשט, מלמד בביהמ\"ד לרבנים בבודפשט. חיבר מחקרים ביהדות."},{"i":16491,"n":"ואעיש ממרוקו","f":"יחיא","k":"ואעיש בן עבי","bp":"אופראן-מרוקו","b":"מחכמי מרוקו."},{"i":16492,"n":"ואעיש, אברהם ממרוקו","b":"נגיד היהודים בטראקס(=מראקש)-מרוקו, שלח את קרובו ר אברהם בוזגלו-אזולאי-שסו לונציה לקנות כלים יקרים למלך מרוקו."},{"i":16493,"n":"ואעיש, אברהם ממרוקו","f":"שמואל","dt":"תקעט","b":"מחכמי מכנאס. קינה לזכרו ב\"קול יעקב\"."},{"i":16494,"n":"ואעיש, יהושע","dt":"תרפז - יח אדר","b":"רב בצפת"},{"i":16495,"n":"ואעיש, ישועה ממכנאס","bt":"תריא","bp":"מכנאס","b":"עלה עם הוריו לטבריה. ראש קהילת הספרדים בצפת-תרסג."},{"i":16496,"n":"ואעיש, שמואל ממכנאס","bt":"תצח","dt":"תקעג-ח","dp":"מכנאס?","b":"תלמיד ר מרדכי בירדוגו ממכנאס. דיין במכנאס, עם ר רפאל בירדוגו, ר ברוך טולדנו, ר פתחיה בירדוגו. הסכים על \"מלאכת הקדש\"-תקסב."},{"i":16497,"n":"ואקראט, מאיר ממכנאס","b":"סופר שטרות במכנאס, חתם-תקסא עם ר מימון בירדוגו, ועם ר רפאל בירדוגו."},{"i":16498,"n":"וארון קאנפוס די, שלמה מצפת","b":"מחכמי צפת, בשליחות במרוקו-תס, מכתב המלצה אליו מר יעקב ן צור מפאס."},{"i":16499,"n":"וארון, יצחק משלוניקי","b":"תלמיד ר לוי ן חביב. ר\"מ בק\"ק \"ישמעאל\"-קאלאבריה חדש בשלוניקי-שנות ה-ש'."},{"i":16500,"n":"וארון, יצחק משלוניקי - ב","dt":"שפא - יב סיון","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":16501,"n":"וארון, משה משלוניקי","dt":"תי","dp":"שלוניקי","b":"מחכמי שלוניקי"},{"i":16502,"n":"וארון, נסים מירושלים","bt":"תריז","dt":"תרפה - ח אדר","b":"רב בירושלים. תשובה ממנו ב\"המאסף\"."},{"i":16503,"n":"וארינגר, יעקב משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":16504,"n":"ואריש, ברוך מאלטונא","b":"מחכמי אלטונא וראש משפחה חשובה שם. חתנו - ר צבי הירש ואריש חרב\"ו מהמבורג."},{"i":16505,"n":"ואריש, יעקב מאלטונא","f":"צבי הירש מהמבורג","bp":"המבורג","dt":"תקסח - ג אייר","dp":"אלטונא","b":"תלמיד ר רפאל הכהן מהמבורג. חתן ר יוסף האן מאה\"ו. מחכמי ביהמ\"ד של ר יחיאל ואליך, ספרא רבה דיין באלטונא-תקמט. חיבר הקדמה ל\"דברי דוד\" המבורג תקנד, הו\"ל לוח לשנת תקסא. בנו - ר פלטיאל."},{"i":16506,"n":"ואריש, פלטיאל מהמבורג","f":"יעקב מאה\"ו","dt":"תקץ","dp":"אלטונא","b":"מחכמי ביהמ\"ד של ר יחיאל ואליך בהמבורג."},{"i":16507,"n":"ואריש, צבי הירש חרב\"ו מהמבורג","dt":"תקלא-ז -יד אייר","dp":"אלטונא","b":"חתן ר ברוך ואריש. מראשוני חכמי הקלויז חדש בהמבורג - בבית ר זליגמן בן זלמן - יחד עם ר ליב פפערשוי, ר יוזפא בן דניאל."},{"i":16508,"n":"וארמזער, זקיל ליב ממיכלשטט","b":"\"המסדרונה\" - פפד\"מ-ירושלים תרמה."},{"i":16509,"n":"וארמזער, יחיאל מהמבורג","bt":"תר","bp":"אלטדורף ליד עטנהיים","dt":"תרס - יב אייר","dp":"המבורג","b":"תלמיד ביהמ\"ד למורים בקרלסרוהא, מורה באיכנהויזן, ת\"ת המבורג. איש חסד. ע\"ש ביהכ\"נ \"כנסת יחיאל\"."},{"i":16510,"n":"וארקיל, מרדכי יעקב מקובנא","b":"רב בקובנא,עלה לארץ וכיהן כרב בעזרה וביצרון."},{"i":16511,"n":"ואתורי, בנימין מאיטליה ולוב","bp":"פיזה-איטליה","dt":"תקסו - כז שבט","dp":"טריפולי","b":"רב באיטליה - במקור מפיזה, עבר ללוב וכיהן כדיין בטריפולי - יחד עם ר דוד טייאר ור מסעוד חי רוקח. חתם על תקנת הגאבילה-תקך, ונזכר ב\"מעשה רוקח\" ליוורנו תרכב ( ב\"מלכי חי\"ל\" - מביא שלדעת גבריאל רוקח נפטר-תקטו - אולם יש לבדוק אם אין הכוונה תקסו)."},{"i":16512,"n":"ואתורי, בנימין מטריפולי - א","bt":"ת","dt":"תע - בערך","b":"רב בטריפולי. עסק בפדיון שבויים - ובין השבויים שפדה - יהודי מאמשטרדם בשם סוארץ שנחטף ע\"י שודדי ים ונפדה בטריפולי, התישב שם וממנו משפחת \"זוארץ\" בלוב."},{"i":16513,"n":"ואתורי, חיים מטריפולי","f":"בנימין","dt":"תקסב - יב תשרי","b":"רב ודיין בטריפולי. חתם על תקנת הגאבילה-תקלח - ונזכר ב\"מעשה רוקח\" ליוורנו תרכב, נזכר גם ב\"השומר אמת\" לר אברהם אדאדי."},{"i":16514,"n":"ואתורי, יצחק מטריפולי","dt":"תרסה - תרעא","dp":"טריפולי","b":"רב ודיין ומקובל בטריפולי בזמן ר משה אסרוסי - ונזכר בספרו \"וישב משה\". תלמיד ר יעקב מימון. התעוור בצעירותו ונתרפא לאחר 33 שנה."},{"i":16515,"n":"ואתורי, יצחק מטריפולי","dt":"תקפט - לפני","b":"מחכמי טריפולי. נזכר בפנקס בי\"ד טריפולי."},{"i":16516,"n":"ואתורי, יצחק מטריפולי","f":"יהודה","dt":"תרכד","b":"תלמיד ר יעקב מימון. דיין ושוחט בטריפולי."},{"i":16517,"n":"ובר, אהרן מירושלים","b":"פרסם מאמרים ב\"שערי ציון\" - ירושלים תרפא."},{"i":16518,"n":"ובר, אליהו צבי מברעזוב","f":"שמחה","bt":"תקע","dt":"תרלט","b":"חתן ר שמעון מירוסלב. רבה של ברעזוב-תרטז."},{"i":16519,"n":"ובר, בן ציון","f":"מרדכי אליעזר מאדא ים","b":"חתן ר דב בריש פ\"ת מציעשינוב. בנו ר שמואל אהרן - זקן חסידי ללוב בירושלים."},{"i":16520,"n":"ובר, בן ציון מירושלים","b":"עורך \"קול תורה\" - ירושלים תרץ, יחד עם ר שמואל אהרן ובר."},{"i":16521,"n":"ובר, דוד מפטראווסלע","f":"מרדכי אליעזר","dt":"תרט - א שבט","dp":"פטראווסלע","b":"תלמיד החת\"ס. רב (לא בתפקיד) בפטראווסלע-תקפב, אדא. נהרג עק\"ה - ונקבעה תענית בקהלה ביום זה עד לחרבן הקהלה בשואה."},{"i":16522,"n":"ובר, זאב וולף מירושלים","b":"בשליחות-תרץ בדרום אמריקה."},{"i":16523,"n":"ובר, חיים מטימבורג","f":"שלמה יהודה ליב","bt":"תרלג","dt":"תרצה","b":"חתן ר נתן נטע דב ליפשיץ מויליפולי, רבה של טימבורג עד תרפב, רב בברעזוב על מקום אביו. עלה לירושלים. כתביו אבדו במלחמת השחרור עם נפילת העיר העתיקה."},{"i":16524,"n":"ובר, יוסף אריה מטימבורג","f":"חיים","bt":"תרנח","dt":"תשג","b":"רב בבוברקא, ברזיב-תרפב, טימבורג על מקום אביו. נספה בשואה."},{"i":16525,"n":"ובר, יצחק מקולומיאה","f":"אלעזר הלוי","k":"בעל צדק ומשפט","bt":"תרך","dt":"תש","b":"רב בקראקא. רב בקולומיאה כששים שנה. מחשובי חסידי צורטקוב והשפיע על האדמור שלא יצא כנגד הציונות. היה ציר בקונגרס הציוני. חיבר \"צדק ומשפט\" קראקא תרנא."},{"i":16526,"n":"ובר, ישכר יהודה דב מפרוכניק","f":"שמחה","bt":"תקף","dt":"תרם","b":"ראב\"ד פרוכניק על מקום אביו."},{"i":16527,"n":"ובר, מיכל מוארשא","k":"בעל חיי עולם הבא","bt":"תריט","bp":"ווארקא-פלך וארשא","b":"התחנך כחסיד, ולמד גם למודים כללים ושפות. גויס לצבא הרוסי וחיבר מאמר \"לצבוא צבא\". מורה בוארשא, מעורכי \"הצפירה\"-תרמו. פרסם מאמרים ב\"הצפירה\". חיבר ספרים בעברית ובאידיש."},{"i":16528,"n":"ובר, מרדכי אליעזר מאדא וירושלי","f":"דוד מפטראווסלע הי\"ד","k":"בעל נובל העלים","bt":"תקפב","bp":"פטרווסלא (הונגריה)","dt":"תרנב - כז תמוז","dp":"ירושלים","b":"תלמיד הכת\"ס, ור שלמה זלמן אולמן ממאקווא, ר יצחק משה פרלס מבאניהאד. התקרב לחסידות והיה מתלמידיו הקרובים של ר מנחם מנדל מקוצק. חתן ר פנחס ליב פרידמן מקאמארן בעל \"פני אריה\", ועבר לשם. רב בפטראווסלא-תריב, אדא (כולל מאהל, בעטשע, ופולדוואר)-תריג, וואלובא(=וואלאוה)-תרלא - בפקודת רבו הדברי חיים מצאנז. בשנת תרלה (באוצר תרמה) עלה לירושלים והיה מקורב ונערץ ע\"י המהרי\"ל דיסקין. חיבר \"ערך דל\" ועוד. בנו ר בן ציון.","bk":[["בכור דל [עמ\"ס בכורות]",""]]},{"i":16529,"n":"ובר, משה מאמסנא","f":"חיים","bt":"תרסב","dt":"תשב","b":"חתן ר נתן דוד הולנדר. רב באמסנא על מקום חותנו. נספה בשואה."},{"i":16530,"n":"ובר, קלונימוס קלמן מפישטיאן","f":"יוסף ממאקווא","bt":"תרלא","bp":"מאקווא","dt":"תרצב - יז תשרי","dp":"פישטיאן","b":"תלמיד השב\"ס, ור אליעזר זוסמן סופר מפאקש ועוד. חתן ר יוסף דב בער קאהן מבאניהאד. רב ברעטה-תרנט, פישטיאן-תרסב וחתנו ר בנציון יוסף הלוי אונגר על מקומו אחריו, ראש לשכת היראים בסלובקיה-תרעט, היה במחלוקת עם האדמור ממונקטש בעניני סמכות הלשכה. מתורתו ב\"עטרת זקנים\". פרסם מאמרים ב\"עמק הלכה\" - באטארקס תרפא."},{"i":16531,"n":"ובר, שלמה יהודה ליב מברזוב","f":"אליהו צבי מברזוב","bt":"תר","dt":"תרעו","dp":"ברעזוב","b":"נכד-אבי אמו ר שמעון מירוסלב. רב באיסטריק-תרלז, ברעזוב-תרל על מקום אביו."},{"i":16532,"n":"ובר, שמואל אהרן מירושלים","b":"עורך: \"קול תורה\" - ירושלים תרץ."},{"i":16533,"n":"ובר, שמחה מפרוכניק","f":"ישכר דב","bt":"תקן","dt":"תרכח","b":"חתן הגביר ר יוסף מרגושיס מלמברג. רב בקרקוביץ, פרוכניק-תקעח כיובל שנים."},{"i":16534,"n":"ובר, שמעון מלונדון","f":"קלונימוס קלמן מפישטן","b":"תלמיד הדעת סופר, עבר ללונדון."},{"i":16535,"n":"וג, אברהם אליעזר מצאנז","f":"חיים","bt":"תרסג","dt":"תשג","b":"רב בירוסלב. נספה בשואה."},{"i":16536,"n":"וג, אברהם יצחק מאויבר-וישיווה","b":"תלמיד ר שלמה זלמן ארנרייך. רב בפאליאן. מעורכי \"דגל התורה\" - אויבר ווישיווה. פרסם מאמרים ב\"אוצר התורה\" - ג'רבה תרץ, \"קבוצי בחורים\" - מארגרטן תרצג, \"דגל התורה\" - אויבר-וישווה תרפח."},{"i":16537,"n":"וג, חיים מצאנז","f":"נח","k":"בעל זכר לאברהם אליעז","bt":"תרלז","bp":"צאנז","dt":"תשכב","b":"חתן ר צבי הערש קורן מגורליץ. רב בקיששבן, עזב את הרבנות ועסק בתעשיה ומסחר. עבר לארה\"ב ושימש כרב. עלה לארץ-תשטז. חיבר \"זכר לאברהם אליעזר\" ברוקלין תשיג."},{"i":16538,"n":"וג, משה פישל מכפר האדאד","f":"שלמה משסבורג","k":"בעל קהלת משה-תרצח","dt":"תש..","b":"שו\"ב בכפר האדאד-ליד סילאג'-צ'ה. נספה בשואה. ?? לא באוצר ??"},{"i":16539,"n":"וגנר, חיים מקוסוב","b":"מלמד לבני האדמור ר\"ח מקוסוב. בנו - ר משולם אב\"ד הורודנקה."},{"i":16540,"n":"וגנר, יוסף מלשצוב","b":"תשובה אליו במהרש\"ם. חתנו הרב גלז על מקומו בלשצוב."},{"i":16541,"n":"וגנר, ישראל מברוקלין","f":"יצחק שמואל מלמברג","b":"חסיד בלז מיושבי בלז. תלמיד לרב מפרוביזנא. חתן ר שרגא פיבל ויליג מבוצאץ. ניצל מהשואה, רבה של ירוסלב, מצא את ארוסתו שניצלה אף היא ונישאו. רב של לה פס-בוליביה, עבר לניו יורק וכיהן כרב. עלה לירושלים-תשס."},{"i":16542,"n":"וגנר, משלם מהורדנקא","f":"חיים","bt":"תקפה","dt":"תרסה","b":"חתן ר שמחה וייך מהורודנקה. ויתר על רבנות שאץ. נשלח ליברוב לבדוק את ר משה תאומים והמליץ לקבלו לרב בהורודנקא."},{"i":16543,"n":"וגנר, שלום מואריש","f":"יוסף מלשצוב","b":"סוחר מואריש מחסידי בלז. גיסו של ר יצחק קרניול."},{"i":16544,"n":"וגר, גרשון מווגר","b":"רב בווגר"},{"i":16545,"n":"וגשל, אביעזרי זליג מהוסיאטין","b":"עזר לר ישראל מרוזין לברוח מרוסיה. בניו ר יהושע אהרן שעשה את השידוך הראשון בין פולנים להונגרים ונשא את בת ר אברהם פלזנבורג. ור יעקב שלמה ור משה."},{"i":16546,"n":"וגשל, אברהם מנחם מנדל משינאווא","f":"אלתר יעקב יצחק מלנצט","k":"אדמור משינאווא מונסי","b":"מצאצאי הנועם אלימלך. חתן ר ישכר דב רוטנברג מווידיסלב (אפטא)."},{"i":16547,"n":"וגשל, אליעזר מזלוטשוב","f":"ישראל מפריסטיק","k":"אדמור מזלוטשוב","dt":"תרפט - כח אלול","b":"מצאצאי הנועם אלימלך. נכד בעל \"לב שמח\". חתן ר צבי רוקח-חתן ר חנוך הניך דב מאלסק."},{"i":16548,"n":"וגשל, אלתר יעקב יצחק מלאנצוט","f":"חיים ראובן","bt":"תרן","dt":"תשכז","b":"רבה של לאנצוט על מקום אביו. חתן ר יצחק רובן מצפת. היגר לניו יורק. על קורותיו בסיביר - \"שלהבת שלא קפאה\"."},{"i":16549,"n":"וגשל, אשר מרדומישל","f":"שלום","bt":"תרסח","bp":"דוקלא","dt":"תשנה","b":"חסיד בלז. רב ברדומישל. ניצל מהשואה ואחריה כיהן כרב בסלין (אוגסבורג)-גרמניה. עבר לארה\"ב."},{"i":16550,"n":"וגשל, חיים ראובן מלאנצוט","f":"יעקב יצחק","bt":"תרך","dt":"תרץ","b":"רב בלאנצוט-תרס על מקום אביו. בנו ר אלטר יעקב יצחק על מקומו אחריו."},{"i":16551,"n":"וגשל, חנוך הניך מבאלעסק","k":"אדמור מבאלעסק","dt":"תש","b":"אדמור באלעסק. נספה בשואה."},{"i":16552,"n":"וגשל, יהושע מלנצהוט נ\"י","f":"אלתר יעקב יצחק מלנצט","k":"אדמור מלנצהוט נ\"י","b":"מצאצאי הנועם אלימלך. חתן ר יעקב הלברשטם מטשאקווא (צאנז)."},{"i":16553,"n":"וגשל, יהושע מפריסטיק קורטשין","f":"ישראל מפריסטיק","k":"אדמור מפריסטיק בנ\"י","bt":"תרל","dt":"תשה","b":"מצאצאי הנועם אלימלך. היגר לארה\"ב, ושימש כאדמור מפריסטיק-קורטשין בניו יורק. הדפיס את ספרי זקנו בניו יורק וביניהם \"נועם אלימלך\"."},{"i":16554,"n":"וגשל, יחיאל","b":"רב בדמביץ חתן ר שמואל הורביץ"},{"i":16555,"n":"וגשל, יחיאל מפריסטיק","f":"יצחק ליב","bt":"תקפא","dt":"תרמג - כז תרמג","b":"רב בפריסטיק על מקום אביו בהיותו בגיל 12! חתן ר יעקב הורביץ ממעליץ."},{"i":16556,"n":"וגשל, יעקב יצחק מלאנצוט","f":"יחיאל","bt":"תר","dt":"תרס","b":"ראב\"ד בלאנצוט, בנו ר חיים ראובן על מקומו אחריו. חתן ר ישראל הורביץ מברנוב."},{"i":16557,"n":"וגשל, יצחק ליב מפריסטיק","bt":"תקס","dt":"תקצג","b":"נכדו של בעל \"שפתי כהן\" מוילנא. חתן ר ישראל אלבוים וגשל מליזנסק. רבה של פריסטיק, בנו ר יחיאל על מקומו אחריו. אחיינו - ר נחום צבי הורביץ מריגליץ."},{"i":16558,"n":"וגשל, ישראל מפריסטיק","f":"יחיאל","bt":"תקצט","dt":"תרס","b":"רב בפריסטיק על מקום אביו."},{"i":16559,"n":"וגשל, מרדכי מבייטש","f":"פנחס","bt":"תרך","bp":"בייטש","dt":"תשב","b":"רב בבייטש, חתן ר יהודה גולדברג. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"המאור\" - ברלין תרצג."},{"i":16560,"n":"וגשל, משה מריגליץ","b":"רב בריגליץ. תשובה אליו שות מהרשם."},{"i":16561,"n":"ודיאנר (ורשנר), יהושע קשמן","f":"שרגא פיביש","k":"בעל נחלת יהושע","bt":"תקמח","bp":"ווערפראוואץ","dt":"תקצא - ט אלול","dp":"ראב-סיגט","b":"תלמיד החת\"ס, ור משה מינץ מאויבן. חתן ר יעקב חיים רייך מקאלוז ועבר לשם-תקסט, עבר עם חמיו לראב-סיגט וכיהן כראש הקהלה, ראש ישיבה בג'יור והחזיקה על חשבונו. בנו - ר אהרן וודיאנר מבלנדעל-טאטי. בקשרים עם החת\"ס, ועם ר משה מינץ. חיבר \"נחלת יהושע\" על התלמוד עם מבוא מאת ב\"ז באכר."},{"i":16562,"n":"ודיסלובסקי, יהודה ליב מלודז","f":"יעקב יצחק מלודז","k":"בעל תולדות רבנו מנחם","bt":"תרלז","bp":"לודז","b":"מחוקרי תולדות ישראל. הו\"ל \"מאור הנפש\" לרמ\"ע. חיבר \"תולדות רבנו מנחם עזריה\" - פיעטריקוב, \"עטרת ראש\" - בכת\"י, מבוא והערות ל\"צרור החיים\" - לר חיים בן דוד-תלמיד הרשב\"א. פרסם ב\"הפלס\", ועוד."},{"i":16563,"n":"והב, סעדיה מתימן","dp":"רדאע","b":"רב ברדאע-תימן-תטו וחתם על פסקי דינים עם חכמי דורו."},{"i":16564,"n":"וואלפ'ס, אברהם","b":"רב בקולומיי-תכ\"ד"},{"i":16565,"n":"וואלצי מדולינא","b":"רב בדולינא"},{"i":16566,"n":"וואקיל, ידידיה משה מירושלים","b":"מחכמי ירושלים, הסכים על \"אדמת קדש\"-תקיג."},{"i":16567,"n":"וואקיל, משה מירושלים","b":"מחכמי ישיבת בית יעקב פירירה בירושלים-תקיח. (לדעת רוזניס הוא החכם ר ידידיה משה)."},{"i":16568,"n":"ווזנר, בנציון יעקב ממונסי","f":"שמואל מבני ברק","b":"רב במונסי."},{"i":16569,"n":"ווזנר, חיים מאיר הלוי מלונדון","f":"שמואל מבני ברק","b":"רב בלונדון."},{"i":16570,"n":"ווזנר, שמואל הלוי מבני ברק","f":"יוסף צבי מוינה","k":"בעל שבט הלוי","b":"תלמיד הדעת סופר, ישיבת חכמי לובלין ועוד. חתן ר מרדכי גלבר מפרשבורג, ועבר לשם. עלה לירושלים-תרצט וכיהן כרב בשכונת גאולה. רב שכונת זכרון מאיר בבני ברק-תשז וראש ישיבת חכמי לובלין בבני ברק."},{"i":16571,"n":"וויגא, רפאל מליוורנו","b":"גביר בליוורנו, יסד ישיבה בירושלים ובראשה ר יעקב חגיז."},{"i":16572,"n":"וולאקו, חיים רבא","dt":"תכט - ח שבט","b":"מגדולי רבני מצרים"},{"i":16573,"n":"וולוביץ, בנימין הלל מסקלט","dt":"תש..","b":"רב בסקלט על מקום ר אלעזר שצברג. נספה בשואה."},{"i":16574,"n":"וולמוט, בן ציון מבוברקא","b":"מחכמי בוברקא-תרמב. תשובה אליו מרבו ב\"הרי בשמים\"."},{"i":16575,"n":"וולנר משה דב בן צבי יהודה","r":"רב בבודפסט, ואחר כך במושב אמרי שפיר ואחר כך רב באשקלון","bt":"1912","dt":"ה'תשסז 2007","bk":[["חמדת צבי",""],["אמרי חמודות - דרושים ושו\"ת למועדים וזמנים",""],["דרושים לחפציהם - על התורה",""],["חמדת הלבבות - תהילים",""],["שאילת חמדת צבי - שו\"ת",""]]},{"i":16576,"n":"וולף","f":"יוסף","k":"בעל תוכחת מגולה","b":"חיבר \"תוכחת מגולה\" - דעסוי."},{"i":16577,"n":"וולף","f":"רמ\"ל מאיר","dt":"תריב","b":"מדקדק ומבאר, חיבר ביאור ותרגום לתורה בלשון אשכנז עם ר משה לנדוי, ונדפס בדפוס אביו-הרמ\"ל - תקצא. חיבר גם \"שפתי ישנים\" פרג תקפח, \"ראשית למודים\" דעסוי תקע, ועוד."},{"i":16578,"n":"וולף באכלוי מיארמוט","b":"רב ביארמוט-תקנג ור בנימין וולף בוסקוביץ על מקומו אחריו-תקנח."},{"i":16579,"n":"וולף בנימין מפילדלפיה","b":"רב בפילדלפיה-תקסב, בקהילת יוצאי אשכנז."},{"i":16580,"n":"וולף בעקער מוילנא","b":"ממיסדי ותומכי ישיבת מייליס בוילנא."},{"i":16581,"n":"וולף הלוי","k":"מפפד\"מ","dt":"תקפח","b":"דיין מחכמי פפד\"מ-תע. חיבר נספח ל\"מעבר יבוק\" - הומבורג תק."},{"i":16582,"n":"וולף הרופא מבון-גרמניה","bp":"בון-גרמניה","b":"רופא בבון, רופא האפיפיור ברומא. בניו הרופאים: היינריך וולף בעיר בון, שלמה וולף בעיר דירען-צרפת."},{"i":16583,"n":"וולף חריף מלוסק","b":"רב בלאסק"},{"i":16584,"n":"וולף מאוסטרהא","f":"ברוך","dt":"תקי - ה סוכות","dp":"אוסטרהא","b":"מחכמי אוסטרהא. אולי אחיו של ר אברהם מאוסטרהא בן ברוך."},{"i":16585,"n":"וולף מהרובשוב","dt":"תקכט - יא כסלו","b":"רב בהרובאשוב"},{"i":16586,"n":"וולף מטארני","dt":"תרלט - כו אייר","b":"מגיד בטארני"},{"i":16587,"n":"וולף מטשיזאבא","dt":"יח חשון","b":"רב בטשיזאבא"},{"i":16588,"n":"וולף מטשרני","k":"וואלף מטשארני-אסטרא","b":"מגיד בטשארני-אסטרא"},{"i":16589,"n":"וולף מלייכשדארף","b":"אלוף וקצין - אחרי תסא - בלייכסדורף."},{"i":16590,"n":"וולף ממיטאוי","bt":"תקם","bp":"פרוסיה","b":"עורך דין. התישב במיטאוי ויסד בית ספר עברי."},{"i":16591,"n":"וולף מפוזנא","b":"רב בפוזנא-שע\"ה"},{"i":16592,"n":"וולף מקאלוב","b":"רב בקאליב-ת\"ר"},{"i":16593,"n":"וולף מקובלנץ","dt":"שע - כט טבת","b":"רופא ורב בקובלנץ. חתם על תקנות אסיפת הרבנים בפפד\"מ-שסג."},{"i":16594,"n":"וולף משה בן פינחס","f":"פנחס","k":"בעל נפש אדם","bt":"תרה","dt":"תש","b":"חתן דודו ר ברוך מנחם מנדל מבוכניה. רב בזגורז, ראב\"ד בוכניה על מקום חותנו. בנו ר מרדכי על מקומו אחריו. חיבר \"נפש אדם\" רוהאטין תרנו. ?? לא באוצר ??","bk":[["נפש אדם",""]]},{"i":16595,"n":"וולף פערשט מברלין","b":"מראשי הקהילה בברלין-תקד, חתם על כתב ההסכם עם ר דוד פרנקל הראב\"ד בברלין."},{"i":16596,"n":"וולף פרנס מאשכנז","b":"פרנס ומנהיג בקהילות אשכנז-ת\"ק"},{"i":16597,"n":"וולף, אברהם מטרנוב","b":"דומ\"צ בטארנא"},{"i":16598,"n":"וולף, איסר בר","f":"רפאל","bt":"1844","bp":"טאווריג","dt":"1935","b":"ממשכילי קובנא. החל לכתוב שירים ומאמרים בגיל 14 והתפרסמו ב\"המגיד\", ועוד. עסקן ציבור בקובנא ובכל רחבי ליטא. חבר עירית קובנא-1872. ייסד את \"ספריית מאפו\". ארגן את כינוס העסקנים היהודים מכל רחבי רודיה בקובנא-1909. תומך בציונות."},{"i":16599,"n":"וולף, אלימלך מבוכניה","f":"ברוך מנחם מנדל","bt":"תקצט","dt":"תרסה","b":"רב בבוכניה על מקום אביו."},{"i":16600,"n":"וולף, אלכסנדר אברהם מקופנהגן","f":"גדליה","k":"בעל תורת ישראל","bt":"1800","bp":"דרמשטט","dt":"תקפח","b":"רב בגיסען-תקפה, קופנהגן-תקפח ורב מדינת דנמרק מטעם הממשלה. חיבר ספרים רבים בשפות שונות. בנו - ר שלום שכנא - כיהן כרב תחת אביו."},{"i":16601,"n":"וולף, אלקנה שמואל מקאלווריה","f":"נתן אהרן","bt":"תקן","dt":"תרכח","b":"רבה הראשון של קלווריה-גליציה. נכדו אריה וולף הוציא - \"משפחת וולף שלזיין\" על תולדות המשפחה."},{"i":16602,"n":"וולף, ברוך מנחם מנדל מאושפיצין","f":"נתן אהרן","bt":"תרמה","dt":"תשב","b":"מחכמי אושפיצין. חתן ר נחמיה בראדט. נספה בשואה."},{"i":16603,"n":"וולף, ברוך מנחם מנדל מבוכניה","f":"נתן אהרן","bt":"תקע","dt":"תרמג","b":"חתן הגביר ר מיכאל ציפרס מקראקא. רבה הראשון של בוכניה-תרכב. בנו ר אלימלך על מקומו אחריו."},{"i":16604,"n":"וולף, ברוך מנחם מנדל מקראקא","f":"נתן אהרן מאושפיצין","bt":"תרלח","dt":"תשה","b":"גביר חסיד בלז בקראקא, בשותפות אחיו ר משה ור ישראל. חתן הגביר ר שאול קורל מקראקא. נספה בשואה."},{"i":16605,"n":"וולף, דב בר זאב מקוצק","k":"חתן הרבי מקוצק","b":"רב בקוצק-תר\"מ"},{"i":16606,"n":"וולף, דב בריש מצאנז","f":"משה גולד'ס בוקסבוים","b":"רב בצאנז בזמן הדברי חיים. נשא את שם משפחתה של אמו."},{"i":16607,"n":"וולף, דוד מזלישטשיק","b":"תשובה אליו בטוט\"ד."},{"i":16608,"n":"וולף, חיים ברוך מוישניצא","f":"פנחס","bt":"תר","dt":"תרס","b":"ראב\"ד בוישניצא על מקום אביו."},{"i":16609,"n":"וולף, יוסף מליטא וארה\"ב","f":"ברנט","bt":"1896","bp":"וילנא","b":"רופא. תלמיד אוני' גלזגו ופילדלפיה. יסד מכון לחקר מחלות לב בפנסילבניה, יזם הקמת מרכז בריאות בפוריה-ליד טבריה. פעיל ציבור ומראשי הפדרציה של יהודי ליטא בפילדלפליה."},{"i":16610,"n":"וולף, יוסף מלנצהוט","b":"רב בלנצהוט. תשובה אליו בשות מהרשם."},{"i":16611,"n":"וולף, יוסף מקאלאטשא","f":"מרדכי מפאקש","k":"בעל גדולת מרדכי","bt":"תקעה","bp":"פאקש","dt":"תרנב - יד שבט","dp":"פאקש","b":"תלמיד החת\"ס, הכתב סופר, ור יחזקאל בנט מנייטרא. חתן ר אברהם שאג מקוברסדורף, ובזיוו\"ש חתן ר ישכר דב בר סימנדל מליפטא. רב בפאקש, קאלאטשא-תריט."},{"i":16612,"n":"וולף, ישראל זאב מאושפיצין","f":"נתן אהרן","bt":"תרסב","dt":"תשל","dp":"ניו יורק","b":"מחכמי אושפיצין, ניסה לסדר הגירה מסודרת של יהודים לארץ ישראל וכשנכשל עבר לפריז ולניו יורק, והוציא לאור ספרי תורה וחסידות."},{"i":16613,"n":"וולף, ישראל יצחק","f":"שלמה","k":"בעל קריסטענטום אדער","bt":"1861","bp":"ראסיין-ליטא","dt":"1926","b":"תלמיד ישיבת וולוזין. היגר לארה\"ב-1893. הו\"ל בקליבלנד \"דער אידישער שטרען\", ועוד. פעיל ציוני. חיבר גם \"ציוניזמוס אין ווארט און טהאט\". ?? לא באוצר ??"},{"i":16614,"n":"וולף, ישראל מבודפשט","b":"דיין בבודפשט."},{"i":16615,"n":"וולף, לוסיאן","k":"בעל מנשה בן ישראל","b":"חיבר באנגלית ספר על ר מנשה בן ישראל."},{"i":16616,"n":"וולף, מרדכי מפאקש","b":"חתן ר צבי הרש קוניץ מפאקש. רב בפאקש. אביו של ר יוסף מקאלאטשא."},{"i":16617,"n":"וולף, משה אליעזר מצאנז","f":"יהושע השל","bt":"תפג","bp":"צאנז","dt":"תקץ","b":"חתן ר יהודה ליב בן ר השל. רבה של צאנז על מקום זקנו ודודו. חי מאה ושבע שנים."},{"i":16618,"n":"וולף, משלם","f":"איסר בר","bt":"1877","bp":"קובנא","dt":"1942","dp":"מחנה ברוסיה","b":"עסקן ציבור מראשי הציונים בליטא, יו\"ר ועד הקהילה בקובנא, וחברת \"עזרה\". עלה לארץ וחזר לליטא. הוגלה ע\"י הרוסים למחנה ונפטר שם."},{"i":16619,"n":"וולף, מתתיהו מבלפרוט","b":"רב ראשי בבלפורט-צרפת-תרע."},{"i":16620,"n":"וולף, ניסן יהודה ליב מקראקא","f":"יהושע פנחס","bt":"תשז","bp":"קראקא","b":"עבר לאוסטרליה בגיל שנתיים. למד בישיבת חברון. רב באוסטרליה."},{"i":16621,"n":"וולף, ניסן יהודה מקראקא","f":"שאול","dt":"תשב","b":"חסיד צאנז מקראקא. נספה בשואה."},{"i":16622,"n":"וולף, נתן אהרן מאושפיצין","f":"משה אליעזר","bt":"תקכ","dt":"תר","b":"רבה הראשון של אושפיצין, רב בוישניצה."},{"i":16623,"n":"וולף, פנחס דוד יהושע השל","f":"נתן אהרן","bt":"תקס","dt":"תרם","b":"ראב\"ד וישניציא, חתן ר איציקל ציינוירט מוישניצא."},{"i":16624,"n":"וולף, פנחס מקלן ופתח תקוה","bt":"תרלה","bp":"קלן","dt":"תשכח","b":"תלמיד ר עזריאל הילסהימר, ר דוד צבי הופמן, ובעל תואר דוקטור. רב בקלן והמחוז. עלה לארץ-תרצו וכיהן כרב בפתח תקוה. חיבר ספרים ובהם ספר בערבית על הנביא יונה, דיוקים על התורה - בכת\"י."},{"i":16625,"n":"וולף, צבי הירש (גריגורי הנס)","f":"איסר בר","bt":"1869","bp":"קובנא","dt":"1942","dp":"קובנא","b":"בנקאי ועסקן ציבור בקובנא. מנהל הבנק היהודי בקובנא. מראשי \"קרן היסוד\" בליטא. חבר מועצת הזקנים בגיטו בזמן השואה. נספה בשואה."},{"i":16626,"n":"וולף, ראובן מדמביץ","f":"יעקב ישראל זאב הכהן","dt":"תש..","b":"מחכמי דמביץ. נספה בשואה."},{"i":16627,"n":"וולף, שלום שכנא מקופנהגן","f":"אלכסנדר אברהם מקופנה","b":"רב בקופנהגן אצל אביו."},{"i":16628,"n":"וולף, שלמה מטורנא","b":"מתורתו ב\"תל תלפיות\"-תרעח."},{"i":16629,"n":"וולף, שמעון מארה\"ב","bt":"1836","bp":"בווריה","b":"הגיע לארה\"ב בנערותו למד משפטים בקליבלנד-אוהיו. ציר ממשלת מצרים בארה\"ב-1881. חבר בועד אגודת \"בני ברית\". חיבר באנגלית - \"יהודי אמריקה כפטריוטים\" - 1896."},{"i":16630,"n":"וולף, שרגא פיבוש מצאנז","f":"משה","bt":"תרי","dt":"תרף","b":"רבו של הדברי חיים בצעירותו. חתן ר נתן שהיה רב בצאנז אצל הדברי חיים. רב בצאנז על מקום אביו."},{"i":16631,"n":"וולפא, יצחק מאוזווענט","dt":"תשג","b":"רב באוזווענט"},{"i":16632,"n":"וולפגנג, אהרן צבי הירש מקראקא","f":"זאב וולף","bt":"תקן","dt":"תרז","b":"דיין בקראקא אצל רדד\"ב מייזלס."},{"i":16633,"n":"וולפגנג, יהודה ליבוש מקראקא","dt":"תרנא","b":"רב בקראקא-תרמא."},{"i":16634,"n":"וולפגנג, משה מציעשינוב","b":"רב בציעשינוב, רב בדמביץ-תרפו."},{"i":16635,"n":"וולפובסקי, שמחה מוארשא","b":"ר\"מ ב\"תחכמוני\"-וארשא. פרסם מאמרים ב\"בית שמואל\" - וארשא תרצו."},{"i":16636,"n":"וולפנזון אברהם","bt":"1804","dt":"ה'תריד 1854","bk":[["מחזה אברהם",""]]},{"i":16637,"n":"וולפנזון, אברהם","f":"זאב","bt":"תקמג","bp":"שקלוב","dt":"תרטו","dp":"ירושלים","b":"דיין בצפת, עלה תקסט עם תלמידי הגרא, בן דוד של ר ישראל משקלוב, מבין כתביו נדפס \"מחזה אברהם\" תל אבי בתשז עם הקדמת נכדו, היה שליח של הישוב מופיע תשובה ממנו בשות יהודה יעלה לר יהודה אסאד, התשובה מופנת לר ישעיה ברדקי בירושלים"},{"i":16638,"n":"וולפנזון, זאב וולף מירושלים","f":"אברהם פינסקר משקלוב","k":"ר ועלוויל באבעס","dt":"תרמא - ל ניסן","dp":"ירושלים","b":"ממשפחת תלמידי הגר\"א בירושלים. בשליחות-תריב-תרטז, הגיה ספרים שנדפסו בירושלים בימיו, ממונה כולל רייסין, ועוד. חתנו - ר אלעזר לנדא מסלונים וירושלים, ונכדו ר אליהו לנדא (מצאצאי הגר\"א)."},{"i":16639,"n":"וולפנזון, יהושע מירושלים","f":"אברהם","bp":"ירושלים","dt":"תרפו - ו סיון","dp":"פתח תקוה","b":"דיין בירושלים אצל בעל \"פאת השלחן\"."},{"i":16640,"n":"וולפסון, אהרן מהאלי וברסלוי","f":"זאב וולף","k":"בעל אבטליון","bt":"תקטו","dt":"תקצה","dp":"פיורדא","b":"מחכמי ברסלוי, מורה, סופר ומדקדק, סייע למנדלסון בתרגום התנ\"ך, חיבר ביאור לשיר השירים יחד עם יואל בריל, חיבר \"אבטליון\", \"ישורון, ועוד."},{"i":16641,"n":"וולפסון, אליהו","f":"נתנאל דובראוונר","b":"חתן הגביר ר חיים שיינפינקל מקרלין. בניו - ר יעקב שמחה מקרלין, ר שלמה זלמן מהורדנא."},{"i":16642,"n":"וולפסון, אליהו מארה\"ב","bt":"תריט","dt":"תרפט - כג חשון","b":"רב בארה\"ב תרמ\"ט"},{"i":16643,"n":"וולפסון, דוד","f":"עייזק","bt":"1858","bp":"דארביאן","dt":"1914","dp":"גרמניה - ירושלים","b":"מנהיג ציוני. הגיע לממל-1872 והתקרב לרב ד\"ר יצחק רילף - מראשוני חובבי ציון בגרמניה. התגורר בליק-גרמניה אצל דוד גורדון עורך \"המגיד\", קלן. הצטרף להרצל והקים את \"אוצר התישבות היהודים\" בלונדון, נלווה להרצל במסעותיו אל הסולטן התורכי ולארץ. יורשו של הרצל בראש ההסתדרות הציונית."},{"i":16644,"n":"וולפסון, הרי","f":"המגיד ממזריטש","bt":"1887","bp":"אוסטרין-פלך וילנא","b":"תלמיד ישיבת סלובודקה, וישיבת ר יצחק אלחנן בניו יורק. למד באוני' הרווארד ונשלח למסע מחקר באירופה. פרופס לפילוספיה. חיבר מאמרים וספרים רבים בנושאים יהודיים וכלליים בעברית ואנגלית."},{"i":16645,"n":"וולפסון, י' מארה\"ב","b":"רב בהרטפורד-קונטיקט. פרסם מאמרים ב\"פרח הלבנון\" - וארשא תרעח."},{"i":16646,"n":"וולפסון, יהושע פאלק זאב","f":"יוסף צבי","k":"בעל פליאות חכמה","bt":"תקצה","bp":"מוינשט-רומניה","dt":"תרעג - אחרי","b":"בקי בחכמה דקדוק וקבלה. רב באקנא-ליד מוינעשט-תרל, פאלטישאן-רומניה-תרלה. נסמך מאת: ר יוסף שאול נתנזון מלבוב, ר ישעיה שור מיאסי, ר משה אריה מבאקוי. חיבר גם \"אניה בלב ים\", ועוד."},{"i":16647,"n":"וולפסון, יחיאל מיכל מיאנישוק","k":"בעל שפת הים","b":"רב ביאנושיק(=יאנישוק)-תרי, וחתנו ר נחום בצלאל דזימיטרובסקי על מקומו אחריו, חתנו גם - ר יעקב משה אשרוביץ מברעזי."},{"i":16648,"n":"וולפסון, יעקב שמחה מקרלין","f":"אליהו בן נתנאל מוולו","b":"נכד ר נתנאל דובראוונר, ונכד(אבי אמו) ר חיים שיינפינקל מקרלין. רב בקרלין. אחיו - ר שלמה זלמן מהורדנא."},{"i":16649,"n":"וולפסון, משה מאנטופול","f":"יחיאל מיכל וולפסון","b":"רב באנטופול-תר\"נ"},{"i":16650,"n":"וולפסון, שלמה זלמן מהורדנא","f":"אליהו בן נתנאל","b":"נכד ר נתנאל דובראוונר, ונכד(אבי אמו) ר חיים שיינפינקל מקרלין. רב בהורדנא. אחיו - ר יעקב שמחה מקרלין."},{"i":16651,"n":"וולפצי הלוי","f":"שמואל הלוי מקאשיווקא","b":"רב בהורידק-ת\"ר"},{"i":16652,"n":"וולפרט חיים בן צבי אברהם","bt":"1860","dt":"ה'תשב 1942","bk":[["בחיר חיים",""]]},{"i":16653,"n":"וולצקי, אברהם משה מארה\"ב","f":"יהושע","dt":"תרפח - כו אייר","b":"גביר בברונסויל-ארה\"ב, ממיסדי ביהמ\"ד \"אוהב שלום\"."},{"i":16654,"n":"וולק צבי הירש בן עזריאל","bt":"1856","dt":"ה'תרסו 1906","bk":[["ספרי עם כתר כהונה – חלק א",""],["ספרי עם כתר כהונה – חלק ב",""]]},{"i":16655,"n":"וולר, איזיק יעקב מויסוקי-מזבצק","b":"אב\"ד ויסוקי-מזובצקי. פרסם מאמרים ב\"הועד\" - פיעטרקוב תרעד."},{"i":16656,"n":"וולר, אליעזר שלמה מויסוקי","f":"יעקב ראובן","dt":"תרנב","b":"נכד ר ראובן מביאליסטוק ומצאצאי ר משה קרמר. חתן ר יצחק אייזק חבר בעל \"בנין עולם\". רב בויסאקי(=מאזובצק) כ-40 שנה ובנו ר יצחק איזיק יעקב על מקומו אחריו. תשובה ממנו בספר בנו - \"ברית עולם\"."},{"i":16657,"n":"וולר, אריה ליב מארה\"ב","f":"שמואל","bt":"תרנט","bp":"הורדנא","b":"תלמיד ישיבת שצוצין אצל ר אלתר שמואלביץ, ישיבת מיר, בזמן מלחה\"ע ה-I לא הספיק לברוח עם חבריו, נשאר בליטא והיה ממיסדי ישיבת \"שער התורה\" בגרודנא, ולישיבה הצטרף גם ר שמעון שקופ, ונסמך ממנו ומאת: ר\"י שוסטר מסוקולקי, ר אברהם גלברט מהורדנא, ר חיים דוד זשורובסקי, ר משה וולפסון מאניפאליע. חתן ר יצחק חיים לין. היגר לארה\"ב, וכיהן כרב בנוארק-תרפג. חבר אגודת הרבנים באמריקה ואגודת ישראל."},{"i":16658,"n":"וולר, דוד מזורובנא","b":"רבה של זורובנא-תריז."},{"i":16659,"n":"וולר, יצחק איזיק יעקב מויסוקי","f":"אליעזר שלמה","k":"בעל ברית עולם","bt":"תריח","dt":"תרנו - יז אב","b":"נכד ר יצחק איזיק חבר בעל \"בנין עולם\". רב בוויסאקי(=מזובצק) על מקום אביו. חתנו - ר ראובן לוינבוך מאליטא."},{"i":16660,"n":"וולר, יצחק דוד מדוקלא","b":"מחכמי דוקלא-תרנח."},{"i":16661,"n":"וונדר, אברהם יעקב מלנצהוט","b":"במנויי \"מנחם ציון\"-תרמה."},{"i":16662,"n":"וונדר, אלעזר מירוסלב","f":"דב בריש","bt":"תרסב","bp":"קאשיצע (ירוסלב)","dt":"תשלז","b":"מחסידי בלז. עלה לארץ-תרפו. חזר לירוסלב.חתן ר צדוק פריניץ מירוסלב. עלה לחיפה ועסק שם בצרכי צבור."},{"i":16663,"n":"וונדר, אריה ברוך מפשמישל","b":"כנראה אבי המשפחה (אולי מקור שמו על שהיה רוכל). מחכמי זולקוא-תקסט."},{"i":16664,"n":"וונדר, אריה ליב מהורודנקה","b":"רב בהורודנקה."},{"i":16665,"n":"וונדר, יצחק איזיק מירושלים","f":"יוסף","bt":"תקנא","dt":"תרלג","b":"רבה של אקמיאן-ליטא, עלה לירושלים-תרכג."},{"i":16666,"n":"וונדר, מאיר יצחק מלמברג","f":"צבי הירש","k":"הו\"ל דרך חיים","bt":"תרל","dt":"תש","b":"מחכמי למברג. ההדיר ספר \"דרך חיים\" לר מנחם די לונזאנו-תרצא. ?? לא באוצר ??"},{"i":16667,"n":"וונדר, מאיר מטרנופול","b":"עסקן בטרנוב. ברכה אליו על פעולותיו בקמחז\"ה-תרסח."},{"i":16668,"n":"וונדר, משה אהרן מפשמישל","b":"חסיד האדמור מבוקובסק, מחכמי פשמישל."},{"i":16669,"n":"וונדר, שמעון מרידיק","dt":"תרפג","b":"חסיד בלז מרידיק."},{"i":16670,"n":"וועלוויל מאנעשעס מוילנא","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז."},{"i":16671,"n":"וועלוויל רויזאס'ס מוילנא","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז."},{"i":16672,"n":"וזאן, דוד","k":"בעל מגן דוד","b":"מגדולי רבני תונס, דיין, פוסק, מקובל, חיבר \"מגן דוד\" חידושים לש\"ס, העתיק כתבי ר'יצחק חי טייב-תקצ\"ו"},{"i":16673,"n":"וזאן, נתן מנאבל","dt":"תרצו","b":"רב בנאבל. נזכר ב\"שלמי תודה\" לר שלמה דאנה."},{"i":16674,"n":"וזאן, שלמה מתונס","f":"יהודה","k":"בעל יריעות שלמה","dt":"תקעב - פסח","b":"רב בסוסא-תונס-תקלג, ופגש אז את החידא בשליחותו. דיין בפיסה."},{"i":16675,"n":"וזנר, אברהם אליהו מזכרון מאיר","f":"שמואל מבני ברק","b":"רב בזכרון מאיר בבני ברק לצד אביו."},{"i":16676,"n":"וחיון, אברהם","f":"דוד","b":"מו\"ץ בתאזא-מרוקו, סופר בי\"ד בפאס-תקמו, חתם עם ר רפאל אהרן מונסינייגו-תקסג. בנו - ר שמואל ה\"ן דוד וחיון."},{"i":16677,"n":"וחיון, אהרן מרבאט-מרוקו","f":"דוד","b":"מחכמי ארבאט(=רבאט)-מרוקו-בשנות ה-ת'."},{"i":16678,"n":"וחיון, יהודה","f":"דוד","dt":"תקנט","dp":"פאס","b":"מקובל,חכם שלם וכולל במקנאס,היה בפאס ונספה בדרכו במגפה,קבור בעוג'ה ערוס"},{"i":16679,"n":"וחיון, יוסף ה\"ן דוד","b":"מחכמי פאס. אביו של ר שמואל."},{"i":16680,"n":"וחיון, מסעוד ה\"ן דוד מפאס","b":"מחכמי פאס-שנות ה-ת'."},{"i":16681,"n":"וחיון, שמואל ה\"ן דוד מפאס","k":"בן אדיב","b":"מחכמי פאס, חתם-תץ עם ר יוסף בהלול. נזכר אצל ר ידידיה מונסונייגו ב\"קופת הרוכלים\"."},{"i":16682,"n":"וטשטין, יהודה ליב מברוסילוב","f":"שלום שכנא","bt":"תרטז","b":"מו\"צ בבוריסלאב(=ברוסילואוו)-פלך קיוב-תרלז. נסמך מאת: ר יוסף יוזפא אפרתי מברדיטשוב, ר נפתלי צבי מסקווירא."},{"i":16683,"n":"וטשטין, יהושע מנובוסליץ","f":"ישראל פסח","dt":"תשד","b":"רב בנובוסעליץ-תרפט. נספה בשואה."},{"i":16684,"n":"וטשטין, ישראל פסח מנובוסעליץ","f":"שלום שכנא מברוסילוב","bt":"תריט","b":"חתן ר שמחה מאויניצא-ליד זיטומיר. מו\"צ בבוריסלב-פלך קיוב-תרמא על מקום אבותיו ואחיו ר יהודה ליב על מקומו אחריו, רב בנובוסליץ(=נאוואסעליץ)-בסרביה-תרנה. נסמך מאת: ר יוסף יוזפא אפרתי מברדיטשוב, ר דוד אורטינבורג, ר ליב בעל \"יד יהודה\". חיבר מאמר \"יראת המלך\" ונדפס בכנה\"ג, חיבר חדושים בש\"ס - בכת\"י."},{"i":16685,"n":"וטשטין, פיבל הירש מקראקא","bt":"תריח","bp":"קראקא","dt":"תרפד","b":"מחכמי קראקא, עסר בחקר קדמוניות. חיבר ספרים מאמרים בכתב עת ועוד וביניהם \"קדמוניות מפנקסאות ישנים\" קראקא תרנג, ועוד. פרסם מאמרים ב\"הפלס\" - ברלין תרסא-תרסה."},{"i":16686,"n":"וטשטין, שלום שכנא מבוריסלב","f":"יהושע זליג","b":"מו\"צ בבוריסלב-תר\"ל"},{"i":16687,"n":"ויבלמן, אליקים","b":"רב בפרשבורג-רמ\"ז,עבר לוינר-ניישטט"},{"i":16688,"n":"ויבצר, אהרן מלבוב","f":"משה","dt":"שפב - ל אב","dp":"לבוב","b":"ר\"מ בלבוב"},{"i":16689,"n":"ויבצר, יהודה ליב מלבוב","f":"משה","dt":"שלג - ל אב","dp":"לבוב","b":"ר\"מ וראב\"ד בלבוב"},{"i":16690,"n":"ויגאדער, יהושע זליג מדבלין","b":"פרסם מאמרים ב\"המגיד\" - סטמר תרפח-תרצט."},{"i":16691,"n":"ויגודסקי, אלכסנדר","dt":"תש","b":"רב בברעזא"},{"i":16692,"n":"ויגודסקי, יעקב","f":"יחיאל","k":"בעל אין שטורם - 1926","bt":"1855","bp":"בוברויסק","dt":"1941","dp":"וילנא","b":"אבי אמו היה רב בנאסוויז. רופא ועסקן ציבור, הצטרף לציונות-1905. במלחמ\"ה ה-I ארגן את הגנת יהודי וילנא ונאסר בידי הגרמנים על כך. יו\"ר הקהלה בוילנא. ציר בסיים הפולני. פרסם מאמרים רבים בנושאי רפואה ויהדות. חיבר ספרי זכרונות באידיש ובהם \"אין שטורם\", \"אין גיהנום\" - זכרונות מבית הסוהר הגרמני, \"אין סמבטיון\" זכרונות מהסיים הפולני. נספה בשואה."},{"i":16693,"n":"ויגוסקי, סנדר מברעזא","b":"פרסם מאמרים ב\"אהל תורה\" - ברנוביץ תרפד."},{"i":16694,"n":"ויגלר, אשר מטרנופול","b":"שו\"ב בטרנופול."},{"i":16695,"n":"ויגלר, זאב וולף מקוזלוב","bt":"תקנה","dt":"תרנח","b":"אבי המשפחה. נינו סטנלי ממונטריאול רשם את תולדות המשפחה."},{"i":16696,"n":"ויגלר, משה מסאסוב","dt":"תרצב","b":"ראה הקהל בסאסוב."},{"i":16697,"n":"ויגר, מנחם מנדל מאטיניא","b":"רב באטיניא-תרע. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":16698,"n":"ויגר, שמעון צבי הירש מקרופיטש","bt":"תר","bp":"בוזנוב","dt":"תרעה","b":"חסיד סטרטין וצורטקוב. אב\"ד קריפטש (ליד סטניסלב). חתן בזיוו\"ש של ר יחיאל מיכל היבנר מניזנוב בעל \"משכנות הרועים\". פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד. תשובות אליו נדפסו בספרי חכמי דורו."},{"i":16699,"n":"ויגרערוויץ, שמואל חיים מקלם","b":"גביר מחכמי קעלם. חתנו - ר חיים גרשון מוסנזון."},{"i":16700,"n":"וידאל - משפחה","b":"משפחה מספרד ואלגיר. השם וידאל היה משמש בדרך כלל כינוי לשם \"יהודה\". השם יהודה כשם משפחה היה בשימוש אצל משפחות המיוחסות לבית דוד."},{"i":16701,"n":"וידאל אפרים","b":"בקי, רב במיורקה, רבו של הרשב\"ץ - שכינהו הקדוש, ונראה שמסר נפשו על קידוש השם (בקונטרס של ר יהודה וידאל מתלמסאן אומר שר אפרים בא מספרד עם ר קרשקש וידאל לתלמסאן ואח\"כ לאלגיר)."},{"i":16702,"n":"וידאל ויואש, משה","b":"מגדולי רבני צרפת,רב בפירפינייאן-ש\"נ"},{"i":16703,"n":"וידאל משלוניקי","f":"שבתי בן אנגל","k":"בעל ספור החיים","dt":"תקי - אחרי","dp":"שלוניקי","b":"חתן ר יצחק ן שאנג'י. דיין בשלוניקי. חיבר הקדמה לספר חותנו \"בארות המים\" ושם גם תשובה ממנו. מדרשותיו נדפס \"ספור החיים\"-תקכא."},{"i":16704,"n":"וידאל, אפרים מספרד","bp":"ספרד","b":"מחכמי מיורקה-קכ. תלמיד הר\"ן, בא מספרד לתלמסאן-שנות הק', ברח לאלג'יר. היה במחלוקת עם ר שלמה צרפתי במיורקה - והריב\"ש עשה שלום ביניהם. מתלמידיו הרשב\"ץ."},{"i":16705,"n":"וידאל, דוד מאלגיר","b":"ראש הקהל בתלמסאן, ותיקן כמה תקנות עם חבריו ר שם טוב בלייח, ור אליהו הכהן - ונכתב הכל בספר ונדפס בווהראן תרם."},{"i":16706,"n":"וידאל, דוד מארטא","b":"חתן ר דוד הכהן-הרד\"ך. רב בארטא על מקום ר שמואל קלעי שעבר לוידין, פטרץ."},{"i":16707,"n":"וידאל, יהודה מאלגיר","bt":"תע","dt":"תקם","b":"רב בתלמסאן. חיבר קונטרס על יהודי תלמסאן ורבניה."},{"i":16708,"n":"וידאל, יעקב משלוניקי","dt":"תסט","dp":"שלוניקי","b":"דיין בשלוניקי."},{"i":16709,"n":"וידאל, יעקב משלוניקי - ב","dt":"תקכד","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":16710,"n":"וידאל, ישראל מאלגיר","bt":"תקם","dt":"תרך","b":"מחכמי תלמסאן, וסופר. חתם בפנקס קהלת תלמסאן. חתם בטיטואן-תקצח עם ר אברהם אנהורי (או שמדובר על חכם אחר?)"},{"i":16711,"n":"וידאל, מרקאדיל מספרד ואלגיר","bt":"ק","dt":"קע - בערך","b":"רב במיורקה, אחרי פרעות קן עבר לאלגיר. לדברי הרשב\"ץ היה ר מרקאדיל מתלמידי הר\"ן."},{"i":16712,"n":"וידאל, משה מספרד וירושלים","b":"רופא מחכמי ספרד, ברושא, עלה לירושלים. נכדו - משה בן מכיר מברושא שמסר הרשאה לרלב\"ח לתבוע את ירושת זקנו."},{"i":16713,"n":"וידאל, נתן","k":"בעל דרושים לכל חפצי'","dt":"של","b":"עמקן,חריף,רב בפפד\"מ"},{"i":16714,"n":"וידאל, קרשקש מספרד","bp":"ברצלונה","b":"תלמיד הרא\"ה והרשב\"א, אחיו של בונפוס וידאל מברצלונה, ושניהם נזכרו בתשובות הרשב\"א. חיבר חדושים לש\"ס. (יש הסוברים שהוא אותו חכם המכונה אצל הריב\"ש \"דון אשתרוק קרישקש\" שחיבר שיטה על הש\"ס). בקונטרס של ר יהודה וידאל מתלמסאן כותב כי הגיע מספרד יחד עם ר אפרים וידאל לתלמסאן ואח\"כ לאלגיר."},{"i":16715,"n":"וידאל, שמואל מאלגיר","bt":"תקל","dt":"תר - בערך","b":"רב בתלמסאן ודיין אצל ר נתן ג'יאן. הסכים על מחזור תלמסאן - ליוורנו תקס."},{"i":16716,"n":"וידאש די, אליהו מצפת","f":"משה","k":"בעל ראשית חכמה","r":"תלמיד האריז\"ל והרמ\"ק","bt":"שי","bp":"צפת","dt":"שמו-שן","dp":"חברון","b":"תלמיד ר משה קורדובירו, מחבר \"ראשית חכמה\", ונציה שלט, ו\"תוצאות חיים\" - והוא קיצור ספרו ראשית חכמה. בסוף ימיו עבר לחברון והיה שם ראש הרבנים. לדברי רוזנס נפטר בשנת שלח וזה אינו שכן בספרו מופיע בברכת החיים. (גדולי החסידות החשיבו מאוד את ספרו וציוו על החסידים ללמוד בו - ובתגובה כמה ממתנגדי החסידות אסרו ללמוד בו כדי להתרחק מהחסידים). לדעת רוזניס הוא אחד ממחברי \"מגיד מישרים\" - ולא ר יוסף קארו.","bk":[["ראשית חכמה - מוסר",""]]},{"i":16717,"n":"וידאש די, משה משלוניקי","dp":"צפת","b":"רב בשלוניקי, עלה לצפת לפני שנת ש'. בנו - ר אליהו בעל \"ראשית חכמה\"."},{"i":16718,"n":"וידאש די, שמואל מתורכיה","b":"מחכמי שלוניקי-שנו בזמן הרא\"ם. מחדושיו ב\"שיטה מקובצת\". חיבר פירוש על איכה - שלוניקי שנו."},{"i":16719,"n":"וידבסקי, צבי יעקב מקשאנוב","f":"אברהם","k":"בעל תפארת צבי יעקב","bt":"תרך","dt":"תרצד","b":"מחכמי קשאנוב. חיבר \"תפארת צבי יעקב\" ירושלים תשלג."},{"i":16720,"n":"וידברג, צבי מסקאלא","b":"מחכמי סקאלא. תשובה אליו ב\"שות מהרי הכהן\"."},{"i":16721,"n":"וידזר, יעקב","k":"בעל דברי חפץ","b":"דרשן,מו\"צ בנמנצין, פאדברעזע-ת\"ר. ?? לא באוצר ??"},{"i":16722,"n":"וידיסלב, יהודה ליב","b":"דיין בלבוב תפ\"ז"},{"i":16723,"n":"וידלר, יצחק מקמרובקא","f":"נתן נטע","b":"רב בקמרובקא-פרוור במינסק, עלה לירושלים-לפני תש."},{"i":16724,"n":"וידמן, יהודה ליב מגרוסורדין","f":"נחמן יעקב","k":"בעל הליכות עולם","b":"נכד ר יצחק מאיר ממאסיף. מחכמי גרוסורדין, וערך עם אחיו ר יוסף מרדכי את הקובץ \"הליכות עולם\"-תשג. נספה בשואה."},{"i":16725,"n":"וידמן, יוסף מרדכי מגרוסורדין","f":"נחמן יעקב","k":"בעל הליכות עולם","b":"נכד ר יצחק מאיר ממאסיף. מחכמי גרוסורדין, וערך עם אחיו ר יהודה ליב את הקובץ \"הליכות עולם\"-תשג. נספה בשואה."},{"i":16726,"n":"וידמן, יחזקאל מסיטשל","f":"יצחק מאיר ממאסיף","k":"בעל אמונה ודעת-תרפח","dt":"תשד","b":"חתן ר מאיר אפל מיועד, רב לא רשמי ביועד, רב בקעכניא, סיטשל(=איזמטשל?)-תרפב. עורך כתב העת \"דגל התורה\" - אויבר-וישוה תרפב. נספה בשואה. הו\"ל מאמר העיקרים לרמח\"ל עם פירוש ממנו בשם \"אמונה ודעת\". פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד. ?? לא באוצר ??"},{"i":16727,"n":"וידמן, יצחק (ולא משה) מאיר","dt":"תש","b":"נרשם בטעות בספרי הביוגרפיה כ\"משה מאיר\". מחכמי איבר-ווישווה-תרמב, רב במאסיף-תרסה על מקום ר חיים אלתר דכנר. פרסם בכתב העת \"דגל התורה\"-תרפז בעריכת בנו ר יחזקאל. חתם על פסק-תרפד עם ר חיים מרדכי יעקב גוטליב, ור דוד שפרבר ונזכר ב\"יגל יעקב\". הניח חדושים בכת\"י."},{"i":16728,"n":"וידמן, משה","b":"דומ\"צ במטרסדורף-תר\"י"},{"i":16729,"n":"וידמן, משה מאיר","f":"וידמן, יצחק","b":"רב במאסיף-תרע\"ד"},{"i":16730,"n":"וידן, שלמה זלמן מבריגל","b":"רב בבריגל בזמן רא\"ל ליפשיץ."},{"i":16731,"n":"וידנבוים, נפתלי הרץ הלוי","f":"אריה ליב","k":"בעל ביאור סידור הגרא","bt":"תרג","bp":"ביאליסטוק","dt":"תרסב","dp":"ירושלים","b":"מחכמי ירושלים, התמנה לרב ביפו ופעל לחיזוק התורה במושבות החדשות. חיבר \"באור סידור הגרא\" ירושלים תרנח, ועוד. ?? לא באוצר ??"},{"i":16732,"n":"וידנבלט, דוד אלימלך מצנסטחוב","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":16733,"n":"וידניק, פישל מרדומישל","b":"רב בטרנוב."},{"i":16734,"n":"וידנפלד, אברהם מסטניסלב","b":"מחכמי סטניסלב-תרלא. סייע בהוצאת \"דעת קדושים\" למברג תרלא."},{"i":16735,"n":"וידנפלד, אליעזר מסטרי","f":"יעקב","bt":"תקל","dt":"תרי","b":"מחסידי רוזין. תלמיד ה\"חוות דעת\". רב בריאמפול. אמו חנה - נקראה ע\"י המגיד מקוזניץ \"בעלת בטן הזהב\" - על שילדה שלוש צדיקים. אחיו: ר נחום, ר אליעזר חתן ר זלמן בריטוועס מסטרי."},{"i":16736,"n":"וידנפלד, דב בריש מטשבין","f":"יעקב","k":"רד\"ב מטשבין","r":"הרב מטשיבין","bt":"תרמא","bp":"הרימלוב","dt":"תשכו - י חשון","b":"חסיד הוסיאטין. חתן הגביר ר ישראל יוסף קלוגר מטשבין. מחכמי טשבין, ובהמשך רבה של טשבין. הקים ישיבה בשם \"כוכב מיעקב\". תואר על ידי הנאצים ב\"שטירמר\" כגדול התלמודיים בעולם ולכן ברח מפניהם לרוסיה. עלה לארץ-תשו. חתן בזיוו\"ש של משה ליבמן מקאשוי. הקים מחדש את ישיבתו בירושלים. חיבר \"דובב מישרים\" טשבין תרצז.","bk":[["דובב מישרים – שו\"ת והגהות",""],["דובב מישרים",""]]},{"i":16737,"n":"וידנפלד, דוד מרוזניאטוב","b":"מחכמי רוזניאטוב-תרצז, רב בסטניסלב-תרעג."},{"i":16738,"n":"וידנפלד, יעקב מטשבין","f":"דב בר","bt":"תרסב","dt":"תשב","b":"ר\"מ בישיבת \"כוכב מיעקב\". חתן ר חיים קנר. נספה בשואה. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":16739,"n":"וידנפלד, יצחק מהרימלוב","f":"יעקב","bt":"תרלד","dt":"תשג","b":"חתן ר יוסף חיים בוימינגר מקראקא. רבה של הרימלוב-תרנד על מקום אביו. בזמן מלחמת העולם הראשונה סייע רבות לבני קהילתו וישב בכלא הרוסי. עבר לוינה."},{"i":16740,"n":"וידנפלד, ישראל יוסף מטשבין","f":"דב בריש","bt":"תרסג","dt":"תשג","b":"ר\"מ בישיבת \"כוכב מיעקב\" בטשבין. חתן ר מנחם זמבה מוארשא. נספה בשואה."},{"i":16741,"n":"וידר, ברוך אברהם מסעקעי-אודוא","dt":"תשד","b":"רבה האחרון של סעקעי-אודווארהי. אחיינו של ר שלום וידר מנירדהאזא בעל \"משמיע שלום\". נספה בשואה."},{"i":16742,"n":"וידר, חיים יעקב נתנאל מבורשא","b":"פרסם מאמרים ב\"דגל התורה\" - אויבר-וישווה תרפח."},{"i":16743,"n":"וידר, מנחם מנדל מסיגט","b":"מדפיס בסיגט, הדפיס כתב עת \"מגד ירחים\" תרנח."},{"i":16744,"n":"וידר, נפתלי הירצקא","f":"שלום וידר","dt":"תשד","b":"מרביץ תורה,דומ\"צ בנירדהאז. חתן גיסו ר משה פרנקל מזשיבא."},{"i":16745,"n":"וידר, שלום מנירד-האזא","f":"חיים אריה מסיגט","k":"בעל משמיע שלום-תשלא","bt":"תרכד או תרטז","bp":"בורשה-מארמארוש","dt":"תשד - טז סיון","b":"תלמיד בישיבת בעל \"קול אריה\" במאד, ובישיבת בעל \"ייטב לב\" בסיגט. חתן ר יצחק איזיק פרידמן מנירדהאזה(=נירעדיהאז). רב בנירדהאזה(=נירד-האזה)-תרנז על מקום חותנו כ-50 שנה. נספה בשואה."},{"i":16746,"n":"וידר, שלמה דב מנירעדהאז","f":"יצחק אלימלך","dt":"תשמה - כה אדר","b":"תלמיד הדעת סופר, ור חיים צבי טיטלבוים מסיגט ור ישעיה זילברשטין מוויצען. חתן דודו ר שלום וידר מנירעדהאזא. רב בנירדהאזא לצד חותנו. ניצל מהשואה ואחריה רב בהונגריה, גרמניה, ניו יורק, עלה לירושלים."},{"i":16747,"n":"וידר, שלמה מבודפשט","k":"בעל קטלוג לשירה ופיו","b":"מלמד בביהמ\"ד לרבנים בבודפשט. חוקר השירה העברית בימי הביניים. הו\"ל קטלוג לשירה ופיוט של גנזי קהיר."},{"i":16748,"n":"וידרוביץ, חיים יעקב מנ\"י","b":"רב במוסקבה-תרנז. פרסם מאמרים ב\"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג."},{"i":16749,"n":"וידרוביץ, יצחק דוד מניעזין","f":"יהושע זליג","bt":"תרכא","b":"רב בקרסנליק(=קראסנאליק)-פלך מינסק-תרמו, בארזנא-פלך צרניגוב, נאעזין(=ניעזין)-פלך צרניגוב."},{"i":16750,"n":"וידרמן, בצלאל מבילקמין","f":"יוסף","bt":"תקו","bp":"בילקמין","dt":"תרך","b":"מחסידי סטרטין. סירב לנהוג באדמורות."},{"i":16751,"n":"וידרמן, יהודה ליבוש מטשאבא","dt":"תשד","b":"דומ\"צ בטשאבא"},{"i":16752,"n":"וידרסהיים, נתנאל זליגמן ממיץ","k":"בעל אמרי בינה","b":"רב במיץ-תקף."},{"i":16753,"n":"וידרקר, יהושע מפשמישל","f":"יעקב","k":"בעל חדושי מהריו","r":"ראב\"ד פשעמישל","bt":"תרלא","bp":"ברזאן","dt":"תשב","b":"חתן ר אלעזר לפיא מילשטוק מנריוב. רב בניישטט-תרעב. רב בפשמישל-תרעט.. נספה בשואה. חיבר \"חדושי מהרי\"ו\" בילגוריא תרצו. ?? לא באוצר ??","bk":[["חידושי מהרי\"ו",""],["חלקת יהושע – ב\"מ",""]]},{"i":16754,"n":"ויואנטי, אברהם דוד חי מאנקונה","k":"בעל כתבי אברהם דוד ח","b":"תלמיד ר יעקב שמשון שבתי סיניגאליה, ור יעקב שמשון שבתי מסיניגאליא. רב באנקונה, ותלמידו ר יצחק רפאל אשכנזי על מקומו אחריו-תרלז. היה בעל ספריה חשובה שאותה ירש תלמידו וממנה נדפסו ספרים חשובים ובהם שו\"ת הר\"ן. מתורתו נדפס קצת מכתבי רבי אברהם דוד חי\" טירנוי תרצב."},{"i":16755,"n":"ויזגאן, אהרן מירושלים","b":"חתם על כתב שליחות ר אברהם ביטון ור שמואל רימון שיצאו בשליחות עדת המערבים לאחר תלאות אבן פארוך בשנת שפה"},{"i":16756,"n":"ויזגאן, מרדכי מירושלים","k":"בעל נובל העלים","b":"מחכמי ירושלים? בשנת תו חתם על התקנה לשחרור תלמידי חכמים ממס."},{"i":16757,"n":"ויזגאן, משה ממרוקו","k":"בעל ויגד משה","bt":"תרסד","bp":"מוגדור","dt":"תשמג","dp":"ירושלים","b":"רב במוגאדור, מראקש, עלה לירושלים, למד ביחד עם ר שלום משאש."},{"i":16758,"n":"ויזל, אברהם שלום ישעיה מקיש","b":"דיין בקיש, פעסט, מונטוידאו. חתן ר יעקב יחיאל שוורץ מקראלי."},{"i":16759,"n":"ויזל, בן ציון מבראשוב וטורדה","f":"כלב פיבל מטורדה","bt":"תריט או תרכד","dt":"תרצח - כד אד\"א","b":"תלמיד השב\"ס. חתן ר אלימלך רוזנפלד מכפר סעפלאק (המכונה \"אספן החתנים\") וגיסיו היו ר משה בן הכת\"ס, ר לייב לנדסברג בן יצחק מגרוסורדין, ור יחיאל מאיר פאנט. מחכמי דיטשא סט מארטו-תרנא, רב בברשוב-תרמט, קרונשטט וחתנו - ר זאב צבי קליין על מקומו אחריו, טורדא-תרנח על מקום אביו. נשיא הלשכה האורטודוכסית בטרנסילבניה-תרצב, וחתנו ר יוסף אדלר - ה\"גאון מטודרא\" על מקומו אחריו בטורדא. הו\"ל ספרי אביו \"קרית ספר\". פרסם מאמרים ב\"לקט ששנ\"ה\" - סטמר תרצד."},{"i":16760,"n":"ויזל, ברוך בנדיט מברסלוי","k":"בעל מקור ברוך","b":"רב בברעסלוי-תק, בנו - ר משה הו\"ל את ספרו עם הוספות - אמשטרדם תקלא, ובנו ר שמואל שהחזיק בלומדי תורה."},{"i":16761,"n":"ויזל, יחזקאל מרדכי","dt":"תשד","b":"רב בפולייענע-קיראליהאז"},{"i":16762,"n":"ויזל, כלב פיבל גד מטורדה","f":"יוסף","k":"בעל קרית ספר-תרסה","bt":"תקצה","bp":"שטאמפן","dt":"תרנח - ג אלול","dp":"טארדא","b":"מוצא משפחתו מפרג. תלמיד ר יעקב צבי ניימן מוראדיש, הכת\"ס, ור יונה צבי ברנפלד מאירשא, ור הלל ליכטנשטין ממארגרטן. חתן הגביר ר יצחק ישכר דב נוסבוים (ניסנבוים) מיאז ועבר לשם. מורה בואלקא לילדי ר שלמה רוטשיליד. רבה הראשון של טורדא-תרכה וכיהן כ-35 שנה, ובנו ר בנציון על מקומו אחריו. (באוצר תאריך פטירתו - תרס - ב אלול). פרסם מאמרים ב\"בית ועד לחכמים\" - סאגהאלם-נייהייזל תרנד. בנו גם - ר שמואל משטמפן ודעווא."},{"i":16763,"n":"ויזל, מרדכי אליעזר מפאליען","b":"תלמיד ר ישראל מויזניץ. נתפרסם כאיש מופת-תרפו והמונים נהרו אליו, לאחר כשנתיים חלה בשיתוק."},{"i":16764,"n":"ויזל, נפתלי הרץ מהמבורג","f":"ישכר בר","k":"בעל גן נעול","bt":"תפה","bp":"המבורג","dt":"ה'תקסה 1805","b":"מזכיר אצל הגביר ר בנימין בן פייטל באמשטרדם, אצל הגביר יוסף בן פייטל מברלין. מתלמידי מנדלסון. היה מחלוקת עליו מצד רבני אשכנז - ורבני איטליה תמכו בו - ובהם: ר\"י פורמיגיני, ר שמחה קלימני, הרב בורגו ועוד. חיבר גם \"הלבנון\", \"יין לבנון\", באור לתנ\"ך עם מנדלסון. בנו - ר שלמה הו\"ל משיריו.","bk":[["דברי שלום ואמת",""],["ספר המדות",""]]},{"i":16765,"n":"ויזל, שלמה אליעזר סגל מטרנאווא","f":"יחזקאל אברהם","dt":"תשד - כ ניסן","dp":"סטמר - ישראל","b":"חסיד אדמורי ויזניץ. רב בטרנאווא. לפני מלחה\"ע השניה החל לנהוג כאדמור."},{"i":16766,"n":"ויזל, שלמה מנחם","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח."},{"i":16767,"n":"ויזל, שמואל בנימין זאב מדווה","f":"כלב פיבל מטורדה","bt":"תרכא","dt":"תרעד - טו אלול","dp":"דעווא","b":"תלמיד השב\"ס. רב בדעווא(=דיווא)-תרן בקהילת סטאטוסקוו, שטאמפן-תרנד על מקום ר משה הרצוג שהחליפו בדווה, ובשנת תרנח התחלפו שנית וחזרו איש איש לקהילתו המקורית."},{"i":16768,"n":"ויזלברג, משה דב מקולומיאה","f":"צבי","bt":"תקף","dt":"תרם","b":"ליקוטים ממנו בספר \"זכרון משה\" בתוך \"ברכת אברהם\" קולומיאה תרמח."},{"i":16769,"n":"ויזמאן, אברהם מתונס","f":"משה","b":"מקובל בתונס, עלה לצפת-שנות ה-תק'."},{"i":16770,"n":"ויזמאן, יחיא מממראקש","dt":"תנו","b":"מו\"ץ במראקש עם ר יצחק דלויה, ר אברהם מאמאן."},{"i":16771,"n":"ויזמאן, מרדכי מאלגיר","bt":"תקנה","dt":"תרך","b":"רב באלגיר, עלה לצפת-תקצח (לאחר הכיבוש הצרפתי)."},{"i":16772,"n":"ויזמאן, שמואל ממוגאדור-מרוקו","b":"רב במוגדור-מרוקו - בשנות התק'. נזכר ב\"תקפו של יוסף\" לר יוסף אלמליח שהסכים עמו כנגד החולקים עליו ובהם - ר מסעוד אדהאן ור יהודה לנקרי."},{"i":16773,"n":"ויזן, משה אהרן","f":"מרדכי צבי","bt":"1878","dt":"1953","b":"בלשן."},{"i":16774,"n":"ויזנברג, שמעון מלובלין","b":"רב בלובלין לצדו של מהר\"ם מלובלין-תרץ."},{"i":16775,"n":"ויזנברג, שרגא","b":"חיבר ספר וכנגדו יצא מנדל בערישעס."},{"i":16776,"n":"ויזנזפט, פנחס","b":"מו\"צ בלודז-תר\"ע"},{"i":16777,"n":"ויזניצר, מרדכי יהודה שלמה מארא","f":"מנחם מנדל מויזניץ","dt":"תשמח - טו אלול","b":"מקורב לאדמורים \"אהבת ישראל\" בויזניץ, ו\"דמשק אליעזר\". רב וראש ישיבה באראד.תחת השלטון הקומוניסטי. פעל עם האדמור מסקולען למען ילדי רומניה. עלה לארץ וכיהן כראש ישיבת אנטינא בבני ברק. לתולדותיו \"דורש לציון\" בני ברק תשנו."},{"i":16778,"n":"ויזנסקי, אהרן משה","f":"יחיאל","k":"בעל עץ הדעת","bt":"1874","bp":"קאלואריה-ליטא","dt":"1948","dp":"תל אביב","b":"למד הנדסה בציריך, פעיל ציוני בציריך. חיבר ספרים שונים במדע. עלה לארץ."},{"i":16779,"n":"ויזנפלד, יעקב מזולקוא","dt":"תרפו","b":"אב\"ד זוקליקוב-אחרי תרסא. בעל ספריה גדולה. חתנו - ר טוביה הכהן רפפורט מטורונטו ירש חלק מספריו."},{"i":16780,"n":"ויזנר, ברוך","b":"דומ\"צ בבאטיו-תרע\"ד"},{"i":16781,"n":"ויזנר, יהושע","dt":"תשד","b":"רב בבאטיו"},{"i":16782,"n":"ויזנר, ישעיה מבני ברק","b":"פרסם מאמרים ב\"תפארת ציון\" - בני ברק תשב - קובץ תלמידי ישיבת \"תפארת ציון\"."},{"i":16783,"n":"ויזנר, ישראל יצחק מבני ברק","b":"פרסם מאמרים ב\"תפארת ציון\" - בני ברק תשב - קובץ תלמידי ישיבת \"תפארת ציון\"."},{"i":16784,"n":"ויזנר, שמואל","dt":"תשד","b":"דומ\"צ בבאטיו"},{"i":16785,"n":"ויזנר, שמואל הלוי","b":"פרסם מאמרים ב\"אהל תורה\" - ירושלים תרצט."},{"i":16786,"n":"ויזנר, שמעיה ממינכן","dt":"תשכא","b":"תלמיד הדעת סופר. חתן ר צבי אריה סאנדר מנאנאש. רב במינכן-תרפח, ניצל מהשואה, רב בניו יורק-תשו."},{"i":16787,"n":"ויזר, אשר אנשיל מגוליגור","bt":"תרסה","bp":"גוליגור","b":"תלמיד מהר\"ם שפירא. חתן ר אריה יהודה ליבזר. חיבר פירוש לתנ\"ך."},{"i":16788,"n":"ויזר, יעקב מוורצקי","b":"חתן הגביר אברהם עבר רוזנברג מזאבידקה."},{"i":16789,"n":"ויזר, ליבוש מסניאטין","b":"מחכמי סניאטין."},{"i":16790,"n":"ויזר, משה מרוזניאטוב","dt":"תש..","b":"מלמד לצעירים. נספה בשואה."},{"i":16791,"n":"ויזר-ויטלש, אלעזר מקומרנא","f":"שמחה","bt":"תקל","dt":"תר","b":"חתן ר יוסף מפוזנא. רבה של קומרנא-תקפז, לאחר שאיבד את רכושו בשרפה בשבת שנמנע מלכבותה. תשובה אליו בטוט\"ד."},{"i":16792,"n":"ויזר-ויטלש, דוד מבוברקא","f":"חיים","bt":"תקס","dt":"תרם","b":"רב בבוברקא על מקום אביו. עלה לצפת. בנו ר חיים שמחה על כסאו בבורקא אחריו."},{"i":16793,"n":"ויזר-ויטלש, חיים מבוברקא","f":"שמחה","bt":"תקכ","dt":"תקץ","b":"רב בבוברקא על מקום אביו. חתן ר יעקב הורביץ מלינסק מבוליחוב. בנו ר דוד על כסאו אחריו."},{"i":16794,"n":"ויזר-ויטלש, חיים שמחה מבוברקא","f":"דוד","bt":"תרי","dt":"תרסה","b":"רב בבוברקא על מקום אביו. אחר פטירתו מכר בנו את חזקתו ועבר ללמברג. תשובה אליו-תרך?"},{"i":16795,"n":"ויזר-ויטלש, יעקב מלמברג","f":"חיים שמחה","bt":"תרלט","bp":"בוברקא","dt":"תשב","b":"מחכר את חזקת רבנות בוברקא. מחכמי למברג. נשיא אגודת ישראל בגליציה המזרחית. ממשתתפי \"יבנה\"-תרפט."},{"i":16796,"n":"ויזר-ויטלש, שמחה מבוברקא","f":"יעקב בן דב בער מלבוב","k":"בעל הגהות על מבוא שע","bt":"תק","dt":"תקף - טז אדר","dp":"קומרנא","b":"חתן הגביר ר חיים רובינשטין מזולקווא. מגדולי דורו. רב בבוברקא-תקס. נינו של ר דב בעריש הכהן מלמברג-תלמיד הבעש\"ט. תלמיד ר יוסף תאומים בעל \"פרי מגדים\" ונזכר בספרו, ור משולם זוסיא מאניפולי. האדמו\"ר ר משה יהודה ליב מסאסוב שיגר אליו \"קוויטל\". הסכים על \"אור פני משה\". חיבר הגהות על \"מבוא שערים\"."},{"i":16797,"n":"ויטאל פליקס, חיים הרופא מאיטלי","b":"למד רפואה בפדובה, התישב בלובלין וקיבל אישור ממיכאל מלך פולין-תלב לעסוק ברפואה בכל מדינת פולין."},{"i":16798,"n":"ויטאל, אברהם","f":"חיים","bt":"כה אדר"},{"i":16799,"n":"ויטאל, דוד מפולייא","f":"שלמה הרופא","k":"בעל כתר תורה","bp":"אפוליא-איטליה","dp":"ארטא","b":"בן למשפחה מקאלבריאה. חכם תלמודי, דרשן, פייטן, רופא, מגדולי רבני איטליה. (ממגורשי ספרד-רנב?). חתן ר דוד הכהן(=הרד\"ך) מקורפו, הגיע עם אביו לפטרס(=פטרץ) ברח-רצג בגלל המלחמה עם ונציה, רב בארטא-תרצד, חיבר \"כתר תורה\", \"מכתם לדוד\", והכין לדפוס שו\"ת רבו מהרד\"ך."},{"i":16800,"n":"ויטאל, יוסף בכור","f":"שלמה","dt":"תרמט - ג תשרי","dp":"ירושלים","b":"בן למשפחה שמוצאה מאיטליה, בשנת שא עלה לצפת, ובשנת שג נולד בנו ר חיים ויטאל. לדברי \"קורא הדורות\" היה סופר מומחה, ותפילין שלו היו מבוקשים מאוד ונקראים תפילין רב קלבריש מפני שהיו אבותיו מקלבריה. וכן מעיד ר יוסף סמברי \"דברי יוסף\" שפה במצרים מבוקשים התפלין שלו ומוכרים אותם בדמים יקרים."},{"i":16801,"n":"ויטאל, משה מירושלים","dp":"צפת","b":"מחכמי ירושלים, בשנת תק חתם על מכתב ראשי הקהלה."},{"i":16802,"n":"ויטאל, משה ממצרים","f":"שמואל","bp":"דמשק","b":"נכדו של ר חיים ויטאל. עבר עם אביו למצרים, דיין במצרים-תמ אצל ר ישראל רומנו, ונזכר ב\"גנת ורדים\". חתם ראשון על העתק תקנת הרדב\"ז בתיווך בין קהילת מסתערב לקהל מערבים. ערך את ספר החזיונות לזקנו."},{"i":16803,"n":"ויטאל, משה מצפת","f":"יוסף","bt":"שיז","bp":"צפת","b":"רב ומקובל, ונזכר בספר הגלגולים לאחיו, וב\"עמק המלך\"."},{"i":16804,"n":"ויטאל, נחמיה","f":"חיים","b":"היה נביא בילדותו בגיל 4 ונפטר בן 13 שנה, כמו אחיו שנתנבא בגיל שנה וחצי ונפטר. נזכר בספר החזיונות."},{"i":16805,"n":"ויטאל, שמואל מדמשק","f":"חיים תלמיד הארי","k":"בעל מקור חיים","bt":"שנח","bp":"דמשק","dt":"ה'תלז","dp":"מצרים","b":"מגדולי תלמידי אביו מהרח\"ו, והחזיק בחלק מכתבי אביו. רב בדמשק-שפ והקים ישיבה בחכמת הקבלה, מצרים-תכג (הגיע לבקשת הג'יליבי רפאל בן יוסף ברהין שחזר ליהדות אחר שהמיר דתו בעקבות ש\"ץ). חתן ר' יאשיה פינטו בעל \"כסף נבחר\". מתלמידיו ר יעקב צמח. נשא ונתן עם חכמי דורו. חיבר גם \"באר מים חיים\", \"חכמת נשים\", ועוד. בניו ר משה רב במצרים, ובן נוסף שנפטר צעיר. הרבה מכתביו אבדו או נגנבו.","bk":[["חמדת ישראל – סידור עם כוונות",""],["באר מים חיים [שו\"ת]",""]]},{"i":16806,"n":"ויטאל-קלבריס, יוסף","b":"מחסידי איטליה בקלבריס-שנת ש',מקובל,כותב ספרים בקדושה"},{"i":16807,"n":"ויטאלי, בנימין כהן צדק מריגייו","f":"אליעזר","k":"בעל גבול בנימין","r":"אב\"ד ריגיו","bt":"תיא","bp":"אליסאנדריא דילה פאליא","dt":"תץ - יז שבט","b":"רב ומקובל, תלמיד ר' משה זכות, אב\"ד באליסאנדריא, בפיימונטה-תלה, ריגייו-תמה. חיבר \"גבול בנימין\", \"אלון בכות\". \"גשמי ברכה\" בכת\"י ממנו - בספריית ר בנימין פואה מריגייו. לפי רוזניס היה גם בירושלים.","bk":[["אבות העולם",""],["גבול בנימין [עה\"ת]",""],["אבות עולם - אבות",""],["אלון בכות - איכה בדרך הפשט",""],["גבול בנימין - דרשות על התורה בדרך הקבלה",""],["גשמי ברכה - שו\"ת (כת\"י - ויתכן שיצא לאור בשנת תשל על ידי מכון הרב ניסים)",""],["עת הזמיר - שירים ופזמונים לימי השבוע ומועדים על דרך הקבלה",""],["פתחי שערים",""],["שו\"ת הרב\"ך",""],["שפר התיקונים - מנהגים",""]]},{"i":16808,"n":"ויטאליש, משה מירושלים","dt":"רסג","b":"רופא מחכמי ירושלים."},{"i":16809,"n":"ויטאש, שבתי מקושטא","f":"יעקב","k":"בעל משיבת נפש","b":"רב בקושטא-תק. חיבר פירוש בלאדינו על האזהרות בשם \"משיבת נפש\"."},{"i":16810,"n":"ויטהול, משה ממישקולץ","b":"רבה הראשון של הקהילה החסידית במישקולץ, ור יוסף רייניץ על מקומו אחריו."},{"i":16811,"n":"ויטל חיים בן יוסף","f":"יוסף מקאלבריה","k":"בעל עץ החיים,מהרח\"ו","r":"תלמיד האריז\"ל","bt":"שג","bp":"צפת","dt":"שפ-ו - ל ניסן","dp":"דמשק","b":"אביו ר יוסף היה סופר סתם מפורסם בצדקותו והתפלין שכתב היו נודעים לשם. למד תורת הנגלה אצל ר משה אלשיך, ונסמך על ידי ר יוסף קארו, את תורת הסוד למד אצל ר משה קורדובירו, ומשנת ש\"ל כשעלה הארי למד אצלו והיה תלמידו המובהק. כנפטר הארי בשנת שלב נחשב ר חיים לממלא מקומו מכיון שהוא היחיד מכל התלמידים שהארי הרשה לו לכתוב את תורתו. בשנת שלז היה במצרים, עבר לכפר עין זיתים ליד צפת ואחר כך לירושלים. ברח בגלל התנכלות אבו סיפין מושל ירושלים שדרש ממנו למצוא בעזרת הקבלה את מנהרות חזקיהו ולכן ברח לדמשק. שב לירושלים ובשנת שמד נתמנה על ידי ר משה אלשיך לדיין ואף הוסמך על ידו (היחיד מכל חכמי צפת). אחרי שנת שנז היה רב בדמשק. חיבר ספרים רבים וספרו העיקרי \"עץ חיים\". במצרים נמצאו הרבה כתבים בכתב ידו, ביניהם חדושים בשס, החידא מזכירם אך הם אבדו. בנו ר שמואל בספרו \"חיים שנים ישלם\" הביא מחדושי אביו בתלמוד. תשובה שלו ב\"שות מהריט\". חתנו - ר יעקב אל מצרי בנבנישתי-נכדו של ר יעקב בירב.","bk":[["תורת חכם",""],["אבן השהם",""],["אדם ישר",""],["אוצרות חיים",""],["ארבע מאות שקל כסף",""],["דרך חיים",""],["התגלות קברי צדיקים",""],["טור ברקת",""],["לב דוד – תשובה",""],["לימודי אצילות",""],["ליקוטי תורה נביאים וכתובים",""],["מאמר פסיעותיו של אברהם אבינו",""],["מבוא שערים",""],["מועדי האר\"י",""],["ספר הדרושים",""],["ספ",""],["ספר יצירה – עם פירוש מהרח\"ו",""],["עולת תמיד",""],["עטרת זהב – מגילת אסתר",""],["עץ הדעת טוב",""],["עץ חיים",""],["פרי טעמי המצוות",""],["פרי עץ חיים",""],["פתורא דאבא",""],["קהילת יעקב",""],["שמונה שערים",""],["שערי הקדושה",""],["עץ חיים, ש\"פ קבור בסוריה",""],["אגרת ר' חיים ויטל",""],["דרך החיים",""],["התכונה",""],["ליקוטי תורה",""],["מחברת הקודש",""],["ספר הגורלות",""],["ספר הגלגולים",""],["ספר הליקוטים",""],["ספר התכונה",""],["עץ החיים עם פירוש פנים מאירות ופנים מסבירות א",""],["עץ החיים עם פירוש פנים מאירות ופנים מסבירות ב",""],["עץ החיים עם פירוש פנים מאירות ופנים מסבירות ג",""],["עץ החיים עם פירוש פנים מאירות ופנים מסבירות ד",""],["שבחי ר’ חיים וויטאל",""],["שער הגלגולים",""],["שער היחודים",""],["שער הכווות",""],["שער הכונות",""],["שער המצות",""],["שער הפסוקים",""],["שער הקדושה",""],["שער מאמרי רז\"ל",""],["שער מאמרי רשב\"י",""],["שער רוח הקודש",""],["רבי חיים ויטאל (מהרח\"ו)",""]],"e":"ש\"ג-ש\"פ"},{"i":16812,"n":"ויטלזון, יהודה מנחם משניצע","b":"רב בשעניצע-תר\"מ"},{"i":16813,"n":"ויטלזון, יעקב דוד מלודז","f":"יהודה מנחם משעניצע","dt":"תשג","b":"חתן ר נתן נטע דאנר מקאלביעל. מו\"צ בלודז."},{"i":16814,"n":"ויטלש, משה מבוברוסק","b":"רב בבויבריק-תר\"מ"},{"i":16815,"n":"ויטמאיר, מאיר צבי הירש מסמבור","f":"גבריאל","k":"בעל דרושי רמץ","bt":"תקנח","bp":"קלוש","dt":"תרלג","b":"חתן ר חיים שטיגלפסט וחתן לוי פרנצוז מברודי. רב בטרמבובלה, סמבור-תקפה. חיבר \"דרושי רמ\"ץ\" פרמישלא תרמז.","bk":[["שו\"ת רמ\"ץ",""],["דרושי רמ\"ץ",""]]},{"i":16816,"n":"ויטמונד, אברהם מאמשטרדם","f":"שמשון","k":"בעל אהבת חסד","dt":"תקל","b":"תלמיד ר אברהם ברודא מפפד\"מ בעל \"אשל אברהם\". מחכמי אמשטרדם. חתנו - ר דוד בלוך הו\"ל את ספרו \"וזה דבר השמיטה\", חיבר גם \"אהבת חסד\" - אמשטרדם תקלו."},{"i":16817,"n":"ויטמן, אברהם שלמה מהוסיאטין","b":"תשובה אליו - מהריא\"ז."},{"i":16818,"n":"ויטמן, יצחק דוד מבליגרד","b":"חסיד סדיגורא מבליגרד, ידידו של רמ\"ל לנגרמן מטורקא. עלה לירושלים. בנו ר חיים טוביה מבליגרד - מחשובי חסידי הפחד יצחק מבויאן (בשליחות בארה\"ב-תרפז - למען שיקום ביה\"כ תפארת ישראל שנפגע ברעש)."},{"i":16819,"n":"ויטנברג, יצחק","f":"צבי הירש","bt":"1905","bp":"וילנא","dt":"1943","b":"מזכיר אגודת פועלים בוילנא. בזמן השואה היה מנהיג במחתרת היהודית בגיטו, נאסר ע\"י שוטרים ליטאים ושוחרר בידי חבריו, ואז הודיע הגיסטפו שאם לא יסגיר עצמו יחוסל הגיטו - הסגיר עצמו לגרמנים. נספה בשואה."},{"i":16820,"n":"ויטנר, פנחס זליג מלבוב","b":"דיין בלבוב-תפ\"ה"},{"i":16821,"n":"ויטנשטיין, זאב דב מפיטסבורג","k":"בעל נחמד למראה","bt":"תרלו","bp":"נמירוב-פלך הורדנא","b":"תלמיד ישיבת וולוזין, ראדין. רב בביהכ\"נ \"שערי תורה\" בפיטסבורג-תרסא."},{"i":16822,"n":"ויטקובסקי, יוחנן","f":"ויטקובר, יוחנן","b":"פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז."},{"i":16823,"n":"ויטקובר, אליהו מברוד","b":"מחכמי ברודי ומקודם מויטקוב הסמוכה. תשובה אליו ב\"בית אפרים\"."},{"i":16824,"n":"ויטקובר, יוחנן מאלטונא","f":"שלמה מפייזר","k":"בעל אגדת פרחים","bt":"תקץ","dt":"תרן - כב כסלו","dp":"אלטונא","b":"תלמיד ר יעקב עטלינגר, ביהמ\"ד למורים בוירצבורג. חתן ר אשר אנשל ליכטנשטין מאלטונא. מלמד בת\"ת באלטונא. פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז, הגיה את ספרי רבו \"ערוך לנר\" ו\"מנחת עני\". חיבר \"אגדת פרחים\" ובסופו על רבני אה\"ו."},{"i":16825,"n":"ויטקובר, שלמה מפייזר","b":"רב בפייזר. בנו - המשורר ר יוחנן."},{"i":16826,"n":"ויטקין, הלל מארה\"ב","k":"הו\"ל אור המוסר","bt":"תרנז-ט","bp":"אמדור","dt":"תשלד - יא אלול","b":"תלמיד ישיבת סלובודקא, ר יוסף יוזל הורביץ מנוברדוק, יסד ישיבות נוברדוק ברוסיה ופולין, עלה לארץ-תרפט והתישב בתל אביב ובני ברק, ויסד ישיבות נוברדוק בארץ. עורך החוברות \"אור המוסר\"."},{"i":16827,"n":"ויטקין, נתן נטע אריה מקאלווריה","f":"אברהם","k":"בעל ירושה עולמית","b":"דיין ומו\"צ בקאלוואריא, עבר לניו יורק, ירושלים."},{"i":16828,"n":"ויטקין, שמעון","f":"יהודה ליב","k":"בעל שביל טוב"},{"i":16829,"n":"ויטקינד, אברהם משה מבולטרימנץ","k":"בעל תועפות ראם","bt":"תרמב","dt":"תשא","b":"רב בסעלוב, רבה האחרון של בולטרימנץ. נספה בשואה."},{"i":16830,"n":"ויטר, דוד מלונדון","b":"רב ברומבורג,ליבק,היגר ללונדון-ת\"ש,עלה לא\"י"},{"i":16831,"n":"ויטרבו, אברהם חיים מנוציה","k":"בעל אמונת חכמים","b":"רב בונציה-תנב. חיבר \"אמונת חכמים\", ובו גם מאמר כנגד המומר פאולי שהמיר דתו בפירנצה-תנב."},{"i":16832,"n":"ויטרבו, דוד ממנטובה","k":"בעל אם למסורת","b":"רב במנטובה בזמן ר יהודה מינדולה שהסכים על ספרו - \"אם למסורת\" - מנטובה תקח."},{"i":16833,"n":"ויטריאל, חיים ממישקולץ","dt":"תרעה","b":"דומ\"צ במישקולץ,התיישב במונקטש"},{"i":16834,"n":"ויטשיק, יצחק מאיירגאלע","dt":"תשג","b":"רב באיירגאלע"},{"i":16835,"n":"ויטשקו, פנחס","f":"צבי הירש","bt":"תרם","dt":"תשג","b":"חתן ר ישראל קרויטהמר מבוצאץ. נספה על קדוש השם בשואה."},{"i":16836,"n":"ויטשקו, צבי הירש","f":"יעקב יהודה אר' טשקר","bt":"תריח","bp":"סלאויטה","dt":"תרצז","b":"נכד ר אליהו מברנובקה בעל \"אורות על תהלים\". חתן ינטשי רוזנר (מצאצאי ר פנחס מקוריץ). שינה שם משפחתו (מאימת הגיוס) מטשקר לויטשקו והתישב בויזניץ. חסיד סדיגורא ובויאן."},{"i":16837,"n":"וייבלמאן, אליקים מפרשבורג","f":"קלונימוס","b":"חתן ר חיים הי\"ד. רב בפרשבורג-ר', ניישטט-ליד וינה."},{"i":16838,"n":"ויידל מוינה","dt":"ת - ה אדר","b":"רב בוינה."},{"i":16839,"n":"וייזנר, יהושע מבאט\"ו","b":"חתן ר יקותיאל יהודה גרינוולד מיארע."},{"i":16840,"n":"וייטץ","k":"בעל משנת רבי אליעזר ראה: וייץ","bt":"תקל - בערך","dt":"תרח","dp":"קושטא","b":"נכד ר אהרן די טולידו. תלמיד ר אליהו עניו. פוסק, דיין בקושטא, חתם-תקצד עם ר חזקיה רפאל הכהן ור חיים משה פריסקו-השני. אב\"ד. בניו ר חיים ור יוסף חיברו הקדמה לספרו \"משנת רבי אליעזר\", הו\"ל ספר רבו \"קונטריס דבר אליהו\" ונדפס בסוף ספרו \"משנת רבי אליעזר\", וכן חיבר גם \"קונטרס הזכרונות\" ונדפס בסוף ספרו. בניו גם ר מנחם, ר סימן טוב."},{"i":16841,"n":"וייל, אברהם מאשכנז","b":"מחכמי אשכנז. בנו - ר יוחנן אביו של ר חיים - חתן המהר\"ל מפרג."},{"i":16842,"n":"וייל, אברהם מזלצבורג","b":"אב\"ד מיהרינגע, זלצבורג ומדינת אבערלנד. בנו - ר יעקב בעל \"תורת שבת\"."},{"i":16843,"n":"וייל, אהרן זאב מקיוב","f":"יהושע","bt":"תרה","b":"תלמיד ישיבת וולוזין. רב בקיוב(=קיעו)-תרל. נסמך מאת: הנצי\"ב, ר יו\"ט ליפמן מביאליסטוק בעל \"עונג יו\"ט\". פרסם מאמרים ב\"מכילתא דרבנן\" - אודסה תרמו."},{"i":16844,"n":"וייל, אהרן מיכאל מצרפת ואלגיר","b":"רב בצרפת, אלגיר - מטעם הקונסיסטואר - תרו-תרכג. חתם על \"יקר סהדותא\" לכבוד ר אברהם אנקאווא - בזמן המחלוקת כנגדו בענין ספרו \"זבחים שלמים\". הטיף לדור הצעיר לאמץ את תרבות צרפת."},{"i":16845,"n":"וייל, אורי פויבר משטמפן","dt":"תריד - טז טבת","dp":"שטמפן","b":"דיין בשטמפן, חתם-תקסז בפנקס הקהל, חתם-תקעו על כתב רבנות ר מרדכי בנט. נדב ש\"ס לביהמ\"ד שם."},{"i":16846,"n":"וייל, אלימלך מדרוהוביטש","f":"משה","b":"נינו של ר שאול וואהל. רב בדרוהוביטש."},{"i":16847,"n":"וייל, אלכסנדר מצרפת","bt":"1813","bp":"אלזאס","b":"סופר בגרמניה, השתתף בכתבי עת בגרמנית. חיבר מאמר \"האשה היהודיה\"."},{"i":16848,"n":"וייל, אלתר מברוד","f":"יוסף בר","bt":"תריז","bp":"ברודי","b":"תלמיד ר חיים יהודה סוסצינר. עבר לארה\"ב-תרסו וכיהן כרב בברונזוויל."},{"i":16849,"n":"וייל, אפרים מסדילקוב","f":"לייב ר אינשיל'ס","dt":"תקצד - ז סיון","dp":"אוסטרהא","b":"אביו היה מתלמידי הבעשט. חתן ר יעקב שמשון משפיטובקה. היה משולח אצל הגביר ר שלמה זלמן זוסמן מאוסטרהא, נאמן בעסק שהיה לר שלמה זלמן בברדיטשוב, אב\"ד סדילקוב. הסכים על ספרים רבים ובהם \"תולדות יוסף\". הגיע כל שנה לאוסטרהא לעלות על קברי אבותיו ורבים הגיעו אליו לקבל ברכתו, ובשנה שנפטר בירך לפני צאתו את כל בניו ונכדיו ונפטר בהיותו באוסטרהא. נקבר ליד המהרש\"א (היה מצאצאיו)."},{"i":16850,"n":"וייל, אריה ליב מקומרנא","b":"רב בקומרנא"},{"i":16851,"n":"וייל, אשר מקרולה","f":"ישראל עוזר ממאד","dt":"תרא - ז כסלו","dp":"קרולה","b":"דומ\"צ בקראלי(=קרולה)."},{"i":16852,"n":"וייל, בייניש","f":"מאיר מבריסק","b":"נכד השר ר שאול וייל. חתן ר יעקב דעליטש מלודמיר."},{"i":16853,"n":"וייל, ברוך מהנובר","dt":"תפט - יא תשרי","b":"מגיד בטופס-תע\"ב"},{"i":16854,"n":"וייל, דוד","f":"ישראל סטרינר","b":"חתן רצ\"ה מדרוהוביטש. בנו ר אברהם מוישניצה, ר יוסף מריידינג, ר שמשון"},{"i":16855,"n":"וייל, דוד מטיסמניץ","f":"פסח","dt":"תרף","b":"לאחר שנתייתם גדל אצל הצמח צדיק מויזניץ עם בנו ר ברוך ולמד עמו - שכנעו שלא לעלות לארץ. מקורב לר חיים מאטיניא. שו\"ב בטיסמניץ."},{"i":16856,"n":"וייל, דוד מטישוויץ","b":"רב בטישוויץ-ת\"ר"},{"i":16857,"n":"וייל, זאב וולף מקיוב","b":"רב בקיוב-תר\"נ"},{"i":16858,"n":"וייל, זנויל מאלזס","dp":"בוסוילער-אלזס","b":"אבי משפחת וייל בהאללע וברלין. חתן ר אליעזר ליפמן מגטינגן וגיסו של ר יצחק בנימין וולף בעל \"נחלת בנימין\"."},{"i":16859,"n":"וייל, חיים יצחק מסניאטין","b":"רב בסניאטין. תשובה אליו - \"בר ליואי\"."},{"i":16860,"n":"וייל, חיים מפרג","f":"יוחנן או אברהם","k":"חתן המהר\"ל מפרג","bt":"שטז","dt":"שצא - ד אד\"א","b":"גביר ונשיא מחכמי פרג-שנא."},{"i":16861,"n":"וייל, חיים משוורזנץ","f":"יעקב משוורזנץ","b":"מחכמי שוורזנץ-תקעו."},{"i":16862,"n":"וייל, יהודה","f":"מאיר מבריסק","b":"נכד השר ר שאול וייל. חתן ר וולף מוילנא בן ר יצחק בייניש מקראקא."},{"i":16863,"n":"וייל, יהודה","f":"השר שאול","b":"חתניו - ר אברהם בן משה מלובלין, ר השל מקראקא (כנראה טעות)."},{"i":16864,"n":"וייל, יהודה ליב","f":"אליעזר","k":"בעל אמרי יהודה","b":"חיבר \"אמרי יהודה\" וילנא תרנג."},{"i":16865,"n":"וייל, יהודה ליב מנ\"י","b":"פרסם מאמרים ב\"הדנו\" - נ\"י תרפה."},{"i":16866,"n":"וייל, יהודה ליבוש מקומרנא","f":"צבי הירש בושקא מאה\"ו","b":"רב בקמרנא-ת\"ק"},{"i":16867,"n":"וייל, יונה (יוסף) מבומברג","f":"יעקב מדונא וביירן","b":"אב\"ד בומברג-שוואבען. בנו - ר משה ונכדו - ר יעקב חתנו של מהר\"ם פדובה."},{"i":16868,"n":"וייל, יונה מצרפת ואלגיר","dt":"תרפט","b":"רב בווהראן מטעם הקונסיסטואר - תרסה-תרפט."},{"i":16869,"n":"וייל, יוסף יהודה מואחניפקה","f":"יהושע אלעזר","bt":"תריב","b":"מצאצאי ר שאול ואהל. רב בוואחניפקה-פלך קיוב-תרן. נסמך מאת ר יוזפא מברדיטשוב."},{"i":16870,"n":"וייל, יעקב","f":"אברהם","k":"בעל תורת שבת","b":"חיבר עולת שבת - קרלסרוהא תקצט."},{"i":16871,"n":"וייל, יעקב מדונא וביירען","f":"מאיר מאולמא","b":"נכד ר יעקב בעל שו\"ת מהרי\"ו. בנו - ר יונה (יוסף) מבומברג ושוואבען."},{"i":16872,"n":"וייל, יעקב מליקאווא","f":"השר שאול","b":"רב בליקאווע-ת\"י"},{"i":16873,"n":"וייל, יעקב מערפורט","k":"בעל תשובות מהר\"י ויי","bt":"ה'קלג","dt":"רטז - בערך","b":"תלמיד ר יקב סגל-מהרי\"ל. נתמנה ע\"י רבו-המהרי\"ל לרב בנירנברג אולם סירב כדי לא לבוא בגבולו של ר שלמה הכהן (שכיהן שם ברבנות), אויגשבורג-קעב, ערפורט-קצח. מגדולי חכמי דורו. חיבר \"שו\"ת מהר\"י וייל\" ונציה רפג. בנו - ר מאיר מאולמא?","bk":[["מהרי\"ו",""],["מהרי\"ו (מהר\"י וויל)",""],["תקוני זבח",""]]},{"i":16874,"n":"וייל, יעקב משוורזנץ","b":"רב בשוורזנץ-לפני תקעו."},{"i":16875,"n":"וייל, יצחק איזיק מפשמישל","f":"שמואל","b":"רב בפשמישל-תקע."},{"i":16876,"n":"וייל, ישראל איסר הלוי","f":"שאול הלוי","b":"תלמיד ר מנחם מנדל מקוצק, חתן ר יצחק מזאמושטש. רב-שנת תקצ."},{"i":16877,"n":"וייל, ישראל מברוד","f":"נטע","bt":"תקע","dt":"תרם","b":"דיין בברודי."},{"i":16878,"n":"וייל, ישראל מלובלין","f":"מאיר מבריסק","dt":"שצט - ו ניסן","dp":"לובלין","b":"היה גם בזולקוא. נכד השר ר שאול וייל. חתן הגביר ר שמואל קלישר. בנו ר שלמה זלמן."},{"i":16879,"n":"וייל, מאיר יעקב מביאליסטוק","b":"ברח מאימת הגיוס לברודי ונעשה חסיד בלז ומהיושבים אצל האדמור. שמו ע\"ש של זוגתו נכדת ר שאול ואהל. אחיו נקרא - פיינסור - כנראה זה שמו."},{"i":16880,"n":"וייל, מאיר יעקב מלעשנוב","b":"רב בלעשנוב. גלה לסיביר במלחמת העולם ה-I."},{"i":16881,"n":"וייל, מאיר יעקב מפשמישל","f":"יצחק מהמבורג","b":"הגיע מפפד\"מ לפשמישל."},{"i":16882,"n":"וייל, מאיר מאולמא","f":"יעקב - שו\"ת מהרי\"ו","b":"אב\"ד אולמא. בנו - ר יעקב מדונא וביירען."},{"i":16883,"n":"וייל, מאיר מברלין וליסא","f":"שמחה","bt":"תקד","bp":"ליסא","dt":"תקפו - ז אדר","b":"תלמיד ר צבי הירש יאנוב מפיורדא. דיין בליסא-תקלא, ר\"מ בביהמ\"ד לרבנים בברלין-תקלז, דיין ואח\"כ ראב\"ד בברלין-תקסט, היה מועמד לרבנות לאסק אך בסוף נבחר ר מאיר צילך. נזכר בשו\"ת החת\"ס."},{"i":16884,"n":"וייל, מאיר מקיל","f":"שמחה","b":"אב\"ד קיל. חברו של ר צבי הירש מברלין, וממנו נודע לר צבי הירש כי בנו שאול הוא המחבר של \"מצפה יקותיאל\" שהוחרם בבית הדין באה\"ו - לאחר שר צבי הירש כמעט החרים את המחבר ולא ידע כי הוא בנו (ר צבי הירש פנה לר מאיר ושאלו מדוע הוא מתנכר לבנו ר שאול - ור מאיר ענה לו \"אהה אדוני והוא שאול\" - ומכאן הבין אביו במה המדובר ואמר \"בני בני מה עכרתני\")."},{"i":16885,"n":"וייל, מאיר מקראקא","dt":"תרפד","b":"רב בקראקא. תשובה אליו \"אמרי דוד\"."},{"i":16886,"n":"וייל, מאיר מרוגוזין","b":"רב ברוגוזין-תר\"כ"},{"i":16887,"n":"וייל, מאניש משטרסבורג","b":"מחכמי שטרסבורג-תקלח, רכש יחד עם אברהם גרינשטין מסכת שבועות מר דוד זינצהיים."},{"i":16888,"n":"וייל, מנחם מפאריס","f":"נתן","bt":"תר","bp":"אינזיסהיים","b":"תלמיד ישיבת קאלמאר, ביהמ\"ד לרבנים בפאריס. רב בוורסיילס-צרפת-תרכד, סגן הרב ר צדוק הכהן בפאריס-תרלה, רב עדת הספרדים בפאריס-תרמא. חיבר \"אחדות תורה שבכתב וע\"פ\" - בצרפתית."},{"i":16889,"n":"וייל, משה אליעזר ממאד","f":"מנחם אליעזר מאושפיצ'","dt":"תקנט - כד אב","b":"רבה הראשון של הדליע-מאד(מאדע)-הונגריה, בנו ר ישראל עוזר על מקומו אחריו. קיבל ברכה להצלחה ברבנות מר לוי יצחק מברדיטשוב. ננזף ע\"י הנו\"א על סידור גט. היה בקשר מכתבים עם ה\"נודע ביהודה\"."},{"i":16890,"n":"וייל, משה הלוי מזמוטשט","f":"שאול הלוי","b":"רב בזאמטשט-תק\"צ"},{"i":16891,"n":"וייל, משה יהודה מצפת","f":"יעקב","b":"מחכמי צפת, בשנת שפא חתם עם חכמי צפת לר ישכר בר איילינבורג."},{"i":16892,"n":"וייל, משה מדזיקוב","b":"מחכמי דזיקוב. פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא."},{"i":16893,"n":"וייל, משה מחעלמא","f":"מאיר וואהל","b":"נכד השר ר שאול וייל. חתן בנימין בייניש ר מענדילש מפוזנא. רב בחעלמא, מאהלוב-ת\"כ."},{"i":16894,"n":"וייל, משה מטימישואר","b":"חתן ר משה דייטש מנייטרא. רב באטיניא-ליד מאקאווע, טימישואר-תרל."},{"i":16895,"n":"וייל, משה מצרפת ואלגיר","b":"רב בתלמסאן-תרלז, ווהראן-תרמג, אלגיר-תרנא - מטעם הקונסיסטואר בצרפת. גילה יחס של כבוד למורשת קהלות המערב והיה מדקדוק במצוות. ביהכ\"נ באלגיר שבו התפלל - נקרא על שמו (עד סגירתו ב-תשכב). חיבר קונטרס בצרפתית על מצבות בית העלמין בתלמסאן."},{"i":16896,"n":"וייל, משה שאול יעקב מלמברג","f":"פנחס","bt":"תקלז","bp":"למברג","dt":"תקפד","b":"מחכמי למברג. חתן ר אברהם צבי ברמן מבוצאץ."},{"i":16897,"n":"וייל, משה שאול מלמברג","f":"שמואל","bt":"תקף","dt":"תרל","b":"חתן הגביר ר סנדר בלוך."},{"i":16898,"n":"וייל, משה שמואל מבאניהאד","b":"דיין בבאניהאד-תקעט-תריט."},{"i":16899,"n":"וייל, נח פויבר משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":16900,"n":"וייל, נפתלי הרץ מפפד\"מ","dt":"תסז - ג אייר","dp":"וינה","b":"פרנס ושתדלן בפפד\"מ, בשליחות בוינה ונפטר בשליחותו."},{"i":16901,"n":"וייל, נתנאל מקרלסרוה","f":"ידידיה?","k":"בעל קרבן נתנאל","bt":"תמז","dt":"תקכט - ל ניסן","dp":"קרלסרוה","b":"תלמיד וחתן ר אברהם ברודא בפרג (ולפי רוזניס תלמיד ר אברהם ברודו בעל \"ברכת אברהם\"). ר\"מ בישיבה בפרג לצד ר יונתן איבשיץ, לאחר גירוש יהודי פרג רב במאהריגנן-מחוז שוורצוולד-תקד, קרלסרוה-תקט.","bk":[["תורת נתנאל",""],["קרבן נתנאל","מפרשי הרא\"ש"],["מנחת נתנאל - מועד ונשים",""],["נתיב חיים - שו\"ע או\"ח",""],["נתיב מים",""],["קרבן נתנאל - על הרא\"ש סדרים מועד ונשים",""],["תורת נתנאל - עה\"ת ושו\"ת",""],["תורת נתנאל [שו\"ת",""],["עה\"ת]",""],["נתיב חיים","מפרשי שו\"ע"],["כללי קרבן נתנאל","כללים"]],"e":"תמ\"ז-תקכ\"ט"},{"i":16902,"n":"וייל, פנחס מלמברג","f":"מאיר מחעלמא","bt":"תק","dt":"תקע","b":"מצאצאי הט\"ז ומחכמי למברג. ונקבר ליד הט\"ז. חתן ר משה הלוי מלמברג."},{"i":16903,"n":"וייל, צבי אריה מנדבורנה","f":"ישראל חריף","bt":"תר","dt":"תרן","b":"רב בנדבורנה-תרך."},{"i":16904,"n":"וייל, צבי הירש מהורדנא","f":"יהודה","bt":"תקמא","dt":"תרכג - כה אדר","dp":"הורדנא","b":"תלמיד ר יוסף הצדיק מפוזנא. דיין בהורדנא. נפטר בגיל 92."},{"i":16905,"n":"וייל, צבי הירש מייטשיס הלוי","f":"נפתלי הירץ מטרנוגרד","b":"חתן ר משה יהושע הורביץ מירוסלב. גיסו של ר אריה ליב הלפרין מבילגוריא. אחיו: ר יצחק הלוי מקאריב חתנו של ר אהרן מירלש בעל \"בית אהרן\". ר שאול מטורבין."},{"i":16906,"n":"וייל, ראובן אליקים מדולינא","f":"שמשון","b":"רב בדולינא. חתנו ר יהודה צבי שטעג מסקוליע רשם את יחוסו. ואת ארבעת אחיו ר צבי הירש קריסנפולי, ר ישראל מברודשין, ר יעקב יוקיל מקיטוב."},{"i":16907,"n":"וייל, שלמה זלמן","f":"ישראל מלובלין","b":"חתנו - ר משה בן הלל בעל \"בית הלל\" - דירנפורט תנא."},{"i":16908,"n":"וייל, שלמה מקושטא","f":"מהר\"י","b":"רב קהלת האשכנזים בקושטא-ש'."},{"i":16909,"n":"וייל, שמואל","f":"יצחק אייזיק","b":"רב-שנת תק\"כ"},{"i":16910,"n":"וייל, שמואל זנויל מראפשויהר","b":"אב\"ד ראפשויהר. חתנו - ר יעקב מוציק משטרסבורג."},{"i":16911,"n":"וייל, שמואל מאוהל(=אליא אויהי)","b":"רב באויהל(=שאטור אליא אויהי=ערלוי)-מחוז זמפלן-תקף."},{"i":16912,"n":"וייל, שמואל מבאניהאד","bt":"תקנה","dt":"תרכז - ל סיון","dp":"באניהאד","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":16913,"n":"וייל, שמואל מלמברג","f":"משה שאול יעקב","bt":"תקס","bp":"למברג","dt":"תרך","b":"חתן הגביר ר אברהם יצחק לבינטל. רב בטיסמניץ."},{"i":16914,"n":"וייל, שמואל מראפלדסוילר","b":"רב בראפאלדסוויילר-תק\"י"},{"i":16915,"n":"וייל, שמעיה מאויבן","b":"רב באויבן-תק\"ך"},{"i":16916,"n":"וייל, שמשון","f":"דוד","b":"שני בשני לשאגת אריה. מנכדי ר ישראל סטרינר. חתן הגביר ר פתחיה. בניו: ר צבי הירש קריסנפולי, ר ישראל מברודשין, ר יעקב יוקיל מקיטוב, ר ראובן אליקים מדולינא."},{"i":16917,"n":"וייל-וולף,ישראל עוזר מאושפיצין","f":"משה וואהל","bp":"אושפיצין","dt":"תקפ - א שבט","b":"רב בטרצול(=טערצאל)-הונגריה, מאדע(=מאד)-תקסט על מקום אביו."},{"i":16918,"n":"וייל-סטרינר, ישראל","b":"נכד שאול ואהל מהיתום והיתומה (בן בנו של השר שנישא אחר פטירת אביו לבת בנו של התוי\"ט שהיתה יתומה). חתן נכדת הט\"ז והב\"ח."},{"i":16919,"n":"וייל-קצנלנבוגן, יהודה מבריסק","f":"מאיר מבריסק","b":"נכד-אבי אמו הקדוש ר פנחס הלוי איש הורביץ מקראקא. חתן גיסו - ר אפרים זלמן שור בעל \"תבואות שור\". מגדולי התורה בבריסק-תי. חתניו - ר נחום מסלוצק, ר משה כץ מלויצק, ר יונה תאומים בעל קיקיון דיונה."},{"i":16920,"n":"וייל-קצנלנבוגן, יצחק חריף מלוד","f":"השר שאול","b":"רב בקונסטנטין, פוזנא-שפ, לודמיר-ת. נזכר בהקדמה ללשון למודים שסייע למחבר בהדפסת ספרו."},{"i":16921,"n":"וייל-קצנלנבוגן, מאיר מבריסק","f":"השר שאול","dt":"שצא","b":"חתן ר פנחס הורביץ בעל \"בית פנחס\"-גיסו של הרמ\"א, ובזיוו\"ש חתן ר נחום מלודמיר. רב בטיקטין, בריסק, ראש מדינה, יסד-שפג את ועד מדינת ליטא. בניו: ר יהודה, ר משה מחעלמא, ר בייניש, ר ישראל מנעשווי ולובלין. חתניו - ר יונה פרנקל-תאומים בעל \"קיקיון דיונה\", ר מרדכי בן אברהם שרנצל."},{"i":16922,"n":"וייל-קצנלנבוגן, שאול","f":"שמואל יהודה קצנלנבוג","k":"השר שאול","bt":"ש","dt":"שעו","b":"חתן הגביר ר דוד דרוקער מבריסק. מלך פולין ליום אחד וביטל הגזירות נגד היהודים, בעל חסד, עניו, ישב בבריסק. חתניו - ר אפרים זלמן שור מבריסק ולובלין, ר בינוש ליפשיץ, ר משה הכהן, ר יוסף קאזי, ר צבי הירש מפוזנא. בניו - ר אברהם מורניק, ולבוב, ר מאיר, ר יצחק, ר יעקב, ר שמואל יהודה."},{"i":16923,"n":"ויין, אהרן מחודרוב","f":"דב בריש","bt":"תרסג","bp":"למברג","dt":"תרצח","b":"מגיד שיעור בישיבת בלז בלמברג. חתן הרב של חודרוב. רבה של חודרוב על מקום חותנו."},{"i":16924,"n":"ויין, אליהו שמואל מבוברקא","f":"אליעזר","bt":"תרכט","bp":"ראזלא","dt":"תרצו","dp":"ירושלים","b":"חסיד סטרטין. חתן ר מאיר הכהן וינד. רב בנריוב, שאץ, בוברקא-תרסו. עלה לירושלים-תרפד."},{"i":16925,"n":"ויין, דב מרוצקי","f":"מרדכי מקיבארטי","dt":"תרצא - יז אלול","b":"מחכמי רוצקי, ר\"מ ומחנך. בנו - ר זאב חיים מארה\"ב."},{"i":16926,"n":"ויין, דוד מחולון","dt":"תשכח","b":"רב בחולון-תרצ\"ז"},{"i":16927,"n":"ויין, זאב חיים מארה\"ב","f":"דב בן מרדכי","bt":"תרסה","bp":"רוצקי-פלך סובלק","b":"תלמיד ישיבות סלובודקא, גרודנא, ישיבת מרכז הרב בירושלים. נסמך מאת: ר איסר זלמן מלצר, ראי\"ה קוק, ר שמעון שקופ, ר אבא יעקב בורוכוב מולקוביסק. חתן ר חיים צבי רובינשטין. ר\"מ בישיבת רבי יצחק אלחנן בניו יורק, רב קהלת אנשי אודסה בשיקגו, בית המדרש בני יעקב בשיקגו. חבר תנועת המזרחי, פעיל צבור."},{"i":16928,"n":"ויין, מרדכי מקיבארטי","b":"אב\"ד קיבארטי. בנו - ר ראובן ונכדו ר זאב חיים מארה\"ב."},{"i":16929,"n":"ויינאכט, חיים ישראל יצחק מפיעט","dt":"תש..","b":"רב בפיעטרקוב. עורך \"כרם בית שמואל\" - פיעטרקוב תרצא (שמו הקודם \"בית ישראל\", \"בית שמואל\", \"כרם בית שמואל\") - מאת תלמידי ישיבת \"בית ישראל\" באלכסנדר, \"כרמנו\" - אלכסנדר-לודז-פיעטרקוב תרצג (המשך \"כרם בית שמואל\")."},{"i":16930,"n":"ויינגרד, יואל מבריסק","f":"משה מבריסק","b":"מכתב ממנו-תקפח לר שלמה זלמן מרגליות."},{"i":16931,"n":"ויינהויז, אשר אנשיל","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":16932,"n":"ויינפריד, משה מפרוסטיץ","dt":"תרה - תרטו","b":"ר\"מ בפרוסטיץ. אחיינו - ר מנחם כץ פרוסטיץ מצעהלים."},{"i":16933,"n":"וייס מיקשה, מאיר צבי מבודפשט","k":"בעל קטלוג ספריית קאו","bt":"1872","dt":"1931","b":"רב ניאולוגי בבודפשט ומלמד בביהמ\"ד לרבנים בבודפשט, ומורה לדת בבתי ספר. הסטוריון. חיבר ספר על \"מחזור ויטרי\"-1894, קטלוג ספריית קאופמן - שברשות האקדמיה למדעים בבודפשט - 1906, ופרסם קטעי גניזה - מקהיר שהיו באוסף קאופמן. ?? לא באוצר ??"},{"i":16934,"n":"וייס, אברהם אלעזר מטאפאלטשן","f":"נתן ברוך מהעלמעץ","bp":"קיראל-העלמעץ","dt":"תשד - ב אב","dp":"אושוויץ","b":"תלמיד השב\"ס, ור יעקב יוסף גינז מביסרמן. חתן ר אשר פאלק לייטנר. רב בקאסטל-תרנט, יאנוש-האזא-תרסד על מקום ר יוסף גרינוולד והרב רובינשטין על מקומו אחריו, טאפלטשן-תרפב. נספה בשואה. חתנו ר אהרן מגיד מטעטש - ניו יורק בעל \"בית אהרן\"."},{"i":16935,"n":"וייס, אברהם מארה\"ב","f":"יהודה","b":"רב בניו יורק. הסכים על \"תולדות יצחק\" ניו יורק תרפה."},{"i":16936,"n":"וייס, אברהם צבי מסטמר ובני ברק","f":"מנחם ממונקטש","bp":"מונקטש","dt":"תשלט - ג סיון","dp":"פתח תקוה","b":"נכד ר שמואל צבי וייס בעל \"אמרי יוסף\". חתן ר ישעיה קלינמן מסאטמר, רב בסאטמר-תרצח. ניצל מהשואה ואחריה עלה לארץ וכיהן כרב בבני ברק"},{"i":16937,"n":"וייס, אהרן מדיווין","f":"שלמה יהודה ויס","bt":"תרנג","dt":"תשב","b":"רב בדיווין"},{"i":16938,"n":"וייס, אהרן ממאקובא","f":"כתריאל שלום","k":"בעל איגרת בר יוחאי","dt":"תשד","b":"ר\"מ במאקעווע(=מאקובה). חיבר גם \"רכוש הים\", ועוד."},{"i":16939,"n":"וייס, אהרן משוראן","b":"חתן ר ישראל איסרל מאייר מפרשבורג. בנו - ר משה הלוי מפרשבורג, נכדו - ר שמואל פרידנטל מגאיטיין."},{"i":16940,"n":"וייס, אלחנן ממאלצקה","f":"יעקב אליעזר ויס","dt":"תרעד - יט אדר","b":"רב במאלצקה"},{"i":16941,"n":"וייס, אליהו מנימרקט","bt":"תרם","dt":"תשב","b":"חתן ר דוב בריש שטרוק מניימרקט. רבה של ניימרקט על מקום חותנו. נספה בשואה."},{"i":16942,"n":"וייס, אלימלך מסקניצה","dt":"תשג","b":"רב בסקניצה"},{"i":16943,"n":"וייס, אליקים","b":"חתן ר יוסף ליכטיג מדומברובא. גיסו של הכת\"ס (נשואים לשתי אחיות)."},{"i":16944,"n":"וייס, אלכסנדר משה מניגרשד ונ\"י","f":"מאיר ממאדיאר-לאפוש","k":"בעל שו\"ת הרא\"ם-תשכד","bt":"תרמב","bp":"מאדיאר-לאפוש","dt":"תשיג - יג ניסן","dp":"ניו יורק","b":"תלמיד השב\"ס, ור יחזקאל בנט מסינער-ואראלי, ור מנחם מנדל שטרן מפלידעש, ור יהודה גרינוולד בסטמר. חתן דודו הגביר ר אברהם אלתר פרנקל מניגרעשט ועבר לשם-תרסה. רב בניו יורק-תרפט."},{"i":16945,"n":"וייס, אלכסנדר סנדר מספינקא","f":"ישראל דב","k":"בעל פאר יוסף","bp":"כפר קרעצקי","b":"הגיע מקרעצקי. חסיד ספינקא. נתחנך בביתו של בעל \"אמרי יוסף\" בספינקא ולמד עם בנו ר יצחק איזיק לימים האדמור מספינקא. חתן ר מאיר צבי סגל ממידאן. נספה בשואה. חיבר ספר תולדות האדמור מספינקא \"פאר יוסף\"."},{"i":16946,"n":"וייס, אריה הכהן מטשרנוביץ","b":"פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז."},{"i":16947,"n":"וייס, אשר אנשיל מנאדי-פאלו","f":"משה שלמה מרקוביץ","k":"בעל שמן למנחה-תשכט","r":"אב\"ד נאידפולו והגליל","bt":"תרמב","bp":"כפר רקוביץ-ליד סעליש","dt":"תשד - יא סיון","dp":"אושוויץ","b":"תלמיד השב\"ס, ור משה גרינולד מחוסט, ור שלמה צבי שטרסר מטירנא וגיסו ר שמואל זלמן וינברגר ממארגרטן. חתן ר יעקב שיק מנאדאודוואר. מלמד באוהל-תרסב, סעפעש-תרסט, האוועשור-תרעב. בזיוו\"ש חתן ר צבי הרש שוורץ מבאלאש-ירמוט - אלמנת ר מנחם צבי רוזנברג מנאדי-פאלו (שהניח 10 יתומים - 5 גם מאם מזיווגו הראשון), וכיהן כרב בנאדי-פאלו על מקומו אחריו. נספה בשואה. אחיו ר ישראל היה ראש הקהל בקלויזנבורג.","bk":[["שמן למנחה - ש\"ס ועל התורה",""]]},{"i":16948,"n":"וייס, בן ציון מרסוויגוב","f":"אהרן מבנדקוביץ","dt":"תשד","b":"נכד ר צבי הירש ממונקאטש. חתן ר יעקב מאיר הכהן פריד מקאפיש. רב ברסוויגוב(=רעסוויגעף). פרסם מאמרים ב\"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":16949,"n":"וייס, ברוך מדולינא","b":"תלמיד ישיבת חכמי לובלין. חתן הרב מוונווליץ-לובלין (שבה קראו את המגילה יומים בגלל נס שנעשה שם). רב בדולינא לצד חותנו. נספה בשואה."},{"i":16950,"n":"וייס, גבריאל","b":"תלמיד הכת\"ס, והעלה על הכתב מתורת רבו, ונדפס בספר \"תורת אבות\" ניו יורק תשן."},{"i":16951,"n":"וייס, דב ברל מסמבור","dt":"תש..","b":"חסיד בלז. מנהל החשבונות באחוזת רטשיץ של ר שמלקא רוקח. לימד בבלז את ר שמואל חתן האדמור. עבר ללמברג. נספה בשואה."},{"i":16952,"n":"וייס, דוד אלימלך מוישק","b":"רב בוישק. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד. הו\"ל ספר זקנו ר אברהם ממונקטש - \"ברכת אברהם\"- סיגט תרסג."},{"i":16953,"n":"וייס, דוד מווישיווה","f":"איזיק עביר מטעטש","b":"רב ודיין באויבר-ווישווה-תרף. נספה בשואה."},{"i":16954,"n":"וייס, דוד מויטקוב","b":"תלמיד הרב מטשבין. רב במוסט, ויטקוב. נספה בשואה."},{"i":16955,"n":"וייס, דוד מילניצה","f":"מאיר","b":"רב בילניצה."},{"i":16956,"n":"וייס, דוד מקורימא","dt":"תשד","b":"רב בקורימא"},{"i":16957,"n":"וייס, דוד צבי מויסוצק","b":"רב בויסוצק (גליל טורקא)."},{"i":16958,"n":"וייס, הלל הלוי מוינר-ניישטט","f":"משה מפרשבורג","bt":"תרנד","dt":"תשטו","b":"תלמיד הדעת סופר. חתן הרב פרופ' דוד כהן-מקורב למלך פרנץ יוזף,. רב בסעמערין(=סאמורין), וינר-ניישטט-תרפה, עב לאמריקה וכיהן כרב בניו יורק-תרצט ומנהל ישיבת רבנו יעקב יוסף. כיהן כרב צבאי בצבא האוסטרי בזמן מלחה\"ע ה-I, וסייע בארגון ההגנה בפרשבורג - בזמן הפרעות בסיומה."},{"i":16959,"n":"וייס, זאב וולף מלייטשוי","b":"רב בקעזמארק, לייטשוי, ועבר לארה\"ב. בנו ר משה מקאסטלן."},{"i":16960,"n":"וייס, חזקיה יעקב פיבל מאיפלשאג","f":"משה מפרשבורג","dt":"תשד - כב סיון","b":"תלמיד הדעת סופר, ור שמעון הירשלר ממאדערן - פרשבורג. חתן ר יוסף צבי סופר משאמשן. רב באיפאלשאג-תרצב. נספה בשואה. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":16961,"n":"וייס, חיים אהרן מהידאלמאש","f":"אשר אנשיל מנאג'פאלו","bt":"תרעד","bp":"נאג'אפאלו","dt":"תשה - כז אב","dp":"רומניה - ירושלים","b":"תלמיד ר שאול בראך, ור שמואל אנגל בקאשוי. חתן ר יחיאל מאיר פאנט מהידאלמאש, ועבר לשם. רבה האחרון של הידאלמאש על מקום חותנו-תשד. נספה בשואה."},{"i":16962,"n":"וייס, חיים יהודה ליב מהמבורג","bt":"תרג","bp":"דעטרעקע סט מיקלוץ","dt":"תרסד - כז אלול","dp":"אוהלסדורף-המבורג","b":"תלמיד הכת\"ס, ור בנימין זאב וולף פוקס מסערעד. חתן ר מנחם דייטש מוערבויץ. מחכמי טורנא-תרלב, ר\"מ בהמבורג - בביהמ\"ד של ר יחיאל וואלאך(=ואליך), רב ח\"ק באהלסדורף-המבורג."},{"i":16963,"n":"וייס, חיים יהודה מריטשע","f":"משלם מהאדאד","bp":"האדאד","dp":"ניו יורק","b":"תלמיד השב\"ס, ור משה גרינולד מחוסט. נסמך מרבותיו ומאת: ר יהודה גרינוולד מסטמר, ר שלמה סופר מברגסאס. חתן הגביר ר נתן קרפל וינשטוק משאראש-פאטאק. רב בטשעפע, ריטשע, קהלת \"אהבת שלום\" בקליבלנד אוהיו. חיבר \"מבחר הפנינים\", \"מליצי חכמים הקדמונים\", ועוד - בכת\"י."},{"i":16964,"n":"וייס, חיים יעקב פיבל","f":"מאיר מטעטש","dt":"תשג","b":"דיין בטעטש על מקום אביו."},{"i":16965,"n":"וייס, חיים משאמשון ונאדוש","b":"רב בשאמשון-תרל\"ו,נאדוש-תר\"מ"},{"i":16966,"n":"וייס, חיים פנחס מנאדוש","dt":"תרלט","b":"רב בנאדוש-תרל\"ה"},{"i":16967,"n":"וייס, חיים צבי הכהן מיאנוב","dt":"תרנד - לפני","b":"רבה של יאנוב. בניו: ר יוסף יצחק על מקומו אחריו, ר בנימין אריה מטשרנוביץ."},{"i":16968,"n":"וייס, יהודה","f":"צבי הירש וויס","b":"דומ\"צ בסובראנץ-תר\"ע,אונגוואר"},{"i":16969,"n":"וייס, יהודה אריה ליב מסעליש","f":"שמעון עוזר מפעהר","bt":"תרח","bp":"פעהער-יארמוט","dt":"תרעב - יד אלול","dp":"סעליש","b":"תלמיד הכת\"ס. חתן נכדת השתדלן ר יוסף גרינבוים 'הגיבור' מטעגלאש. שו\"ב בסעליש-תרלט."},{"i":16970,"n":"וייס, יהודה ליב (יאצוויץ)","f":"משה יאצוויץ","dt":"תרכב - אחרי","b":"תלמיד החת\"ס, ור מרדכי בנט, ור ברוך פרנקל-תאומים מלייפניק. חתן ר שבתי טרנטשין מנייטרא. רב בנייטרא."},{"i":16971,"n":"וייס, יהודה מהרמאנשטדט","dt":"תרנג - בערך","b":"תלמיד ר אברהם קרפלס מגירבא. חתן ר משה יהודה פולק מבערעט אויפאלו. דיין בהרמאנשדטדט, והיה שם מחלוקת בינו לראשי הקהל, וכשמונה ר צבי הורביץ לרב התפלגה הקהלה ור יהודה פרש עם גיסו ר אברהם פולק והקימו קהילה חרדית נפרדת."},{"i":16972,"n":"וייס, יהודה משה הכהן","b":"תשובה אליו ב\"דבר משה\"."},{"i":16973,"n":"וייס, יהושע","b":"תלמיד ישיבת אויהל. פרסם מאמרים ב\"הפלפול\" - שאפראן תרצח."},{"i":16974,"n":"וייס, יהושע השל הכהן מנאדימעדי","bt":"תריד","dt":"תרפה","b":"תלמיד מהר\"ם שיק. חתן ר יוסף לוק ממעדיער. רב וראש ישיבה בנאדי-מעדיער על מקום חותנו, וחתנו ר שמעון שאטין על מקומו אחריו."},{"i":16975,"n":"וייס, יהושע מהוניאד","f":"חיים מצעהלים","k":"בעל כתר תורה-תשג","bt":"תרס","bp":"קלויזנבורג","b":"תלמיד ר אליעזר דוד גרינוולד בישיבת צעלהים ובישיבת ווישווה. מחכמי הוניאד. נספה בשואה - בשנת תשג גויס לגדוד עבודה בצבא ההונגרי ונשלח אל מותו באוקראינה."},{"i":16976,"n":"וייס, יוחנן מאיפאלישאג","b":"רב באיפאלישאג-תרמ\"ב"},{"i":16977,"n":"וייס, יונה יהודה","b":"אחיינו של ה\"מאור ושמש\". חתן ר שלמה פישר מיורדנוב והתגורר אצלו."},{"i":16978,"n":"וייס, יוסף חיים הכהן מסטמר","b":"עורך \"מגד ירחים\" - סטמר תרפה."},{"i":16979,"n":"וייס, יוסף יצחק מיאנוב","f":"אברהם אבלי מרדזין","b":"חתן ר נחום צבי מגריידינג ועבר לשם. רב בדוברוטבור (ליד קמינקא), זבירטוב, רבה של יאנוב-תרלו על מקום אביו. הדפיס ספר אביו \"זכרון ארהם\" למברג תרך - עם הוספות משלו."},{"i":16980,"n":"וייס, יוסף מאיר מספינקא","f":"שמואל צבי ממונקטש","k":"אדמור מספינקא-אמרי י","r":"רב ואדמו\"ר בספינקא","bt":"תקצח","bp":"מונקטש","dt":"תרסט - ו אייר","dp":"ספינקא - פתח תקוה","b":"תלמיד מהר\"ם א\"ש מאונגוואר ובנו ר מנחם א\"ש. מייסד שושלת ספינקא. מקורב לשר שלום מבלז, ר מנחם מנדל מויזניץ, ר יצחק איזיק מזידיטשוב - חיבר הקדמה לספרו \"לקוטי תורה\", והדברי חיים מצאנז. תלמיד ר מאיר א\"ש, ר מנחם א\"ש ור שמעלקא מסעליש. חסיד האדמור ר יצחק איזיק מידיטשוב שהסמיכו לאדמור-תרך. ניהל ישיבה בבורשה-תריד, בזיוו\"ש חתן ר ערא יעקב באש מספינקא ועבר לשם. כיהן כאדמור מספינקא-תרלו. חיבר \"אמרי יוסף\", ועוד. עליו ב\"פאר יוסף\", \"בית ספינקא\" ירושלים תשיט, ועוד. החסידות היתה מיזוג של זידיטשוב, צאנז, ובלז והאדמור אמר: \"בלז היא עמוד התורה, זידיטשוב עמוד העבודה וצאנז עמוד החסד\" - וחסידים מחסידיות אלו עברו לספינקא.","bk":[["אמרי יוסף – תורה ומועדים",""],["קונטרוס ברכות והודאות",""]]},{"i":16981,"n":"וייס, יוסף מזבורוב","f":"משה ויס","dt":"טו חשון","b":"רב בזאבארוב-תרע\"ז"},{"i":16982,"n":"וייס, יוסף מטרעבושן","b":"פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי."},{"i":16983,"n":"וייס, יוסף מטשיסנא","f":"משה","bt":"תרלז","dt":"תרצא","b":"חתן ר משה יהושע שטרנהל מקולומיאה ובזיוו\"ש חתן ר יעקב זיכרמן מזבורוב. רב בזבורוב-הונגריה על מקום אביו, טשיסנא (ליד לובלין) (והיה שם מחלוקת עם השגת גבול ברבנות - קמחז\"ה-תרסח). חתן"},{"i":16984,"n":"וייס, יוסף מקאסאן","b":"דומ\"צ בקאסאן-תר\"ס"},{"i":16985,"n":"וייס, יוסף צבי מערלוי","dt":"תרם - ב תשרי","b":"רבה הראשון של ערלוי(=אויהל)-תר. לחם בריפורמים. בזמן המרד ההונגרי-1848 פעל לטובת המורד קושוט לאיוש - כנגד השלטון האוסטרי, ולאחר דיכוי המרד הסתתר בעזרת ההגמון, נאסר ושוחרר. נכדו - ר סטפן וייז - מנהיג יהדות אמריקה ורב ריפורמי."},{"i":16986,"n":"וייס, יחזקאל פיבל מיערגן","dt":"תשד","b":"רב ביערגן"},{"i":16987,"n":"וייס, יעקב אליעזר מאגראם","f":"שלום ממיסלא","bt":"תריב-ד","bp":"מיסלא","dt":"תרעד - יט אדר","dp":"באניהאד","b":"תלמיד הכת\"ס, ור חזקיה פיבל פלויט משוראן. חתן ר מרדכי יפה-מרגליות מבודפשט. רב בבודפשט, פאקש, העדיעס, סענטגרוד, טיניא, אגראם-תרמח. הו\"ל ספר זקנו \"שושן עדות\" ו\"לבנימין אמר\"."},{"i":16988,"n":"וייס, יעקב בן ציון מזידיטשוב","b":"מקובל מזידיטשוב. קרובם של האחים מסוואליעווע ומונקטש. תלמיד העטרת צבי. חתן הגביר ר אברהם עביר רוזנברג."},{"i":16989,"n":"וייס, יעקב יוסף מספינקא ארה\"ב","f":"ישראל חיים מספינקא","k":"אדמור מספינקא ארה\"ב","bt":"תרעו","dt":"תשמח - יט ניסן","b":"חתן ר אלתר מנחם מנדל מבורשא (שושלת קוסוב), ובזיוו\"ש חתן דודו ר אברהם אביש מקראלי (שושלת רופשיץ). ניצל מהשואה ואחריה כיהן כאדמור מספינקא בארה\"ב וארץ ישראל, והקים ישיבה ומוסדות שם.","bk":[["שיח יעקב יוסף - דרשות",""]]},{"i":16990,"n":"וייס, יעקב מוינה","k":"בעל אוצר שירי ישורון","b":"חזן ראשי בוינה-תרם."},{"i":16991,"n":"וייס, יעקב מיאנאשי","b":"תלמידו ומחותנו של ר אשר אנשל יונגרייז בעל מנחת אשר."},{"i":16992,"n":"וייס, יעקב מקורימא","f":"משה מזבארוב","bt":"תרם","dt":"תרצו - יז שבט","b":"רב בקורימא-תרסו."},{"i":16993,"n":"וייס, יעקב משנדישוב","b":"רב בשנדישוב-תרס."},{"i":16994,"n":"וייס, יעקב פיבל","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":16995,"n":"וייס, יצחק איזיק מוינה","f":"מאיר","k":"בעל דור דור ודורשיו","bt":"1815","bp":"מזריטש","b":"ר\"מ במזריטש-תר. עבר לוינה והיה מגיה בדפוס. ר\"מ בביהמ\"ד לרבנים בוינה אצל הד\"ר ילינק. הו\"ל \"בית המדרש\", \"בית תלמוד\". חיבר גם \"ארח לצדיק\", \"נצח ישראל\", ספר זכרונות. חיבר מאמרים ב\"כוכבי יצחק\", \"ישורון\", \"האסיף\"."},{"i":16996,"n":"וייס, יצחק איזיק מסוואלייוע","f":"אברהם","k":"בעל בית יצחק","r":"רב בסוואליווא, ואחר כך ראב\"ד מונקטש","bt":"תקפד","bp":"מונקאטש","dt":"תרנב-ד -כב אד\"ב","b":"תלמיד ר יצחק איזיק מזידיטשוב, והדברי חיים מצאנז. רב בסוואלייווע-תריט, ראב\"ד במונקאטש-תרלז. חיבר גם \"דברי יצחק\", \"תולדות יצחק\". בנו - ר קלונימוס קלמן מקאפוש, חתנו - ר אלימלך לוי פייש מטהאש. מתלמידיו - אחיינו בעל \"דברי אמת\" מספינקא.","bk":[["בית יצחק [עמ\"ס מגילה]",""],["בית יצחק - מגילה",""],["דברי יצחק - דרשות וליקוטים",""],["תולדות יצחק - עה\"ת -",""]]},{"i":16997,"n":"וייס, יצחק איזיק מספינקא","f":"יוסף מאיר מספינקא","k":"אדמור מספינקא-חקל יצ","r":"אדמו\"ר מספינקא","bt":"תרלה","bp":"ספינקא","dt":"תשד - יג סיון","b":"חתן ר ישכר בעריש איכנשטין האדמור מוערקי בעל \"מלבוש לשבת\". אדמור בספינקא על מקום אביו. אחרי מלחמת העולם ה-I עבר למונקטש והקים בה ישיבת \"בית יוסף\", סעליש והחזיק בה ישיבה. נספה בשואה. חיבר \"חקל יצחק\", ועוד. עליו ב\"חסידות ספינקא ואדמוריה\" ירושלים תשיח, ועוד. בין מקבלי ברכתו - מלך אנגליה.","bk":[["חקל יצחק",""]]},{"i":16998,"n":"וייס, יצחק יעקב מדולינא וירושל","f":"יוסף יהודה ממונקטש","k":"בעל מנחת יצחק","bt":"תרסב-ה","bp":"דולינא","dt":"תשמט","b":"תלמיד ר חיים אלעזר שפירא ממונקטש. חתן ר פנחס סגל צימטבוים מגרוסורדין, ובזיוו\"ש חתן ר חיים דב (דוד) הלפרין האדמור מווסלוי, ובזיווג שלישי חתן ר חיים מאיר הגר האדמור מויזניץ. רב במונקטש, רב בגרוסורדין-תרפט יחד עם חותנו. ניצל מהשואה ואחריה חזר לכהן כרב בגרוסורדין, עסק בהתרת עגונות יחד עם ר דוד שפרבר מברשוב. ראב\"ד מנצסטר-תשח. ראב\"ד העדה החרדית בירושלים-תשל. חיבר \"מנחת יצחק\" לונדון תשטו. לזכרו \"כבה נר המערבי\" ירושלים תשן, ועוד. פרסם מאמרים ב\"לקט ששנ\"ה\" - סטמר תרצד.","bk":[["מנחת יצחק","שו\"ת - אחרונים"],["דברי יצחק",""],["מנחת יצחק – שו\"ת ועל התורה",""],["מנחת יצחק (שו\"ת)",""]],"e":"תרס\"ב-תשמ\"ט"},{"i":16999,"n":"וייס, יצחק מאיקריטא","f":"שמעון עוזר","k":"בעל תולדות יצחק","dt":"תרנב - בערך","b":"תלמיד הכת\"ס. חתן ר אברהם מאיקריטא. רב באיקריטא. ?? לא באוצר ??"},{"i":17000,"n":"וייס, יצחק מגורליץ","b":"חתנו - הכת\"ס, בנו - ר אליקים וייס."},{"i":17001,"n":"וייס, יצחק מנאדי-אידא(=נאדיאש)","b":"תלמיד ר יהודה ליב יולס משעבעש ורשם מחדושי רבו - לפני תרסה."},{"i":17002,"n":"וייס, יצחק מניו יורק","b":"רב קהילת מחז\"ה-זלוטשוב בניו יורק. תשובה אליו - \"אבני זכרון\"-תרעו."},{"i":17003,"n":"וייס, יצחק מפרשבורג וערבא","f":"ישעיה ישכר בער מפרשב","k":"בעל שיח יצחק","bt":"תרלג","bp":"פרשבורג","dt":"תשב-ד - כו תמוז","dp":"לובלין","b":"בן אחות ר יעקב פרגר מאדא. תלמיד השב\"ס. חתן ר אפרים פישל סופר מברעזביץ. רב בפרשבורג-תרנג, קדלבורג(=קרלסבורג)-תרסו, וערבא(=וורבוי)-תרעו. נספה בשואה. חיבר \"בינה לעתים\", \"אבני בית היוצר\" - על חכמי פרשבורג, ועוד. פרסם מאמרים ב\"דבר בעתו\" - פאקש תרסט, \"המעין\" - פרשבורג תרצד, \"הנשר\" - טירנוי תרצג-תשד. אחיו - ר שבתי משימאני."},{"i":17004,"n":"וייס, יצחק מקרלסבורג","b":"פרסם מאמרים ב\"דבר בעתו\" - פאקש תרסט."},{"i":17005,"n":"וייס, יצחק משאלא","b":"חתן ר יעקב מאיר צבי משוראן. בנו - ר יקותיאל מטיסא-פירעד."},{"i":17006,"n":"וייס, יקותיאל מטיסא-פירעד","f":"יצחק משאלא","k":"בעל אור הבקר","bt":"תרכא","bp":"שאלא","dt":"תשא - ו סיון","dp":"טיסא-פירעד","b":"נכד(-אבי אמו) ר יעקב מאיר צבי פרידלנדר משוראן). תלמיד השב\"ס. חתן ר חיים יעקב בלוי מטיסא-פירעד, ועבר לשם ולימד תורה כ-40 שנה. מאמר ממנו ב\"המעין\" - בודפשט תשז (לאחר השואה!). לתולדות חייו מאת בנו בשם \"חיי יהודי שלם\" בתוך ספרו \"דבש וחלב\"."},{"i":17007,"n":"וייס, ישעיה ישכר בער מפרשבורג","b":"מחכמי פרשבורג. חתן ר מרדכי הלוי פרגר מפרשבורג. בניו - ר שבתי שעפטל משימאני, ור משה מפרשבורג, ור יצחק מוערבא."},{"i":17008,"n":"וייס, ישעיה ממונקטש","f":"איזיק עביר מטעטש","bt":"תרכד","bp":"טעטש","b":"מחכמי סיגט, ומלמד, ורב ביהכ\"נ של משפחת כהנא, ונחשב לאחד מגדולי הרבנים בעירו. נספה בשואה."},{"i":17009,"n":"וייס, ישראל אלתר מבאקאני","k":"בעל פאר משולם","b":"שו\"ב בבאקאני."},{"i":17010,"n":"וייס, ישראל חיים מספינקא","f":"יצחק איזיק מספיקנא","dt":"תשד - כט אייר","b":"רב בספינקא. חתן ר אלעזר רובין מגליגוב, ובזיוו\"ש חתן דודו ר אברהם יקיר רובינשטין. בנו ר יעקב יוסף - אדמור מספינקא בארץ ישראל וארה\"ב. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":17011,"n":"וייס, ישראל חיים מספינקא ב\"ב","f":"יעקב יוסף מספינקא","k":"אדמור מספינקא ב\"ב","b":"חתן ר ירחמיאל צבי יהודה בן ר יחיאל יהושע מביאלא. אדמור מספינקא בבני ברק על מקום אביו."},{"i":17012,"n":"וייס, ישראל מטשיטש","dt":"תשד","b":"רב בטשיטש"},{"i":17013,"n":"וייס, מאיר אלעזר מספינקא ארה\"ב","f":"יעקב יוסף מספינקא","k":"אדמור מספינקא ארה\"ב","bt":"תשיח","b":"חתן ר מרדכי דוד מסאסרגין (שושלת רופשיץ). אדמור מספינקא בארה\"ב."},{"i":17014,"n":"וייס, מאיר מדברצין","b":"רב הקהלה הניאולוגית בדברצין-לאחר מלחה\"ע ה-I, הוד-מאזו ואשארהאי-1933. עלה לארץ וכיהן כמרצה באוניברסיטה העברית בירושלים."},{"i":17015,"n":"וייס, מאיר מטעטש","b":"דיין בטעטש, ובנו ר חיים וייס על מקומו אחריו."},{"i":17016,"n":"וייס, מאיר ממילניצה","f":"משה","b":"חתן רי\"ד באב\"ד מבוסק. רב במילניצה, בנו ר צבי אלעזר על מקומו אחריו."},{"i":17017,"n":"וייס, מאיר מפעקעטע ולאפוש","f":"נפתלי מגירבעט","k":"בעל תורתו של ר מאיר","bt":"תרב","bp":"גירבעט-מעדיאש","dt":"תרעד - י אדר","b":"תלמיד הכת\"ס, ר יהודה אסאד, ר מאיר פרלס בקרולה ור אהרן דוד דייטש. חתן ר אהרן מרגליות-פרקש מניגרעשט. שו\"ב ודיין במאדיאר-לאפוש, רב בפעקעטא-ארדויא-תרנג. בנו ר חיים בעל אוצר החיים. בנו ר אלכסנדר משה בעל שו\"ת רא\"ם, ובסוף ספר בנו נדפס ספרו \"תורתו של ר מאיר\" ירושלים תשכד."},{"i":17018,"n":"וייס, מנחם ממונקטש","f":"משה מלאפיש וזבורוב","dt":"תשד","b":"מצאצאי ר מאיר א\"ש מאונגוואר. דומ\"צ במונקאטש. מכתב ממנו ובהם על משפחתו לר יו\"ט ליפא ברוין. בנו - ר אברהם צבי מסאטמאר."},{"i":17019,"n":"וייס, מנחם מנדל מפיעטרקוב","b":"דומ\"צ בפיעטרקוב-תרצה."},{"i":17020,"n":"וייס, מרדכי מביסטריץ","b":"רב בביסטריץ-תר\"כ"},{"i":17021,"n":"וייס, מרדכי משימאני","f":"שבתי שעפטל משימאני","dt":"תשד","b":"רב בשימאני על מקום אביו."},{"i":17022,"n":"וייס, משה הלוי מפרשבורג - ב","f":"אהרן משוראן","b":"חתן ר ישראל איסרל מאייר מפרשבורג. מחכמי פרשבורג."},{"i":17023,"n":"וייס, משה חיים מקלינורדין","dt":"תרפב - כו אדר","b":"גביר,החזיק ישיבה בארמונו בקליינוורדיין","bk":[["ברית משה [על הסמ\"ג]",""],["ברית משה",""]]},{"i":17024,"n":"וייס, משה יעקב מבני ברק","b":"רב נוה אחיעזר-בני ברק-תשן."},{"i":17025,"n":"וייס, משה יעקב מפרשבורג","f":"שמואל מפרשבורג","k":"בעל מי זהב","bt":"תרסז","bp":"פרשבורג","dt":"תשמב - ט כסלו","dp":"פתח תקוה","b":"תלמיד הדעת סופר. תלמיד ישיבת השב\"ס בפרשבורג, מחברי אגודת \"אהבת ציון\" בפרשבורג ונואם באגודה. חתן ר שמעון הירשלר ממאדערן ופרשבורג. ראש הקהלה בפרשבורג, גם בזמן השואה ואחריה, עלה לארץ-תשי והתישב בפתח תקוה עם אביו וכיהן כרב."},{"i":17026,"n":"וייס, משה מגרודק","b":"דיין ומגיד בגרודק-תר\"נ"},{"i":17027,"n":"וייס, משה מגרידינג","f":"אברהם יעקב","bt":"תר","dt":"תרעה","b":"חתן ר משה הלוי קורפ. רב בגרידינג. בנו ר שמואל צבי על מקומו אחריו."},{"i":17028,"n":"וייס, משה מוונגרוב","b":"רב בוונגרוב-תר\"ל"},{"i":17029,"n":"וייס, משה מיבלניץ","b":"רב ביאבלניץ-קוסטלאן-תרנ\"ה"},{"i":17030,"n":"וייס, משה מלאפוש וזבורוב","f":"צבי הירש מלאפוש","bt":"תר או תרי","dt":"תרעו - כז אב","b":"תלמיד ר יוסף שאול נתנזון בעל השו\"מ. היה הראשון שנקרא ע\"ש החתם סופר. חתן ר יעקב וינברגר מפלאנטש, וגיסו של ר אהרן הלברשטם בן ה\"דברי חיים\" מצאנז, ובזיוו\"ש חתן ר יצחק איזיק פרידמן מנירדהאזה אב\"ד בויאם. רבה של מאדיאר לאפוש-תרלה בזיבנבירגן על מקום אביו. רבה של זבורוב-תרן על מקום אביו. בניו: ר יוסף מצישנא, ר יעקב מקורימא."},{"i":17031,"n":"וייס, משה מלודז","dt":"תשג","b":"בועד הרבנים בלודז. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":17032,"n":"וייס, משה מסערדאוהל","f":"יונה","bt":"תקץ","dt":"תרסד - יד ניסן","b":"תלמיד הכת\"ס, ור יהודה אסאד, ור מיכאל הופמן מסערדאוהל. מחכמי סערדאוהל."},{"i":17033,"n":"וייס, משה מפרשבורג","f":"ישעיה ישכר בער","bt":"תרכא","bp":"פרשבורג","dt":"תרצו - ז אלול","dp":"בודפשט","b":"תלמיד השב\"ס, ודודו ר יעקב פרגר מאדא ור אברהם אליעזר אלט מקוברסדורף. חתן ר אברהם שלום הכהן פונק. רב בפרשבורג ומייסד חברת \"מענגי שבת\"."},{"i":17034,"n":"וייס, משה מפרשבורג","f":"אהרן משוראן","b":"חתן ר ישראל איסר מייער מפרשבורג. חתנו - ר שמואל פרידנטל מגוייטין."},{"i":17035,"n":"וייס, משה מפרשבורג","f":"ישעיה ישכר בער מפרשב","b":"אחיו של ר יצחק בעל \"אבני בית היוצר\". מחכמי פרשבורג, וחובב ציון."},{"i":17036,"n":"וייס, משה מקאסטלן","f":"זאב וולף מלייטשוי","bt":"תרכז","bp":"קעזמארק","dt":"תרץ - ט אלול","dp":"טירנא","b":"תלמיד השב\"ס, ור משה סופר מטיסא. חתן ר יעקב קופל קרויס מאטש ועבר לשם. רב בקאסטלאן (ליד טירנא), בודפשט-תרעח, טירנא. חתנו - ר אפרים מנשה ירוחם הכהן וילקוביץ מפישטיאן בעל \"פרי ירוחם\"."},{"i":17037,"n":"וייס, משה שבתי מטארק סט מיקלוש","f":"קלונימוס קלמן בעל פי","bt":"תרלא","b":"חתן רשב\"ן מקארצוג. רב בטאראק סט מיקלוש-תרע. גיסו - ר מאיר שטיין מטירנוי."},{"i":17038,"n":"וייס, משה שלמה מסעאיני","f":"אשר אנשל-שמן למשחה","bt":"תרסו","bp":"אויהל","b":"חתן ר אברהם שלום ירוחם פרידמן מטורץ, ועזר לחותנו בניהול הישיבה, דיין בואראהל (=סעאיני). נספה בשואה."},{"i":17039,"n":"וייס, משה שלמה מראקוביץ","b":"רב בראקוביץ. בנו ר אשר אנשל מנאדי-פאלו. חתנו - ר שמואל זלמן וינברגר ממארגרטן."},{"i":17040,"n":"וייס, משלם פייש מקלויזנבורג","f":"יצחק","k":"הו\"ל לחם ושמלה לזקנו","b":"נכד ר שלמה גאנצפריד. מחכמי לאפוש, רב בקלויזנבורג-אחרי מלחמת העולם ה-I. נספה בשואה. ?? לא באוצר ??"},{"i":17041,"n":"וייס, נטע צבי מירושלים","r":"מגיד מישרים בירושלים","bt":"תרלג","bp":"ירושלים","dt":"תרעח","b":"תלמיד המהרי\"ל דיסקין, והיה מהיחידים שהספידוהו. נזכר בלוח א\"י של טוקצינסקי שהביא הערות ממנו.","bk":[["נטעי חמד - אגדות הש\"ס",""]]},{"i":17042,"n":"וייס, נפתלי הרץ הלוי ביזביצקי","f":"משה הלוי ביזביצקי","bt":"תקם","bp":"סלונים","dt":"תרנב - כז ניסן","dp":"ירושלים","b":"תלמיד ישיבות ליטא והחת\"ס. חתן ר זליג לבל מאולאזשאקאד. שו\"ב ורב בסנט-דמעטער-תרלד, עלה לירושלים-תרמח, ולימד בביהמ\"ד חסידים של ר ברוך שוורץ וב\"אהל שרה\" במאה שערים. בנו ר יהודה אהרן הלוי וייס בעל \"בשעריך ירושלים\"."},{"i":17043,"n":"וייס, נפתלי הרץ מוילחוביץ","dt":"תשד","b":"עילוי מראזאווליה. רב בוילחוביץ. גורש לגליציה-תשא. נספה בשואה. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":17044,"n":"וייס, נפתלי הרץ ממארמרוש","f":"לייב מטעטש","bp":"טעטש","b":"חתן ר יעקב צבי גרטנר מריזאווליה-מארמרוש, ועבר לשם. רב בוילחוביץ אצל ר חיים מאיר הגר. גורש לפולין-תשא ונספה בשואה."},{"i":17045,"n":"וייס, נפתלי צבי מספינקא","f":"יעקב יוסף מספינקא","k":"אדמור מספינקא ארה\"ב","b":"אדמור מספינקא בארה\"ב."},{"i":17046,"n":"וייס, נפתלי צבי מספינקא ובילקא","f":"יצחק אייזיק-חקל יצחק","dt":"תשד","b":"חתן ר נחום אהרן. רב בבילקא. נספה בשואה."},{"i":17047,"n":"וייס, נתן נטע מטרבושאן","dt":"תשד","b":"רב בטרעבושאן. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":17048,"n":"וייס, עזריאל מני-מעדיאש","b":"רב בנירמעדיאש-תר\"מ"},{"i":17049,"n":"וייס, עקיבא אריה מתל אביב","f":"יוסף חיים הכהן","bt":"1869","bp":"גרודנא","dt":"1946","b":"פעיל ציוני, עלה לארץ-1906. ממיסדי שכונת \"אחוזת בית\" שהיתה ראשיתה של תל אביב. חיבר \"ראשיתה של תל אביב - תשיז."},{"i":17050,"n":"וייס, פנחס מנאדאש ושאמשון","dt":"תרמ - יח שבט","b":"רב בנאדאש, שאמשון על מקום ר אלכסנדר זלנפרינד, ור יוסף צבי סופר על מקומו אחריו."},{"i":17051,"n":"וייס, צבי","f":"יוסף מזברוב","b":"נכד ר משה וייס מלאפוש וזבורוב. חתן ר שלמה זלמן קליין מסילאג'-צ'ה. רב בכפר שיללמד שהיה בגליל רבנות חותנו. נפטר מיד לאחר השואה."},{"i":17052,"n":"וייס, צבי אלעזר ממילניצה","f":"מאיר","dt":"תש..","b":"חתן ר ישראל יוסף לאו מקולומיאה והיה רב לצדו. רב במילניצה על מקום אביו. נספה בשואה. פרסם מאמרים ב\"עטרת תפארת\" - פודוולוטשיסק-בילגוריי תרצא."},{"i":17053,"n":"וייס, צבי הירש מזבורוב-הגר","f":"אליקים","k":"בעל עמודי אש","bt":"תקעח","bp":"זבורוב","dt":"תרנז - כו אדר","dp":"דומברובה","b":"גיסו של הכתב סופר - שהיה נשוי לאחותו (אביו היה גיסו של הכת\"ס והיו נשואים לשתי אחיות). נכד ר יוסף חריף לייכטאג. חתן רבו מהר\"ם א\"ש מאונגוואר בעל \"אמרי אש\", ועבר לשם, ובזיוו\"ש חתן הכת\"ס. רב בסרדנא-תרה על מקום גיסו ר מנחם א\"ש שעבר לחוסט, רב בזבורוב-תריט, רבה הראשון של לאפוש-תרכב ובנו ר משה על מקומו אחריו, רב בסובראנץ-תרלא, דומברובה-גליציה על מקום זקנו. בזיוו\"ש חתן אחותו של בעל \"קול אריה\", ובזיוו\"ש חתן ה\"כתב סופר\". בנו - ר משה מזאברוב. (באוצר - הספר עמודי אש נמצא ע\"ש מנחם וייס)","bk":[["עמודי אש לבית יוסף - שו\"ת וחידושי אגדה על התורה",""]]},{"i":17054,"n":"וייס, צבי יהודה מסערדאוהל","f":"משה מקאסטלאן","bt":"תרנד","bp":"אטש","dt":"תשה - ח ניסן","b":"תלמיד הדעת סופר, ועוד. חתן ר יהושע גולדשטין מסערדאוהל. רב בהעלישטאבא, סערדאוהל. נספה בשואה."},{"i":17055,"n":"וייס, קלונימוס קלמן מאויהל","f":"יהודה ליב מיאצעויץ","k":"בעל פי שנים-תרמא","bt":"תקץ - בערך","bp":"נייטרא","dt":"תרע - טו אד\"א","b":"תלמיד הכת\"ס, ור יחזקאל בנט מנייטרא, ור וולף תרצ'ס מטאפלטשאן. חתן ר נתן בנימין ליבר מפרשבורג. גר בנייטרא, רב בטשאבא-תרכב, מילדוי-תרכז, קרלסבורג-תרלח בקהילת סטטוס קוו על מקום ר אברהם פרידמן, אויהל-תרנא בקהילת הסטטוס-קוו-עד תרסו. ציר בקונגרס היהודי-תרכט ופרש עם הצירים החרדים. חיבר מאמרים ב\"המגיד\"-תרל. הרב הניאולוגי של ועספרעם - א' הוכמוטה, יצא כנגד ספרו \"פי שנים\" בשני מאמרים בעתון ההונגרי-גרמני נאוצייט, ור קלונימוס השיב לו בגרמנית בחוברת \"קנאת האמת\" פרשבורג תרמב. בנו ר משה שבתי מסט מיקלוש. (באוצר הרבנים החליף בין אביו לחותנו)"},{"i":17056,"n":"וייס, קלונימוס קלמן מקאפוש","f":"יצחק","b":"שו\"ב בווייאן (ליד קאפוש), בעל תפלה וקורא בתורה אצל האדמור ר יהושע פריד בקאפוש."},{"i":17057,"n":"וייס, קלמן מאונגוואר","f":"משה שמואל","b":"תלמיד הכת\"ס, ור חיים צבי מנהיימר מאונגוואר. רב באונגואר-תרצא. חתן ר אברהם מאונגוואר."},{"i":17058,"n":"וייס, רפאל שמואל","f":"שבתי משימאני","b":"מכתב ממנו על משפחתו - ג'מייקה תשיד."},{"i":17059,"n":"וייס, שבתי שעפטל (שמשון) משימנ","f":"ישעיה ישכר בער","k":"בעל הלכתא רבתא לשבתא","bt":"תרכו או תרם","bp":"פרשבורג","dt":"תשד - ג חשון","dp":"שימאני","b":"תלמיד השב\"ס, ור שרגא פייש פישמן מפרשבורג ודודו ר אברהם פרגר מטאפלטשאן. חתן ר אברהם הופמן מינושהאזא. גר בשארוואר-תרמט, רב בשימאני(=נאגי-שימוני)-תרנה ובנו ר מרדכי על מקומו אחריו. פרסם מאמרים ב\"דבר בעתו\" - פאקש תרסט. נכדיו הדפיסו את ספרו \"הלכתא רבתא לשבתא\" - בני ברק תשל. תלמידו - ר פיבל בוכינגר רשם מחברות ובהם מתורת רבו.","bk":[["הלכתא רבתא לשבתא",""]]},{"i":17060,"n":"וייס, שלום מאוהל ונ\"י","k":"בעל תורת שלום","b":"רב באוהל, ניו יורק."},{"i":17061,"n":"וייס, שלמה יהודה מחומסק","b":"מו\"צ בחומסק-תר\"ח"},{"i":17062,"n":"וייס, שלמה ליב מלוגוש","dt":"תרנד - כסלו","b":"רב בלוגוש-תרכד כ-40 שנה. יצא במכתב גלוי כנגד דד\"ר משה מור הירשפלד - רב הקהלה הניאולוגית בטימישואר, על חופה שערך שלא כדין."},{"i":17063,"n":"וייס, שלמה מסעמניץ","bt":"תרנו","bp":"טאפלאטשן","dt":"תשד - יט סיון","dp":"אושוויץ","b":"תלמיד הדעת סופר. חתן ר אברהם אהרן מנייטרא. רב ברעטה-תרפה, סעמניץ-תרץ. נספה בשואה."},{"i":17064,"n":"וייס, שלמה מפעזינג","f":"נתן מטארדשקעד","bt":"תרלו","bp":"טארדשקעד","dt":"תשב","b":"תלמיד השב\"ס, ור משה פורהאנד מנייטרא-מאקווא. חתן ר יונה אדלר מפעזינג. מחכמי פעזינג, פרשבורג. נספה בשואה."},{"i":17065,"n":"וייס, שמואל אהרן מצאנז","b":"נכד ר יוסף חריף מזבורוב. מחכמי צאנז. פרסם מאמרים ב\"המפלפל\" - קראקא תרעג, \"תל תלפיות\"-תרעח."},{"i":17066,"n":"וייס, שמואל דוד מטלג'ש","f":"אשר אנשל מאג'פאלו","bt":"תרע","dt":"תשד","b":"חתן ר יעקב יחיאל שוורץ מקראלי. רב בנאדי-פאלו, טלג'ש(=טאלדעש) - בשנות התרצ'. בשנת תשא גירשו ההונגרים את היהודים מכל האזור והגיע לגרוסורדין. נספה בשואה. נזכר במבוא לספר אביו \"שמן למנחה\" ירושלים תשכט."},{"i":17067,"n":"וייס, שמואל דוד מסט-איוואן","b":"רב בסט-איוואן-תרע\"ד"},{"i":17068,"n":"וייס, שמואל זנויל מוערבא","f":"סיני מאיר","dt":"תרצ-ד","b":"תלמיד השב\"ס. חתן ר יהושע בריסק מדאדא. דיין בטיסא-פולגאר, וערבא(=וורבוי)-תרע."},{"i":17069,"n":"וייס, שמואל מפרשבורג","bt":"תקצט","bp":"קאמארן","dt":"תרמו - יג סיון","dp":"פרשבורג","b":"תלמיד הכת\"ס. רופא ראשי בבית החולים היהודי בפרשבורג, ותמך בתלמידי הישיבה."},{"i":17070,"n":"וייס, שמואל מפרשבורג ופתח תקוה","f":"ישעיה ישכר בר מפרשבו","b":"מחכמי פרשבורג, עלה לארץ והתישב בפתח תקוה."},{"i":17071,"n":"וייס, שמואל צבי מבנדקוביץ","f":"אהרן ממונקטש","dt":"תרצח - י שבט","b":"חתן ר יוסף ר\"ב מקאסאני. רב בבנדקוביץ. חתנו - ר ישראל מנחם אלתר חיים קרויס על מקומו אחריו."},{"i":17072,"n":"וייס, שמואל צבי מגרידינג","f":"משה","k":"בעל פרי לבנון,בעל מול הר האלהים","bt":"תרמו","bp":"גריידינג","dt":"תשט - כא אייר","dp":"תל אביב","b":"תלמיד ישיבת פוניבז והתפרסם כ\"פשטן הקאמאיי\". עבר עם אביו לריגה ופרסם יצירות ספרותיות. פעיל בתנועת \"פועלי ציון\", מורה וחבר מערכת \"החבר\". למד שפות שמיות בפטרבורג. עלה לארץ-1927 ועסק בהוראה."},{"i":17073,"n":"וייס, שמואל צבי מורצקי","f":"יצחק איזיק -בית יצחק","b":"בן דודו של האדמו\"ר מספינקא בעל \"אמרי יוסף\"."},{"i":17074,"n":"וייס, שמואל צבי ממונקאטש","bt":"מונקטש","dt":"תרלט - כא ניסן","b":"תלמיד הבני ישכר מדינוב (שסידר את חופתו), מהרי\"צ מראזלי, השר שלום מבלז, ר מאיר מפרמישלן, ור יצחק איזיק מזידיטשוב (שביקש את חסידיו להגיש לר שמואל קוויטלאך). חתן ר צבי הירש ממונקאטש. ראב\"ד במונקטש. בנו - ר יוסף מאיר בעל \"אמרי יוסף\" - האדמו\"ר הראשון מספינקא., ר אהרן מבנדעקוביץ, ר אברהם ממונקאטש וצפת. אחיו - ר מרדכי שעלה לארץ."},{"i":17075,"n":"וייס, שמואל צבי משאמקוט","b":"ראש הקהל בשאמקוט. תלמיד חכם שלא כיהן ברבנות אך השיב תשובות והתכתב עם גדולי דורו. תשובות ממנו ב\"קרן לדוד\", \"לחם שלמה\", \"יגל יעקב\", \"אפרקסתא דעניא\", \"אבני זכרון\"."},{"i":17076,"n":"וייס, שמעון הכהן מאויבן","f":"יהודה","k":"בעל מספד מר","b":"מחכמי אויבן. חיבר קונטרס-אויבן תקצז \"מספד מר..\" על ר גרשום טעמעשוואר, ר משה פאל, ר יוסף יאמבאק."},{"i":17077,"n":"וייס, שמעון מוישק","f":"שמואל צבי מבנעד-קויט","dt":"תשד","b":"רבה האחרון של וישק. נספה בשואה."},{"i":17078,"n":"וייס, שמעון מלאשנץ","b":"רבה של לאשנץ-הונגריה. תשובה אליו ב\"מראה משה\" לר משה פירסט - תרה."},{"i":17079,"n":"וייסברג, שלמה זלמן מהומנא","b":"רב בהומנא. פרסם מאמרים ב\"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":17080,"n":"וייספיש, אברהם מירושלים","f":"אשר לעמיל מגאלין ויר","dt":"תרמו"},{"i":17081,"n":"וייספיש, צבי הירש","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":17082,"n":"וייסקופף, דוד מואלרשטין","f":"יצחק זליגמן","bt":"תקנח","bp":"גונצהויזן (מיטל-פרקוניה)","dt":"תרמב- יט אדר","dp":"קליינורדין","b":"תלמיד החת\"ס, ור אברהם בינג מוירצבורג ור משה הכהיימר מאנשבאך. חתן ר זקל אחי ר מנדל רוזנבוים מצעל. עבר לוירצבורג-תקפו, רב באויב (אונטר-פרקוניה)-תקץ, נורדלינגן-תר, ולרשטין-תרט, ואשרטרילינגן-תרך, קליינורדין-תרלו. פרסם מאמרים ב\"הלבנון\" - ירושלים-פאריס תרכג-תרמב. חתנו ר חיים נתנזון מוורעשען בעל \"עבודה תמה\". חתנו ר מרדכי מיכאל הכהן קאהן על מקומות אחריו. בנו ר משה - רב בפריז, ר מאיר."},{"i":17083,"n":"וייסקופף, מאיר מפיורדא","f":"דוד מוולרשטין","b":"מחכמי פיורדא."},{"i":17084,"n":"וייסקופף, משה מפאריס","f":"דוד מוולרשטין","bt":"תקצז","dt":"תרצו - טו שבט","b":"תלמיד הכת\"ס, ור יעקב עטלינגר מאלטונא, ור יצחק דב במברגר מוירצבורג. רב בקולמאר-תרטו, קהילת יראים בפריז(=פאריס)-תריט. חתנו - ר יהודה ליאופולד סנדר."},{"i":17085,"n":"וייסרוז, זקן","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":17086,"n":"וייץ, חיים יצחק דוד","f":"דב","k":"בעל לקוטי חיים","bt":"תר","bp":"טרנופול","dt":"תרסז","b":"תלמיד המנחת חינוך. עלה לירושלים-תרמח והיה מגדולי הלומדים שם. חיבר \"לקוטי חיים\" ירושלים תשכז."},{"i":17087,"n":"וייץ, יוסף מטרנופול","b":"רב בטרנופול. פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז."},{"i":17088,"n":"וייץ, ישראל יעקב מלויצק חאנאחא","b":"תלמיד ר אברהם ליב בעל \"מלאת אבן\". אב\"ד לוצק-פלך ווהלין."},{"i":17089,"n":"וייץ, מרדכי","b":"פרסם מאמרים ב\"בית אברהם\" - וארשא תרצד, פרסם מאמרים ב\"הלפיד\" - וארשא תרצז - על הישיבות הראשונות בפולין."},{"i":17090,"n":"וייצל, אשר מדרהטשין","f":"מרדכי וייצל","b":"רב בדורהיטשין(=דרהטשין)-תר\"ע"},{"i":17091,"n":"וייצל, דוד","dt":"תשיח - ח תשרי","b":"רב בברנוביץ"},{"i":17092,"n":"וייצל-רוזנבלט, מרדכי מסלונים","f":"אברהם מנחם מאנטאפולי","k":"בעל הדרת מרדכי","bt":"תקצט","bp":"אנטיפוליה-פלך גרודנא","dt":"תרעו","dp":"סלונים","b":"שמו רוזנבלט ע\"ש ספרו \"עלה חבצלת\" שחיבר בנעוריו. בזיוו\"ש חתן הגביר ר אברהם גרינברג מאשמינא. תלמיד ר פנחס מיכאל מאנאטפולי, ר מרדכי זקהיים מפינסק, ישיבות סימיאטיש, פינסק. מקובל ונחשב לצדיק שברכותיו מתקיימות. רב בבוטן וכונה \"הצדיק מבוטן\", ונהרו אליו ממקומות רחוקים לבקש ברכה ועצה - אך לא חסידים. רב בבוטען-תרכז, קרליץ(=קארעליצי)-תרמז, אושמיאנה(=אשמינא)-תרנב, סלונים-פלך גרודנא-תרסד וראש ישיבה. בניו - ר אשר מדרוהוטשין, ר שמואל יהושע מסלונים. חתניו: אב\"ד גודליעווא, אב\"ד ביטען. נכדו - חיים חייקל לונסקי - הו\"ל \"\"תולדות הגאון ר מרדכי וייצל מאשמינא\" וילנא תרעז."},{"i":17093,"n":"ויכסלבוים, מנחם מוניש מרודניק","f":"מרדכי הלוי","bt":"תרי","bp":"רודניק","dt":"תרף","b":"היגר לניו יורק-תרמז, ויסד את כולל אמריקה בארץ ישראל."},{"i":17094,"n":"וילאסקו די, אברהם משלוניקי","dt":"תקז","dp":"שלוניקי","b":"מבני הקהלה האיטלקית בשלוניקי-תקד וחתם אז על הסכם בין האיטלקים לבין בני קהלת שלוניקי בענין הסדרת המס."},{"i":17095,"n":"וילאסקו די, יצחק משלוניקי","b":"מבני הקהלה האיטלקית בשלוניקי-תקד וחתם אז על הסכם בין האיטלקים לבין בני קהלת שלוניקי בענין הסדרת המס."},{"i":17096,"n":"וילבוש, גדליהו","f":"זאב","bt":"1865","bp":"גרודנא","dt":"1943","dp":"חיפה","b":"מהנדס ותעשיין. פעיל בחובבי ציון ו\"בני משה\". עלה לארץ ויסד ביח\"ר והקים מפעלי השקייה. חזר לרוסיה והקים במינסק בית חרושת למכונות שהעסיק כ-200 פועלים יהודים. חזר לארץ-1912. פרסם זכרונות ופרקי אוטוביוגרפיה בעתונים שונים."},{"i":17097,"n":"וילבוש, נחום","f":"זאב","bt":"1879","bp":"לוסוסנו-ליטא","b":"מהנדס. עלה לארץ-1903, היה חבר המשלחת לחקר תוכנית אוגנדה. הקים מ פעלי תעשיה ומים. פרסם מאמרים בחקירת ארץ ישראל בעברית, רוסית וגרמנית."},{"i":17098,"n":"וילד, ברוך מגורליץ","b":"מראשי הקהל בגורליץ"},{"i":17099,"n":"וילדא, חיים מזלאבין","f":"יעקב משוערזנא","k":"בעל אוצר חיים","bt":"תריז","b":"נינו של ר יחזקאל איסרלש - והחזיק בכת\"י חדושי זקנו. חתן ר משה קוטק מסטרידוב. רב בציראוויץ(=טשוראויטש)-פלך צערניגוב-תרנא, שוורזנה(=שוערזנא)-פלך מוהילוב, זאלובין(=זלאבין)-פלך מוהילוב. תולדות משפחתו במגילת יוחסין למשפחות תומרקין-וילדא - נדפס באודסה."},{"i":17100,"n":"וילדה, יעקב משוורזנץ","b":"תלמיד ר יוסף ריבלין מירושלים בעל \"אהל יוסף\". רב בשווערזנה(=שוורזנץ)-פלך מוהילוב-תרכ."},{"i":17101,"n":"וילדויער, ישראל ממיטאוי","f":"יעקב","b":"גביר במיטאוי."},{"i":17102,"n":"וילדמן, אלימלך ממיזאטש וירושלי","b":"אב\"ד מיזאטש, עלה לירושלים. בניו - ר יהושע אלתר בעל עמק יהושע, ר מרדכי יוסף בעל מי מעין."},{"i":17103,"n":"וילדמן, יהושע אלתר","k":"בעל בנין יהושע","bt":"תריח","dt":"תרצד","dp":"ירושלים","b":"מו\"ץ בוארשא. רב בערים פופובה, וישניץ, בילרודקה וקונסקבולי(=קאנסקיוואליא). חיבר \"בנין יהושע\" וארשא תרנח, ועוד. עלה לירושלים-תרפד."},{"i":17104,"n":"וילדמן, מרדכי יוסף","f":"אלימלך ממיזאטש וירוש","k":"בעל מי מעין"},{"i":17105,"n":"וילדשטין, יצחק מקרניץ","b":"גביר בקרניץ. ראש ישיבה בצאנז. חתניו - רז\"ו איזנבך מצאנז ורצ\"א שפירא מברטש."},{"i":17106,"n":"וילהיים, אהרן מפעזינג","f":"חיים","bt":"תקצט","bp":"אודווארד","dt":"תרנט - אדר","dp":"פעזינג","b":"תלמיד הכת\"ס. חתן ר יצחק ברוין מדיאנדיאש. רב בקאטה-תרל, פעזינג-תרלג, חתנו ר שרגא הכהן רוזנברג על מקומו אחריו."},{"i":17107,"n":"וילהיים, חיים מאודווארד הסבא","b":"אביו של ר אהרן מפעזינג."},{"i":17108,"n":"וילהיים, חיים ממאראש הנכד","f":"אהרן מפעזינג","dp":"ניו יורק","b":"רב במאראש וואשארהלי. עבר לניו יורק."},{"i":17109,"n":"וילהיים, משה יעקב","b":"רב בסבטיטש-תר\"מ"},{"i":17110,"n":"וילהלם מברלין","f":"יעקב בר","bt":"1797","bp":"ברלין","b":"חייל בצבא הפרוסי, בנקאי עם אביו, מדען ואסטרונום. חיבר ספר אסטרונומיה על הכוכב מאדים, ועוד."},{"i":17111,"n":"וילובסקי, יעקב דוד - רידב\"ז","f":"זאב וולף","k":"בעל שו\"ת רידב\"ז","bt":"תרה-ו","bp":"קוברין-פלך הורדנא","dt":"תרעד - א תשרי","dp":"צפת","b":"מגדולי חכמי דורו, רב באיזאבלין-תרכח, בוברויסק-תרלו, וילנא-תרמח, פלאצק-תרמג, וילקומיר-תרמז, סלוצק-תרן והקים שם ישיבה, חיבר פירוש לתלמוד ירושלמי. בשליחות באמריקה-תרס להדפסת הירושלמי, רב בניו יורק, שיקגו-תרסג ועזב בגלל מצב היהדות שם, עלה לצפת-תרסה ויסד ישיבת \"תורת ארץ ישראל\", עין זתים-תרעב. חיבר גם \"מגדל דוד\", חידושי רידב\"ז, \"בית הרידבז\", \"חנה דוד\" ועוד. תשובות ממנו בקבצים שונים. בספרו \"נימוקי רידב\"ז\" שיקגו תרסד - מספר על המצב הקשה של היהדות באמריקה. היה מעורב במחלוקת אודות השמיטה וחיבר \"קונטרס השמיטה\".","bk":[["רידב\"ז","מפרשי ירושלמי"],["תוספות הרי\"ד","מפרשי ירושלמי"],["בית רידב\"ז","שו\"ת - אחרונים"]]},{"i":17112,"n":"וילטרניץ, בנימין וולף","f":"מאיר הקדוש","k":"בעל גבול בנימין","b":"שו\"ב בפרג, חיבר גבול בנימין על שחיטות ובדיקות למהר\"י וייל - פרג תסז."},{"i":17113,"n":"ויליג, שרגא פיבל הלוי מבוצאץ","f":"ישראל","bt":"תרל","bp":"דרהאוה","dt":"תשב - ד תשרי","b":"רב בדלטין, ראב\"ד בבוצאץ-תרסג והקים שם ישיבה. נספה בשואה. מתלמידיו רמח\"א בלוך. פרסם מאמרים ב\"משכנות יעקב\" - דרוהוביטש-בילגוריי תרצב."},{"i":17114,"n":"ויליגר, מרדכי מסיגט ונ\"י","f":"משה מסיגט","k":"בעל פרדס מרדכי","bt":"תרנו","bp":"בושטינא-פלך מרמרוש","b":"נכד הצדיק ר יצחק זאב בעל \"לישרים תהלה\". תלמיד בעל ערוגת הבשם בחוסט, בעל \"מעשה למלך\" בוייצען, ר חיים צבי טיטלבוים מסיגט בעל \"עצי חיים\". נסמך מר דוד שליסל ממונקטש. חתן הגביר ר בנימין פרלשטין ממונקטש ועבר לשם. היגר לארה\"ב וכיהן רב בניו יורק-תרפח. חיבר גם \"אוצר נחמד\", אנציקלופדיה על התוספות - בכת\"י, \"קובץ התוספות\" - ובו רבבות שיטות וכללים מהתוספות לפי א-ב, \"אוצר הש\"ס\" ובו סדר הענינים בש\"ס לפי א-ב."},{"i":17115,"n":"ויליגר, משה","f":"יצחק זאב--לישרים תהל","b":"מחכמי בושטינא-מרמרוש. תלמיד ר אלעזר לעוו מאונגואר, בעל \"קול אריה\" מברגסאס, בעל \"יטב לב\" מסיגט. חתן ר מנדל ולרשטין. בנו - ר מרדכי מארה\"ב."},{"i":17116,"n":"ויליטרו, דוד משלוניקי","b":"מבני הקהלה האיטלקית בשלוניקי-תקד וחתם אז על הסכם בין האיטלקים לבין בני קהלת שלוניקי בענין הסדרת המס."},{"i":17117,"n":"וילייסיד, אברהם ישראל","dt":"תיא","dp":"ירושלים?","b":"מראשי קהילת ירושלים, שותף להסכמה בין אשכנזים וספרדים בענין כספי החלוקה - עם ר מאיר אשכנזי. חתום על אגרת משנת שסט שנשלחה לפדובה אודות שליחות ר גדליה קורדובירו."},{"i":17118,"n":"וילייסיד, אברהם מניקופול","b":"רב בניקופול, נזכר ב\"כנסת הגדולה\" תקנה שתיקן בניקופול שלא לתקוע בתפלת לחש משם מעשה שהיה וכו', בנו - ר שמואל מקושטא."},{"i":17119,"n":"וילייסיד, אברהם מקושטא","f":"שלמה","b":"תלמיד דודו - ר חיים בנבנישתי בעל כנסת הגדולה. מחכמי קושטא. חברו של ר משה שלטון."},{"i":17120,"n":"וילייסיד, אליעזר מרודוס","b":"רב ברודוס-שע, ור משה אמאטו על מקומו אחריו."},{"i":17121,"n":"וילייסיד, גדליה מספרד ושלוניקי","b":"חזן ופייטן בספרד, לאחר הגירוש חזן בשלוניקי. כנראה ממגורשי סביליה."},{"i":17122,"n":"וילייסיד, דוד מקושטא","f":"יעקב","b":"רב בקושטא-שנות ה-ש', נזכר אצל ר יוסף טרני."},{"i":17123,"n":"וילייסיד, עובדיה הרופא מחברון","b":"רופא מחכמי חברון. נזכר ב\"נבחר מכסף\" בענין המקוה בחברון."},{"i":17124,"n":"וילייסיד, עזריה מקושטא וירושל","dp":"ירושלים","b":"מחכמי קושטא. עלה לירושלים (עם ר יו\"ט גוקליר), חברון-שן. בשנת שפג חתם על אגרת אודות שליחותו של ר חנניה בן ברהון."},{"i":17125,"n":"וילייסיד, ראובן? מקושטא ומצרים","b":"גביר מקורב לוזיר בקושטא ומצרים-ת' בערך."},{"i":17126,"n":"וילייסיד, שלמה מקושטא","f":"שמואל מקושטא","b":"מחכמי קושטא, חתן ר ישראל בנבנשתי (ולדעת רוזניס חתן ר חיים בנבנישתי בעל כנסת הגדולה). בנו ר אברהם נשא ונתן עם ר חיים בנבנשתי בעל \"כנסת הגדולה\"."},{"i":17127,"n":"וילייסיד, שמואל מקושטא","f":"אברהם מניקופול","dt":"שצב","b":"רב בקושטא-שפ, היה במחלוקת עם ר יוסף טרני בענין גט. מתלמידיו - ר דוד אגוזי, ר משה בנבנשתי בעל פני משה, ר חיים בנבנישתי המזכירו בספרו, נזכר בספרי הפוסקים בדורו ואחריו."},{"i":17128,"n":"וילימובסקי, יוסף יצחק","dt":"תשג","b":"רב בסעלץ"},{"i":17129,"n":"וילינגר, יחזקאל שרגא","b":"פרסם מאמרים ב\"הכוכב\" - מונקטש-נ\"י תרצה."},{"i":17130,"n":"ויליצקר, אשר אנשיל","dt":"תשד","b":"רב בעלץ"},{"i":17131,"n":"ויליצקר, יואל מטערסיף","f":"יצחק איצק","dt":"תשד - כה אייר","dp":"אושוויץ","b":"חתן ר משה טיטלבוים בן ר אליהו בצלאל מטעטש. רב בטרעסיף-קרפטרוס. נספה בשואה."},{"i":17132,"n":"ויליצקר, יצחק איצק","dt":"תקע - ג סיון","b":"דיין בקרקא"},{"i":17133,"n":"ויליצקר-אשכנזי, יצחק מסטניסלב","f":"יעקב הירש צבי מסקול","k":"אדמור מסטניסלב","bt":"תרכח","dt":"תשב - כא תשרי","dp":"סטניסלב","b":"חתן ר אשר אנשל מאייר אשכנזי מסטניסלב. עלה לירושלים-תרן, וחזר לסטניסלב לכהן כרב ואדמור-תרנז על מקום חותנו. נספה בשואה. בנו ר אשר אנשיל - רבה של בלז-בסרביה, טערסיף-קרפטורוס."},{"i":17134,"n":"וילכפורט, לוי צבי מאושפיצין","bt":"תרע","b":"נכד ר אברהם אביש חיים בוך מקולשיץ. מחסידי רדומסק באושפיצין. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":17135,"n":"וילמובסקי, אלתר הכהן","b":"פרסם מאמרים ב\"הדנו\" - נ\"י תרפה, \"המסלה\" - נ\"י תרצו."},{"i":17136,"n":"וילנא, יעקב מוילנא","b":"מחכמי וילנא. בנו ר אליהו קלצקין"},{"i":17137,"n":"וילנא, יצחק איזיק מהנובר","dt":"תקסו - כט ניסן","b":"תלמיד ר יונתן איבשיץ. דיין בהנובר. חדושים ממנו ב\"מנחת יהודה\" - אמשטרדם תקכג."},{"i":17138,"n":"וילנא, ישראל איסר","dt":"כז חשון","b":"מגדולי תלמידי הגר\"א-תק\"מ,עלה לא\"י"},{"i":17139,"n":"וילנא, שלמה בכור מירושלים","dt":"תקעה - ג חשון","dp":"ירושלים","b":"נכד ר חיים ירוחם וילנא-אלישר. מחכמי ירושלים, בשנת תקסז חתם על אגרת תלמידי \"כנסת ישראל\", גיסו של הראשון לציון ר יונה נבון"},{"i":17140,"n":"וילנאי זאב","bt":"1900","dt":"ה'תשמח 1988","bk":[["מדריך ארץ ישראל",""]]},{"i":17141,"n":"וילנסקי, יחיאל הכהן מתל אביב","bt":"תרעב","dt":"תשנט","b":"דיין בתל אביב."},{"i":17142,"n":"וילנסקי, יצחק איזיק","dt":"תשג","b":"מרביץ תורה בראדין"},{"i":17143,"n":"וילנסקי, יצחק חיים","b":"מחכמי לובאויטש."},{"i":17144,"n":"וילנסקי, שלום","dt":"תשג","b":"רב באייזטישק"},{"i":17145,"n":"וילנסקי, שמואל חרקובר מארה\"ב","f":"נחום מאיר מחרקוב","k":"בעל נר שמואל - תשסא","bp":"חרקוב","dt":"תשך - י כסלו","b":"תלמיד ישיבת ראדין, סלובודקה. ניצל מהשואה ונדד עם ישיבת מיר ליפן ולסין, ואחריה ראש ישיבת \"בית התלמוד\" בניו יורק, יחד עם ר אריה ליב מאלין. פרסם מאמרים ב\"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר, \"תורה אור\" - שנחאי תשו. מתורתו נדפס \"נר שמואל\" ירושלים תשסא."},{"i":17146,"n":"וילנציק, דוד","b":"רב-שנת תרי\"א"},{"i":17147,"n":"וילנציק, יעקב מפיקעלי","f":"דוד","k":"בעל דלתי תשובה","bt":"תריא","b":"חתן ר חיים נתנזון מזידיק בעל \"שפתי חן\". רב באנטיגול-תרלד, זופרן-תרלו, פיקעלי(=פיקאלן)-פלך קובנא-תרמג-ח וגיסו ר יוסף בנציון פרידמן על מקומו אחריו. מתורתו בספרי חכמי דודו ובהם \"שדי חמד\", \"דרכי תשובה\", ועוד. פרסם מאמרים ב\"הפלס\", ועוד."},{"i":17148,"n":"וילנקין - משפחה במינסק"},{"i":17149,"n":"וילנקין, אברהם","f":"שלום יחיאל מיכל מויל","b":"נכד ר יעקב-חתנו של בעל \"חיי אדם\" ובנו של ר אליהו ואשתו בלומקא (שנתברכה במינסק מפי בעל שאגת אריה - והקימה בית מדרש במינסק ועלתה לארץ - והשם וילנקין בה ממנה שהיתה נוסעת הרבה ממינסק לוילנא)."},{"i":17150,"n":"וילנקין, זאב וולף מויטבסק","b":"גביר מחכמי ויטבסק, מינסק."},{"i":17151,"n":"וילנקין, יעקב","f":"אליהו","b":"חתן בעל \"חיי אדם\" ונזכרה בסוף \"חיי אדם\" בענין הנס וכו'. שם משפחתו מאמו בלומקא ממינסק שהיתה לרגל עסקיה הרבה בוילנא, ושנתברכה בידי בעל \"שאגת אריה\" והקימה בימ\"ד במינסק, ועלתה לירושלים - נפטרה תקעא, על צואתה חתם ר חיים מוולוזין ובנו ר יצחק."},{"i":17152,"n":"וילנקין, מרדכי אליהו מנוברדוק","b":"העתיק כת\"י על תריג מצוות לר דוד לידא ממגנצא."},{"i":17153,"n":"וילנקין, ניקואלי מקסימוביץ","bt":"1855","bp":"גלובוק-פלך וילנא","dt":"1937","b":"עורך דין וסופר. פרסם שירים ב\"נאוואייע וורעמיא\", ועוד. עורך \"נובי-פוט\". היגר מרוסיה. פרסם בשם העט \"נורד ווסט\"."},{"i":17154,"n":"וילנר, אברהם יעקב מוילמפול","f":"דב בער","b":"דיין בוילנא-תקי אצל ר יהושע השל-אב\"ד וילנא, וחתם עם היסו\"ד-תקי, מו\"צ בויליאמפול - חתם גם ב-תקפד. בקי בחשון והנדסה. אחיו - ר משה, ר יצחק זעלקא."},{"i":17155,"n":"וילנר, אהרן מטלוסט","bt":"תרנט","bp":"טלוסט","b":"לבקשת ר\"י מצורטקוב גדל אצל דודו ר מאיר ארק לאחר שנתייתם, והביא מחדושיו בספריו. ניצל מהשואה וכיהן כרב וראש ישיבה בניו יורק. השאיר כתבים על הש\"ס ועל התורה. מתורתו \"הערות על המנ\"ח\" - צפונות-תשנב."},{"i":17156,"n":"וילנר, אריה ליבוש מטלומטש","f":"שמואל מהאליטש","b":"רב בהאליטש על מקום אביו. תשובות אליו בספרי ר שלמה קלוגר ור יוסף שאול נתנזון."},{"i":17157,"n":"וילנר, בנימין דוד מירושלים","dt":"תרנג - ו חשון","dp":"ירושלים","b":"עלה לירושלים-תקצט, מו\"ץ בירושלים-תרט, חתם עם ר שמואל סלנט."},{"i":17158,"n":"וילנר, בצלאל","b":"נכד ר אורי שרגא פיבל מוילנא. גיסו - ר צבי הירש ויטעס לנדא."},{"i":17159,"n":"וילנר, דוד צבי מזורובנא","b":"תלמיד החת\"ס שברכו באריכות ימים (וחי כמאה שנה)."},{"i":17160,"n":"וילנר, דוד שמואל מדולינא","b":"תשובה אליו - \"מחזה אברהם\"-תרמו."},{"i":17161,"n":"וילנר, זאב וולף מבקשביץ","f":"שמואל","b":"רבה של בקשביץ."},{"i":17162,"n":"וילנר, יחזקאל מסערהייא","f":"יהודה ליב בן הגר\"א","b":"נכד הגר\"א. חתן ר איסר שחור מוילנא. הו\"ל יחד עם אחיו ר טוביה שיר השירים עם פירוש הגר\"א - זקנם. חתניו: ר אברהם עפראן מוילנא, ר שמואל אהרן גרדזנסקי."},{"i":17163,"n":"וילנר, ישכר בעריש מוארשא","f":"יהודה ליב בן הגר\"א","dt":"תרה - ד אלול","b":"נזכר ב\"נחלת עולמים\". נכד הגר\"א. בניו: ר משה, ר שלמה, ר אליהו, ר משלם."},{"i":17164,"n":"וילנר, ישראל מברזיב","f":"אברהם יאטשימירער","b":"ממלא מקום הרב בברזיב. מלמד בללויז צורטקוב."},{"i":17165,"n":"וילנר, מרדכי מיזען","b":"תשובה אליו - מהרש\"ם-תרנח."},{"i":17166,"n":"וילנר, פנחס זליג מלבוב","f":"יהודה","b":"דיין בלבוב, חתם-תפד עם ר אהרן זליג בן שמואל למשפחת צבי, ר אברהם כץ, ועוד."},{"i":17167,"n":"וילנר, קלמן מטרנוב","dt":"תשג","b":"רב בטרנוב. נספה בשואה."},{"i":17168,"n":"וילנר, שמואל מהאליטש","dt":"תריד - כו אייר","b":"נכד הצדיק ר שלמה וילנר הנזכר ב\"לקוטים יקרים\" נכדו של ר שמואל וילנר מתלמידי הבעשט. חתן ר צבי הירש מנדבורנה וגיסו של ר אברהם חיים הלוי שפירא מברזן."},{"i":17169,"n":"וילנר, שמואל מנוברדוק","f":"שמלקא מסלוצק","b":"נכד(-אבי אמו) ר דוד קיידנובר. מ\"מ ומו\"צ בנוברדוק בזמן ר ראובן בן משה."},{"i":17170,"n":"וילף, אברהם יעקב מרוזניאטוב","f":"ישעיה יוסף","bt":"תרו","bp":"דרוהוביטש","dt":"תרן","b":"חתן רא\"ל קנביל מרוזניאטוב. רב ברוזניאטוב על מקום חותנו. בנו ר אליעזר ליפא חיבר \"פאר הדור\" לתולדות זקניו - ויצען [תרעה]."},{"i":17171,"n":"וילף, אליעזר ליפא","f":"אברהם יעקב מרוזניאטו","k":"בעל פאר הדור","b":"חיבר \"פאר הדור\" לתולדות זקניו - ויצען [תרעה]."},{"i":17172,"n":"וילף, דוד נתן מסטרי","b":"רב בסטרי וסיגט-תרך. תשובה אליו בשו\"מ."},{"i":17173,"n":"וילף, יהושע מלמברג","b":"חסיד בלז. חתן ר פייביש עבנער. מחכמי למברג ומדפיס בדפוס חותנו."},{"i":17174,"n":"וילף, ישעיה יוסף מדרוהוביטש","k":"אדמור מרוזלא-דרוהוב'","bt":"תקעה","bp":"דרוהוביטש","dt":"תרכד","b":"לאחר שנתייתם גדל אצל ר מרדכי לטנר. חתן הגביר ר יוסף בונם סומעליר מרוזלא. נסמך לאדמור ע\"י העטרת צבי וכיהן כאדמור ברוזלא (ר יהודה צבי איכנשטין כיהן גם הוא כאדמור ברוזלא והיה מחלוקת בין החסידים - אך שני האדמורים היו בידידות). עבר לדרוהוביטש. חיבר \"חזון ישעיהו\" הנקרא \"תפלה לעני\" למברג תרכז. נכדו ר אלתר רשם את תולדותיו בספרו \"פאר הדור\"."},{"i":17175,"n":"וילף, שלמה מדרוהוביטש","f":"ישעיה יוסף","k":"בעל מבוא המדרש","bt":"תר","dt":"תרץ","b":"רב בדרוהוביטש. חיבר \"מבוא המדרש\" למברג תרלז, ועוד.","bk":[["אמרות שלמה",""],["התנהגות הדרך",""],["מבוא המדרש",""],["מעשי הגדולים",""]],"e":"ת\"ר~-תרצ\"א~"},{"i":17176,"n":"וילפורט די, דוד מפרובנס","k":"בעל כללי חשבונות העב","b":"רב בלויזרא-פרובנס. חיבר \"כללי חשבונות העבורים\"."},{"i":17177,"n":"וילק, זלמן מליטא","bt":"1860","bp":"קובנא","b":"עסקן ציוני, חבר בחובבי ציון. לאחר משבר אוגנדה עבר למוסקבה."},{"i":17178,"n":"וילק, יעקב מזבנא","b":"מחכמי זבנא-תרנח. השתתף ב\"אהל מועד\"."},{"i":17179,"n":"וילק, מאיר מלאסק","b":"אב\"ד לוסק. מחותן עם ר עקיבא איגר. תשובה ממנו ב\"הפלס\" - ברלין תרסא-תרסה."},{"i":17180,"n":"וילק, משה מאושפיצין","b":"תלמיד ישיבה באושפיצין. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט, \"כתר תורה\" - אושפיצין תרצט."},{"i":17181,"n":"וילקוביץ, אפרים מנשה ירו' הכהן","k":"בעל פרי ירוחם","b":"רב בפישטיאן. חתן ר משה וייס מקאסטלן. ?? לא באוצר ??"},{"i":17182,"n":"וילקנסקי-אלעזרי, יצחק אביגדור","f":"אליעזר יהושע","k":"בעל בדרך","bt":"1880","dt":"1955","b":"תלמיד ישיבת טלז, למד באוני' ברן פילוספיה וכלכלה, עלה לארץ-1908, ועסק בשכלל החקלאות בארץ. יסד את משק העופות הראשון בארץ, ועוד. פרסם מאמרים בנושאי חקלאות. ציר בקונגרסים הציוניים.. חיבר גם \"מדות\" - ת\"א תרפד, ועוד. על שמו המושב בית אלעזרי."},{"i":17183,"n":"וילקנסקי-אלעזרי, מאיר","f":"אליעזר יהושע","k":"בעל ספורים מחיי הארץ","bt":"1882","bp":"איישישוק","dt":"1949","dp":"כפר ויתקין","b":"תלמיד ישיבת איישישוק, פוניבז. עלה לארץ-1905. פרסם ציורים ורשימות מחיי הארץ. תרגם ספרים לעברית."},{"i":17184,"n":"וילר, בנימין זאב וולף מירוסלב","f":"חיים שמחה","k":"בעל בנימין זאב האחרו","bt":"תקף","dt":"תרסז","b":"חתן הגביר ר יצחק זנדבנק מצשינוב. מחכמי ירוסלב. חיבר \"בנימין זאב האחרון\" פרמישלא תרנט. ?? לא באוצר ??"},{"i":17185,"n":"וילר, יעקב מביטשא","k":"בעל בית יעקב","b":"נכד הרבי ר השל. רב בביטשא-ליד טרנטשין-תקפ."},{"i":17186,"n":"וילר, משה אהרן מאיזנשטט","dt":"תקפט - יג תמוז","b":"חתן ר משה גינז מאיזנשטט. גיסו של ר עקיבא איגר."},{"i":17187,"n":"וילר, שמואל מהעדילא מאדע","f":"משה אהרן","bt":"תקעג","bp":"איזנשטט","dt":"תרמז - כב אלול","dp":"העדילא מאדע","b":"תלמיד החת\"ס והכת\"ס. רב בהעדילא מאדע-תרט."},{"i":17188,"n":"וילשטטר, אליהו מקרלסרוה","f":"אפרים","b":"אב\"ד קרלסרוה-תקצו, חתם-תר על מכתב המלצה לר אריה ליב בן אשר ולרשטין - נכד השאגת אריה. חתם-תקץ על מכתב המלצה לשוחט שמעיה בן נתן הלוי מאיכשטען."},{"i":17189,"n":"וימפען, גינענדלה מקאלמאר","f":"אברהם גרוינר-גרומבך","b":"אשת ר שמואל וימפען מקאלמאר-אלזאס. העתיקה את כל התלמוד הבבלי עם מראה מקומות בשנים תסו-תסז."},{"i":17190,"n":"וינברג - האחים מבילגוריי","b":"מדפיסים בבילגוריי, הדפיסו כתב העת \"עטרת תפארת\"."},{"i":17191,"n":"וינברג וינברגר, משה","b":"רב בראקוב-תרכ\"ח,וולברום-תרל\"ו"},{"i":17192,"n":"וינברג, אברהם יהושע השל מסלוני","f":"ישכר ליב מסלונים","k":"אדמור מסלונים","bt":"תרנח","dt":"תשלח - כד ניסן","b":"חתן ר דוד וינדפלד מוארשא. אדמור בסלונים, עלה לארץ-תרצה והתישב בתל אביב. חיבר \"אוצר ערכי התורה - באהלי ישכר\"."},{"i":17193,"n":"וינברג, אברהם מוארשא","k":"בעל ראשית בכורים","r":"חבר בועד הרבנים בוורשא","bt":"שציצין","bp":"שציצין","dt":"תשב","b":"תלמיד בעל \"אבני נזר\". רב וחבר בועד הרבנים בוארשא - עם ר מנחם זמבא. נספה בשואה.","bk":[["ראשית בכורים - בכורות (זבחים כת\"י)",""]]},{"i":17194,"n":"וינברג, אברהם מטרנוב","k":"בעל תורת הכתב האחיד","bt":"תרנב","bp":"טרנוב","dt":"תשל","b":"מורה ומחנך בפולין. עלה מטרנוב לחיפה-תרצו. לפני השואה. חיבר \"תורת הכתב האחיד\" חיפה תשיג, ועוד."},{"i":17195,"n":"וינברג, אברהם מסטרי","b":"מחכמי סטרי. תשובה אליו \"מהר\"י הכהן\"."},{"i":17196,"n":"וינברג, אברהם מסלונים","f":"מיכל אהרן","b":"נכד ר יוסף דוד בן ר יצחק מתתיהו בן ר נח בן ר יחיאל מיכל אהרן בן ר אברהם האדמור מסלונים הראשון. ראש ישיבת חב\"ד בלוד. חתן נכדת דודו ר אברהם בן נח מסלונים ירושלים. הקים ישיבת \"באר אברהם\" ע\"ש חותנו ורבו בירושלים ובני ברק. מתורתו בקובץ \"נחלי אמונה\"."},{"i":17197,"n":"וינברג, אברהם מסלונים ברנוביץ","f":"שמואל מסלונים","k":"אדמור מסלונים ברנובי","bt":"תרמד","dt":"תרצג - א אייר","b":"חתן ר צבי מלומאז (שושלת קוצק). מקים ישיבות \"תורת חסד\", רב ואדמור מסלונים אחר פטירת אביו בביאליסטוק, ברנוביץ. רוב חסידי סלונים עברו אליו וחלקם נשארו עם אחיו ר ישכר בסלונים. ביקר כמה פעמים בארץ. חיבר \"בית אברהם\".","bk":[["בית אברהם",""],["בית אברהם (סלונים)",""]]},{"i":17198,"n":"וינברג, אהרן מיענדזיוב","f":"חיים","bt":"תריח","bp":"יענדזעוו","dt":"תשג","b":"רב ביענדזוב, אנדרב(=אנדרעוו)-פלך קיעלץ-תרן. פרסם מאמרים ב\"בית אברהם\" - וארשא תרצד, \"הכרם\" - וארשא תרפז."},{"i":17199,"n":"וינברג, אפרים","f":"נפתלי מנמירוב","k":"בעל לקוטי אבן","bt":"תקס","dt":"תרמג - יד תשרי","dp":"אומן","b":"יד ימינו של ר נתן נמירוב-תלמיד ר נחמן מברסלב. עלה לירושלים-תרלג, נסע לאומן-תרמב ונפטר שם. חיבר גם \"תפילות הבקר\"."},{"i":17200,"n":"וינברג, בנימין","b":"רב בטובריב-תר\"נ"},{"i":17201,"n":"וינברג, דב בריש","f":"דוד וינברג","b":"רב בנאשעלסק-תר\"צ"},{"i":17202,"n":"וינברג, דב בריש מויליצקא","b":"מחכמי ויליצקא-תרנד. תשובות אליו \"הרי בשמים\"."},{"i":17203,"n":"וינברג, דב בריש מקראקא","dt":"תרצו","b":"גביר חסיד בקראקא. חדושיו אבדו בשואה."},{"i":17204,"n":"וינברג, דוד","bt":"תרכ","dt":"תשב - י חשון","b":"רב בגור-תרס\"ה"},{"i":17205,"n":"וינברג, חיים צבי מטאוויאן","b":"רב בטאוויאן-פלך קובנא-תרל, וחתנו ר נחום בן ציון סנדלוביץ על מקומו אחריו."},{"i":17206,"n":"וינברג, יחיאל יעקב","f":"משה","k":"בעל שרידי אש","r":"רב בפילווישקי, ראש בית המדרש לרבנים בברלין,","bt":"תרמה","bp":"צ'חנוביץ","dt":"תשכו - ג שבט","dp":"לוזאן - ירושלים","b":"תלמיד ישיבות לומז'ה, סלובודקא, ומיר. נסמך מאת: ר צבי רבינוביץ מקובנא, ר משה דינשבסקי, ר אליהו ברוך קאמאי ממיר, ר אליעזר רבינוביץ ממינסק. רב בפילוישוק(=פילווישאק)-פלך סובאלק, ד\"ר מאוניברסיטת ברלין וגיסן, וכיהן כמרצה בגיסן. ר\"מ בביהמ\"ד לרבנים בברלין על מקום ר אברהם אליהו קפלן. ניצל מהשואה - היה עצור סמוך לנירנברג. ר\"מ בישיבת מונטרה-שוייץ. מגדולי דורו והשיב לשאלות מכל התפוצות. פרסם מחקרים בעתונות העברית והגרמנית בעניני הלכה ויהדות. פרסם מאמרים ב\"יגדיל תורה\" - סלוצק-בוברויסק תרסט, \"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה, \"המאור\" - תל אביב תרצה, \"קול תורה\" - ירושלים תרץ, \"תבונה\" - ירושלים תשא-תשח, \"תלפיות\" - נ\"י תשד.","bk":[["שרידי אש","מפרשי ש\"ס - אחרונים"],["לפרקים",""],["את אחי אנכי מבקש - ראשי פרקים להידברות בין פלגי היהדות",""],["כלילת שאול - בשיטת הרמב\"ם בביעור חמץ (כת\"י)",""],["כתבי הגאון רבי יחיאל יעקב וינברג - בתלמוד ובהלכה",""],["מחקרים בתלמוד",""],["שרידי אש - שו\"ת",""],["שרידי אש (חידושים)",""],["שרידי אש","שו\"ת - אחרונים"]],"e":"תרמ\"ד-תשכ\"ו","rb":"פילווישוק","yl":"ישיבת מיר, ישיבת סלבודקה","co":{"a":"54.720193,23.226683","b":"52.666667,22.516667"}},{"i":17207,"n":"וינברג, יחיאל ישעיה מיענדזיוב","f":"אהרן מיענדזיוב","k":"אדמור מחנטשין","b":"מצאצאי החוזה מלובלין. חתן ר חיים שמואל מחנטשין, רב ביענדזיוב על מקום אביו ואדמור חסידי חנטשין. נספה בשואה."},{"i":17208,"n":"וינברג, יעקב יצחק מלאטאויטש","b":"נכד בעל \"דברי אמת\" מלובלין. רב בלאטאוויץ-פלך וארשא-תרל."},{"i":17209,"n":"וינברג, יעקב משה","b":"רב בנאוואסעליץ"},{"i":17210,"n":"וינברג, ירחמיאל מרדכי","f":"יעקב יצחק מלאטאוויץ","bt":"תרכג","b":"מצאצאי בעל \"דברי אמת\" מלובלין. רב בעליסק(=עלוסק)-פלך לובלין-תרמה, קרילוב-פלך לובלין-תרנח."},{"i":17211,"n":"וינברג, ישכר ליב מסלונים","f":"שמואל מסלונים","k":"אדמור מסלונים","bt":"תרלג","dt":"תרפח - כח ניסן","b":"חתן ר שלום מבראהין (שושלת קוידנוב). אדמור בסלונים על מקום אביו."},{"i":17212,"n":"וינברג, ישעיה מסטוישין","f":"דוד וינברג","b":"רב בסטוישין-תר\"פ"},{"i":17213,"n":"וינברג, ליפמן מריגא","b":"מו\"צ בריגא. אחיינו של ר אליעזר ליפמן ליכטנשטין מטוקום."},{"i":17214,"n":"וינברג, מיכל אהרן","f":"אברהם וינברג","dt":"תרסד - כח חשון","b":"רב בסלונים"},{"i":17215,"n":"וינברג, מנחם מניימרקט","bt":"תרלא","b":"חתן ר נתן במברגר מוירצבורג. רב בניימרקט-תרנ\"א"},{"i":17216,"n":"וינברג, מרדכי גרשון מירושלים","f":"אברהם חיים","bt":"תריב","bp":"ירושלים","dt":"תרפג - כג ניסן","dp":"ירושלים","b":"סופר, עסקן צבור, בירושלים, פעל לבנין השכונות בירושלים."},{"i":17217,"n":"וינברג, מרדכי יהודה מקמניץ","f":"יעקב הלל מברנוביץ","k":"בעל עטרת מרדכי","b":"תלמיד ישיבת \"כנסת בית יצחק\" בקמניץ. חיבר \"עטרת מרדכי\" - בילגוריי תרצט."},{"i":17218,"n":"וינברג, משה","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":17219,"n":"וינברג, משה מוולברום","f":"דב בעריש","b":"רב בראקוב-פלך ראדום-תרכח, וולברום-פלך קיעלץ-תרלו."},{"i":17220,"n":"וינברג, משה מזידיטשוב","b":"חסיד בויאן. הגיע מזידיטשוב לכהן כרב בנובוסליץ-בסרביה, על מקום ר אלתר בלימס (חסידי סדיגורא שהתנגדו לו הביאו כנגדו את ר ישראל פסח וטשטין מברוסילוב)."},{"i":17221,"n":"וינברג, משה מלומזה וניו יורק","b":"סופר וצייר, חיבר ספר תהלים מצוייר - בכת\"י."},{"i":17222,"n":"וינברג, נח מסלונים ירושלים","f":"יחיאל מיכל אהרן מסלו","dt":"תרפז - כג אלול","dp":"ירושלים","b":"נכד האדמור ר אברהם מסלונים הראשון. עלה לארץ-תרל בפקודת זקנו האדמור."},{"i":17223,"n":"וינברג, נפתלי הרץ מנמירוב","f":"יהודה","dt":"תרך - יב אב","b":"מבחירי תלמידי ר נחמן מברסלב, חבר של ר נתן שטרנהרץ. התגורר באומן ליד קבר ר נחמן. בנו ר אפרים בעל \"לקוטי אבן\"."},{"i":17224,"n":"וינברג, צבי זאב ממישעגאלע","f":"גרשון","bt":"תרכה","b":"רב במישעגאלע-פלך וילנא-תרנג."},{"i":17225,"n":"וינברג, שלמה מויליצקה","b":"מחכמי ויליצקה. מתורתו \"ועד חכמים\"."},{"i":17226,"n":"וינברג, שמואל יעקב","b":"רב בשעראדז"},{"i":17227,"n":"וינברגר, אביגדור משומקוט","f":"יצחק","k":"בעל סמיכת נופלים","dt":"תרע.. - ד טבת","b":"מחכמי שומקוט, עסק בסחר אתרוגים וישב כמה חדשים בשנה בטריאסט - מרכז סחר האתרוגים. חתן ר זליג הירש פישהוף - גיסו של ר הלל ליכטנשטין. חסיד האדמור בעל \"אמרי יוסף\" מספינקא."},{"i":17228,"n":"וינברגר, אברהם יהודה ליב מטשרט","f":"יהושע אהרן צבי","bt":"תקצח","dt":"תרעא - כד חשון","dp":"טשערטעז","b":"תלמיד הכת\"ס. חתן ר משה צבי גרוס מאוואש-אויווארוש. מחכמי טשערטעז."},{"i":17229,"n":"וינברגר, אברהם יצחק מדוקלא","f":"מרדכי יהושע מדוקלא","k":"בעל פני יצחק","r":"רב בפריישדטל ואח\"כ בקלייוורדיין חתנו של בעל ה'טיב גיטין'","bt":"תקסה","bp":"דוקלא","dt":"תרמה - יב חשון","b":"תלמיד החת\"ס. חתן ר צבי הירש הלר חריף מאונגוואר בעל טיב גיטין. אחר פטירת חותנו נישאה חותנתו לחתם סופר ועבר עמה לפרשבורג. רב בפריישטטל-תקץ, קליינוארדין(=קיש-וארדה)-תרד ויסד ישיבה שם. מראשוני חסידי הדברי חיים מצאנז בהונגריה. חיבר \"פני יצחק\" מונקטש תרנב.","bk":[["מלל לאברהם",""],["פני יצחק - סוגיות הש\"ס",""]]},{"i":17230,"n":"וינברגר, אברהם ליב מלמברג","b":"מחכמי למברג. תשובה אליו \"אבן יקרה\"."},{"i":17231,"n":"וינברגר, אלתר יצחק איזק מטורקא","f":"אלעזר מסינעויער","k":"בעל בית יצחק","bt":"תרסה","dt":"תשלד","b":"תלמיד ישיבת חוסט אצל ר יוסף דושינסקי, האדמור ר מנחם מנדל הגר מאוברוישיוא, נסמך מרבו ומאת: ר ישעיה שלום רוקח מואניוויטש. רב בטורקא, והקים בטורקא ישיבת \"דגל התורה\", ממיסדי ישיבות \"נצח ישראל\" בפולין, ניצל מהשואה ועבר לניו יורק-תשו הקים ישיבת \"דגל התורה\" ועמד בראשה בניו יורק. חיבר \"בית יצחק\" ניו יורק תשלב. פרסם מאמרים ב\"משכנות יעקב\" - דרוהוביטש-בילגוריי תרצב. אחיו של ר אשר יונה."},{"i":17232,"n":"וינברגר, אפרים פישל מזלישטשיק","f":"יעקב","k":"בעל יד אפרים","bt":"תרעב","bp":"פשמישל","dt":"תשכד","b":"תלמיד מהר\"ם שפירא, ואחר כך ר יעקב הופמן מפפדמ. חתן ר זאב וולף תאומים מזלישטשיק. רב בקלן-תרץ, בויטן-שלזיה - תרצא, זלישטשיק-תרצג על מקום חותנו. התחבא בזמן השואה מתחת לכנסיה בחסות הכומר ששילם על כך בחייו. ניצל מהשואה והגיע לארץ-תשד. חתן בזיוו\"ש של ר אברהם מרדכי קליערס מטבריה. רב ביד אליהו-תל אביב. חיבר \"יד אפרים\" תל אביב תשלו. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב.","bk":[["יד אפרים","שו\"ת - אחרונים"]]},{"i":17233,"n":"וינברגר, אפרים פישל מפרמישלא","b":"פרסם מאמרים ב\"הנצח\" - לבוב תרפז, \"קהילת יעקב\" - זבורוב-סלובקיה תרפה."},{"i":17234,"n":"וינברגר, אשר יונה מטימישואר","f":"אלעזר מסינעווער","bt":"תרסז","dt":"תשנו","dp":"ירושלים","b":"אחיו של ר יצחק אלטר וינברגר ראש ישיבת דגל התורה. תלמיד ר אברהם יוסף גרינולד בחוסט. חתן ר דודו פינקוס מטימשואר ועבר לשם, הקים ישיבת \"אהבת תורה\". ניצל מהשואה. היגר לארה\"ב-תשי ופתח בית מדרש בניו יורק. עלה לארץ-תשכה. חסיד ויזניץ. תלמיד ר יוסף צבי דושינסקי בחוסט, ר יהושע בוקסבוים בגלנטא ומנחם מנדל הגר בווישווה. ראש ישיבה בטימישואר. ניצל מהשואה, ואחריה היגר לניו יורק ופתח בית מדרש בנוסח ויזניץ."},{"i":17235,"n":"וינברגר, אשר ממיהלביץ","b":"ראב\"ד במיהלוויץ-תרכ\"ו"},{"i":17236,"n":"וינברגר, ברוך יהודה ליב מהאדס","dt":"תר - כו כסלו","dp":"האדעס","b":"מחכמי האדעס. תלמיד החת\"ס."},{"i":17237,"n":"וינברגר, דב זאב מניו יורק","f":"יהושע מדינוב ונ\"י","k":"בעל שמן הטוב","b":"מצאצאי בעל \"בני ישכר\". רב בניו יורק. חיבר \"שמן הטוב\" נ\"י תשמח."},{"i":17238,"n":"וינברגר, דוד מיולניצא","dt":"תשג","b":"רב ביולניצא"},{"i":17239,"n":"וינברגר, הלל מסערדאוהל","f":"שמואל לוי וינברגר","dt":"תשג","b":"מג\"מ ומחברי אגודה \"עץ חיים\" - פרשבורג תרעא - ללימוד תורה של חבורה מחכמי פרשבורג. דומ\"ץ בסערדאוהל על מקום אביו."},{"i":17240,"n":"וינברגר, יהודה ליב מניגרשד","f":"פנחס מניגרשד","dt":"תרצב - ז-כ חשון","dp":"ניגרשד","b":"רב בניגרשד(=ניגרעשט) על מקום אביו ואחיו ר שמואל-תרנה וכיהן כ-37 שנה. חתנו - ר יואל כץ מערדעד."},{"i":17241,"n":"וינברגר, יהושע אהרן צבי ממרגרט","f":"משה משוסברג","k":"בעל שות מהריאץ-תרעג","bt":"תקעה","bp":"שוסבורג","dt":"תרנב - כח כסלו","dp":"מרגרטן","b":"מחשובי רבני הונגריה. תלמיד זקנו ר אהרן משה גידונג מפעזינג, ר בנימין וולף מוורבוי בעל \"שערי תורה\", והחת\"ס. חברו של הכת\"ס. חתן הגביר ר יעקב בער פלדמן מכפר פעטרא ליד מארגרטן ועבר לשם, קיבל הצעה לרבנות מארגרטן והעבירה לידיד נפשו ר הלל ליכטנשטין שקיבלה, ולאחר פטירת חותנו עזב ר הלל את רבנותו לטובת חברו ר יהושע שכיהן שם -30 שנה, ובנו ר שמואל זלמן על מקומו אחריו. פרסם מאמרים ב\"קובץ מפרשי התורה\" - מארגרטן תרצג.","bk":[["שו\"ת מהריא\"ץ",""],["לקוטי מהריא\"ץ",""]]},{"i":17242,"n":"וינברגר, יהושע מבלז","f":"מרדכי","k":"אדמור מדינוב","bt":"תרנד","dt":"תשכו","b":"היגר לארה\"ב. היה אדמור מדינוב בניו יורק."},{"i":17243,"n":"וינברגר, יהושע פנחס ממארגרטן","f":"שמואל זלמן ממרגרטן","dt":"תשד","b":"תלמיד ר יהודה גרינוולד בסטמר, ור ישעיה זילברשטין בוויצען. רב בסעפלאק(=סיפ-לאק) וגליל מארגרטן על מקום אביו וראש ישיבה (ואחיו ר מרדכי עזריאל על מקום אביו בעיר מארגרטן). נספה בשואה."},{"i":17244,"n":"וינברגר, יחזקאל ממארוש-אויוואר","b":"רבה הראשון של מארוש-אויוואר-תרל. עלה לירושלים."},{"i":17245,"n":"וינברגר, יחזקאל שרגא מאופאליא","dt":"תשד","dp":"אושוויץ","b":"רב וראש ישיבה באופאליא - חאת הישיבות החשובות בהונגריה לפני השואה. נספה בשואה."},{"i":17246,"n":"וינברגר, יעקב מבודפשט","f":"פנחס וינברגר","b":"דרשן,מג\"מ בבודפסט-תר\"פ"},{"i":17247,"n":"וינברגר, יעקב מדוקלא","f":"אלישע","dt":"תרלב","dp":"ירושלים","b":"מחכמי דוקלא, עלה לירושלים."},{"i":17248,"n":"וינברגר, יצחק איצק מניקלשבורג","dt":"תרכח","b":"רב בניקלסבורג"},{"i":17249,"n":"וינברגר, ישראל מטירנוי","f":"דוד","k":"בעל בית הילל","b":"נכד(-אבי אמו) ר הלל ליכטנשטין בעל משכיל אל דל. חיבר ספר \"בית הילל\" לתולדות זקנו."},{"i":17250,"n":"וינברגר, ישראל מליפיאן","b":"דומ\"צ בליפיאן"},{"i":17251,"n":"וינברגר, מאיר מליטוביסק","b":"רבה של ליטוביסק-תרפב על מקום חותנו ר פנחס אלימלך בער."},{"i":17252,"n":"וינברגר, מנחם מנדל מדוקלא","f":"משה","dt":"תרכד"},{"i":17253,"n":"וינברגר, מרדכי יהושע מדוקלא","f":"משה","bt":"תקמה","dt":"תרך","b":"רב בדוקלא-תקף. מקור משפחתו בפרנקל תאומים ושינו שמם לוינברגר. חתן ר חיים יעקב שטורם מדוקלא ועבר לגור שם."},{"i":17254,"n":"וינברגר, מרדכי מדינוב","bt":"תרך","bp":"דינוב","dt":"תשב","b":"נכד ה\"בני ישכר\". לאחר שנתייתם גדל אצל ר דוד מדינוב. חתן ר וולף וינברגר משמש השר שלום. שינה את משפחתו לשם חותנו. ראב\"ד בבלז אצל שלשה אדמורים. נספה בשואה."},{"i":17255,"n":"וינברגר, מרדכי מהומאנא","dt":"תרעג - ז אדר","dp":"אויהל","b":"תלמיד ר מנחם א\"ש מאונגואר. דומ\"צ בהומאנא. נזכר ב\"חלקת השדה\"."},{"i":17256,"n":"וינברגר, מרדכי עזריאל ממארגרטן","f":"שמואל זלמן ממארגרטן","bt":"תרסז","dt":"תשד - ג סיון","dp":"אושוויץ","b":"חתן ר הלל וינברגר מדונא-סרדאהי. רב במארגרטן על מקום אביו-תרצד וראש הישיבה. מקורב לחסידות והכניס אופי חסידי בישיבה. נספה בשואה."},{"i":17257,"n":"וינברגר, משה (כרמלי) מקלויזנבו","k":"בעל ספר וסייף","b":"תלמיד ר אליעזר דוד גרינוולד בסטמר, סמינר לרבנים בבודפשט. שומר מצוות ורב בקהילה הניאולוגית (קונגרסאית) בקלויזנבורג-1934. ניצל מהשואה ובמהלכה עסק בהצלת יהודים, ואחריה עלה לארץ ועסק בחינוך. פרופ' בישיבה אוניברסיטה בניו יורק. חיבר גם \"ספר זכרון לקלויזנבורג\", \"הטרגדיה של יהודי טרנסילבניה\", ועוד."},{"i":17258,"n":"וינברגר, משה מניו יורק","f":"ישכר","k":"בעל דרש דרש משה","bt":"תריד","bp":"הונגריה","dt":"תש - ו סיון","dp":"ניו יורק","b":"תלמיד ר מאיר פרלס מקראלא. הגיע לארה\"ב-תרם, וכיהן כרב אנשי אונגרן בניו יורק, רב בפילדפליה, עזב את הרבנות-תרעה ועסק במסחר בניו יורק. חיבר גם \"הואיל משה\", ועוד. פרסם מאמרים ב\"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג."},{"i":17259,"n":"וינברגר, משה משסבורג","b":"ראב\"ד בשסבורג-תק\"פ"},{"i":17260,"n":"וינברגר, משה פלנטש","b":"מגדולי וחשובי דוקלא-תק\"מ"},{"i":17261,"n":"וינברגר, עקיבא יוסף ממארגרטין","f":"יהושע אהרן צבי","bt":"תרי","bp":"מארגרעטין","dt":"תרפה - טו אדר","b":"תלמיד הכת\"ס, חתן ר שמואל טישלר מהאדאמאד-פאלווא. רב במארגרטן, בנו ר נחמיה על מקומו אחריו."},{"i":17262,"n":"וינברגר, פנחס מנדל מדוקלא","f":"משה","bt":"תקסב","bp":"פלנטש","dt":"תרכב","b":"מחכמי דוקלא. חתן ר אברהם אריה ליב הורביץ."},{"i":17263,"n":"וינברגר, פנחס מניגרשד","f":"משה וינברגר","k":"בעל שות מהר\"ף שוסברג","bt":"תקפג","bp":"שוסבורג","dt":"תרנג - יג אדר","dp":"ניגרעשט","b":"דרשן, רב בניגרשט-תרג. אחיו של ר אהרן יהושע בעל שו\"ת מהריא\"ץ. חתן בנו - ר יואל כץ מערדער הו\"ל את ספרו שו\"ת מהר\"ף עם הערות ממנו בשם \"גלילי זהב\"."},{"i":17264,"n":"וינברגר, שלום מבודפשט","f":"פנחס מניגרשד","dt":"תרצד - יב טבת","b":"רב בפיר-ליד טשאנד, בודפשט-תרסה."},{"i":17265,"n":"וינברגר, שלום משלם","k":"אדמור מטשאבא","b":"נכד-בן בתו האדמור מטשאבא, ואדמור על מקומו אחריו וראש ישיבת \"עטרת שמואל\". הו\"ל ספר זקנו \"ברכת שמואל\" עם תולדותיו."},{"i":17266,"n":"וינברגר, שלמה יהודה מניר-באגאד","bt":"תריג או תרכג","dt":"תרצג - ו חשון","b":"רב בנירבוגאד-תרמח. פרסם מאמרים ב\"וילקט יוסף\"."},{"i":17267,"n":"וינברגר, שמואל זלמן ממארגרטין","f":"יהושע אהרן צבי ממרגר","bt":"תרכג","bp":"מארגרטין","dt":"תרצד - יד כסלו","dp":"מרגרטין","b":"תלמיד השב\"ס, ור דוד ניימן מפרשבורג. חתן הגביר ר משה שלמה וייס מראקוביץ, ועבר לשם. גיסו של ר אשר אנשיל וייס מנאג'פאלו. רב וראש ישיבה במארגרטין-תרנג על מקום אביו כ-40 שנה - לאחר שאחיו הבכור ר עקיבא יוסף ויתר על התפקיד, ובנו ר מרדכי עזריאל על מקומו אחריו במרגרטין, ובנו ר יהושע פנחס על מקום אביו בגליל מרגרטין. פעל להשכנת שלום בגרוסורדין בין החסידים למתנגדים. פרסם מאמרים ב\"קובץ מפרשי התורה\" - מארגרטן תרצג. חתנו - ר מרדכי בריסק ממרגרטן."},{"i":17268,"n":"וינברגר, שמואל לוי מבאניא","f":"פנחס מניגרשד","k":"בעל שו\"ת מהר\"ש לוי","bt":"תרך","bp":"ניגרשד","dt":"תרפה - א אדר","b":"תלמיד דודו ר יהושע אהרן צבי (=מהריא\"ץ) במארגרטן, המהר\"ם שיק בחוסט. חתן ר הלל ליכטנשטין מקולומיאה בעל \"בית הלל\". רב בבודרוג-קרסטור-תרמט, ניגרשד-תרנג על מקום אביו, באניא-תרנה, סרדאוהל(=סערדאוהל)-תרסו וראש ישיבה, ובנו ר הלל על מקומו אחריו. רוב כתביו אבדו בשואה. נכדו ר יחיאל וינברגר הו\"ל מכתביו שו\"ת מהר\"ש לוי - תשלג. פרסם מאמרים ב\"עמק הלכה\" - באטארקס תרפא."},{"i":17269,"n":"וינברגר, שמואל מרישא","b":"מחכמי רישא-תריח."},{"i":17270,"n":"וינברגר, שמואל צבי","dt":"תשד","b":"רב בטשעטשעוויץ"},{"i":17271,"n":"וינברגר-תאומים, נתן נטע זאב","f":"מנחם מרדכי תאומים","b":"נכד(-אבי אמו) הברוך טעם. נאלץ לברוח מברודי להונגריה ושינה שמו לוינברגר."},{"i":17272,"n":"וינגוט, אלעזר","dt":"תשג","b":"רב ביאפובה"},{"i":17273,"n":"וינגוט, אפרים שלמה זלמן מליפנא","f":"מיכאל דוב מפיעטריקוב","k":"בעל עוז מלך","bt":"תרד","b":"רב בסלעשין-פלך קאליש-תרלד, פיעטרקוב-פלך וארשא-תרנא על מקום אביו, אסטרוב-פלך לומזה, ליפנא-פלך פלאצק-תרנה. חיבר גם \"אורה לציון\"."},{"i":17274,"n":"וינגוט, אפרים שרגא מקאליש","bt":"כא אדר תרמח","dt":"תשיא","b":"רב בקאליש, רב ומו\"צ בצפת","bk":[["לחם אשי - על התורה",""]]},{"i":17275,"n":"וינגוט, יחיאל מאיר","f":"ישכר מנדל","bt":"תרמח","bp":"קלעטשוב-פולין","dt":"תשלג - כד טבת","dp":"ירושלים","b":"תלמיד ישיבת סוכטשוב אצל ה\"אבני נזר\" ואצל בנו \"השם משמואל\". חתן ר יצחק הלוי לובינסקי מסלופצה. עלה לארץ-תרצה, והתישב בבני ברק והיה ממקורביו של החזון איש. רב חסידי גור בבני ברק על מקום ידידו ר נחמן שמואל מיאדוסר (הרב מבראק)."},{"i":17276,"n":"וינגוט, ישכר מקויל וצנסטחוב","f":"יהודה הלוי","k":"בעל פתחי שערים","r":"אב\"ד דק\"ק טשנחסטוב","bt":"תקמט","dt":"תריב","b":"מקורב למגיד מקוזניץ. תלמיד ר חיים אוירבך בעל \"דברי משפט\". חתן ר אפרים הלוי מקויל. רב בסמפלנה, פלונסק, קויל, סטריקוב, צנסטחוב-תקפ. חיבר גם \"שער הלקוטות\". מתורתו ב\"בית אברהם\" - וארשא תרצד. בנו - ר מיכאל דב. (באוצר הרבנים מכונה וינגרט).","bk":[["שער הלקוטות - פתחי שערים",""],["פתחי שערים",""]]},{"i":17277,"n":"וינגוט, מיכאל דוב מפיעטרקוב","f":"ישכר מקויל וצנסטחוב","k":"בעל אגודת אזוב מדברי","bt":"תקעט","dt":"תרמז","b":"תלמיד ר אליהו רגולר. מו\"ץ בפיעטרקוב-תרח - תריט, ובנו ר אפרים שלמה על מקומו אחריו.","bk":[["אגודות אזוב מדברי",""]]},{"i":17278,"n":"וינגוט, שמואל יהודה מקוואהל","f":"ראובן ישראל","r":"רב בעיר ריסעשיץ כעשר שנים ואח\"כ כחמישים שנה בעיר קוואהל","bt":"תריח","dt":"נהרג על קידוש השם יג מרחשון תש","b":"רב בקאוואהל-פלך וארשא-תרמב.","bk":[["חיי שעה - ביוגרפיה",""],["פתחי מגדים - חנוכה",""]]},{"i":17279,"n":"וינגוט, שמעון י'","dt":"תשג","b":"רב בקאוולי"},{"i":17280,"n":"וינגורט, ישראל מקאליש","b":"ראב\"ד בקאליש"},{"i":17281,"n":"וינגורט, מנחם מנדל מראדום","f":"אלכסנדר סנדר","k":"בעל אור הישרים","bt":"תריח","dt":"תרפז","b":"נסמך מאת: ר יואב יהושע מקינצק. ראב\"ד בראדום-תרמ. פרסם מאמר ב\"שערי תורה\" - וארשא תרסג-תרצט - בענין הסכמתו וחזרתו של ר יהודה ליב צירלזון לכהן כרב בראדום."},{"i":17282,"n":"וינגורט, שאול מביליץ","f":"אברהם מביליץ","bt":"תרעה","bp":"ביליץ","dt":"תשו","b":"למד באוניברסיטה ובבימ\"ד לרבנים בברלין. רב בברלין. חתן ר אליהו בוצ'קו ולימד בישיבתו במונטרי-שוויץ. פרסם מאמרים ב\"בית המדרש\" - מונטרה תש.., עסק בהצלה בזמן השואה. לזכרו נדפס \"יד שאול\" בעריכת ה\"שרידי אש\" ור\"פ ביברפלד - תל אביב תשיג."},{"i":17283,"n":"וינגיסט, יעקב מחרסקוב","b":"מחכמי חרסקוב. תשובה אליו - \"קול מבשר\"-תרצא."},{"i":17284,"n":"וינגרט,שמואל מפלאהן וירושלים","b":"רב בפלאהן-גרמניה, ירושלים. חתם-תשה על מכתב רבני ירושלים."},{"i":17285,"n":"וינגרטן, אברהם אבא יוסף מיאנוב","f":"שמריהו מליבישוב","k":"אדמור מליבישוב","dt":"תרכא","dp":"פינסק","b":"רב ביאנוב, ליבישוב, פינסק."},{"i":17286,"n":"וינגרטן, אברהם אבא מיאנוב","f":"חיים יצחק מיאנוב","k":"אדמור מיאנוב ליבישוב","dt":"תרפא","b":"חתן ר דוד מסאווראן. אדמור ביאנוב. בנו ר חיים יצחק אב\"ד ליעדז'-בלגיה."},{"i":17287,"n":"וינגרטן, דוד מחורזיל ורישאש","k":"בעל חדושי הר\"ד צבי","b":"חסיד קוצק וגור. רב בחורזיל, רישאש. מצאצאיו - ר דוד בן אהרן יוסף וינגרטן מירושלים."},{"i":17288,"n":"וינגרטן, דוד מירוסלב","dt":"תרנד","b":"רב בירוסלב אצל ר שמואל ולדברג."},{"i":17289,"n":"וינגרטן, דוד מירושלים","f":"אהרן יוסף","bt":"תרלג","bp":"ירושלים","b":"מצאצאי ר דוד מחורז'ל בעל חדושי הר\"ד צבי. תלמיד ישיבת \"חיי עולם\". ממיסדי שכונת \"בתי וארשא\" בירושלים, מיסד ומנהל \"בית יתומות כללי\" בירושלים-תרסב, ממונה כולל וארשא-תרסה, חבר ועד הכללי לקופת רמבעה\"נ."},{"i":17290,"n":"וינגרטן, זאב וולף מסמבור","b":"מחכמי סמבור. תשובה אליו בשו\"מ."},{"i":17291,"n":"וינגרטן, חיים יצחק מיאנוב","f":"אברהם אבא יוסף מינוב","k":"אדמור מליבישוב","dt":"תרלט"},{"i":17292,"n":"וינגרטן, חיים יצחק מליעדז","f":"אברהם אבא מיאנוב","b":"מצאצאי ר משה מסאוורן, ור יעקב אריה מקאוולע. בנו של האדמור מיאנוב ולא כיהן כאדמור. חתן ר מאיר נחום יונגרלייב בן סנדר שמואל מוישנוביץ (זלוטשוב). רב בליעדז-בלגיה. נסמך מאת הרי\"מ אפשטין מנוברדוק."},{"i":17293,"n":"וינגרטן, יהושע מליובאשוב","dt":"תשג","b":"רב בליובאשוב"},{"i":17294,"n":"וינגרטן, יחיאל מיכל מיאנוב","f":"שמריהו מליבישוב","k":"אדמור מליבישוב","dt":"תרכה - כד סיון","b":"חתן ר חיים הכהן מפינסק וירושלים."},{"i":17295,"n":"וינגרטן, יחיאל צבי מגוטא","b":"תלמיד ר שמואל דוד אונגר בישיבת טירנוי. פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי, \"משא ומתן\" - טירנוי תרצא."},{"i":17296,"n":"וינגרטן, יעקב אריה ליב מליבשוב","f":"חיים יצחק מיאנוב","k":"אדמור מליבישוב","dt":"תרפב","b":"חתן ר גדליה אהרן מסוקוליבקא (ליניץ)."},{"i":17297,"n":"וינגרטן, יצחק אהרן מליבישוב","f":"יעקב אריה ליב","k":"אדמור מליבישוב","dt":"תשב","b":"חתן ר מנחם נחום אפשטין מקוברין-ביאליסטוק. אדמור בליבישוב, עבר לקוברין, ופינסק. ביקר אצל חסידיו בארץ ובארה\"ב וחזר לאירופה. נספה בשואה. בניו ר אברהם אבא, ר שמריהו, ר משה ור ישראל - נספו בשואה."},{"i":17298,"n":"וינגרטן, יצחק סגל","b":"תלמיד ישיבת קאליב. פרסם מאמרים ב\"הפלפול\" - שאפראן תרצח."},{"i":17299,"n":"וינגרטן, שמואל הכהן","b":"פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו."},{"i":17300,"n":"וינגרטן, שמריהו מליבישוב","f":"אברהם אבא יוסף","k":"אדמור מליביטשוב","dt":"תרו - א תמוז","b":"חתן ר דוד מסטעפין. רב בקוברין, רב ואדמור בליביטשוב-תקסב."},{"i":17301,"n":"וינגרטן-הלפרן, דוד","f":"שלמה יצחק הלפרן","b":"רב בליזנסק-תרי\"א"},{"i":17302,"n":"וינד, ברוך מרדומשיל","f":"ישראל","dt":"תרעא","b":"חתן ר אברהם ברנד מרדומישל. רב ברדומישל אצל ר\"ש אנגל."},{"i":17303,"n":"וינד, הלל מדרוהוביטש","f":"יצחק יהודה ליב","k":"בעל סוגה בשושנים","bt":"תרעג","bp":"דרוהוביטש","dt":"תשמח","dp":"ירושלים","b":"עלה לירושלים-תרצח ברשות האדמור מבלז ולמד בישיבת תורת חיים. והיה גבאי של האדמור אחר שעלה לארץ. חתן ר פנחס אפשטיין. חיבר \"סוגה בשושנים\" ירושלים תשלח. פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח."},{"i":17304,"n":"וינד, יצחק איציק מאורמין","f":"שמעון","k":"בעל יד ושם","bt":"תקסט","bp":"מטרסדורף","dt":"תרכו - ד אלול","dp":"אורמין","b":"תלמיד החת\"ס. חתן ר יעקב הרצוג מאבאני. רב באורמין-תקצז. חיבר \"קול נהי\" פרשבורג תרכה."},{"i":17305,"n":"וינד, מרדכי הכהן","b":"מתורתו - \"עולת חודש\"-תשט."},{"i":17306,"n":"וינד, שרגא הכהן מטרנוב","b":"מחכמי טרנוב. תשובה אליו \"מנחת יחיאל\"."},{"i":17307,"n":"וינדין, משה ממטרסדורף","b":"מו\"צ במטרסדורף-ת\"ר"},{"i":17308,"n":"וינדלינג, מרדכי צבי מקראקא","f":"אליהו","k":"בעל תולדות מרדכי","bt":"תרכא","dt":"תרפט","b":"מחכמי קראקא. חיבר \"תולדות מרדכי\" - לא רשום? בביבליוגרפיה. ?? לא באוצר ??"},{"i":17309,"n":"וינדנר, אברהם צבי הרש","bp":"פרויענקירכן","dt":"תרנא - ג טבת","dp":"פרשבורג","b":"תלמיד החת\"ס. חתן ר ברוך בייא-רוט מפרשבורג (נשא את אשתו בהוראת רבו)."},{"i":17310,"n":"וינדען, אברהם הירש מפרשבורג","b":"מחכמי פרשבורג, עסק ברוכלות ובשעת הליכתו בשווקים היה חוזר על פה על מסכתות בש\"ס."},{"i":17311,"n":"וינדרמן, משה מנדבורנה","b":"תשובה אליו - \"מנחת יהודה\"."},{"i":17312,"n":"וינוגרד, אברהם חיים מפינסק ויר","f":"פסח","k":"ר חיים מתמיד","bp":"פינסק","dt":"תרמו","dp":"ירושלים","b":"רב בפינסק, עלה לירושלים-תרמב עם בניו ר יצחק ור יוסף אליהו שהקימו את ישיבת תורת חיים בירושלים על שמו"},{"i":17313,"n":"וינוגרד, יוסף אליהו מירושלים","f":"אברהם חיים","k":"בעל נתיבות החיים","r":"ראש ישיבת תורת חיים","bt":"תריד","dt":"תרעח","dp":"ירושלים","b":"מחכמי ירושלים, עלה לארץ בשנת תרמב יחד עם אביו, והיה עוזר לאחיו ר יצחק ומלמד תורה בישיבת \"תורת חיים\" שיסד ר יצחק. לאחר פטירת ר יצחק בשנת תרעג התמנה לראש הישיבה. חיבר \"נתיבות החיים\" והדפיסו בעילום שמו, בשנת תשטו נדפס חלק נוסף על ידי נכדו ר יעקב שמואל וינוגרד בירושלים.","bk":[["נתיבות החיים - דרוש ונשים נזיקין",""]]},{"i":17314,"n":"וינוגרד, יצחק מירושלים","f":"אברהם חיים","r":"ראש ישיבת תורת חיים","bt":"תריא","bp":"פינסק","dt":"תרעג","dp":"ירושלים","b":"מחכמי ליטא תלמיד ישיבת וולוזין ונודע שם כ\"עילוי מפינסק\". בשנת תרמז עלה לירושלים והקים את ישיבת \"תורת חיים\" ביחד עם אחיו ר יוסף אליהו. השאיר חבורים בכתי. היה מפורסם גם כחזן ודרשן.","bk":[["תורת חיים – קדשים",""]]},{"i":17315,"n":"וינוגרד, פנחס מרדכי מירושלים","k":"בעל תולדות אהרן","bt":"תריט","bp":"שטוצין","dt":"תרסב","b":"עלה לירושלים וסייע לקרובו ר יצחק וינוגרד ביסוד ישיבת תורת חיים. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":17316,"n":"וינוגרד, שמחה מירושלים","f":"אברהם חיים","bt":"תרכג","bp":"פינסק","dt":"תרצח","dp":"ירושלים","b":"עלה בשנת תרמג, עם אביו ואחיו, והיה ראש ישיבת תורת חיים שנוסדה על ידי אחיו ר יצחק."},{"i":17317,"n":"וינוגרד, שמעון מירושלים","f":"יצחק","bp":"ירושלים","dp":"ירושלים","b":"רב באהיא, מרביץ תורה ב\"תורת חיים\" בירושלים-תרצב, רב בניו יורק. פרסם מאמרים ב\"היכל התורה\" - נ\"י תרצג."},{"i":17318,"n":"וינוגרדוב (וינשטין), יוסף","f":"ישראל ברוך מליאזני","bt":"1866","bp":"וילנא","dt":"1937","dp":"תל אביב","b":"משורר אצל חזנים בוילנא ואודסה. תלמיד ביהמ\"ד למורים בוילנא. למד באיטליה מוסיקה והיה זמר באופרה במוסקה ופטרבורג וחביב על הצאר ניקולאי השני. סירב להמיר את דתו, ועבר לאופרה של מילנו. העלה אופרה \"ריגולטו\" באידיש. היגר לארה\"ב והפך לחזן אדוק וירא שמים."},{"i":17319,"n":"וינזר, מרדכי מאנדנברג","b":"פרסם מאמרים ב\"דבר בעתו\" - פאקש תרסט."},{"i":17320,"n":"וינט, זלמן מאיטליה","k":"האשל הגדול בטערוויז","b":"מגדולי חכמי איטליה-ר\"י. סידר מנהגים וסליחות ליהדות איטליה."},{"i":17321,"n":"וינטורה - משפחה","b":"משפחה יהודית באיטליה, בבלקן, ובארץ ישראל. פירוש השם וינטורה = מזל באיטלקית, (יש הסבורים כי פירוש השם וינטורה הוא ציון). מוצא המשפחה מהעיר טיבולי שליד רומא, לשם גלו היהודים לאחר החורבן, וגורשו משם ע\"י האפיפיור פיוס החמישי (כנזכר ב\"עמק הבכא\"). חלק מבני המשפחה כינו עצמם וינטורה מטיבולי. משם נפוצה המשפחה באיטליה, בשלוניקי, ניקופול, טבריה, מחוז דלמציה רגוזה (לשעבר איטליה, וכיום קרואטיה)"},{"i":17322,"n":"וינטורה, אברהם מרוסג'וק","b":"מאנשי קהלת רוסג'וק-תקס בערך."},{"i":17323,"n":"וינטורה, אליהו מוידין","f":"אברהם","k":"בעל כוכבא דשביט","bt":"תקיא - בערך","bp":"אישפאלאטו","b":"תלמיד וחתן אחיו ר דוד שבתי וינטורה. רב בוידין-תקלט, ברח לרוסג'וק-תקס, מו\"צ ומרביץ תורה באישפלטרו-תקס. בשליחות לגיוס כסף להדפסת ספרו \"כוכבא דשביט\"-תקנט, בספאלאטו, ובראגוזה."},{"i":17324,"n":"וינטורה, אלעזר מאיטליה","f":"שמואל","b":"מחכמי פיררה-ש'. נזכר בספרי חכמי דורו."},{"i":17325,"n":"וינטורה, חיים","b":"חתנו ותלמידו של ר חיים אבולעפיה בעל \"עץ החיים\" על התורה. עלה עם חותנו מאזמיר לטבריה (תפ?), בשנת תקא בשליחות טבריה לאיטליה, ובכל מקום יסד קופות מיוחדות לטבריה על דעת פקידי קושטא, אולי הוא המביא לדפוס במנטובה את ספרו של ר יעקב בירב \"זמרת הארץ\", הוא כתב הקדמה לספר חותנו \"עץ החיים\" אזמיר תצד, חדושי תורה שלו מובאים בספר \"דברי דוד\" לר דוד מילדולה."},{"i":17326,"n":"וינטורה, יהושע רפאל מוידין","b":"דיין בוידין-שנות ה-ש'."},{"i":17327,"n":"וינטורה, יוסף מטיבולי","b":"רב בטיבולי-ליד רומא, עבר לניקופול לאחר גזרות האפיפיור פיוס החמישי. בניו: ר רפאל, ר משה. (מצאצאיו קבלו את השם טיבולי במקום וינטורה)."},{"i":17328,"n":"וינטורה, יצחק מפיסרו","b":"רב בפיסרו-איטליה. תשובה ממנו ב\"שלום הבית\" לר מנחם קאזיס."},{"i":17329,"n":"וינטורה, ישמעאל אליהו מאיטליה"},{"i":17330,"n":"וינטורה, מימון","f":"יצחק","k":"בעל אמרות טהורות","b":"תלמיד ר יהודה ביבאס מקורפו."},{"i":17331,"n":"וינטורה, משה מטיבולי","f":"יוסף","k":"בעל ימין משה","dt":"שפד - אחרי","b":"שו\"ב בניקופול, מלמד בסיליסטרה(=אישטריאה), עלה לירושלים-שנא דרך מצרים - חתם שם על פסק של ר יוסף ן לב, ישב אצל ר זכריה גטניו במצרים, ולמד שם אצל ר אברהם יצחקי, וכיהן כשו\"ב בירושלים. בשליחות באיטליה. חיבר \"ימין משה\" מנטובה שפד."},{"i":17332,"n":"וינטורה, רחמים אברהם מסופיה","f":"שבתי דוד-נהר שלום","bt":"תקיט - בערך","bp":"ספלאטו(=ספליט)","dt":"תקפט - טז אד\"א","dp":"פיליבי או איסקופיה","b":"עבר עם אביו לוידין-תקלט, תלמיד דודו ר אליהו וינטורה. רב הקהלה הספרדית בבוקרשט (הנקראת \"לועזים\"), ניש על מקום ר יהודה עלי בעל \"קמח סולת\", סופיה-תקע על מקום ר חיים יעקב משה הלוי, עבר בפיליפופולי-תקפב בדרכו לארץ ונשאר שם לכהן (לא יכל להמשיך בדרכו בגלל מרד היונים) כרב כ-8 שנים ור יעקב פינץ מרוסג'וק על מקומו אחריו או ר משה יצחק הלוי."},{"i":17333,"n":"וינטורה, רפאל מניקופול","bp":"טיבולי","b":"הגיע עם משפחתו מטיבולי-איטליה לניקופול. תלמיד ר יוסף מזרחי, ורב וראש ישיבה בניקופול על מקום רבו אחריו, ור יהודה בנבנישתי משלוניקי על מקומו אחריו."},{"i":17334,"n":"וינטורה, שבתי דוד מאיטליה","f":"אברהם","k":"בעל נהר שלום","r":"דיין באיספאלטרו שבאטליה","bt":"תצב","bp":"אישפאלטרו (=ספליט)","dt":"תקנט - לפני","dp":"וידין","b":"תלמיד ר דוד פארדו, רב באישפלטרו(=ספליט קרואטיה)-תקלג על מקום רבו (שעבר לסרייבו), יצא בדרכו לארץ ועבר דרך וידין ונשאר לכהן כרב בוידין-בולגריה-תקלט. חיבר גם ככבא דשביט, ויצא לאור ע\"י ר אליהו אחיו וחתנו של ר שבתי. מתלמידיו ר אברהם יונה שחיבר הקדמה לספר רבו. בנו ר רחמים אברהם.","bk":[["נהר שלום",""],["נהר שלום","מפרשי שו\"ע"],["ככבא דשביט",""],["נהר שלום – או\"ח",""]],"e":"תצ\"ב~-תקנ\"ט~"},{"i":17335,"n":"וינטורה-בואינה, גבריאל","b":"תיווך בין תורכיה לספרד-שעד."},{"i":17336,"n":"וינטורי, יחיאל מרומאניה","b":"משורר ופייטן ברומאנייה בזמן ר נתנאל טרבוטו. חברו של ר אליה מריקנטי."},{"i":17337,"n":"וינטר, אליעזר משטמפן","f":"יוסף משה מהאליטש","bt":"תקעא","bp":"האליטש","dt":"תרנג - כב אלול","dp":"שטמפן","b":"נכד ר ישעיה דיין מהאליטש. תלמיד החת\"ס (החת\"ס בירך את זקנו בבן וקרב את ר אליעזר כשלמד אצלו). חתן ר אליעזר שטרסר מעיר חדש (בהמלצת החת\"ס שלא חשש לצוואת רבי יהודה החסיד בענין שם אבי הכלה כשם החתן). רב ברייטץ-תרא, שטמפן-תריב על מקום ר משה מרדכי בנט (ביניהם כיהן באופן זמני הדיין ר גומפל גיירינג)."},{"i":17338,"n":"וינטר, דב בריש מחורוסטקוב","f":"יוסף","k":"בעל כורת דבש","bt":"תרכט","dt":"תרצט","b":"רב בחרסקוב(=חרסטקוב)-גליציה-תרנט. רב יוצאי גליציה בוינה-תרסח, ושוב בחרסקוב. חיבר \"כורת דבש\" \"צפיחת בדבש\" בכתב יד. פרסם מאמרים ב\"בית ועד לחכמים\" - לונדון תרסב, \"ועד חכמים\"."},{"i":17339,"n":"וינטר, חיים יהודה ליב","f":"מרדכי"},{"i":17340,"n":"וינטר, מנחם מנדל מאויהל","b":"דומ\"צ באויהעל-תרמ\"ב"},{"i":17341,"n":"וינטר, מרדכי","f":"יצחק מטיסמניץ"},{"i":17342,"n":"וינטר, משה מחרסקוב (רוסקוב)","b":"רב בחרסקוב-תרסז (רוסקאוו-תרע)."},{"i":17343,"n":"וינטר, פיבש (פייש) מהאליטש","f":"יוסף משה מהאליטש","b":"נכד ר ישעיה דיין מהאליטש. רב בהאליטש-תריד. אחיו - ר אליעזר משטמפן."},{"i":17344,"n":"וינטרוב, אברהם משה ממרקישוב","k":"אדמור ממרקישוב","dt":"תרעה - יח שבט","b":"תלמיד ר יהודה ליב ור צדוק הכהן מלובלין. אדמור-תרס על מקום רבו בלובלין, עבר לזליחוב, מרקישוב, וארשא. מתולדותיו ב\"מלאכי עליון\"."},{"i":17345,"n":"וינטרוב, אהרן יהודה מליסוביק","f":"יעקב יצחק","bt":"תרסו","bp":"ליסוביק","b":"תלמיד זקנו - ר גרשון מוניש מליסוביק. חתן הרב מלנצינה בעל \"עמק אברהם\". נסמך מאת: האדמור מסוקולוב, הרחי\"נ זילברברג, רח\"ל גינצבורג משדליץ, מהרש\"ד כהנא, רצ\"י מיכלזון, ועוד. רב בליסוביק-תרפט, עלה לארץ-תרצו וכיהן כרב בקרית יוסף."},{"i":17346,"n":"וינטרוב, דב מבני ברק","b":"פרסם מאמרים ב\"תפארת ציון\" - בני ברק תשב - קובץ תלמידי ישיבת \"תפארת ציון\"."},{"i":17347,"n":"וינטרוב, יהושע עוזיאל ממרקישוב","f":"אברהם משה ממרקישוב","k":"אדמור ממרקישוב","dt":"תש..","b":"אדמור ממרקישוב בוארשא. נספה בשואה. חתנו ר משה זאב שצדרוביצקי מביאליסטוק - נספה בשואה."},{"i":17348,"n":"וינטרוב, יעקב דוד מרדומסק","f":"יצחק איזיק יום טוב","k":"בעל פירוש לתהלים","bt":"תרי","dt":"תרפד - כ ניסן","b":"מקורב לגדולי האדמורים ובהם ר מנחם מנדל מוורקא, ר בריש מביאלא, בעל ישמח ישראל מאלכסנדר, ר אהרן צבי מביאלא, ר מנדל מסטריקוב. מחסידי סטריקוב-תשם, ונאמן ביתו של האדמור מסטריקוב - ר אברהם לנדא. מלמד תורה וחסידות ואף הגישו לו קוויטלאך (למרות שלא שימש כרב או כאדמו\"ר).","bk":[["אבני המקום - דברים המושכים לבו של אדם לשמים",""],["אמרי דוד - תהלים",""],["מטע אהלים - אמרות טהורות",""],["מימי הירדן - רעיונות נשגבים",""],["מכלל מציון - דברים המושכים לבו של אדם לשמים",""],["נאוה תהלה - הגדה של פסח",""]]},{"i":17349,"n":"וינטרוב, ישראל יצחק מוארשא","k":"בעל גרש כרמל","b":"מו\"ץ בוארשא. חיבר \"גרש כרמל\" על רש\"י לתורה - וארשא תרמה."},{"i":17350,"n":"וינטרוב, נח גד מרדומסק","f":"יעקב דוד","b":"חתן ר שמואל צבי טיטלבוים בעל \"הנשאר בציון\". הו\"ל ספר חותנו - \"הנשאר בציון\" ירושלים תשג, והוסיף סיפורים על גדולי החסידות ששמע מחותנו."},{"i":17351,"n":"וינטרוב, שלמה מהורודנקה","b":"מחכמי הורודנקא. תשובות אליו בשות מהרשם."},{"i":17352,"n":"וינטרוב, שמואל מקרלין","b":"רב ור\"מ בקרלין-תר\"צ"},{"i":17353,"n":"וינטרניץ, יעקב מפרשבורג","b":"תלמיד בישיבת פרשבורג בזמן מלחה\"ע ה-I."},{"i":17354,"n":"וינטרניץ, משה דוד מסטמר","bt":"תרלך-ג","bp":"מארמארוש","dt":"תשד - יב סיון","dp":"אושוויץ","b":"תלמיד ר מנחם מ נדל פאנט בדעש, ה\"ייטב לב\" בסיגט, ועוד. חתן ר בנימין זאב מנדלבוים מסטמר. דיין בסטמר-תרנה ואח\"כ ראב\"ד על מקום חותנו אחריו. נספה בשואה. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב."},{"i":17355,"n":"וינטשבסקי, מוריס (ליפא בן ציון","f":"זיסל נובחוביץ","k":"בן נץ","bt":"1856","bp":"יאנובה","dt":"1932","b":"משורר בקובנא, וילנא, הגיע לאוראל, קניגסברג ושם יסד את הירחון \"אספת חכמים\" וחתם בשם \"בן נץ\" - חלוץ העתונות הסוציאליסטית באידיש. היגר לארה\"ב-1894 והיה עורך \"אמת\". חיבר ספורים משלים ופיליטונים, ותרגם לאידיש יצירות שונות. קובץ כתביו נדפס - 1927."},{"i":17356,"n":"ויניג, וולף מפפד\"מ","f":"אברהם","dt":"תקנד - ג אדר","dp":"פפד\"מ","b":"מחכמי פפד\"מ."},{"i":17357,"n":"ויניג, חיים מיבלונוב","b":"אב\"ד יבלונוב (והיה מחלוקת עם ר אהרן לנדא על הרבנות). תשובות אליו שות מהרי הכהן."},{"i":17358,"n":"ויניג, נפתלי יעקב מפשמישל","f":"דוד","k":"בעל משפיל גאים","bt":"תקץ","dt":"תרמו","b":"דיין בפשמישל על מקום אביו. חיבר \"משפיל גאים\" פשמישל תרלג, ועוד."},{"i":17359,"n":"ויניצקי, דב","f":"חיים שאול","bt":"1894","bp":"בוטרימנץ","dt":"1941","b":"תלמיד ישיבה, טכניון בוארשא. מורה ומנהל בי\"ס \"תרבות\" בבוטרימנץ. נספה בשואה."},{"i":17360,"n":"ויניק, ישראל משה","b":"תשובה אליו בשו\"מ."},{"i":17361,"n":"וינישתי ן, רחמים שניאור מי-ם","dt":"תריא","dp":"אלכסנדריה","b":"מחכמי ירושלים. בשליחות-תריא בצפון אפריקה ונפטר בדרכו במצרים. נספד ב\"מקוה מים\" לר אהרן עזריאל."},{"i":17362,"n":"וינלז, דוד מרדיכוב","b":"רב ברדיכוב-תרמה. מחכמי ברודי ולמברג-תרפד. סידר לדפוס את כתבי המהרש\"ק."},{"i":17363,"n":"וינמן, בנימין מוארשא","b":"תלמיד ישיבת \"בית שמואל\" בוארשא. פרסם מאמרים ב\"בית שמואל\" - וארשא תרצו."},{"i":17364,"n":"וינמן, יחיאל מקולבסוב","f":"יהושע","k":"חיאל שועס","bt":"תרכה","bp":"קולבסוב","dt":"תרצה","b":"חתן ר פנחס מברנוב. דיין בקולבסוב. התישב בקראקא-תרעט."},{"i":17365,"n":"וינמן, צבי הירש מפיאסק","b":"אב\"ד פיאסק (האם = פיעסק)"},{"i":17366,"n":"וינמן, שמואל מדווה","dt":"תש - אייר","b":"רב בכפר מארוש-איליה-ליד דווה כ-30 שנה."},{"i":17367,"n":"וינעקאר, יחיאל יוסף","b":"רב-שנת תר\"ל"},{"i":17368,"n":"וינעקאר, משה הלוי משומסק","f":"יחיאל יוסף וינקור","bt":"תרכ","b":"רב בשומסק-ווהלין-תרן."},{"i":17369,"n":"וינפלד אברהם בן יחזקאל שרגא","f":"יחזקאל שרגא מפריסטיק","k":"בעל אבן יחזקאל","bt":"תרץ - בערך","dt":"תשמז","b":"ניצל מהשואה בגיל יד. רב במונסי. חיבר \"אבן יחזקאל\" ניו יורק תשי, \"שובה ישראל\".","bk":[["אבן יחזקאל",""],["יהי אור",""],["לב אברהם",""],["שובה ישראל",""]]},{"i":17370,"n":"וינפלד, דוד יואל מסאנוק","f":"שמואל צבי","bt":"תרלה","dt":"תשה","b":"חתן ר יהודה כץ ראבד סאנוק. מחכמי סאנוק ומדפיס. עלה לירושלים והעביר לשם את בית הדפוס ובניו הקימו ממנו את הוצאת \"אשכול\"."},{"i":17371,"n":"וינפלד, יחזקאל מזמיגרוד","b":"רב בזמיגרוד-תרם."},{"i":17372,"n":"וינפלד, יעקב יצחק מקמינקא","b":"בה מקראקא לכהן כרב בקמינקא. נפטר לפני השואה."},{"i":17373,"n":"וינפלד, יעקב שאול מסאנוק","f":"דוד יואל","k":"בעל משנת יעקב","bt":"תרסז","bp":"סאנוק","b":"עלה לירושלים-תרצו, והקים עם משפחתו את הוצאת \"אשכול\". חיבר \"משנת יעקב\" ירושלים תשלח."},{"i":17374,"n":"וינפלד, ליפמן משעבעש","bp":"שעבעש","dt":"תרטז - טו אלול","dp":"פרשבורג","b":"תלמיד הכת\"ס, ונפטר בצעירותו."},{"i":17375,"n":"וינפלד, נפתלי מקראקא","b":"נכד ר נפתלי מרופשיץ. סופר סתם מחכמי קראקא-תרעג."},{"i":17376,"n":"וינפלד, פנחס מלבוב","b":"מזכיר קהילת לבוב-לפני השואה."},{"i":17377,"n":"וינפלד, שמואל דוד מגורליץ","f":"אשר ישעיה","k":"בעל מאמרי מדע וחקירה","bt":"תרם","bp":"גורליץ","dt":"תשג","b":"חסיד צאנז. חתן ר יוסף רובין מקירעמא. מחכמי קאשוי, עלה לירושלים-תרצג - והיה שם מחוגי הקנאים. חזר לקאשוי-תרצו. נספה בשואה. חיבר \"מאמרי מדע וחקירה\" מונקטש תרצג."},{"i":17378,"n":"וינפלד, שמואל צבי מגורליץ","f":"יוסף חיים","bt":"תרטו","bp":"גורליץ","dt":"תשב","dp":"ירושלים","b":"רב בסטרופקוב. עלה לירושלים. מתורתו ותורת בנו בספר \"בית שמואל ודוד\" ירושלים תשו. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב."},{"i":17379,"n":"וינפלד, שרגא פיבל מסאנוק","f":"דוד יואל","bt":"תרסה","b":"עלה לארץ-תרפז והיה חבר קיבוץ ידי משה. חזר לגליציה ועלה שוב בתרצח. ועסק בירושלים בהדפסת ספרים."},{"i":17380,"n":"וינצימר, מרדכי יצחק מירושלים","f":"חיים יהודה-פרי חיים","k":"בעל תשועת מרדכי","b":"מחכמי ירושלים. חיבר גם \"שדה בוכים\" - תרכג."},{"i":17381,"n":"וינקופף, יעקב דוד מאמשטרדם","bt":"תרד","b":"תלמיד ביהמ\"ד לרבנים באמשטרדם, בעל תואר ד\"ר. רב ודיין באמשטרדם-תרלו."},{"i":17382,"n":"וינקופף, יצחק יוסף בן ציון","k":"בעל דרכי הנסיגה","b":"מחכמי אמשטרדם ומלמד ב\"עץ חיים\" באמשטרדם."},{"i":17383,"n":"וינקלר, חיים צבי מראצפרט","k":"בעל חוקי חיים-תרנז","dt":"תרנט - כו תמוז","dp":"סעליש","b":"רב בראצפרט, עזב בגלל מחלוקת ונדד במקומות שונים. היה כפר ואמושפרץ-תרמג, מארגרטן-תרן ומלמד שם לתלמידים, עבר לסעליש-תרעו. (יש רושמים פטירתו - תרעו - כה תמוז)"},{"i":17384,"n":"וינקלר, יעקב מנאגי-קאניזא","dt":"תשד","b":"רבה האחרון של הקהילה הניאולוגית בנאגי-קאניז'א. חיבר מאמר על תולדות השבועה היהודית - בהונגרית-1919, פרסם מאמרים ב\"ז'ידו סאמלא\". היה חבר במועצת העיר. נספה בשואה."},{"i":17385,"n":"וינקלר, יצחק דוד מהיבניב","f":"שלמה","k":"בעל רכב על דבר אמת","b":"עלה לירושלים עם אביו אולי בתרי. חיבר \"רכב על דבר אמת\" - \"גבולי שבת\" - ירושלים תרפו."},{"i":17386,"n":"וינקלר, מיכאל שלום מירושלים","k":"בעל טוב טעם","r":"מיכאל שלום איש ירושלים","bt":"תרכה או תרל","bp":"ירושלים","dt":"תרצב - כא תמוז","dp":"ניו יורק","b":"תלמיד ונכד ר מאיר מיאסי בירושלים, ר מאיר אוירבך, ר חיים זוננפלד. עזב את ירושלים ונסע לגרמניה ולמד בביהמ\"ד לרבנים בברלין ובעל תואר ד\"ר. רב בברלין-תרנב, שרלוטנבורג-תרסז, מגנצא-תרסט, וויסבאדן-תרעא, קופנהגן-תרעד. בשליחות בניו יורק ושם נפטר. חיבר \"טוב טעם\" פפדמ תרסח, \"משברי ים\" ירושלים תשלו. נסמך מאת: ר בנימין פרידמן מגרידיטין, ר נחום אורי גליס מסלטוינה, ר אליעזר ליפשיץ מזדונסקא ואליא, ר\"ז במברבגר מקיסינגן.","bk":[["טוב טעם – טעם כעיקר",""],["משברי ים – סנהדרין",""]]},{"i":17387,"n":"וינקלר, מרדכי יהודה ליב מברזוב","f":"נפתלי","k":"בעל לבושי מרדכי-תרעב","r":"חמיו של המהרי\"ץ דושינסקי","bt":"תרה","bp":"לעפנטוויץ-מחוז נייטרא","dt":"תרצב - יז תמוז","b":"מגדולי פוסקי דורו. תלמיד ר וולף תרצ'ס בטאפלטשאן, ר מרדכי יהודה גליק מיאהנא, והכת\"ס, ובישיבת ר יצחק אהרן לנדסברג מגרוסורדין שהיה רבו המובהק. חתן ר מנחם מנדל קרויס מבאנפי הוניאד ועבר לשם. רב במעזא טעלעגד-תרלד - שהיה במחוז של רבו, רב בברעזבא-תרלט וראש ישיבה שם, רב וראש ישיבה במאד-תרסא וראש הישיבה שם, ור חיים צבי ארנריך על מקומו אחריו. מתלמידיו ר ישעיה זילברשטין מוויצען, ר שמעון גרינפלד מסנמיהאי. פעל למען העגונות אחרי מלחה\"ע ה-I. חתנו - ר יוסף צבי דושינסקי מגלנטה וירושלים. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב, פרסם מאמרים ב\"הלכה למעשה\" - דעש תרצג. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"יגדיל תורה\" - ברלין-קראקא תרנא, \"כנסת חכמים\"- בורגו-פרונד - ס. וואראהל תרסה, \"הנשר\" - טירנוי תרצג-תשד. חיבר גם: \"ישב מצרף\", שו\"ת. חתנו - ר יוסף צבי דושינסקי מחוסט וירושלים.","bk":[["לבושי מרדכי","שו\"ת - אחרונים"],["לבושי מרדכי – שו\"ת",""]]},{"i":17388,"n":"וינקלר, משה","b":"רב במרטינסברג-תרע\"ד"},{"i":17389,"n":"וינקלר, נפתלי מסיגט","dt":"תשד","b":"תלמיד ר אליעזר ליפא הורביץ בעל \"הרי בשמים\" - שהזכירו בספרו. עבר מגליציה לכהן כדיין ורב בקהילה הספרדית בסיגט - לאחר הפילוג בקהילה - כ-50 שנה. נספה בשואה. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":17390,"n":"וינר, אברהם (פסלבורג)","f":"אשר אנשיל מפרג","dt":"תעו - כו אדר","b":"בנו - ר אשר אנשל מוינר (יש בלבול בינו לבין ר אברהם וינר ממישקולץ)."},{"i":17391,"n":"וינר, אברהם (פסלבורג) ממישקולץ","f":"אשר אנשיל","dt":"תקצב - יב שבט","dp":"מישקולץ","b":"חתן הגביר ר ליב באשאן מעיר חדש. רב בעיר חדש(=ניישטטל, נאוי-מעסטא), מישקולץ-תקסא על מקום אביו ורצו למנות את גיסו ר צבי מאסאד על מקומו (ולא ברור אם אכן התקבל). הסכים על \"דעת ישכר\", \"בית יצחק\", \"זרע שמואל\", \"אהל ישכר\". מבניו: ר דוד ממישקולץ. (יש בלבול בינו לבין ר אברהם וינר-פסלבורג)"},{"i":17392,"n":"וינר, אברהם אבא","b":"בנו - ר יעקב חותנו של ר דב (נייהוף?)."},{"i":17393,"n":"וינר, אברהם יעקב מירושלים","b":"תלמיד ישיבת \"ר ישראל אמריקנר\" בירושלים. פרסם מאמרים ב\"קובץ חדושי תורה\" - ירושלים תרצה."},{"i":17394,"n":"וינר, אברהם מיכל מסוביינישוק","bt":"תרמח","dt":"תשא","b":"רב ברקישאק, רבה האחרון של סובנישאק(=סוביינישוק). נספה בשואה. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":17395,"n":"וינר, אברהם מלנצהוט ויזלוביץ","bp":"לנצהוט","dt":"תשא","b":"רבה של יזלוביץ-תרפט, צורטקוב-תרצו. נספה בשואה. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"הירדן\" - רישא תרץ."},{"i":17396,"n":"וינר, אהרן מתתיהו מגרוסורדין","f":"שרגא פיבוש מגרוסורדי","b":"רב בגרוסורדין-תקפג על מקום אביו."},{"i":17397,"n":"וינר, אלחנן משאט","dt":"תשג","b":"רבה האחרון של שאט-ליטא. נספה בשואה."},{"i":17398,"n":"וינר, אליהו יוסף מאנטורפן","f":"יהושע","bt":"תרלא","bp":"מומנהיים-אלזאס","b":"תלמיד ביהמ\"ד לרבנים בברסלוי. נסמך מאת: ר\"ר וייל משטרסבורג, ר א' אורי ממיץ, ר\"י וייל מקולמר. חתן ר משה להמן מאברנהיים-אלזס. רב בדירמנאך-אלזס, פלסבורג-לותרינגן, אנטורפן-תרסה. פרסם מאמרים בשפות שונות, הו\"ל פירוש הרמב\"ם על מסכת ע\"ז."},{"i":17399,"n":"וינר, אשר","k":"בעל אור הישר ראה: וינר שרגא צב","b":"רב בפראדן"},{"i":17400,"n":"וינר, אשר אנשיל ממישקולץ -הנכד","f":"שמעון או אברהם פסלבו","bt":"תס","dt":"תקס - טז אייר","dp":"מישקולץ","b":"נכד ר אשר אנשל וינר מפרג (או ר שמעון וינר), מצאצאי בעל צמח צדק. ברח מפרג בגלל הלשנה והגיע לאויבן (לפי ברוין היה בשליחות בוינה ונאלץ לברוח בגלל מטרוניתא אחת וכשהגיע לאויבן פגש את מהר\"ם מינץ שיעץ לו לשנות שמו ל\"בן פורת\"(=יונגרייז). רב בסערעד-תקב, רבה הראשון של מישקולץ-תקך ומחוז בארשאד-תקכח (קאמידאט בארשאד). הסכים על \"זרע שמואל\" - וינה תקעו. נפטר בגיל 100!. בניו: ר שרגא פיבש (פייש) מגרוסורדין, ר אברהם וינר-פסלבורג. חתניו: ר שמואל הלוי יונגרייז מפאפא, ר משה נתן שפירא מאלמאשד, ר צבי יצחק הרשפלד. נספד ע\"י חברו - ר יונתן איבשיץ. (לפי ברוין היה בנו של ר אברהם וינר-פסלבורג שנפטר בשנת תעו)."},{"i":17401,"n":"וינר, אשר אנשיל מפרג - הזקן","f":"מיכל","dt":"תעד - ה תמוז","dp":"פרג","b":"נכד ר שמעון וינר, ומצאצאי בעל צמח צדק. חתן ר אליעזר מנדל פאנטא מניקלשבורג. ראב\"ד מו\"ש בפרג. בניו: ר זלמן פסלבורג, ר אברהם פסלבורג. (יש המחליפים בינו לבין נכדו ממישקולץ)."},{"i":17402,"n":"וינר, דב בר ממגנצא","dt":"תצב - ד טבת","b":"רב בווסטהאפן,מגנצא"},{"i":17403,"n":"וינר, דוד (פסלבורג) ממישקולץ","f":"אברהם מעיר חדש","dt":"תריד - כו חשון","dp":"באלאשא-יארמוט","b":"דומ\"צ במישקולץ-תר. נזכר ב\"תומך כבוד\" לר יונתן אלכסנדרזון."},{"i":17404,"n":"וינר, יוסף מפרשבורג","f":"שמעון","b":"חתם על תקנות הח\"ק בפרשבורג-תקס."},{"i":17405,"n":"וינר, יוסף מרדכי מסטריזוב","b":"חסיד צאנז. רב בסטריזוב-תרלט."},{"i":17406,"n":"וינר, יוסף צבי","f":"ישעיהו טוביה","k":"בעל ארץ הבחירה","bt":"תרצו","bp":"רחובות","dt":"תשעב - כג אייר","dp":"ירושלים","b":"תלמיד ישיבת חברון, היכל התלמוד. רב בגן יבנה, נס ציונה על מקום ר ישראל בארי. חיבר ספרים רבים.","bk":[["ארץ הבחירה","סדר זרעים"]]},{"i":17407,"n":"וינר, יעקב","f":"אברהם אבא","b":"חתן ר חיים פילצר. חתנו - ר דב (נייהוף?), ר חיים אפל."},{"i":17408,"n":"וינר, יעקב מפרג","f":"מרדכי מהמבורג","k":"בעל קול קול יעקב","dt":"תקב - טו חשון","dp":"פרג","b":"ראב\"ד בפרג. חיבר \"קול קול יעקב\" פרג תקסב."},{"i":17409,"n":"וינר, יעקב משטיינמנגר","f":"שמשון","b":"קבל תעודת חבר-תריא מאת ר יהודה ליב קניגסברג משטיינמנגר. גיסו - ר שמואל בורגר בעל \"שבעה עינים\"."},{"i":17410,"n":"וינר, יצחק איצק מאורמין","f":"שמעון וינר","dt":"תרכו - ד אלול","b":"רב באורמין-הונגריה. פרסם מאמרים ב\"אוצר חכמה\" - לבוב תרך, \"שומר ציון הנאמן\" - אלטונא תרו-תרטז."},{"i":17411,"n":"וינר, ירמיה מבוריסוב","b":"מרביץ תורה בבוריסוב-תר\"כ"},{"i":17412,"n":"וינר, ישעיה","f":"שמחה","k":"בעל בגדי קדש","b":"רב-שנת תקך. חיבר גם \"בגדי ישע\"?"},{"i":17413,"n":"וינר, מאיר אליהו מויזון","f":"יהודה יעקב","k":"בעל רב טבחיא","bt":"תרכו","b":"רב בוויזון-פלך קובנא-תרן על מקום ר חיים דון יחיא, יעדוובנה(=יעדוואבנא)-פלך לומזה-תרע. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":17414,"n":"וינר, מיכאל מאירשא","f":"אברהם מאירשא","bp":"אירשא","b":"תלמיד הכת\"ס. נסמך להוראה-תרלב ע\"י רבני אירשא והסביבה."},{"i":17415,"n":"וינר, מיכל (מפרג?)","b":"חתן ר אליעזר בן טודרוס-חתנו של ר חיים בן סיני מקעלן. בנו - ר אשר אנשל וינר מפרג(-נפטר תעד)."},{"i":17416,"n":"וינר, מרדכי מפרשבורג","k":"בעל מאמר מרדכי","bp":"פרג","dt":"תרפז - ל שבט","dp":"פרשבורג","b":"תלמיד הכת\"ס, ור חיים סופר מבודפשט. נכד ר ישעיה וינר מפרג בעל \"בגדי ישע\". חתן ר ישראל איסרל מאיער מפרשבורג. חיבר \"מאמר מרדכי\" בתוך \"מצות משה\" שהו\"ל, והו\"ל \"שערי תשובה\"."},{"i":17417,"n":"וינר, משה יונה מסלנט","dt":"תשג","b":"רב בסאלאט. נספה בשואה."},{"i":17418,"n":"וינר, משה מברזען","dt":"תשב","b":"רב בברזן שהתפרנס מעסקיו. נספה בשואה."},{"i":17419,"n":"וינר, משה מלבוב","f":"מנחם מנדל מסוקולוב","b":"משפחה של למדנים ושדכנים שעברו מסוקולוב ללמברג. דיין בלמברג."},{"i":17420,"n":"וינר, נח מנובגרד","f":"ישראל יעקב מטראב","bt":"תרה","b":"תלמיד ישיבת וולוזין, תלמיד ר ברוך מרדכי ליפשיץ מנוברדוק, כולל קובנא. חתן הגביר ר יהודה בן יצחק בונימוביץ מאשמינא ועבר לשם. רב בוועוויי(=וועווייא)-פלך וילנא-תרלז, נאוואגראד(=נובוגרד)-פלך לומזה-תרמז בהמלצת ר יצחק אלחנן מקובנא. נסמך מאת: המלבי\"ם, ר יעקב אליהו מסלובודקא. חתניו: ר שמואל שפירא מסאהל, ר חיים ברל מלינארציק מלומזה, ר יוסף אריה נענעדיק מסאחיוואלי."},{"i":17421,"n":"וינר, פנחס מדרושקופל","f":"משה יוסף","bt":"תרמג","b":"תלמיד דודו ר שמעון פלאצק, ור יעקב מרדכי מבילגוריא, רב בדרושקופל(=דרושקיפאליא)-ווהלין-תרסו."},{"i":17422,"n":"וינר, צבי דוב מנייטרא","f":"שמעון וינר","b":"דומ\"צ בנייטרא-תר\"י"},{"i":17423,"n":"וינר, רפאל מארה\"ב","b":"רב בברונקס,עלה לא\"י-תרצ\"ב"},{"i":17424,"n":"וינר, שמואל","f":"ירמיה וינר","k":"בעל קהלת משה","bt":"תרכ","dt":"תרפט-תרצב","b":"חובב ספר וביבליוגרף","bk":[["רשימת הגדות",""]]},{"i":17425,"n":"וינר, שמעון מלאשברין","bt":"תקכט","bp":"מטרסדורף","dt":"תרלא - כח שבט","dp":"לאשברין","b":"תלמיד החת\"ס, ור ישכר בר בלוך ממטרסדורף, ור מרדכי בנט. רב במטרסדורף, סנט גרוד-תקעד, לאשברין-תקצד ובנו ר יוסף על מקומו אחריו. מחדושיו ב\"אבני נזר\" (בתוך ספרי צאצאיו \"דברי שלמה\" ו\"דברי יוסף\"). עוד מבניו: ר יצחק, ר צבי דב."},{"i":17426,"n":"וינר, שמעון מפרג","f":"אברהם פסלבורג","b":"מגדולי פרג-ת\"ק"},{"i":17427,"n":"וינר, שמעון מקריפטש","b":"חתן ר יחיאל מיכל היבנר מניזניב בעל \"משכנות הרועים\". רב בקריפשט-תרע."},{"i":17428,"n":"וינר, שרגא פייש מגרוסורדין","f":"אשר אנשל ממישקולץ","dt":"תקסג - ו אייר","dp":"גרוסורדין","b":"חתן ר מתתיהו ניגרשל מפרג בעל \"באר שבע\". רב בגרוסורדין-תקנט ובנו ר אהרן מתתיהו על מקומו אחריו."},{"i":17429,"n":"וינר, שרגא צבי פייש מפראדן","b":"רב בפראדן-תר\"נ"},{"i":17430,"n":"וינרב, אהרן זאב מדולינא","f":"[יעקיל]","b":"רב בדולינא. תשובה אליו בשו\"מ."},{"i":17431,"n":"וינרב, אשר ענזיל מסוכוסטוב","b":"אב\"ד סוכוסטוב-תרלג."},{"i":17432,"n":"וינרב, ברוך שלמה מבוסק","f":"מרדכי מראדוש","bt":"תקס","dt":"תרם","b":"רב בבוסק."},{"i":17433,"n":"וינרב, גרשון מניו יורק","k":"בעל תמים מאירים","b":"רב בניו יורק. ?? לא באוצר ??"},{"i":17434,"n":"וינרב, זאב אהרן מניזנוב","f":"שמואל זנויל","k":"בעל אספרה כל נפלאותי","bp":"ניזנוב","b":"תלמיד ר יחיאל מיכל היבנר מניזנוב. חתן ר נחום מאיר הלר. ניצל מהשואה ופגש בגרוסורדין את אשתו בנו ובתו. עבר לפריז, ולניו יורק שם כיהן כנשיא כולל גליציה. חיבר \"אספרה כל נפלאותיך\" - בסוף \"אמרי חיים מבורשטין\" - טוסון-אריזונה תשנא."},{"i":17435,"n":"וינרב, חיים זאב מסאסוב","f":"אריה ליב","bt":"תרם","dt":"תשג","b":"רב בסאסוב, קמינקא-תרפה. חיבר ספרים ושו\"ת עבור אחרים ולא נזכר שמו עליהם. נספה בשואה. פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":17436,"n":"וינרב, חיים מראווא","b":"רב בראווע-תק\"ז"},{"i":17437,"n":"וינרב, יהודה ליב מברנוב","f":"אפרים פישל הכהן","bt":"תרן","dt":"תשמג","dp":"רמת גן","b":"כתב בכתבי עת שונים, עבר לפרנקפורט ולמד בישיבה שם. נספה בשואה. חתן ר זלמן רוזן ברימנוב ועבר לשם. ניצל מהשואה. בזיוו\"ש חתן דוד נוסבוים. עלה לארץ."},{"i":17438,"n":"וינרב, יהושע מרוה-רוסקה","b":"מחכמי רוה-רוסקה."},{"i":17439,"n":"וינרב, יוסף מבוסק","f":"ברוך שלמה זלקא","bt":"תרכח","bp":"בוסק","dt":"תשג","b":"חתן ר אברהם קורץ, ובזיוו\"ש חתן ר שרגא פיבל קורץ. היגר לקנדה והיה הרב הראשון של טורונטו."},{"i":17440,"n":"וינרב, יעקב דב","b":"תשובה אליו - \"בית יצחק\"-תרנג."},{"i":17441,"n":"וינרב, יעקיל מדולינא","b":"רב בדולינא. בנו ר אהרן זאב על מקומו אחריו."},{"i":17442,"n":"וינרב, ישראל בן ציון מבורשטין","b":"מחכמי בורשטין. תשובה אליו - שו\"מ."},{"i":17443,"n":"וינרב, מנדל מרוה-רוסקה","b":"מחכמי רוה-רוסקה. תשובה אליו בשו\"מ."},{"i":17444,"n":"וינרב, מרדכי מרדיש מראווא","f":"חיים","bt":"תקל","dt":"תקצג","b":"אב\"ד גרבוביץ, אונגוואר. מתלמידיו שם - ר שלמה גנצפריד. גיסו המהרש\"ק הדפיס ממנו קונטרס בסוף ספר החיים שלו."},{"i":17445,"n":"וינרב, משה מנחם מליפנא","bt":"הונגריה","dt":"תרב","b":"תלמיד ר שמחה בונם מפשיסחא, ר מנחם מנדל מקוצק. רב בליפנא, לויביטיש."},{"i":17446,"n":"וינרב, שמואל מדולינא","f":"אברהם","b":"חתן חנה בלוך מדלטין ועבר לשם. מסורת המשפחה שכל בני וינרב מדולינא הינם קרובים."},{"i":17447,"n":"וינרב, שמואל מפרשבורג","bp":"זידיטשוב","dt":"תשך - אחרי","b":"תלמיד השב\"ס. מחכמי פרשבורג וממיסדי חברת \"מבקשי תורה\". עלה לארץ-תרפז והתישב בבני ברק."},{"i":17448,"n":"וינריך, יוסף צבי ממישלניץ","b":"מחסידי בובוב ממישלניץ-תרמה."},{"i":17449,"n":"וינריך, ירחמיאל ישראל מליזנסק","f":"מאיר שמעון","k":"בעל אמרי ישראל","bt":"תרע","bp":"ליזנסק","dt":"תשנט","b":"חסיד ר פנחס מאוסטילה. ניצל מהשואה ועלה לארץ. נעשה חסיד גור. חיבר \"אמרי ישראל\"."},{"i":17450,"n":"וינריך, שלום מגליציה","f":"שרגא ברוך","dt":"תשמה","b":"ניצל מהשואה ועבר לניו יורק, הקים שם את דפוס נאבעל. חסיד בובוב."},{"i":17451,"n":"וינשטוק, אברהם מסדיגורא","b":"גבאי של האדמור רא\"י מסדיגורא. כתב בשמו הסכמה לעירין קדישין תליתאי-תרעד."},{"i":17452,"n":"וינשטוק, אריה ליב מסמבור","b":"רב בסמבור. תשובה אליו בשות \"גבעת הלבונה\"."},{"i":17453,"n":"וינשטוק, בנימין ברוך זאב מירו","f":"אביגדור אברהם","bp":"עיר חדש","dt":"תרלב - כה אד\"א","dp":"ירושלים","b":"בילדותו זכה לראות את החוזה מלובלין. תלמיד ר יוסף ברוך בן בעל \"מאור ושמש\", והיהודי הטוב מניישטט. עלה לירושלים-תרח-יא, עמד בראש קהלה חסידית ובראש כולל ורשה, ויצא בשליחות כמה פעמים, התמנה כדיין בבית הדין החסידי. חברו של האדמו\"ר אלעזר מנחם מללוב. חתם נגד הר\"מ ירושלמסקי ב\"אמת ומשפט\". כנראה הוא שהיה ממונה על כולל פולין החסידי. בנו - ר מנחם קלוימוס אלתר. חתנו - ר אלימך פרלמן (בנו של ר ישראל איסר מרוזוודוב)."},{"i":17454,"n":"וינשטוק, גרשון מקיטוב","f":"משה אליהו זאב","bt":"תריח","bp":"פרוסקורוב","dt":"תשא","b":"סוחר ומחכמי קיטוב."},{"i":17455,"n":"וינשטוק, דוד מסטמר","b":"פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי."},{"i":17456,"n":"וינשטוק, דוד פתחיה מקיטוב","f":"גרשון","k":"בעל קול דוד","r":"נעקה\"ש בשואה","bt":"תרלה","bp":"קיטוב","dt":"תש","b":"חתן ר בריש בר מליטוביסק. מחכמי פודהייץ, עבר לוינה ולאנטוורפן. נספה בשואה. חיבר \"קול דוד\" ירושלים תשך.","bk":[["קול דוד – עה\"ת",""]]},{"i":17457,"n":"וינשטוק, יהודה ליב נח","f":"ישראל צבי הלוי","bt":"תרצו","bp":"ניו יורק","dt":"תשלט","b":"חתן ר אברהם אברומזון. רב ומחנך בארה\"ב."},{"i":17458,"n":"וינשטוק, יוסף מירושלים","k":"בעל וילקט יוסף","b":"מחבורת המקובלים בירושלים-תשיב, מתלמידי ר יהודה אשלג בעל הסולם."},{"i":17459,"n":"וינשטוק, יעקב יוסף מסטמר","k":"בעל מנחם ציון","b":"מחכמי סטמר, תלמידו וחסידו של ר אהרן ראטה - לימים האדמור מתולדות אהרן בירושלים. הו\"ל \"מנחם ציון\" ובו סיפורים ושיחות מר מנדלי מרימנוב ותלמידו ר הערש מרימנוב - את הסיפורים קיבל מהאדמור ר אהרן רוט בעל \"שלחן הטהור\"."},{"i":17460,"n":"וינשטוק, יצחק מקלויזנבורג","f":"משה דוד","k":"בעל עיקר חובת הלבבות","b":"שו\"ב בקלויזנבורג-תרסג, באניא-תרפה. נספה בשואה. ?? לא באוצר ??"},{"i":17461,"n":"וינשטוק, ישראל מברוד","f":"משה צבי","k":"בעל במעגלי הנגלה","bt":"תרסט","bp":"ברודי","b":"למד בישיבת מטרסדורף בוינה, ואצל ראמ\"מ שטינברג. ד\"ר מביהמ\"ד בוינה. עבר לאנגליה-תרצח וכיהן כרב. פעיל במזרחי. חתן ר דוד וינטר מליבק. עלה לארץ. חיבר \"במעגלי הנגלה והנסתר\" ירושלים תשל, \"טמירין\" עם הקדמת תולדותיו - תשלב-תשמא."},{"i":17462,"n":"וינשטוק, מנחם קלונימוס אלתר","f":"ברוך בנימין זאב","b":"מחכמי ירושלים. ידידו של האדמו\"ר מללוב, בניו - ר מרדכי, ר שמעון עזריאל - נפטר צעיר."},{"i":17463,"n":"וינשטוק, משה יאיר מירושלים","k":"בעל אור הדעת","r":"ראש מתיבתת תורת חסד בירושלם","bt":"תרנט","dt":"תשמב","dp":"ירושלים","b":"ראש מתיבתת תורת חסד בירושלם, נדפס יחד עם ספר פירוש המרכבה לרבינו יוסף גיקטיליא ראש מתיבתת תורת חסד בירושלם, נדפס בתוך ספר מראה האדם ראש מתיבתת תורת חסד בירושלם, נדפס בתוך ספר יצירה עם פירוש יוצר אור","bk":[["נתיבות יאיר",""],["סידור הגאונים והמקובלים",""],["חדרי המרכבה והיכל כסא הכבוד",""],["אור הדעת - פרקים בהסתכלות פנימית על האדם",""],["אור עולם - תהילים",""],["דברי יאיר - על התורה ומועדים",""],["חדרי המרכבה - על מרכבה דיחזקאל",""],["יוצר אור - שיטה מקובצת על ספר יצירה",""],["ימות עולם - איגרת דרב שרירא גאון",""],["כינור בן דוד - שירה",""],["מאור התורה - תורת לשון המקרא בנגלה בנסתר ובחסידות",""],["מאור התפילה - שיטה מקובצת על התפילה",""],["מאורות המצות - שיטה מקובצת על המצוות המשולבות בתפילה, ציצת, תפילין, וקריאת שמע",""],["מערכת האדם - עניני האדם בחומר ובצורה לפי סדר א' ב'",""],["מראה האדם - פרקים בידיעת מבנה האדם ברוחניות ובגשמיות, בפנימיות ובחיצוניות",""],["משאת משה - שירים",""],["נועם הכבוד - מבוא אל האדרות",""],["נתיבות יאיר - שיטה מקובצת על האידרות וספרא דצניעותא ורעיא מהימנא",""],["פרי קודש הילולים \\ קודש הילולים - ר' משה ור' דוד מלעלוב",""],["קדושת התורה ודקדוקה - עה\"ת, משלי, תרי עשר, תהילים, שיר השירים, וקהלת",""],["רוח ממללא - פרקים על דקדוק לשון הקודש בפנימיות ובחיצוניות",""],["שלחן המערכות בסתרי החכמה - ובו עשר מערכות",""],["שנים עשר שבטי ישראל",""],["תולדות חכמי הדורות",""],["תפארת בית דוד - תולדותיו של ר' דוד בידרמן מללוב",""]],"e":"תרנ\"ט-תשמ\"ב"},{"i":17464,"n":"וינשטוק, נתן קרפל משאראש פוטוק","f":"ישראל משאראש פוטוק","dt":"תרסו - ה אדר","dp":"שאראש-פוטוק","b":"נכד ר משה פריד ממונקטש. תלמיד הכת\"ס, ור שמעון סופר מערלוי(=אויהל). חתן ר משה סופר. מחכמי שאראש-פוטוק."},{"i":17465,"n":"וינשטוק, שמעון עזריאל זליג","f":"מנחם קלונימוס אלתר","b":"מחכמי ירושלים. היה חולה מילדותו בשחפת, ואביו פנה לאדמו\"ר ר אלעזר מנחם מללוב שיעץ לו להשיאו אישה כדי שלפחות ישאר זכר ממנו, והוליד בן - ר משה צבי אריה - התייתם בגיל 3 וגדל אצל זקנו."},{"i":17466,"n":"וינשטי ן","k":"משפחה","b":"משפחה משלוניקי שעברה לוינה-תק.., לאחר הסכם שלום בין התורכים לאוסטרים שהתיר לנתינים תורכים לעסוק במסחר ללא הגבלה באוסטריה."},{"i":17467,"n":"וינשטין, אברהם מליסקובה","b":"פרסם מאמרים ב\"אור תורה\" - לונדון תרצד."},{"i":17468,"n":"וינשטין, אברהם ניסן מירושלים","f":"ראובן","dt":"תרכו - א כסלו","dp":"ירושלים?","b":"שליח ירושלים בארצות רבות בשנים תרטו תרך, בשליחות בארה\"ב-תרך למען כולל הפרושים - וחתמו על כתב השליחות - ר ישעיה ברדקי, ר יוסף זונדל סלנט, ועוד, חזר בתרכב. נפטר במגפת החולירע בירושלים. אודותיו ב\"הלבנון\", וב\"מגנזי ירושלים\"-תרץ, פנקס שליחותו נתפרסם על ידי בארון ס.וו. 1943. בנו - ר ראובן דוד - נפטר צעיר. נזכר ב\"זכרון לחובבים הראשונים\" יג."},{"i":17469,"n":"וינשטין, אהרן מתל אביב","f":"מנחם מנדל","k":"בעל בני אהרן","bt":"תרנג","bp":"הנצביץ-פלך מינסק","dt":"תשכא","b":"תלמיד ר ברוך בר ליבוביץ, ר איסר זלמן מלצר, והסבא מנובהרדוק. ראש ישיבת \"בית יוסף\" נוברדוק במזריטש ובתל-אביב. חתנו ר משה שמואל שפירא - ראש ישיבת באר יעקב. פרסם מאמרים ב\"בית מדרש\" - תל אביב תשא."},{"i":17470,"n":"וינשטין, דב ברל מקרליפקה","b":"מחכמי קרליפקה. תשובות אליו - \"אורין תליתאי\"."},{"i":17471,"n":"וינשטין, יהושע צבי מקלויזנבור","f":"יצחק אהרן מדעש","k":"בעל ברכת יהושע-תשב","bt":"תרנה","bp":"דעש","dt":"תש..","b":"תלמיד ר יחזקאל פאנט מדעש. מלמד בקלויזנבורג, והקים שם בית מדרש-תרצח לחסידי דעש. נספה בשואה."},{"i":17472,"n":"וינשטין, יצחק","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ."},{"i":17473,"n":"וינשטין, יצחק אהרן מדעש","bt":"תרכח","bp":"זמפלן","dt":"תרצט - יב שבט","dp":"דעש","b":"תלמיד השב\"ס, ור אלעזר לעוו באויהל. רב ומלמד בדעש."},{"i":17474,"n":"וינשטין, יצחק בן ציון","bt":"תרכה","bp":"האדהאז","dt":"תרפד - ה אדר","dp":"קלויזנבורג","b":"תלמיד בעל \"ייטב לב\" בסיגט. התישב בקלויזנבורג והקים בית דפוס, היה פעיל ציוני ומתומכי ר משה שמואל גלזנר, הדפיס את העתון הציוני \"השחר\". ביקר בארץ ופגש את הנציב העליון הרברט סמואל, ציר בכינוסים הציוניים בטרנסילבניה."},{"i":17475,"n":"וינשטין, יצחק מוישנובה","f":"אברהם","b":"אב\"ד וישנובה-תרצז."},{"i":17476,"n":"וינשטין, ישראל","b":"פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז."},{"i":17477,"n":"וינשטין, מאיר מבני ברק","b":"פרסם מאמרים ב\"תפארת ציון\" - בני ברק תשב - קובץ תלמידי ישיבת \"תפארת ציון\"."},{"i":17478,"n":"וינשטין, מאיר שרגא","f":"ר\"מ","bt":"תריז","b":"חתן ר שמחה שמואל מסטויפצי בעל \"משרת משה\". רב בוואסלוביץ. נסמך מאת: ר יצחק אלחנן, ר חיים אליעזר ואקס, ר ברוך צבי מפיעטרקוב, ר ישראל איסר ממזריטש."},{"i":17479,"n":"וינשטין, משה חיים מהאדהאז","b":"תלמיד החת\"ס. רשם מתורת רבו ונדפס ממנו ב\"דרשות חת\"ס\"."},{"i":17480,"n":"וינשטין, צבי אריה מסלטוינה","f":"[הירש ליב]","b":"רב בסלטוינה - תשובות אליו בשנים תרג - תרלט."},{"i":17481,"n":"וינשטין, רחמיל אהרן","bt":"1877","bp":"וילנא","dt":"1938","b":"מראשוני הבונד. תלמיד ביהמ\"ד למורים בוילנא. מורה באושמיאנה, וארשא. ציר בועידו הבונד בוארשא-1900, ביאליסטוק-1904. הצטרף למפלגה הקומוניסטית ומילא תפקידים בכירים עד שנאסר-1937 ומת בכלא."},{"i":17482,"n":"וינשל, בן ציון (ולדימיר)","f":"שאול","bt":"1863","bp":"גרודנא","dt":"1943","dp":"חיפה","b":"רופא ועסקן ציוני., עבר לבאקו. ציר בקונגרסים הציוניים. עורך עתון ההסה\"צ בקווקז. עלה לארץ-1922. פרסם מאמרים רבים ברפואה."},{"i":17483,"n":"וינשל, פנחס מאוסטרהא","k":"אדמור מאוסטרהא","b":"אדמור באוסטרהא - לפני מלחה\"ע ה-I."},{"i":17484,"n":"וינשלבוים, זאב וולף מרישא","bt":"תקץ","dt":"תרסה - ב ניסן","b":"רב ברישא - בספר \"ברכה שלמה\" מסופר אודותיו."},{"i":17485,"n":"וינשלבוים, שלמה אריה ליב","f":"זאב וולף מבלדנוב","k":"בעל הכנת לב לתפלה,בעל ברכת שלמה","r":"הצדיק מטיטשין","bt":"תרט","dt":"תרפז - י תמוז","b":"תלמיד רמ\"מ הרטמן, ר חיים יהודה גינצבורג, ר יעקב משה מקומרנא, ר חיים אורי גולדברג מרישא, והדברי חיים מצאנז. דמות פלאית של צדיק עממי ללא שושלת ומפורסם במופתיו. חסיד צאנז. חתן ר חיים יהודה גינצבורג. גר בטיטשין. ההדיר \"קול בוכים\" ל ר אברהם גלאנטי. חיבר \"הכנת לב לתפלה\" בילגוריא תרפז. מתולדותיו בספר בן אחותו ר אבא וקס מלובובה - \"ברכה שלמה\". בניו: ר אברהם, ר מאיר ור יעקב ויקסלבוים מרישא. חתנו ר אברהם זאב מאנד מטיטשין.","bk":[["הכנת לב לתפלה - על התורה",""]]},{"i":17486,"n":"ויס אברהם","bt":"1896","dt":"ה'תשל 1970","bk":[["לשאלת מקורות הסוגיות",""]]},{"i":17487,"n":"ויס איזיק הירש","bt":"1815","dt":"ה'תרסה 1905","bk":[["בית המדרש",""],["די גרינדער און בויער פון יודענטום",""],["זכרונותי",""]]},{"i":17488,"n":"ויס יצחק יעקב בן יוסף יהודה","bt":"1902","dt":"ה'תשמט 1989","bk":[["דברי יצחק",""],["מנחת יצחק חלק א",""],["מנחת יצחק חלק ג",""],["מנחת יצחק חלק ה",""],["מנחת יצחק חלק ז",""],["מנחת יצחק חלק ט",""]]},{"i":17489,"n":"ויסאקינסקי, שמואל","b":"רב-שנת תר\"ל"},{"i":17490,"n":"ויסאקיר, דוד מצפת","dt":"תקצז","dp":"צפת","b":"מחכמי צפת. נהרג ברעידת האדמה-תקצז."},{"i":17491,"n":"ויסבורג, טוביה יחיאל מליסקא","b":"מחכמי ליסקא-תרכה."},{"i":17492,"n":"ויסבך, בצלאל דב מקוזובה","k":"בעל מאמר בצדק","bt":"תקף","dt":"תרם","b":"רבה של קוזובה. רב בבוצ'צ'י - מולדביה ושם היה בדין תורה ארוך עם האב\"ד ר יוסף אהרן מרילוס. חיבר ספר להצדיק עצמו בדין \"מאמר בצדק\" יאסי תרלב. (כנגדו הופיע \"קול יעקב\" - טשרנוביץ תרלב)."},{"i":17493,"n":"ויסבלום אלעזר בן אלימלך נפ’","bk":[["משנה למלך",""]]},{"i":17494,"n":"ויסבלום, אברהם יצחק מסטאשוב","f":"אלעזר מסטשוב-יד אלעז","bt":"תרסב","bp":"סטאשוב","dt":"תשל","b":"תלמיד ר מאיר יחיאל הלצשטוק האדמור מאוסטרובצא ונסמך ממנו ומאת ר אלתר אליעזר הורביץ מריגליץ. רב בסטאשוב וראש ישיבה שם, רב במיץ, רב קהלת חסידי בובוב בוינה-תרפח ור\"מ בישיבת \"בית אברהם\". חתן ר יוסף ויינשטיין. ניצל מהשואה והגיע לארה\"ב וכיהן כרב קהלת \"בני משה יוסף אנשי זאויכוואסט בניו יורק. חבר אגודת הרבנים באמריקה ואגודת ישראל."},{"i":17495,"n":"ויסבלום, אברהם יצחק מסטאשוב","b":"נכד ה\"נועם אלימלך\". ונכד ר יוסף ברוך \"היהודי הטוב\" מניישטאט מצד אמו. אדמור בליזנסק, בנו ר דב על מקומו אחריו. מבניו גם ר נפתלי משנדישוב-חתן ר חיים מאיר מפינשטוב (ראודשיץ) - נפטר תרעט."},{"i":17496,"n":"ויסבלום, אברהם יצחק מסטשוב","f":"אלעזר מסטשוב","dt":"תשנא - ד תמוז","b":"מצאצאי הנועם אלימלך. חתן ר יוסף וינשטין. ניצל מהשואה, ואחריה היגר לארה\"ב, וכיהן כרב בניו יורק."},{"i":17497,"n":"ויסבלום, אברהם מבריסק","f":"בנימין זאב מבריסק","k":"בעל זרע אברהם","bp":"ליטא","dt":"תס","b":"התישב בוילנא-תד. תלמיד ר שבתי שפטל הורביץ. חתן הגביר ר אליהו ליפשיץ מבריסק ועבר לשם, וכיהן כרב ודרשן. חיבר גם \"זרע אברהם\". בנו - ר משה."},{"i":17498,"n":"ויסבלום, אהרן זאב וולף הלוי","b":"חתן ר מנחם מנדל מאטקיווער מטורקא. רב בטורקא על מקום חותנו. רב במערין-תרעו."},{"i":17499,"n":"ויסבלום, אלימלך","f":"אלעזר","k":"ר' מלך דובצ'יס","dt":"תרנח","b":"מצאצאי הנועם אלימלך. רב ואדמור בליזנסק-תרס, ובידו היו מפתחות הציון (של הנו\"א)."},{"i":17500,"n":"ויסבלום, אלימלך מליזנסק","f":"אליעזר ליפא","k":"בעל נועם אלימלך,אדמור מליזנסק","r":"הרבי של האדמורי\"ם, ספרן של צדיקים","bt":"תעז","dt":"תקמז - כא אדר","b":"תלמיד המגיד ממזריטש. חתן ר אהרן רוקח-אחיו של ר אלעזר מאמשטרדם, ובזיוו\"ש חתן ר יעקב מרגליות. מפיץ החסידות בפולין וגליציה. לתולדותיו ב\"אהל אלימלך\", ועוד.","bk":[["נועם אלימלך – עה\"ת",""],["נועם אלימלך המבואר",""],["צעטיל קטן",""],["נועם אלימלך (ליז'ענסק)",""]],"e":"תע\"ז-תקמ\"ז"},{"i":17501,"n":"ויסבלום, אלימלך מסטאשוב","f":"אברהם יצחק מסטשוב","k":"אדמור מסטאשוב","dt":"תשב - כט סיון","b":"חתן ר שמואל אהרן רובין מקורטשין. נספה בשואה."},{"i":17502,"n":"ויסבלום, אלימלך מרודניק","f":"מנחם ישכר דב מפשורסק","k":"אדמור מרודניק","bt":"תקמח או תקעז","dt":"תרט - יט טבת","dp":"סוקולוב-גליציה","b":"תלמיד ר נפתלי צבי מרופשיץ. חתן הגביר ר איציקל מרידניק. רב ואדמור ברידניק לאחר פטירת רבו האדמור מרופשיץ, עבר ללנצהוט. מתורתו ב\"שדה דבש\" - \"דבש השדה\" ובספר בנו ר אלעזר מרישא."},{"i":17503,"n":"ויסבלום, אליעזר ליפא","f":"אברהם מטיקטין","b":"תושב לאפאחאי שליד טיקטין. צדיק ועשיר בזמן הבעשט. אביהם של הנועם אלימלך ור זושא, אח נוסף היה רופא בצבא הפרוסי."},{"i":17504,"n":"ויסבלום, אליעזר ליפא מנ\"י","f":"ישראל חיים","k":"בעל דברי אליעזר","bt":"תרמד","bp":"ליזנסק","dt":"תשך","b":"מצאצאי הנועם אלימלך. היגר לארה\"ב וכיהן כרב בניו יורק. חתן דודו ר נפתלי ויסבלום מליזנסק, ובזיוו\"ש חתן ר יעקב שרייבר מפרימישלן. חיבר גם \"ילקוט הדרוש\" ניו יורק תרפז. עורך \"הלבנון\" סיגט-נ\"י-סטמר תרפו-תרפח, \"פרח לבנון\" - תרעח. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב, \"מגד ירחים\" - סטמר תרפה. עורך \"פרח הלבנון\" - וארשא תרעח, \"קהילת יעקב\" - זבארוב-סלובקיה תרפה."},{"i":17505,"n":"ויסבלום, אלעזר","f":"נפתלי","bt":"תרנב","dt":"תרפט","dp":"אנטוורפן","b":"מתוך נוסח מצבתו"},{"i":17506,"n":"ויסבלום, אלעזר מליזנסק וחמלניק","f":"אלימלך-נעם אלימלך","bt":"תקב","dt":"תקסו - כח תמוז","b":"חתן ר ישראל צבי הירש ליפינר מגרודזיסק-תלמיד המגיד ממזריטש, ובזיוו\"ש חתן ר הרשל הארבאטקע, ובזיוו\"ש חתן ר שמואל מלמד משינאווא. סירב לכהן כאדמור על מקום אביו, ונהג אדמורות בשושן פורים כל שנה. רב בחמלניק. הביא לדפוס את ספרי אביו. בסוף נועם אלימלך לאביו הדפיס אגרת הקודש שלו. הו\"ל ספר אביו \"לקוטי שושנה\". כתב את דברי תורתו של אביו וחיבר להם הקדמה, ומתורתו ב\"נועם אלימלך\". עליו ב\"פרקי דרבי אליעזר\". ומכתביו נדפס \"פרקי דרבי אלעזר\" בני ברק תשמז ע\"י רמ\"מ ויזניצר. חיבר \"אורח לצדיק\" וארשא תרנג. (תאריך פטירתו נרשם גם כו אדר תקעג, וגם תקץ). בנו ר אלימלך מרימנוב-חתן דודו ר אליעזר מליזנסק."},{"i":17507,"n":"ויסבלום, אלעזר מסטשוב","f":"אברהם יצחק מסטשוב","k":"בעל יד אליעזר","b":"רב בסטאשוב-תר\"ס. נכד הנועם אלימלך. ?? לא באוצר ??"},{"i":17508,"n":"ויסבלום, אלעזר מרישא","f":"אלימלך מרידניק","k":"אדמור מרישא","bt":"תקצח","dt":"תרע - טו תמוז","dp":"סוקולוב","b":"גדל אצל הדברי חיים מצאנז לאחר שנתייתם. חתן ר דוד מקשאנוב בנו של הדברי חיים ובזיוו\"ש חתן ר חיים יונה הלפרין מרישא. רב ואדמור בבוקובסק-תרלו, פשוורסק-תרלח, רישא. חיבר \"משנה למלך\" פרמישלא תרסב. חתנו ר שלמה בן ר צבי הירש מרוזוודוב (שושלת רופשיץ) על מקומו אחריו.","bk":[["משנה למלך - על התורה",""]]},{"i":17509,"n":"ויסבלום, דוד אלימלך מנדבורנה","f":"משלם זושא","dt":"תרפה","b":"חתן ר אליעזר יצחק טייכר מאולינוב. בנו ר מאיר מנדבורנא"},{"i":17510,"n":"ויסבלום, חנא אלחנן מליזנסק","f":"אלימלך","k":"אדמור מליזנסק","dt":"תרפג","b":"חתן ר יוסף שיף מנבליץ. אדמור בליזנסק."},{"i":17511,"n":"ויסבלום, יוסף מרישא","b":"חסיד מחכמי רישא-תרעח. דברי תורה ממנו ב\"פרח לבנון\"."},{"i":17512,"n":"ויסבלום, יעקב","f":"אלימלך מליזנסק","b":"רב ואדמור במוגילניצה. דברי תורה ממנו ב\"בית אהרן\" ובספר \"יסוד אמונה ומדת ענוה\"."},{"i":17513,"n":"ויסבלום, יעקב יצחק מזידיטשוב","f":"נפתלי מליזנסק","k":"אדמור מזידיטשוב","b":"חתן ר יעקב נפתלי הרץ לבין מזידיטשוב. גר בזידיטשוב, סאנוק."},{"i":17514,"n":"ויסבלום, יעקב יצחק מסוירז","f":"נפתלי","bt":"תרסז","bp":"זידיטשוב","dt":"תשלד","b":"גדל בסטניסלב אצל דודו האדמור מאלסק לאחר פטירת הוריו. חתן ר חיים הלוי אייזן מסוירז. רב בסוירז על מקום חותנו. עלה לחיפה-תרצה."},{"i":17515,"n":"ויסבלום, מאיר מנדבורנה","f":"דוד אלימלך","bt":"תרלב","bp":"נדבורנא","dt":"תרעג - ב תשרי","b":"נכד הנועם אלימלך מצד אמו, ור זושא מצד אביו. חתן ר יוסף לייפר מבורשא-אחיו של האדמור ר מרדכי מנדבורנא. תלמיד ר משה'ליה מבורשא. למד בחוסט אצל בעל \"ערוגות הבושם\". רב בנדבורנה. רב בנדבורנא ומלמד, מתלמידיו ר יוסל ברנדוין נכד ר חיים, ור שמואל היבנר. נפטר בחיי אביו. בניו: ר משלם זושא אדמור בבורשא, ר יוסף מברגסז, ר ישכר ברצי וראכל גיטל - נספו בשואה. חתניו: ר לוי יצחק לייפר מאראד וחיפה, ר משה שיף בן שמעון האדמור מליזנסק בקלויזנבורג."},{"i":17516,"n":"ויסבלום, מנחם ישכר דב מנדל בער","f":"אלעזר מליזנסק","k":"אדמור מפשוורסק","b":"חתן ר אברהם משה מפשעוורסק. נפטר בחיי אביו."},{"i":17517,"n":"ויסבלום, משה","f":"אברהם מבריסק","b":"מאבות המשפחה - אביהם של ר יעקב קופל (לדעת אלפסי - לא זה שהיה תלמיד הבעשט), ר אברהם מטיקטין - זקנו של הנועם אלימלך."},{"i":17518,"n":"ויסבלום, משה אהרן מבריסק","f":"שלמה חיים מקמניץ","bt":"תרג","bp":"קמניץ-ליטא","dt":"תרסג","dp":"ירושלים או בריסק","b":"ר\"מ בישיבת \"בלומקעס\" במינסק, רב בבריסק, וואלצין, עלה לירושלים (ולפי דור רבניו וסופריו ח\"ו - נפטר בבריסק). נפטר ללא ילדים."},{"i":17519,"n":"ויסבלום, משלם זושא מבוארשא","f":"מאיר מנדבורנה","k":"אדמור מבוארשא","bt":"תרסז","dt":"תשג","b":"נתייתם בילדותו וגדל אצל דודו ר ברצי באונגוואר ולמד אצל האב\"ד רא\"י גרינולד. חתן ר אלימלך דובצה וולקנפלד שהחזיק במפתחות האוהל בליזנסק. אדמור בבוארשא על מקום זקנו ר יוסף לייפר. נספה בשואה."},{"i":17520,"n":"ויסבלום, משלם זושא מצפת","f":"נפתלי מליזנסק","k":"אדמור מנדבורנא","dt":"תרן - כה כסלו","dp":"צפת","b":"תלמיד ר חיים מקוסוב. חתן ר דוד אריה ליב בן צבי הירש מנדבורנא ועבר לשם. עלה לצפת-תרכה (לאחר שראה בחלום את רבו מצוה עליו לעלות). בנו ר דוד אלימלך ונכדו ר מאיר מנדבורנא."},{"i":17521,"n":"ויסבלום, נפתלי","b":"פרסם מאמרים ב\"פרח הלבנון\" - וארשא תרעח."},{"i":17522,"n":"ויסבלום, נפתלי מבולחוב","f":"ישראל יוסף","k":"אדמור מבוליחוב","bt":"תרכב","dt":"תרעח - יב ניסן","dp":"זידיטשוב","b":"מצאצאי הנועם אלימלך. חתן דודו ר צבי לבין. רב בבוליחוב. נדד בעיירות לקבץ הסכמות ומינויים להדפסת ספרי זקנו בעל \"עטרת צבי\"."},{"i":17523,"n":"ויסבלום, נפתלי מליזנסק","f":"אלעזר מליזנסק","k":"אדמור מליזנסק","bt":"תקכה-תקם","dt":"תקצט - כה חשון","b":"נכד הנועם אלימלך ורב על מקומו בליזנסק - סירב לנהוג באדמורות. תלמיד ר מנחם מנדל מקוסוב. היה מפורסם במופתים. (באוצר הרבנים מופיע כי היה בנו של הנועם אלימלך)."},{"i":17524,"n":"ויסבלום, נפתלי מנ\"י","b":"פרסם מאמרים ב\"קהילת יעקב\" - זבורוב-סלובקיה תרפה."},{"i":17525,"n":"ויסבלום, נפתלי משנדישוב","f":"אברהם יצחק","bt":"תרך","dt":"תרעט","b":"חתן ר חיים מאיר מפינטשוב. רב בקושיץ, ובשנדישוב. בנו ר ברל על מקומו אחריו."},{"i":17526,"n":"ויסבלום, נתן יחזקאל מלודמיר","f":"אלעזר","dt":"תשד","b":"מצאצאי הנועם אלימלך. רבה של לודמיר ואחר בסלובקיה על מקום חמיו ר נפתלי טוכמן. נספה בשואה."},{"i":17527,"n":"ויסבלום, פנחס","b":"פרסם מאמרים ב\"הלבנון\" - סטמר תרפח."},{"i":17528,"n":"ויסבלום- משפחה","b":"לפי מסורת משפחתית העניק קיסר אוסטריה לנועם אלימלך שם משפחה זה - כשהתיצב לפניו בגלימה לבנה מקושטת בפרחים."},{"i":17529,"n":"ויסבלט, נחום מקיוב-הגדול ממאלי","f":"יעקב","k":"בעל מחצית השקל","bt":"תרכה","b":"ר\"מ במאלין-פלך קיוב וכונה \"הגדול ממאלין\". רב בקיוב-תרסב. חיבר גם \"פרדס רמונים\", \"עלי הגפן\", \"מים טהורים\", \"לוח\" לשנת תרן-תרנא, ועוד."},{"i":17530,"n":"ויסברג, יצחק יעקב","b":"פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":17531,"n":"ויסברג, מנחם זאב מטורקני","dt":"תרנה - ט טבת","b":"חתן ר יעקב צבי ולדמן מבורשא. תלמיד הדברי חיים מצאנז. רב בדאברא, טורקאני."},{"i":17532,"n":"ויסברג, משה בער","f":"מנחם זאב מטורקני","dt":"תשד","b":"חריף,רב בטרקאני-תרנ\"ו"},{"i":17533,"n":"ויסברג, שלמה דוד (דוב)","f":"שמואל","bt":"תריב","b":"רב בפראבישטש-פלך קיוב-תרם."},{"i":17534,"n":"ויסברג, שמואל מאיסטריק","f":"שלמה מפרובישטש","b":"מחכמי איסטריק-תרעא. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":17535,"n":"ויסברגר, אלתר חיים מפודגורזע","b":"מחכמי פודגורזע - תשובה אליו במנחת יחזקאל."},{"i":17536,"n":"ויסברד, אברהם הכהן","f":"זכריה מנדל מראדין","bt":"תרכז","dt":"תרצג-ו -כג כסלו","dp":"ירושלים","b":"מצאצאי ר רפאל הכהן מהמבורג. תלמיד ר יצחק בלזר, ישיבת מיר, סלובודקא, וולוזין. רב ברעייל, טוחא(=טולא)-תרסא, בסמולנסק-תרעח, עלה לירושלים-תרצג. בן דודו - ר דוד כהן \"הנזיר\" מירושלים."},{"i":17537,"n":"ויסברד, אברהם שרגא","dt":"תשג","b":"רב בפרייל"},{"i":17538,"n":"ויסברד, איסר מדרביאן","bt":"תרנז","dt":"תשא - תמוז","b":"תלמיד בכולל סלובודקא. רבה האחרון של דרביאן. פרסם מאמרים ב\"בית ישראל\" - קובנא תרפב, \"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":17539,"n":"ויסברד, דוד יוסף","dt":"תשג","b":"רב בקרשניק"},{"i":17540,"n":"ויסברד, זכריה מנדל מראדין","b":"רב באליטא,ראדין-תר\"כ"},{"i":17541,"n":"ויסברד, יוסף יהודה מריזינובקא","f":"ישראל ליפא","bt":"תקצז","b":"רב בריזניווקה-פלך קיוב-תרלו."},{"i":17542,"n":"ויסברד, ישעיה כץ מבאקשט","f":"זכריה מנדל מראדין","bt":"תריו","b":"אמו ממשפחת בלומקעס וילענקין ממינסק. תלמיד ישיבת וולוזין. נסמך מאת: הנצי\"ב, ר ירוחם יהודה הגדול ממינסק. רב בבאקשט-בארישוקה."},{"i":17543,"n":"ויסברד, מרדכי מאיר מטורבין","k":"אדמור מטורבין","dt":"תשג","b":"נכד ר יעקב מאפטא, ומצאצאי האדמור ר דוד מללוב. אדמור בטורבין."},{"i":17544,"n":"ויסברוט, יצחק מידליטש","b":"רבה של ידליטש-תרצב."},{"i":17545,"n":"ויסברום, ירוחם יהודה ממוסקבה","b":"רב במוסקבה-תר\"ע"},{"i":17546,"n":"ויסהויז, אהרן צבי מסטניסלב","f":"משה ניסן","k":"בעל אוצר בלום","bt":"תקצז","bp":"סטניסלב","dt":"תרסז","b":"מחכמי סטניסלב. חיבר \"אוצר בלום\" למברג תרעג. נפטר ללא ילדים."},{"i":17547,"n":"ויסוצקי, קלונימוס זאב","bt":"1824","bp":"זאגר-ליטא","dt":"1904","dp":"מוסקבה","b":"תלמיד ישיבת וולוזין, ור ישראל סלנטר בקובנא. התישב במוסקבה-1858 והקים בית מסחר לתה שהפך לעסק בינלאומי. השתתף בפעולות לאומיות ופילנטרופיות, ויחד עם פוליאקוב והברון גינצבורג הקים בפטרברוג \"ועד להגנה על זכויות היהודים\". ציוני והשתתף בועידת חובבי ציון בקטוביץ-1894. ביקר בארץ-1889 ו-1894 ופרסם רשמים מהביקור ב\"האסיף\". החזיק את \"השלוח\" על חשבונו. תרם סכומים גדולים למוסדות חינוך בארץ, וברוסיה - ובעיקר דאג לחינוכם של ידלי הקנטוניסטים."},{"i":17548,"n":"ויסטינצר, ישראל גילדע מאוגסטוב","b":"תלמיד החת\"ס. מלמד תורה באוגוסטוב. נכדו - ר יקותיאל עזריאלי - אב\"ד זכרון יעקב."},{"i":17549,"n":"ויסטניצקי, יהודה הכהן","b":"פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":17550,"n":"ויסטניצקי, יצחק הכהן","f":"אברהם אבא מהורדנא","k":"בעל דברי יצחק","b":"נכד ר משה הכהן השכל מויסטיניץ(=וישטיניץ).חיבר \"דברי יצחק\" - וילנא תרכח."},{"i":17551,"n":"ויסטר, תיאודור מפרשבורג","b":"עמד בראש התאחדות הקהלות בסלובקיה במדינת צכוסלובקיה החדשה-תרעט."},{"i":17552,"n":"ויסמן, אברהם מסאבאסלו","b":"דומ\"צ בסטרפקוב,נירדהאז,רב בסובוסלו(=הוידא-סאבאסלו)-תרל, ובנו ר יעקב צבי על מקומו אחריו."},{"i":17553,"n":"ויסמן, יעקב נתן מטוראוו","k":"בעל מחשבות בעצה","b":"רב בטוראוו."},{"i":17554,"n":"ויסמן, יעקב צבי מהוידא-סאבאסלו","f":"אברהם מסאבאסלו","dt":"תרמט - יט אד\"א","b":"תלמיד בעל \"קול אריה\". חתן האדמור ר שמואל פרנקל מדאראג וקאמאד בעל \"אמרי שפר\". רב בהוידא-סאבאסלו על מקום אביו (דור רביעי לרבנות שם) וחתנו ר שלמה (שמואל) כץ על מקומו אחריו. באוצר תאריך פטירתו יט אד\"ב תרן."},{"i":17555,"n":"ויסמן, יצחק איזיק ממיץ דוקלא","f":"יעקב הלוי","bt":"תק","dt":"תקסד - כח תשרי","dp":"דוקלא","b":"חתן ר נתן נטע שפירא. רבה של דוקלא-תקמב. בנו - ר נטע לנדא. (באוצר הרבנים מופיע כשני רבנים שונים)"},{"i":17556,"n":"ויסמן, ישראל אריה מצורטקוב","dp":"ארץ ישראל","b":"רב בצורטקוב-תרי. עלה לארץ."},{"i":17557,"n":"ויסמן, מרדכי צבי הלוי מסובאלק","k":"בעל דברי חכמים","b":"מחכמי סובאלק."},{"i":17558,"n":"ויסמן, משה חיים","b":"רב בהאדהאז-תרל\"ו"},{"i":17559,"n":"ויסמן, פסח אהרן מקאמין קשירסק","f":"אריה יהודה ליב","bt":"תרכ","b":"רב באזיריאן(=אזיריאן)-מחוז לודמיר-תרמג, קאמין-קשירסק-ווהלין."},{"i":17560,"n":"ויסמן, צבי הרמן מסובוסלו","b":"רב וראש ישיבה בפובוסלו-מחוז האידו-תרלט."},{"i":17561,"n":"ויסמן, שלמה זלמן","f":"בן ציון","b":"תלמיד יח\"ל. נפטר לפני השואה."},{"i":17562,"n":"ויסמן, שמשון מלופאטין","f":"ענזיל","bt":"תרסז","bp":"טרנופול","dt":"תשב","b":"חתן ר חיים ליבוש המרלינג מלופטין. רב בלופטין ליד חותנו. נספה בשואה."},{"i":17563,"n":"ויסמן-חיות, אשר שמחה בזלין","bt":"תר","bp":"זלין","b":"מחכמי רישא, עבר לוינה. בקי בשפות רבות, עסק בהוראה ובפרסום מאמרים רבים."},{"i":17564,"n":"ויסמן-חיות, מרדכי מטרנוב","f":"יצחק יהודה ליב","k":"מו\"ח וגם חומ\"ה","bt":"תקצא","bp":"טרנוב","dt":"תרעד","b":"מחכמי ברודי ולמברג, עבר לוינה. חיבר \"משל ומליצה\" טרנוב תרך. ההדיר את הירושלמי קראטשין תרכו, ועוד. פרסם מאמרים ב\"הבונה\" - לבוב תרסד, \"מגד ירחים\" - סיגט תרנח."},{"i":17565,"n":"ויסמן-חיות, שמואל מדינוב","f":"אפרים פישל","k":"בעל שירים קצרים","bt":"תרל","dt":"תרסד","b":"מחכמי דינוב. חתן ר יהודה ליבוש שוועבער מפשמישל. חיבר \"שירים קצרים ומכתמים\" קראקא תרנז. ?? לא באוצר ??"},{"i":17566,"n":"ויסמנדל חיים מיכאל דב","bt":"ה'תרסד","dt":"ה'תשיח","b":"הר' חמ\"ד וייסמנדל חיבר קינה לט' באב, על חורבן יהדות אירופה - \"סלח נא א-ל, לגוף ישראל\". שמו \"חיים\" נוסף בסוף ימיו.","bk":[["תורת חמד",""],["מן המיצר",""]]},{"i":17567,"n":"ויסמנדל, משה דוד מטירנוי","b":"מצאצאי ר מיכאל זלצר הראשון. מחכמי טירנוי."},{"i":17568,"n":"ויסמנדל, עמרם מטירנוי","b":"תלמיד ר שמואל דוד אונגר בישיבת טירנוי. פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי, \"משא ומתן\" - טירנוי תרצא."},{"i":17569,"n":"ויסנבסקי, יצחק","b":"רב בקולטינין-תרפ\"ט"},{"i":17570,"n":"ויסנברג, יעקב מארה\"ב","f":"משה","bt":"תרנו","bp":"ראזינוי-פלך גרודנא","b":"תלמיד ישיבת סלונים-אצל ר שבתי יגל, ר דוד טבל דינובסקי במאלטש, ישיבת סלובודקה. נסמך מאת: ר יוסף חיים טרופ, ר שמחה זליג מבריסק, ר דוד פיגנבוים מפרחינא, ר דוד טבל דינובסקי ממאלטש. חתן ר דוד הלל. רב בבערעזא, היגר לארה\"ב-תרץ וכיהן כרב קהלת \"בית ישראל\" בואוסטר-מסצוסס, קהלת \"שערי תורה\". חיבר חדושים על פרשיות התורה. חבר אגודת הרבנים באמריקה ותנועת המזרחי."},{"i":17571,"n":"ויסנברג, שלמה זלמן מקאשוי","b":"פרסם מאמרים ב\"קהילת יעקב\" - זבורוב-סלובקיה תרפה."},{"i":17572,"n":"ויסע, יוסף מעיר חדש","f":"יצחק שמואל","bt":"תקעב","bp":"פלימענע-ליד פרוסטיץ","dt":"תרס - ה כסלו","b":"רב בפרערוי, גאיא, עיר חדש-תרי כ-42 שנה."},{"i":17573,"n":"ויסקי, יהושע ליב","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ."},{"i":17574,"n":"ויסקי, יצחק יוסף","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח."},{"i":17575,"n":"ויסקנסקי, נחמיה אלתר","f":"שמואל","bt":"תרטז","b":"רב בוויזנא-פלך וארשא-תרם, ראדזימין-תרנא."},{"i":17576,"n":"ויסר, דב ברל מצורטקוב","b":"מחכמי צורטקוב-תרכח."},{"i":17577,"n":"ויסשטין, אשר","b":"רב בסלונים"},{"i":17578,"n":"ויסשטין, משה שמואל מטרנופול","f":"עזריאל הלוי","k":"בעל דרך אמונה","bt":"תקסב","bp":"טרנפול","dt":"תרמב","b":"מחכמי טרנופול. חיבר \"דרך אמונה\" דרוהוביטש תרנז."},{"i":17579,"n":"ויסשטין, צבי הירש מבילקמין","f":"משה איזנשטין","k":"בעל מאורות צבי","bt":"תף או תץ","bp":"בילקמין","dt":"תקנג - יט אב","b":"דיין אצל ר אריה ליב ברנשטיין רב המדינה, רב בבילקמין(=בולקאמין) - איזנשטין, ראב\"ד בלבוב. בנו ר מאיר קריסטיאנופולר - ראב\"ד ברודי. חיבר \"מאורות צבי\" - בכתב יד. נזכר ב\"זכרון כהונה\", \"נפש דוד\", חתם-תקן עם ר שמואל שיינדלינגר. בנו - ר מאיר קריסטינאפוליר מברודי בעל \"יד המאיר\"."},{"i":17580,"n":"ויפש מקלוניא-קלן","b":"מגדולי חכמי אשכנז,מרביץ תורה בקלוניא-ר\"מ"},{"i":17581,"n":"ויציק, משה יצחק מראגולה","dt":"תשג","b":"רב בסויאדושץ, ראגולה. נספה בשואה."},{"i":17582,"n":"ויצמן, יעקב מימפולי","bt":"תרך","bp":"ימפולי","dt":"תרפא - כד חשון","b":"רבה של גרודק(=גרידינג). פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד, \"קובץ מפרשי התורה\" - מארגרטן תרצג."},{"i":17583,"n":"ויצמן, יעקב מלובלין","b":"פרסם מאמרים ב\"העץ\" - לובלין תרצג."},{"i":17584,"n":"ויצן, שמואל יוסף מזלין","b":"רב בזלין."},{"i":17585,"n":"ויצנבלום, יצחק מקשאנוב","f":"אברהם צבי","bt":"תרלט","dt":"תשב","b":"תלמיד ר נח הולצר. חתן ר שלמה גלזר. נספה בשואה."},{"i":17586,"n":"ויצנהויזן, יהודה יודא מברלין","b":"מראשי הקהילה בברלין. חתם על הסכם ויתור מס הקהילה ממשה מנדלסון-תקכג."},{"i":17587,"n":"ויצנפלד, אברהם יעקב מקראקא","f":"שמחה משה","k":"בעל חליפת מכתבים","bt":"תקפט","bp":"קראקא","dt":"תרנח","b":"חתן ר יוסף ליזר מגזירז. והתגורר בזגירז, ושב לקראקא לאחר שגורש מרוסיה. חיבר \"חליפת מכתבים\" קראקא תרס."},{"i":17588,"n":"ויצנר, אהרן צבי מפשמישל","f":"מתתיהו","bt":"תרסו","bp":"פשמישל","b":"חתן ר חיים כץ חסיד הוסיאטין. ניצל מהשואה, אחרי השואה גר בצורטקוב ובברעזוב ופעל רבות להיתר עגונות. רבה של פשמישל. עבר לבודפסט-תשו. חתן בזיוו\"ש של ר יוסף דוד טורקלטאוב אב\"ד דיורע. עבר לארה\"ב-תריא וכיהן כרב בניו יורק."},{"i":17589,"n":"ויצנר, מנחם יהושע","k":"בעל דברי שלום ואמת","b":"חיבר \"דברי שלום ואמת\" קולומיאה תרנח (שם המחבר בשער - \"יו\"ם\". ניסה לארגן אספת רבנים בלמברג."},{"i":17590,"n":"ויקסלבוים, יעקב מרישא","f":"שלמה אריה וינשלבוים"},{"i":17591,"n":"וירגא - משפחה","b":"משפחת רבנים מספרד."},{"i":17592,"n":"וירגא ן, יהודה מספרד","k":"בעל שבט יהודה","b":"מקובל, אסטרונום, ומקורב למלכות, רב בשביליא-ספרד, ברח לליסבון בגזירת השמד-רמ (עוד לפני הגירוש), ונהרג עק\"ה בכלא כשסירב לגלות את שמות האנוסים. חיבר \"שבט יהודה\" על צרות ישראל במשך התקופות."},{"i":17593,"n":"וירגא ן, יהודה מרודוס","f":"יוסף מאדרינופול","k":"בעל קצור ספר המספר","bp":"רודוס או אדרינופול","dp":"רודוס","b":"בשנת שך היה מחכמי רודוס, עלה לצפת בזמנו של ר יוסף קארו ואחת משאלותיו מובא בשות \"אבקת רוכל\" (לדעת רוזניס - נפטר ברודוס בטרם הספיק לעלות לצפת)."},{"i":17594,"n":"וירגא ן, יוסף מאדרינופול-הנכד","f":"שלמה","k":"בעל שארית יוסף","dt":"שיב","b":"רב ודיין באדרינופולי. בנו - ר יהודה מרודוס. (אצל רוזניס - יש בלבול בינו לבין בעל אותו השם שהיה ממגורשי ספרד - אולי זקנו?)."},{"i":17595,"n":"וירגא ן, יוסף מספרד - הזקן","k":"בעל שבט יהודה","bt":"רך","bp":"שיריץ-ספרד","b":"מחכמי ספרד, לאחר הגירוש עבר לפורטוגל, עבר לתורכיה, רב באדרינופול. העתיק ספר קרובו ר יהודה - \"שבט יהודה\", עם הוספות ממנו. אחיו - ר שלמה - השלים את חבורו. (למעשה יש בלבול"},{"i":17596,"n":"וירגא ן, מאיר מאיטליה","dt":"שי","b":"מחכמי ספרד שהגיע לאיטליה בזמן הגירוש, עבר לאוילונה(=אבילונה)-אלבניה, עבר לשלוניקי. תלמיד ר דוד מסיר ליאון, ור יוסף פאסי. דיבר פעם כנגד הרמב\"ם ולבסוף נידוהו וביקש מחילה בבי\"ד."},{"i":17597,"n":"וירגא ן, שלמה מספרד איטליה אדר","k":"בעל שבט יהודה","b":"מחכמי ספרד ומקובל ותוכן נודע, לאחר כיבוש מלגה-רמז - פעל למען היהודים שנשבו בשליחות הקהלות. לאחר הגירוש עבר לפורטוגל, נאלץ לחיות כאנוס עד שהורשו האנוסים לעזוב-רסו ועבר לאיטליה (ולדעת רוזניס עבר לאדרינופול וכיהן כרב ודיין). לאחר פטירת אחיו - ר יוסף - שהעתיק וערך את ספר קרובם \"שבט יהודה\" והשלים-רף את הספר, ובספרו חולק על הפילוסופיה של ר יהודה הלוי ושל הרמבם."},{"i":17598,"n":"וירגא ן, שמואל מספרד וצפת","f":"יהודה","b":"מחכמי ספרד, והגיע לצפת אחר הגירוש (לפי רוזניס ישב ברודוס ורק בסוף ימיו הגיע לצפת). מובא בתשובות הרדב\"ז, נשא ונתן עם ר יוסף קארו והמבי\"ט. חתם-שכט על מכתב התמיכה של רבני קושטא ומצרים בדון יוסף נשיא."},{"i":17599,"n":"וירגא שלמה בן יהודה","bt":"1460","dt":"ה'שיד 1554","bk":[["שבט יהודה",""]]},{"i":17600,"n":"וירגא, משה","b":"רב-שנת ש'"},{"i":17601,"n":"וירט, אהרן","b":"עורך הקובץ \"אור תורה\" קולומיאה תרץ."},{"i":17602,"n":"וירנה ן, יהודה","b":"עק\"ה,מקובל,תוכן ומהנדס,רב בשיבילה,ברח לליסבון ונתפס שם"},{"i":17603,"n":"וירניק, מאיר מוארחופקי","f":"ישראל יהודה","bt":"תרכח","b":"רב בוארחופקה-פודוליה-תרסב."},{"i":17604,"n":"וירניק, צבי זאב מוילנא","f":"שלמה זלמן","k":"בעל קרני צבי"},{"i":17605,"n":"וירקר, מאיר","k":"בעל כתנות אור","b":"דיין בחרחוב-ת\"ק"},{"i":17606,"n":"וישוביאנסקי, דב מרדכי מלוקניק","f":"מאיר","b":"תלמיד ר אליהו רגולר. חתן ר שמואל קלמר-אחיו של רבו. בנו - ר הירש יעקב טוב מראסיין."},{"i":17607,"n":"וישינסקי, מרדכי יואל מקוטנא","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא, \"נהור שרגא\" - אלכסנדר תרצט."},{"i":17608,"n":"וישל","k":"חתן הרש\"ל","b":"מגדולי חכמי דורו בלובלין-ש\"ס"},{"i":17609,"n":"וישנבסקי, יהושע ליב","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ."},{"i":17610,"n":"וישנבסקי, יעקב ממינסק","b":"חתן ר משה יהודה ליב בעל \"מילי דאבות\". מו\"צ במינסק. חתנו - הגביר ר שמחה ליב איזראליט מקלצק."},{"i":17611,"n":"וישנבסקי, פרץ מקלישצוב.","b":"גביר תלמיד חכם בקלישצוב. חתנו - ר יצחק מאיר קלטנובסקי."},{"i":17612,"n":"וישנוביץ, דוד אהרן מארה\"ב","k":"בעל אמרי דעת","b":"מחכמי ארה\"ב. חיבר \"אמרי דעת\" נ\"י תרעח."},{"i":17613,"n":"וישניבסקי, יצחק אליזר","dt":"תשא","b":"רב בקאלטינאן"},{"i":17614,"n":"וישניק, אליעזר אלימלך מבילסק","b":"רב בבילסק. הניח חבורים על הש\"ס - בכת\"י."},{"i":17615,"n":"וישקובסקי, אברהם מאוטואצק","b":"פרסם מאמרים ב\"יגדיל תורה\" - פראגא-וארשא תרפז."},{"i":17616,"n":"וכטפוגל, דוד מארה\"ב","f":"משה יום טוב ממונטריא","b":"רב בקהלת \"לינת הצדק\" בפילדלפיה."},{"i":17617,"n":"וכטפוגל, חיים יוסף מארה\"ב","f":"משה יום טוב ממונטריא","b":"רב בקהלת \"בית ישראל\" בקיימבריג-מסצוסס."},{"i":17618,"n":"וכטפוגל, יצחק יעקב מירושלים","dt":"תשלה - כה שבט","b":"מו\"צ בירושלים-תרפז. פרסם מאמרים ב\"הדביר\" - ירושלים תרעט, \"ועד חכמים\" - ירושלים תרפג, \"כרם ציון\" - ירושלים תרצה-תשיג - קובץ \"מדרש בני ציון\", \"קול תורה\" - ירושלים תרץ."},{"i":17619,"n":"וכטפוגל, משה יו\"ט מקול וקנדה","f":"דוד","k":"בעל דברי משה","bt":"תרלט","bp":"מזריטש","dt":"תשיא","dp":"מוטריאול - ירושלים","b":"תלמיד ישיבות לומז'ה, סלובודקה, סלוצק (היה מ-14 התלמידים שהביא עמו ר איסר זלמן מלצר - כשהקים את הישיבה). מגדולי בעלי המוסר. רב בקויל-ליד פלונגיאן, מונטריאול-תרפ, וכיהן כסגן יו\"ר ועד הרבנים שם לצד ר צבי הירש הכהן. פרסם מאמרים ב\"מרכז התורה\" - מונטריאול תשב. בניו: ר נתן מאיר, ר דוד, ר חיים יוסף."},{"i":17620,"n":"וכטפוגל, נתן מאיר מארה\"ב","f":"משה יום טוב ממונטריא","b":"מנהל ישיבת לייקווד."},{"i":17621,"n":"וכטרליץ, אשר משאטמנסדורף","dt":"תקפז - יג אייר","dp":"פרשבורג","b":"תלמיד החת\"ס. חתן ר ישכר דב בר הלוי פרנק סופר קהילת פרשבורג. רב בשאטמנסדורף(=שוטלסדורף)-תקפד, פרשבורג, מגיד בפרג. תשובה אליו ב\"חתם סופר\". (עסק קצת במסחר אך לא הצליח מחמת שהקדיש את זמנו לתורה - פעם שאלו החת\"ס אודות הצלחתו והשיב שמצדו המשיח כבר יכול לבוא - ע\"ד שאמרו \"אין בן דוד בא עד שיכלה פרוטה מן הכיס\")."},{"i":17622,"n":"וכשטיין, דב ברנרד","b":"פרסם מאמרים ב\"אהל מועד\" - פודגורזע תרנח."},{"i":17623,"n":"ולאגו, שבתי מירושלים","b":"מחכמי ישיבת \"בית אל\" בירושלים-תקיח."},{"i":17624,"n":"ולבר, אהרן מתתיה ממונקטש ופעסט","k":"בעל לקוטי ראם","bt":"תרה","dt":"תרעח - אחרי","b":"תלמיד המהר\"ם שיק, האדמור ר יצחק איזיק מזידיטשוב, מקורב גם לאדמור ר יוסף מאיר מספינקא. סופר סת\"ם מחכמי מונקטש, עבר לבודפשט. חיבר לוח ימי שנות עולם, \"לקוטי ראם\", ועוד - בכת\"י. הגיה ספרי תורה עבור כמה אדמורים, וכן הגיה עבור ר שלמה גנצפריד את ספרו \"קסת סופר\"."},{"i":17625,"n":"ולברומסקי, יחיאל או ירחמיאל","bt":"תרסה","dt":"תשג","b":"רב בקאלי, ליטומירסק-תרצד."},{"i":17626,"n":"ולברינסקי, י' ח' דוד מסקידל","f":"משה צבי מסקידל","bt":"תרמח","dt":"תרצא - כט טבת","b":"נכד(-אבי אמו) ר יחיאל מיכל אפשטין בעל \"ערוך השלחן\". דרשן, אב\"ד סקידל על מקום אביו, היגר לארה\"ב וכיהן כרב בברונקס-ניו יורק."},{"i":17627,"n":"ולברינסקי, משה צבי הירש מסקידל","k":"בעל שאל וענה","b":"חתן ר יחיאל מיכל אפשטין בעל \"ערוך השלחן\". רב בסקידל-תרס."},{"i":17628,"n":"ולגלרנטר, איתמר מקונסקוואלא","k":"בעל משמרת איתמר","dt":"תקצא - יז אייר","b":"תלמיד החוזה מלובלין, המגיד מקוזניץ, והיהודה הקדוש מפשיסחא. כונה בשם \"השרף\". גביר ולמדן. חיבר \"משמרת איתמר\". בנו ר חיים משה יצחק.","bk":[["משמרת איתמר - עה\"ת",""]]},{"i":17629,"n":"ולגלרנטר, חיים יצחק מקראקא","b":"תלמיד ישיבה בקראקא. תשובה אליו \"משיב שלום\"."},{"i":17630,"n":"ולגלרנטר, ירחמיאל אלימלך מארה","f":"ישראל אלעזר","bt":"תרסט","bp":"מיעכוב-פלך קילצע","b":"תלמיד ר הירש ליב פרומר מזבריצא, מהרי\"ל גרוברד מטורונטו, ישיבת רבי יצחק אלחנן בניו יורק. רב בקהלת \"בית יעקב\", \"עדת ישראל\" בהמילטון-קנדה-תרץ, דטרויט בקהל \"בית תפלה עמנואל\". חבר אגודת הרבנים באמריקה. נשיא ישיבת \"בית יהודה\" בדטרויט."},{"i":17631,"n":"ולד, אליהו","f":"מרדכי אריה ליב מקירל","b":"אביו של ר אפרים ואלד בעל \"שבט אפרים\"."},{"i":17632,"n":"ולד, אפרים מסטמר","f":"אליהו בן מרדכי","k":"בעל שבט אפרים-תרפז","dt":"תש..","b":"מחכמי סטמר. תלמיד ר שאול בראך מקרולה. גיסו של ר נטע יעקב ברגר מאודווארי. נספה בשואה."},{"i":17633,"n":"ולד, דן מלמברג","b":"חסיד בלז. רב בזולקוא. ר\"מ בישיבת רדומסק בבנדין. חתן ר אהרן לורברבוים. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":17634,"n":"ולד, יוסף מהעלמעץ","f":"מרדכי אריה מהעלמעץ","dt":"תרסו - טו אייר","b":"רב בהאנשוויץ, העלמעץ וגליל בודרוג, וחתנו ר יואל צבי גלטשטין על מקומו אחריו."},{"i":17635,"n":"ולד, יעקב מאיר מקלויזנבורג","f":"יוסף מקירל הלמעץ","bt":"תרכו או תרלד","dt":"תרפח - יב טבת","dp":"קלויזנבורג","b":"תלמיד השב\"ס. חתן ר יוסף שמחה רפפורט (לפי חכמי טרנסילבניה ואהלי שם - חתן ר משה שמואל גלזנר מקלויזנבורג). רב בקלויזנבורג-תרנח, וחתנו ר שמעון בלוקסנהים על מקומו אחריו."},{"i":17636,"n":"ולד, מרדכי אריה ליב מקיראל","f":"מנחם מנדל גרליחיוער","bt":"תקנה","bp":"ברדיוב","dt":"תרלו - טו אלול","dp":"קיראל-העלמעץ","b":"תלמיד החת\"ס ור שלום אולמן לקנבאך, ובזיוו\"ש חתןר יונתן בנימין אסטריכר מטשענגער. רב בהאנשוביץ-תרו, קיראל-העלמעץ-תרח, בנו ר יוסף על מקומו אחריו."},{"i":17637,"n":"ולד, שמשון זליג מטשען","f":"יהודה אריה ליב","bt":"תרעא","bp":"זבורוב","dt":"תשד","b":"חתן ר חיים כץ מקאשוי, עבר לגור בקאשוי. נספה בשואה. השאיר כתבים רבים שמהם חובר \"עמודי שמשון\" שנדפס בסוף \"שפתי מהרי\"ש השלם\" לונדון תשלג."},{"i":17638,"n":"ולדברג, משה מלמברג","f":"יואל","k":"בעל כך היא דרכה של","bt":"תקצב","bp":"למברג","dt":"תרסא","b":"חתן הגביר ר אריה ליב כהנא מיאסי. התגורר ביאסי. התעשר מעסקי בנקאות וקיבל מהקיסר תואר \"ברון\". חיבר \"כך היא דרכה של תורה\" יאסי תרכד - והוא כנגד ספר \"דרכה של תורה\"."},{"i":17639,"n":"ולדברג, שמואל מירוסלב","f":"יואל","k":"בעל עטרת שושנים","bt":"תקץ","bp":"למברג","dt":"תרסו","b":"חתן ר אברהם הלוי בירנבוים מפילץ. רבה של זולקווא-תריז, ירוסלב-תרכז. חיבר גם \"דרכי שינויים\" למברג תריד. פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז."},{"i":17640,"n":"ולדיסלובסקי, יחיאל' יהודה ליב","f":"דוד זיידל","dt":"ז כסלו","b":"נכד ר איזיק בן דוד בן נחום מלאסק. חתן - ר משה מאוזרקוב-חתנו של ר חיים אוירבך מלונטשיץ. רב בקוואהל, בלאשקי. בנו - ר מנחם מקאזמינקא."},{"i":17641,"n":"ולדיסלובסקי, מנחם מקזמינקה","f":"יחיאל יהודה","b":"רב בקאזמינקה"},{"i":17642,"n":"ולדלר, אברהם ליפמן משנלנקה","b":"רב בשנלנקה-תרנ\"ה"},{"i":17643,"n":"ולדלר, יעקב","f":"צבי הרש","dt":"תרסב - בערך","b":"תלמיד החת\"ס. אחיו של ר משה."},{"i":17644,"n":"ולדלר, משה מיערגין","b":"חתן ר מרדכי שלנק בירושלים. אחיו של ר יעקב."},{"i":17645,"n":"ולדלר, שלמה ליפמן משלאנק","f":"משה","bt":"תקצא","bp":"יערגין","dt":"תרסד - ה סיון","b":"לאחר שנתייתם-תרי גדל אצל הכת\"ס. תלמיד ר דוד ביסטריץ ממליכדורף. חתן ר פנחס ליב פרידן מקאמארן ועבר לשם. רב בקיקינדע-תרכב, שלאנק-תרכה. פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז, \"יגדיל תורה\" - ברלין-קראקא תרנא."},{"i":17646,"n":"ולדמירסקי, משה יצחק מסחוב","dt":"תשג","b":"רב בסחוב"},{"i":17647,"n":"ולדמן, אלעזר אלימלך","f":"ישראל שמעון מאיר"},{"i":17648,"n":"ולדמן, ארנו מקו-באניא","dt":"תשד","b":"רב הקהילה הניאולוגית בקו-באניא-ליד-1938 בודפשט. נספה בשואה."},{"i":17649,"n":"ולדמן, זליג זאב וולף מירוסלב","f":"שלמה זלמן","bt":"תרמט","bp":"ירוסלב","dt":"תשב","b":"חתן ר יהודה ליב קפרף והתישב בפפד\"מ כסוחר ספרים עתיקים. נספה בשואה - בסיביר."},{"i":17650,"n":"ולדמן, יחזקאל מאיר","b":"פרסם מאמרים ב\"בית מדרש\" - תל אביב תשא."},{"i":17651,"n":"ולדמן, יעקב צבי מבורשה-מארמרוש","f":"מרדכי ליבוש מהעלמעץ","dt":"תרמג - כז אב","dp":"וינה","b":"חסיד צאנז. חתן ר ברוך אברהם בינדיגר מהנשביץ. רב בבורשא-מארמרוש-תרטו, היה מחלוקת-תרל בינו לבין חסידי ויזניץ בעירו לאחר שאחד מהחסידים אמר כי האדמור מויזניץ הוא המשיח, הרב יצא כנגד דבריו ועל כך החרימוהו חסידי ויזניץ, ובהתערבות האדמור מויזניץ הוחזר לרבנותו. בניו ר משה עזריאל דיין בבורשא, ר מנחם שלום, ר ישראל שמעון מאיר. חתניו - ר ישכר בערצי לייפר - אדמור מאונגוואר, ר מנחם זאב ויסברג. מחדושיו בירחון \"ילקוט יוסף\"."},{"i":17652,"n":"ולדמן, ישראל שמעון מאיר","f":"יעקב צבי מבורשה","b":"נכד(-אבי אמו) ר ברוך אברהם בינדיגר. חתן ר שמואל שפירא מלנצהוט. בנו - ר אלעזר אלימלך."},{"i":17653,"n":"ולדמן, מנחם מנדל שלום מקלאסני","f":"יעקב צבי מבורשה","bt":"תרך","dt":"תרץ","b":"חתן ר משה בינדיגר מבוקובסק. רב בקלסני-ויליצקה-תרס."},{"i":17654,"n":"ולדמן, מנלי מזלישטשיק","b":"מחכמי זלישטשיק. תשובה אליו - טוט\"ד."},{"i":17655,"n":"ולדמן, משה עזריאל מבורשה","f":"יעקב צבי מבורשה","dt":"תרצד - י ניסן","b":"תלמיד בעל \"ייטב לב\" בסיגט. חסיד צאנז. רב בבורשה-מארמרוש-תרעד."},{"i":17656,"n":"ולדמן, נפתלי מנחם מביסטריץ","b":"חתן ר עוזיאל בודנר-מייזלש מביסטריץ. דיין בביסטריץ-תרצב על מקום חותנו. נספה בשואה."},{"i":17657,"n":"ולדן, אהרן מוארשא","f":"ישעיהו נתן","k":"בעל שם הגדולים החדש","dt":"תרעב - כג תמוז","dp":"קיעלץ","b":"מקושר לגדולי האדמורים ובהם ר מנחם מנדל מקוצק, בעל חדושי הרי\"ם, ועוד. רב בוארשא. חיבר גם \"מקדש מעט\", ועוד. בנו - משה מנחם בעל \"נפלאות הרבי\", יצחק מאיר, ר יוסף אריה ליב."},{"i":17658,"n":"ולדן, משה מנחם","f":"אהרן-שם הגדולים החדש","k":"בעל נפלאות הרבי"},{"i":17659,"n":"ולדנברג, אליעזר יהודה מירושלים","b":"רב בירושלים. פרסם מאמרים ב\"בכורי ציון\" - ירושלים תשד, \"המאור\" - תל אביב תרצה, \"הפוסק\" - תל אביב תש-תשיד, \"קול תורה\" - ירושלים תרץ-תשז."},{"i":17660,"n":"ולדר, אליעזר מנארול","k":"עורך גפן פוריה","b":"מחכמי נארול, וארשא. השתתף בעריכת הירחון \"גפן פוריה\". פרסם מאמרים ב\"חדרי תורה\" - קראקא תרפו. ?? לא באוצר ??"},{"i":17661,"n":"ולדר, שלמה ליפמן משענלנקע","b":"אב\"ד שענלענקע. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"יגדיל תורה\" - ברלין-קראקא תרנא, \"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":17662,"n":"ולדרסקי, ישראל","f":"חייקל שפירא","k":"בעל מקוה ישראל","b":"רב בנאוואפרגא-תר\"כ"},{"i":17663,"n":"ולדשטין, אברהם שלמה מארה\"ב","k":"בעל מילון עברי אנגלי","bt":"תרלד","bp":"קובנא","dt":"תרצב - סיון","b":"חכם וסופר בניו יורק, עלה לארץ-תרעד והיה מורה בתל אביב."},{"i":17664,"n":"ולדשטין, אמיל מפרשבורג","b":"עתונאי ציוני, עבר לפרשבורג והיה מזכיר התאחדות הקהלות בסלובקיה-תרעט."},{"i":17665,"n":"ולדשטין, יצחק אלחנן","k":"השערשובר","bt":"תרנד","bp":"שרשוב","dt":"תשא-ג","b":"תלמיד הסבא מנוברדוק. חתן ר אלתר שמואלביץ, וגיסו של ר חיים שמואלביץ. ר\"מ בישיבת בית יוסף בפינסק, ובאוסטרובצה. נספה בשואה."},{"i":17666,"n":"ולדשטין, משה מגניזן","b":"רב בגניזן-תר\"כ"},{"i":17667,"n":"ולדשטין-השרשרובר, י'א","k":"בעל תורת יצחק","dt":"תשג","b":". ?? לא באוצר ??"},{"i":17668,"n":"ולדשן, אברהם אהרן מאלקניק","dt":"תשא","b":"רב באלקניק"},{"i":17669,"n":"ולודובר, צבי הירש מהיבניב","b":"צדיק בהיבניב-תרח."},{"i":17670,"n":"ולוזינוס (ולוסיניו), יעקב","bt":"1657","bp":"פרנמבוקא-אמריקה","b":"רופא בן למשפחת אנוסים שהגיעו להולנד ומשם לאמריקה, עבר להאג, אנטורפן. חיבר ספר פילוסופיה כנגד שפינוזה, וספר כנגד החכם הנוצרי ראקעלא - על יסודות אמונת ישראל."},{"i":17671,"n":"ולוזינוס (ולוסיניו), יצחק","b":"תלמיד ר יצחק אבוהב. רב באמשטרדם. דרשה ממנו מיום חנוכת ביהכ\"נ הספרדי - ונדפסה באוסף דרשות - אמשטרדם 1675."},{"i":17672,"n":"ולוסקי, אברהם יעקב","bt":"תר","dt":"תשלד - ד אב","b":"רב בדנציג,אנגליה,עלה לא\"י-תש\"ח"},{"i":17673,"n":"ולוסקי, אברהם ירוחם פישל","f":"נפתלי הירץ וולוסקר","b":"חתן ר יעקב שלמה רוטנברג מלינסק. רב בלינסק על מקום חותנו."},{"i":17674,"n":"ולוסקי, ליבוש מסמבור","dp":"ניו יורק","b":"היגר לאהרב-תרמח. רב לקהילת יוצאי גליציה בניו יורק."},{"i":17675,"n":"ולוצקי, קופל","f":"הלל","bt":"1865","bp":"ליטא","dt":"1926","dp":"קובנא","b":"תלמיד ביהמ\"ד למורים בוילנא. מורה ומנהל בי\"ס יהודי ממשלתי בקובנא, עסקן ציבורי. מנהל הגימנסיה העברית בקובנא. מזכיר ראשי של קהילת קובנא."},{"i":17676,"n":"ולטירא, אהרן חי מונציה","k":"בעל בקשה חדשה","b":"רב משורר ודרשן בונציה-תצה בזמן הרמ\"ז ור ישעיה ניצה. זקנו של ר חיים ואלטירה הנזכר ב\"פחד יצחק\". משיריו נדפסו בשם \"בקשה חדשה\" - ליוורנו תק."},{"i":17677,"n":"ולטירא, חיים מונציה","f":"משה","bp":"ונציה","b":"רב באנקונה, סיניגאליה, פינאלי, ונציה. תשובה ממנו בענין אתרוג - והיה מחלוקת עם רבני אישפלטרו וטורינו. חתם עם רבני ונציה כנגד פסק ר יעקב חזק מפדובה."},{"i":17678,"n":"ולטירו, חיים","b":"רב-שנת תק\"מ"},{"i":17679,"n":"ולטמן, יצחק מהאראדניע ונ\"י","k":"בעל שיח יצחק","b":"רב בהאראדניע, ניו יורק-תרפד."},{"i":17680,"n":"ולטמן, שמואל צבי מקאליש","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":17681,"n":"ולטנר, זושיה מאנגליה","bt":"תרעג - בערך","bp":"הונגריה","dt":"תשסג","dp":"ירושלים","b":"היגר לאנגליה-תרצט, ולמד בגייטסהד. הקים ישיבה בסנדרלנד-אנגליה ובה למדו תלמידים רבים ממרוקו. הקים ישיבה בטנג'יר-תשיב (בסיוע שמואל טולדנו). מנהל \"אוצר התורה\" במרוקו-תשטו. עלה לירושלים-תשם."},{"i":17682,"n":"ולטספרייד, א' שמואל","dt":"תשג","b":"רב בטאמשוב,מזוויצק"},{"i":17683,"n":"ולטפרויד, אברהם משה מפשדבורז","f":"עמנואל ולטפרייד","k":"אדמור מפשדבורז רוספש","bt":"תר","dt":"תרעח - כב אלול","dp":"פשדבורז","b":"תלמיד הדברי חיים מצאנז. חתן הגביר ר גרשון חיים לנדא מקמינסק, ובזיוו\"ש חתן הגביר ר מאיר אברמזון מלובלין. רב בסילעוו (=סובליוב)-תרכט ברח בגלל עלילת דם שהעוללה עליו-תרלב, פשדבורז-תרלג על מקום אביו, רב ואדמור ברוספשא-תרמה, וחזר לפשדבורז-תרעו. בנו - ר חיים אליעזר מפשדבורז (נפטר צעיר)."},{"i":17684,"n":"ולטפרויד, אלתר מאיר עמנואל","b":"מחכמי צנסטחוב. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":17685,"n":"ולטפרויד, ישעיה מוואלא קאליש","f":"אברהם משה מרוספשא","k":"אדמור מוואלא קאליש","dt":"תרצט - יב אב","b":"חתן ר יחיאל מאלכסנדר. האדמור הראשון בקאליש. התפרסם כבעל תפלה ויודע נגן."},{"i":17686,"n":"ולטפרויד, ישעיה מפשדבורז","f":"מאיר מלוסק","k":"אדמור מפשדבורז","bt":"תקיח","dt":"תקצא - ד אלול","dp":"פשדבורז","b":"תלמיד החוזה מלובלין, היהודי הקדוש מפשיסחא, ור דוד מללוב. חתן ר דן לוינברג. רב בפשדבורז ובנו ר עמנואל מאן על מקומו אחריו-תרי (ובגלל שהיה צעיר נתמנה בינתיים ר משה מללוב לאב\"ד פשדבורז עד שעלה לירושלים). מתורתו ב\"דברות חיים\"."},{"i":17687,"n":"ולטפרויד, ישראל","f":"שלמה זלמן וולטפרויד","dt":"תשג","b":"מו\"צ בשידלובצה"},{"i":17688,"n":"ולטפרויד, ישראל מרדומסק","f":"אברהם משה מרוספשא","k":"אדמור מרדומסק","dt":"תש..","dp":"[סוסנוביץ]","b":"חתן ר אברהם מפשיטיק (שושלת פשיסחא). רב ואדמור ברדומסק-תרע. נספה בשואה."},{"i":17689,"n":"ולטפרויד, מאיר","f":"שלמה זלמן וולטפרויד","dt":"תשג","b":"מו\"צ בקאליש"},{"i":17690,"n":"ולטפרויד, נח אליהו מפשדבורז","f":"חיים אליעזר","b":"התייתם בילדותו. מכתב המלצה עבורו מר נתן דוד גרינבוים מפשדבורז-תרצה."},{"i":17691,"n":"ולטפרויד, עמנואל מפאביניץ לודז","f":"אברהם משה מרוספשא","k":"אדמור מפאביניץ ולודז","dt":"תרצט - יט אדר","b":"נכד ר ישעיה מפשעדבורז. חתן ר יהושע מדזיקוב, ובזיוו\"ש חתן ר אריה ליב מאוזרוב. אדמור בפאביאניץ, לודז-תרפא. בהלוויתו בלודז השתתפו כמאה אלף יהודים. קברו נכרה ע\"י ר אליעזר דוד מרדושיץ."},{"i":17692,"n":"ולטפרויד, עמנואל מפשדבורז","f":"ישעיה מפשדבורז","k":"אדמור מפשדבורז","bt":"תקסג","dt":"תרכד - כז שבט","dp":"וארשא","b":"תלמיד ר ישכר דב מרדושיץ. חתן ר ישראל בן החוזה מלובלין, ובזיוו\"ש חתן ר משה אהרן מקוטנא. רב ואדמור בפשדבורז-תרי - על מקום אביו (ר משה מללוב כיהן באופן זמני על מקום אביו עד שעלה לירושלים) ובנו ר אברהם משה על מקומו אחריו."},{"i":17693,"n":"ולטפרויד, פנחס","f":"שלמה זלמן ולטפריי","dt":"תשג","b":"רב בוונכצק"},{"i":17694,"n":"ולטפרויד, שלמה זלמן מטומשוב","f":"אברהם משה מרוספשא","k":"אדמור מטומשוב רוספשא","bt":"תרל","dt":"תשב","b":"חתן ר פנחס מקינצק (שושלת פשיסחא). אדמור ברוספשא, טומשוב, לודז-במלחה\"ע ה-I, עבר לוארשא בתחילת השואה. נספה בשואה עם שבעת בניו."},{"i":17695,"n":"ולטפרוינד, חיים אליעזר מפשדבור","f":"אברהם משה","k":"אדמור מפשדבורז","b":"נכד ר עמנואל מפשדבורז. אב\"ד פשדבורז. נפטר צעיר. בנו - ר נח אליהו."},{"i":17696,"n":"ולטפרוינד, חיים מלודז","f":"עמנואל מפאביניץ לודז","bt":"תרנז","dt":"תשב - כט אדר","dp":"דומברובה","b":"חתן ר יוסף יהודה צארניכע-חתן ר אשר אנשיל מרדושיץ-לודז. רב בלודז, נתבקש להיות אדמור לחסידים באנטורפן אך לא הסתייע. נספה בשואה."},{"i":17697,"n":"ולטפרוינד, יצחק מאיר מפאביניץ","f":"עמנואל מפאביניץ לודז","k":"אדמור מלודז","bt":"תרנו","dt":"תשג - טו תשרי","dp":"טרבלינקה","b":"חתן דודו ר יחזקאל-אחיו וחתנו של ר אברהם משה מרוספשא, ובזיוו\"ש חתן ר אלימלך מסטאשוב (ליזנסק). אדמור בחיי אביו בלודז."},{"i":17698,"n":"ולטשוק, אברהם שמואל מברזנה","b":"חתן ר דוד אריה. רב בברזנה-תרס. חתנו - ר שניאור זלמן גורליק."},{"i":17699,"n":"וליטובסקי, שלמה מבושביץ","f":"יהושע דב בער","k":"בעל שביב המאיר","b":"רב בבושאוויץ-פלך מינסק-תרלח. חיבר \"שביב המאיר\" - תרסח."},{"i":17700,"n":"וליטשקער, אלימלך מסטניסלב","b":"פרסם מאמרים ב\"קבוצי בחורים\" - מארגרטן תרצג."},{"i":17701,"n":"ולייסיד","k":"ראה: וילייסייד","b":"מחכמי קושטא. עלה לירושלים."},{"i":17702,"n":"וליניץ, אהרן אשר מארה\"ב","k":"בעל שמירת שבת","b":"רב בארה\"ב-תשב. ?? לא באוצר ??"},{"i":17703,"n":"ולירו, חיים אהרן מירושלים","f":"יעקב","bt":"תרה","bp":"ירושלים","dt":"תרפג - ט אלול","dp":"ירושלים","b":"גביר בירושלים, מראשי העדה הספרדית. אחיו יוסף משה מיפו."},{"i":17704,"n":"ולירו, יעקב - א","dt":"תקכא - כו אדר","dp":"ירושלים","b":"עלה לירושלים."},{"i":17705,"n":"ולירו, יעקב מירושלים - ג","f":"חיים אהרן מירושלים","bp":"ירושלים","b":"בנקאי בירושלים"},{"i":17706,"n":"ולירו, יעקב מקושטא וירושלים","dt":"תרם - כב כסלו","dp":"ירושלים","b":"עלה לירושלים-תקצה. שו\"ב בירושלים, גביר ומנהיג בעדה הספרדית, חתם בענין המחלוקת בחברון-תרכב, ועוד."},{"i":17707,"n":"ולירו, יצחק מירושלים (ן ואליר)","f":"מנחם","b":"גביר בירושלים-תרל, חתם על מכר קרקע."},{"i":17708,"n":"ולירו, יצחק מקושטא","b":"מדפיס-תעא בדפוס של יונה בן יעקב בקושטא."},{"i":17709,"n":"ולירו, משה מירושלים","f":"חיים אהרן","bt":"תרמג","bp":"ירושלים","b":"שופט בירושלים."},{"i":17710,"n":"ולירו, משה מירושלים ויפו","f":"יעקב מירושלים","dt":"תרלט - יד סיון","b":"התישב ביפו ועסק במסחר, סגן קונסול שבדיה בירושלים וביפו, עסק בעניני צבור, חתם עם רבני ירושלים-תרלז."},{"i":17711,"n":"ולירו, נסים מירושלים","b":"מחכמי ירושלים-תקן."},{"i":17712,"n":"ולירו, שמואל ממוריאה ואיטליה","f":"יהודה","k":"בעל חזון למועד","b":"רב ורופא במוריאה-יוון-של, הגיע לונציה להדפיס את ספריו. כנראה למד רפואה בפדובה, נדד רבות, היה בקורפו-שלט. פאטרץ-שמה, בונציה נעזר בפרנס אברהם שאקי בהדפסת ספריו. חיבר גם \"יד המלך\", \"עמק הבכא\", ועוד."},{"i":17713,"n":"ולך, אברהם מזאלעשיץ","b":"מחכמי זאלעשיץ-תרעג ליד ברוזדוביץ. תשובה אליו \"במחזה אברהם\"."},{"i":17714,"n":"ולך, דוד יהודה מגליציה","b":"נסמך מר יצחק שמלקיס, גר בפפד\"מ. עבר ללונדון. מתורתו - \"יגדיל תורה\"-תשלו ע\"י נינו ח' הלפרין."},{"i":17715,"n":"ולך, יוסף דניאל","f":"שבתי מראזינאי","k":"בעל רחשי לב"},{"i":17716,"n":"ולך, משה מברודי","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":17717,"n":"ולך, שבתי מרוזינאי","bt":"תרג","dt":"תרפט - כג אד\"א","b":"רב ברוזינאי. בנו - ר יוסף דניאל בעל רחשי לב."},{"i":17718,"n":"ולמן, אברהם אבא מזדולבינה","f":"חיים יעקב","bt":"תרלז","b":"רב בזדולבינה-ווהלין-תרס. נסמך מאת: ר שלמה הכהן מוילנא, ר צבי הירש רבינוביץ מקובנא, ר משה דנישבסקי מסלובודקא, ר שלמה יואל מראוונא."},{"i":17719,"n":"ולמן, מנחם מנדל (ישראל)","k":"הו\"ל הכוכבים","b":"סופר חרדי במינסק. הו\"ל \"הכוכבים\", פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן, \"שערי תורה\" - וארשא תרסג-תרצט - בקורת על \"דורות ראשונים\" לראי\"ה הלוי. (ישנו מנחם מנדל הלוי שהיה נכדו של ר משה יהודה זילברברג בעל זית רענן - כנראה בן חתנו - ר ישראל יעקב מפלונסק - האם זה אותו הרב?)"},{"i":17720,"n":"ולנטין, גבריאל מראגוזה","b":"רב בראגוזה-תק."},{"i":17721,"n":"ולנטין, שמעון סגל","b":"אב\"ד יאנקוביץ-ליד באייה. מהחותמים על אסיפת רבני הונגריה נגד הניאולוגים - פאקש-תרד."},{"i":17722,"n":"ולנר, אברהם דוד מצפת","b":"מראשי כולל צפת-תרס."},{"i":17723,"n":"ולנר, אשר לעמל מזשאמבוקרט","f":"יצחק ליב וולנר","dt":"תרלט","b":"רב בזשאמבוקרט"},{"i":17724,"n":"ולנר, דוד ממארמארוש","f":"דב","dt":"תרי - יא אד\"א","b":"תלמיד ר מרדכי בנעט מניקלשבורג. שו\"ב בקיראי-דארוץ."},{"i":17725,"n":"ולנר, יצחק ליב מגלנטא","bp":"סעמניץ","dt":"תרט - יד סיון","b":"רב בגאלאנטא על מקום ר אריה יהודה ליב טלטש-טויבר."},{"i":17726,"n":"ולנר, משה דב מאשקלון","f":"צבי יהודה מפילפסאלאש","k":"בעל חמדת צבי","b":"תלמיד הדעת סופר, ור אשר אליקים טשעך מבורשוד-מעזא-קערסטעש, ור דב לבלוביץ מקיש-קערעש ועוד. חתן ר ישראל ועלץ מבודפשט. רב בבודפשט-תרצז. ניצל מהשואה ואחריה עלה לארץ-תשי וכיהן כרב באשקלון, ירושלים. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד. אחיו - יוסף (נפטר צעיר - תשב)."},{"i":17727,"n":"ולנר, צבי אריה מפילעפסאלאש","b":"שו\"ב בפילעפסאלאש-תש. בנו - ר משה דב."},{"i":17728,"n":"ולנשטין, זולטן מפעטש","dt":"תשד","b":"רב בקהילה הניאולוגית בקומראן(=קומארום)-1920, פעטש. חיבר \"תולדות קהילת פעטש\", ועוד ספרים - בהונגרית. נספה בשואה."},{"i":17729,"n":"ולנשטין, מאיר מבעזע","b":"חתן ר משה נחום רוזנבוים מואשאן. רב בפאפא, בעזע."},{"i":17730,"n":"ולנשטין, משה נחום מירושלים","f":"מאיר","k":"בעל בני משה","r":"ראב\"ד העדה החרדית בירושלם","bt":"תרא","bp":"פאפא (הונגריה)","dt":"תרפב - כג אדר","dp":"ירושלים","b":"תלמיד הכת\"ס, ור אהרן דוד דייטש מבלאלש-ירמוט. חתן אחי רבו ר שמעון דייטש מירושלים. עלה לירושלים-תרכד ועמד בראש עדת הונגריה בירושלים, דיין אצל מהרי\"ל דיסקין ואח\"כ ראב\"ד. חתנו - ר אהרן הלוי פרג מירושלים בעל \"נרות אהרן\".","bk":[["בני משה",""]]},{"i":17731,"n":"ולפגנג, יהודה ליב","dt":"תרנא - יט שבט","b":"דיין בקרקא"},{"i":17732,"n":"ולפה, דוד ממאראטש","dt":"תרמד","b":"רב במאראטש על מקום ר יצחק בן צבי."},{"i":17733,"n":"ולפה, יעקב מאוז'וונט","b":"חתן ר ישראל בנימין בנדט פיבלסון. רב באוז'וונט-ליטא-תרפו."},{"i":17734,"n":"ולפיש מסטרי","b":"צדיק בסטרי בזמן תלמידי הבעשט."},{"i":17735,"n":"ולפיש, ירוחם מוארשא","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":17736,"n":"ולפיש, ישכר בריש משינאווא","k":"בעל קול נגידים","bt":"תקעד","dt":"תרמו","b":"מחכמי שינאווא. חיבר \"קול נגידים\" פרמישלא תרמא, \"מנחת מרחשת\" פרמישלא תרמא. ?? לא באוצר ??"},{"i":17737,"n":"ולפיש, ישראל יעקב מזקרטשין","f":"ישעיה","k":"בעל מחשבות ישראל","bt":"תרי","dt":"תרמו - כב טבת","b":"חתן ר נתן פוזנרזון-פלאצקר מליטמורסק. רב במינצק-ליד וארשא, ז'קרטשין-תרמ. בנו - ר דוד הו\"ל את ספרו \"מחשבות ישראל\" - וארשא תרס."},{"i":17738,"n":"ולפיש, שמחה בונם מפמורן","b":"רב בפמורן. תשובות אליו - שות מהרשם."},{"i":17739,"n":"ולפמן, אפרים הכהן מחווסטוב","f":"חיים צבי מהרמנאווקא","bt":"תרטו","b":"נסמך מאת: ר דוד שור מטולנא, ר בנימין קימלפלד מוסליקוב. רב בטרוויצא(=טאהראוויצא)-תרמא, הרמנובקה(=הערמאנאווקא)-תרמו ובנו ר יצחק איזיק על מקומו אחריו, חווסטוב(=חוואסטוב)-פלך קיוב-תרנט."},{"i":17740,"n":"ולפמן, וילהלם מברודי ואודסה","f":"מתתיה","k":"בעל ישורון","bp":"ברודי","dt":"תרכה - כא אב","dp":"דרזדן","b":"דוקטור לפילוסופיה מלייפציג, התישב באודסה, מוסקבה. חיבר ספר על משוררי גרמניה, חיבר שירים."},{"i":17741,"n":"ולפמן, חיים צבי הכהן","b":"רב ומו\"צ בהרמונקה-תר\"ל"},{"i":17742,"n":"ולפמן, יצחק איזיק מהרמנווקא","f":"אפרים הכהן","bt":"תרלח","b":"רב בהרמנובקה(=הערמאנאווקא)-פלך קיוב-תרנט על מקום אביו שעבר לחווסטוב."},{"i":17743,"n":"ולפסברג, ישראל יהודה ליב מלבוב","k":"בעל קול יהודה","dt":"תשב","b":"רב בויניק, ראב\"ד בלבוב. חיבר הגהות \"קול יהודה\" על ספר חסידים. נספה בשואה."},{"i":17744,"n":"ולפר, אבא","b":"מגיד במינסק"},{"i":17745,"n":"ולפרט, אליעזר מקידאן","b":"רב בקידאן-תר\"כ"},{"i":17746,"n":"ולפרט, אריה ליב דובער","f":"צבי הירש הלוי","bt":"תר","b":"תלמיד קיבוץ לומדי תורה באיישישוק. רב בווילקי-תרלג, גרינקישק-פלך קובנא-תרלו. נסמך מאת ר יעקב אליהו סגל מויליאמפול. חתניו: ר בן ציון יעקבזון מניעזין, ר אברהם נח פאליי משקלוב, ר אברהם יוסף לינדין מדוינסק, ר שלמה אסאייסקי."},{"i":17747,"n":"ולפרט, דוד מנחם מפראן","f":"יצחק","b":"רב בפראן-ליטא-תרפא."},{"i":17748,"n":"ולפרט, חיים מליבוי","f":"צבי אברהם","b":"חתן ר דוד רגנשבורג מוינדאוי ושאד. שו\"ב וש\"ץ בפרוינבורג, מו\"ץ בדבלען(=דבלן)-קורלנד, ליבאוי. פרסם מאמרים ב\"המאור\" - תל אביב תרצה."},{"i":17749,"n":"ולץ, יצחק מפרשבורג","dt":"תשד","b":"מזכיר ישיבת פרשבורג. נספה בשואה."},{"i":17750,"n":"ולץ, ישראל מבודפשט","f":"צבי מלעמעש","k":"דברי ישראל","bt":"תרמז","dt":"תשלד - ז חשון","dp":"ירושלים","b":"תלמיד השב\"ס, ור יוסף ליב סופר מפאקש ור שמואל גוטליב מפאפא. חתן ר חיים אפרים באליטי מטארנאליא, ובזיוו\"ש חתן ר שמואל בנימין וולף שפיגל מוויצען. רב בטיניע-תרעג, בודפשט-תרף, ניצל מהשואה, ואחריה דיין בבית הדין להתרת עגונות. עלה לירושלים-תשי. חתנו ר משה שמעון הופמן רו\"מ בבודפשט. עורך \"תל תלפיות\" - וייצען תרצז על מקום ר דוד צבי קצבורג. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"לקט ששנ\"ה\" - סטמר תרצד, \"המעין\" - פרשבורג תרצד, \"הנשר\" - טירנוי תרצג-תשד, \"המעין\" - בודפשט תשז (לאחר השואה!)."},{"i":17751,"n":"ולץ, משה מבודפשט","f":"ישראל מבודפשט","k":"בעל המביט לארץ","dt":"תשה - א שבט","dp":"פעסט","b":"תלמיד הדעת סופר, ור יוסף צבי דושינסקי בירושלים. חתן ר שלמה זלמן אליהו פולק מזענטא. רב בבודפשט. נספה בשואה. חיבר \"מגלת מתתיהו\" עם פירוש בהונגרית. פרסם מאמרים ב\"מקבציאל\" - גרבה תרצה."},{"i":17752,"n":"ולץ, משלם זלמן כץ מבודפשט","f":"ישראל מבודפשט","k":"בעל תל תלפיות","b":"מדפיס בבודפשט. הו\"ל חוברת \"תל תלפיות\" ובה גם מחדושי אביו."},{"i":17753,"n":"ולץ, צבי מלעמעש","b":"מחכמי לעמעש, ביסטריץ-באניא, בודפשט. בנו ר ישראל רב בטיניע ובודפשט."},{"i":17754,"n":"ולקוביץ, בנימין יחזקאל מקניזיץ","f":"יהודה צבי-יפיח אמונה","bt":"תרכז","b":"רב בקניזין-פלך מוהילוב-תרנח."},{"i":17755,"n":"ולקוביץ, יהודה צבי","k":"בעל יפיח אמונה","b":"רב-שנת תר\"ל. חיבר ספרי אמונה ובהם גם - \"יגיד צדק\", \"מסורת הברית\", \"אש דת\" ובו הוכחות להשגחה פרטית בדורות האחרונים, ועוד."},{"i":17756,"n":"ולקובסקי, אליהו מרדכי","f":"צבי יחיאל הלוי","k":"בעל מערכת התלמוד","bt":"תרלד","dt":"תשכג","dp":"ירושלים","b":"תלמיד ישיבות סלובודקה וראדין. רב במאיסיאד, סאלוק(=סאלאק), פודולסק-ליד מוסקבה והיה חבר הרבנות במוסקבה עם ר אבא דוד גולדפין, הרב זלדין, והרב שלייפר. קראז-ליטא-תרצב, עלה לירושלים והיה חבר הרבנות שם-תרצד. פרסם מאמרים ב\"תבונה\" - ירושלים תשא."},{"i":17757,"n":"ולקין, אהרן מפינסק ושאד","f":"יעקב צבי","k":"בעל בית אהרן","bt":"תרכג-ה","bp":"שומיאץ-רוסיה","dt":"תשב","b":"תלמיד ישיבת וולוזין, ור יצחק אלחנן מקובנה. חתן ר בן ציון סורוצקין מזכירנא. רב בגרוזד-תרמט על מקום ר איצה'לה מפוניבז, שאט(=שאד)-פלך קובנא-תרסה וראש ישיבה שם, אמציסלב-תרעב, פילוישוק, פינסק-תרפ. מגדולי הדרשנים, בשליחות אגו\"י-תרעד יחד עם ר מאיר הילדסהיימר, באנגליה, ובאמריקה, וסירב להצעות רבנות שם, רב בפינסק, נאסר ע\"י הקומוניסטים לחצי שנה. נספה בשואה. חיבר גם \"זקן אהרן\", \"מצח אהרן\", ועוד. מאמר ממנו ב\"הפוסק\" - תל אביב תש-תשיד, \"שערי ציון\" - ירושלים תרפא.","bk":[["זקן אהרן – שו\"ת",""],["חשן אהרן – חו\"מ",""],["מצח אהרן – דרוש",""],["סביב ליראיו - על היראים",""],["בית אהרן – ש\"ס",""],["בית אהרן",""]],"e":"תרכ\"ה-תש\"ב"},{"i":17758,"n":"ולקין, חיים מוולוזין","f":"אהרן מפינסק-בית אהרן","bt":"תרנו","dt":"תשג","b":"חתן ר יעקב שפירא מוולוזין. ר\"מ בוולוזין. נספה בשואה."},{"i":17759,"n":"ולקין, יצחק אלחנן","f":"אהרן וולקין","bt":"תרס","dt":"תשב","b":"רב פעלים,רב באנטיפוליא-תרפ\"ח"},{"i":17760,"n":"ולקין, שמואל מלוקטע-וואלין","b":"מראשי אגודת רבני רומניה - ניו יורק - תשט"},{"i":17761,"n":"ולקנפלד, אלימלך","f":"יהודה ליבוש ולקנפלד","b":"שנת תר\"מ. בנו ר חיים."},{"i":17762,"n":"ולקנפלד, אלימלך מליזנסק","k":"אדמור מליזנסק","b":"נכד ר אלימלך מליזנסק. חתן ר משולם זושא מנדבורנא. נקרא \"רבי אלימלך דובצ'יס\". החזיק במפתחות הציון של ה\"נועם אלימלך\" בליזנסק."},{"i":17763,"n":"ולקנפלד, בן ציון מליזנסק","f":"אלימלך מליזנסק הנכד","dp":"ארה\"ב","b":"חתן ר ישראל ולדמן מבוארשא. ניצל מהשואה, ואחריה היגר לארה\"ב."},{"i":17764,"n":"ולקנפלד, חיים מברזסטוק","f":"אלימלך","bt":"תרם","dt":"תש","b":"רב בברזסטוק לצד זקנו ואחר כך רב המקום."},{"i":17765,"n":"ולקנפלד, חיים מרזאסטיק","f":"אלימלך וולקנפלד","b":"מו\"צ ברזאסטיק-תר\"ע"},{"i":17766,"n":"ולקנפלד, יהודה ליבוש מברזסטוק","f":"שמואל","bt":"תקצו","dt":"תרעה","b":"תלמיד ר יצחק מסוקולוב. נסמך מהאדמור מצאנז, ור ישראל מ טורנא. חתן ר יצחק ליב וגשל. מו\"צ בפריסטיק-תרך, רבה של ברזסטוק-תרלד. חיבור ממנו בהלכה ואגדה עם הסכמות - בכתב יד. בנו - ר אלימלך."},{"i":17767,"n":"ולקנפלד, שמואל","b":"רב-שנת ת\"ר"},{"i":17768,"n":"ולרשטין, אברהם הלוי","k":"חתן המהר\"ל מפרג","b":"מגדולי חכמי דורו-ש\"פ"},{"i":17769,"n":"ולרשטין, אברהם משנייטוך","f":"אשר","k":"בעל מאמר אברהם","b":"רב בשנייטוך-תק. חיבר \"מאמר אברהם\", \"מחזה אברהם\", \"זרע אברהם\" - פיורדא תקטז."},{"i":17770,"n":"ולרשטין, אריה יהודה ליבש","f":"אברהם שבתי","bt":"תקם","dt":"תרי","b":"רבה של סטריזוב-תקצח. חתן ר יחזקאל בלומנפלד מרישא. בנו - ר יצחק חיים מריישא."},{"i":17771,"n":"ולרשטין, יהושע השל מרישא","f":"יצחק חיים מרישא","k":"בעל כרם יהושע","bt":"תרד","dt":"תרסד - כ טבת","b":"תלמיד ה\"דברי חיים\" מצאנז. חתן הגביר ר אברהם מרדכי מסרעט. אב\"ד ברישא-תרן על מקום אביו, וראש עדת חסידי צאנז ברישא. חיבר \"כרם יהושע\" למברג תרנט, ועוד."},{"i":17772,"n":"ולרשטין, יוסף מדוברומיל","f":"יצחק חיים מרוהטין","bt":"תרה","dt":"תרע","b":"רב בדוברומיל. תשובה אליו מאחיו ב\"שדה יהושע\"."},{"i":17773,"n":"ולרשטין, יצחק חיים מרוהטין","f":"אריה יהודה ליבש","bt":"תקף","dt":"תרמב - יא ניסן","b":"נכד(-אבי אמו) ר יחזקאל צבי בלומנפלד מריישא. רבה של רוהטין, רישא-תרטז על מקום אביו וזקנו. חתן ר אברהם גוט מדוברומיל. בנו ר יהושע השל על מקומו אחריו."},{"i":17774,"n":"ולרשטין, מרדכי שמואל מטרנופול","k":"בעל תולדות יוסף","bt":"תקף","dt":"תרן","b":"מחכמי טרנופול. חיבר \"תולדות יוסף\" לזכר רבו \"מנחת חינוך\" - בכתב יד. כתב בכתבי עת \"השחר\" ועוד."},{"i":17775,"n":"ולרשטין, פייש ממאדע","b":"רב בטעט,פילפיץ,ראאב,מאדע-תק\"צ"},{"i":17776,"n":"ולרשטין-הלר, יהודה ליב מדוקלא","f":"זאב וולף","bt":"תץ","dt":"תקס","b":"חתן ר זכריה מנדל פרנקל מירוסלב. רבה של דוקלא, ירוסלב-תקלז ור משה יהושע הורביץ על מקומו ואחריו ר נפתלי הרץ חריף."},{"i":17777,"n":"ון גלדרן, לצרוס מוינה וגרמניה","b":"חתן ר שמעון מיכל - ראש היהודים מפרשבורג. נכדו - היינריך היינה."},{"i":17778,"n":"ון גלדרן, שמעון מפרשבורג","b":"נכד ר שמעון מיכל-ראש קהלת פרשבורג. עלה לארץ-תקמה."},{"i":17779,"n":"ונדזיגולה = ואנדזיוגאלא","k":"קהילה","b":"ליטא - מחוז קובנה. ראשית הישוב במאה ה-17, לפני מלחה\"ע היו כמעט כל התושבים יהודים, לפני השואה כ-500 יהודים, ועוד יהודים רבים בכפרים הסמוכים שעסקו בחקלאות ונקראו \"ישובניקים\". יהודים רבים היגרו לאמריקה או עלו לארץ. רבנים: ר צמח זקש מקידאן, ר בנימין ביינוש, ר יהושע צבי רבינוביץ, ובניו ר מאיר מקרוק, ר יעקב גרשון מסורוילישוק, ר קלמן רבין, ר יעקב מרוזליה, ר אהרן זלצר, ר ניסן עובדיה רוזנסון, ר ישראל רוזנסון, ר חיים בן נחום יהודה קליבנוב - רבה האחרון נספה בשואה."},{"i":17780,"n":"ונדרובסקי, אריה דב מפיעסק","f":"יעקב פרץ מבראזאנקא","k":"בעל פרי עץ הדר","bt":"תרו","bp":"בראזאנקא-פלך וילנא","b":"תלמיד ישיבת סלונים, קובנא - ונקרא בשם \"דער ראזענקער מתמיד\". חתן ר צבי פולוציק מפיעסק. חיבר גם \"קול אריה\" תרנד, ועוד חבורים בכת\"י. אחיו רי\"ז ונדרובסקי מניו יורק."},{"i":17781,"n":"ונדרובסקי, יצחק זאב מארה\"ב","f":"יעקב פרץ","k":"בעל מנהגי בית יעקב","bt":"תרטז","bp":"רוזנקה-פלך וילנא","b":"תלמיד ישיבות ליטא. חתן הגביר ר שמואל בילצינסקי. היגר לארגנטינה, עבר לכהן כרב בקהלת \"חיי אדם אנשי מינסק\" בניו יורק-תרנה. נסמך מאת: ר יצחק אלחנן מקובנא, ר אלכסנדר משה לפידות, ר נח חיים מסטוצין."},{"i":17782,"n":"ונה, יצחק","k":"בעל פעמון זהב","dt":"תל","b":"מגדולי חכמי תימן","bk":[["נימוקי מהרי\"ו - רמב\"ם (כת\"י)",""],["פעמון זהב \\ חידושין - תכלאל (כת\"י)",""],["רכב אלקים - על התורה בדרך קבלה (כת\"י)",""]]},{"i":17783,"n":"ונטורה, משה מאזמיר","bt":"תרנג","bp":"אזמיר","dt":"תשלח - יא אב","b":"מחכמי אזמיר, רב באלכסנדריה-תרצח. עלה לארץ-תשיט, ועסק בחינוך."},{"i":17784,"n":"ונקרט, צבי הירש מזלישטשיק","b":"רב בזלישטשיק-תרצג. תשובה אליו ב\"אמרי דוד\"."},{"i":17785,"n":"ונרסמן, יצחק איזיק","dt":"תשג","b":"רב בפינטשוב"},{"i":17786,"n":"וסטרייך, בן ציון יצחק מקנטש'-א","b":"רב בקנשטינא(=קנטשוגה)-תק\"נ, גיסו של ר אלימלך מליזנסק"},{"i":17787,"n":"וסטרייך, בן ציון יצחק מקנטשוגה","f":"יוסף יוסקא","bt":"תרכה","dt":"תרסח","b":"רב בקנטשוגה(=קנצוגה)-תרמג על מקום אביו. בנו ר יוסף יוסקא על מקומו אחריו."},{"i":17788,"n":"וסטרייך, בן ציון מבילקמין","f":"יוסף יוסקא","bt":"תרסד","dt":"תשב","b":"חתן ר מרדכי יוסף ספיר מצאנז. רב בצאנז ליד חותנו. רבה של בילקמין. נספה בשואה."},{"i":17789,"n":"וסטרייך, יוסף יוסקא מגריבוב","f":"ישראל הלל מגריבוב","bt":"תקע","dt":"תרמג - כ סיון","b":"חתן ר יהושע לנדא מקנטשוגה, גיסו של ר אלימלך מליזנסק. רב בגריבוב על מקום אביו. רב בקנטשוגה-תרט על מקום חותנו. בנו ר בן ציון יצחק על מקומו אחריו. חתנו - ר יעקב יצחק הורביץ מרדומישל."},{"i":17790,"n":"וסטרייך, יוסף יוסקא מקנטשוגה","f":"בן ציון","bt":"תרמה","bp":"קנטשוגה","dt":"תשד","b":"חתן ר אלעזר רוקח מהיבנוב. רבה של קנטשוגה(=קנצוגה)-תרסט על מקום אביו. רב בבוסרמין. וחזר לקנטשוגה. נספה בשואה. בנו - ר בן ציון יצחק מבילקמין - נספה בשואה."},{"i":17791,"n":"וסטרייך, ישראל הלל מגריבוב","f":"יוסף יוסקא מגריבוב","bt":"תקם","dt":"תרו - ב סיון","dp":"רימנוב","b":"תלמיד ר צבי הירש הלר, ר אריה ליב מוישניצא, תלמידו וכותב תורתו של ר קלונימוס בעל \"מאור ושמש\", מקורב לדברי חיים מצאנז, ור נפתלי צבי מרופשיץ. רבה של גריבוב ובריגל. בנו ר יוסף יוסקא על מקומו אחריו בגריבוב. חתנו ר דוד \"גרף\" ברדק-קלגסברון מוישניצא."},{"i":17792,"n":"וסטרייך, ישראל הלל משנדישוב","b":"ר נפתלי צבי מרופשיץ נסע לקבל את פניו. בנו ר יוסף יוסקא מבריגל."},{"i":17793,"n":"וסטרילינגן, יוסף מאנשבך","b":"בקי,דיין באנשבך-ת\"ק"},{"i":17794,"n":"וסל, שמואל","bt":"תרלא","dt":"תרפח - כט ניסן","b":"רב ראשי לאשכנזים ביוגוסלביה"},{"i":17795,"n":"וסלובסקי, יחיאל","b":"פרסם מאמרים ב\"בית מדרש\" - תל אביב תשא."},{"i":17796,"n":"וסלי, בנימין זאב וולף וולפגנג","k":"בעל נתיב אמונה","bt":"1804","bp":"טרביטש","dt":"תרל - כא ניסן","dp":"וינה","b":"תלמיד בישיבה בטרביטש. דוקטור למשפטים, ומרצה באוניבר' בפרג. פרופסור ללשון עברית, שופט. חיבר גם \"איבער דער אייד\", ועוד, פרסם מאמרים בחכמה ומדע."},{"i":17797,"n":"וסלי, ברוך אליהו מבאניהאד","k":"בעל עטרה ליושנה","b":"רב בבייאה, באניהאד. חיבר \"עטרה ליושנה\" כנגד המתקנים. בנו - ר דוד מפרשבורג."},{"i":17798,"n":"וסלר, אברהם מרדכי","bt":"תרנב","bp":"סמולוביץ","dt":"תשא - תמוז","b":"תלמיד ישיבת סלובודקה. חתן ר יוסף ליב בלוך מטלז. מנהגל רוחני בסמינר למורים \"יבנה\". רב באניקשט על מקום ר אליהו-בר שור ור קלמן יצחק קדישביץ בעל \"תולדות יצחק\" על מקומו אחריו, רבה האחרון של פלונגיאן. פעיל באגו\"י. נספה בשואה."},{"i":17799,"n":"וסף גרשון הכהן","bt":"תקצח","b":"רב בקשטוקוביץ-תרמ\"א"},{"i":17800,"n":"וסרטיל, אשר מקשנוב","bt":"תרפו","bp":"קשנוב","b":"תלמיד ביהמ\"ד בברלין. גורש בתרצח לזבונשיין וחזר לגרמניה. למד בדרמשטט אצל הרב מרצבך. עלה לירושלים-תרצט ולמד בישיבת חברון."},{"i":17801,"n":"וסרטרילינג, נפתלי הרש מקירכהן","b":"תלמיד ר יונתן איבשיץ. חתן בעל \"שמחת הנפש\". רב בקירכהאין ומדינת הסן-תקמ."},{"i":17802,"n":"וסרטרילינגן, יוסף מאיטינגן","f":"ענזיל","b":"תלמיד ר יעקב פופרש בעל \"שב יעקב\". דיין במדינת אנשבאך-תץ בערך. תשובות ממנו בספרי חבריו - ר יוסף שטינהרט בעל \"זכרון יוסף\" ור יעקב ברלין בעל \"באר יעקב\". חיבר חדושים על הש\"ס."},{"i":17803,"n":"וסרלויף, זאב","f":"יצחק מלנצהוט","bt":"תשה","dt":"תשמג","b":"עלה לארץ עם הוריו-תשי. חתן ר פנחס שינמן. רב בבני ברק וחבר המפד\"ל."},{"i":17804,"n":"וסרמן, אלחנן בונם צבי מברנוביץ","f":"בנימין בינוש","k":"בעל קובץ שיעורים","r":"ר\"י אהל תורה בראנוביטש","bt":"תרלז","bp":"בירז'","dt":"תשא - יא תמוז","b":"תלמיד ישיבת סלובודקה, ר אליעזר גורדון מטלז, ר חיים סולוביציק מבריסק ור שמעון שקופ מגרודנה ותלמידו המובהק של ה\"חפץ חיים\". חתן ר מאיר אטלס משאוולי. ר\"מ באמציסלאוו-תרסג, ראדין-תרסז, בריסק-תרע, סמולוביץ-תרעד, ראש ישיבת \"אוהל תורה\" בברנוביץ-תרפא. מראשי אגו\"י. בשליחות מטעם הישיבה באמריקה-תרצח, וחיבר שם חוברת \"עקבתא דמשיחא\" על הסכנה לעם ישראל, כשפרצה המלחמה חזר לתלמידיו בישיבה, (וסירב להצעה להעביר את הישיבה לאמריקה), העביר את הישיבה לליטא והשתדל להעבירה לשנחאי אך לא הספיק. נספה בשואה. פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ, \"פרי עץ חיים\" - טלז תרצט - קובץ תלמידי ישיבת טלז, \"שערי ציון\" - ירושלים תרפא, \"תלפיות\" - טרנוב תרצח.","bk":[["קובץ שיעורים",""],["קובץ הערות",""],["עקבתא דמשיחא",""],["קובץ הערות - יבמות",""],["קובץ מאמרים",""],["קובץ מאמרים ואגרות",""],["שיעורי רבי אלחנן וסרמן",""],["שיעורי וחידושי רבי אלחנן",""],["קובץ הערות","מפרשי ש\"ס - אחרונים"]],"e":"תרל\"ה-תש\"א"},{"i":17805,"n":"וסרמן, אליעזר שמחה מארה\"ב","b":"פרסם מאמרים ב\"המתיבתא\" - נ\"י תשג."},{"i":17806,"n":"וסרמן, זלמן מבאד-מרגנטהים","b":"רב בבאד-מרגנטהים (מחוז וירטנברג). נזכר בהקדמת \"תקנות עגונות\". בנו - ר יצחק משה."},{"i":17807,"n":"וסרמן, ישעיה","b":"פרסם מאמרים ב\"תורת ארץ ישראל\" - ירושלים תרץ."},{"i":17808,"n":"וסרמן, משה מליסינקא","f":"נתן","bt":"תרמו","b":"נסמך מאת: האדמור מרחמיסטריבקא, ר פנחס מאומן, ר מרדכי וולפאהגר. רב בליסינקה-פלך קיוב-תרסז."},{"i":17809,"n":"וסרמן, משה שמשון מברוד","f":"יהושע השל","k":"בעל שאילת משה","bt":"תרנא","bp":"ברודי","dt":"תשכב","b":"רב בברודי, רב בצבא האוסטרי במלחמת העולם הראשונה ומפקד על הטיפול בפליטים. רב בליבק לצד ר שלמה קרליבך. רב בקיעל-תרפג, דרמשטט-תרפד, ברסלוי-תרצא. חתן ר חיים זויערברג. עלה לארץ-תש והיה רב בתל אביב. ההדיר ספר \"בית יוסף צבי\" לר שלמה קרליבך. חיבר \"שאילת משה\" תל אביב תשיז."},{"i":17810,"n":"וסרמן, נחמן שמואל","dt":"תשג","b":"רב בסטוויסק"},{"i":17811,"n":"וסרמן, נפתלי","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":17812,"n":"וסרפיש, יעקב דוד","bt":"תרכג","dt":"תרצ - כו טבת","b":"רב בשמולזינה"},{"i":17813,"n":"וסרצוג, דוד הכהן מלונדון","f":"חיים לאמזער מוילנא","k":"בעל תולדות בר כוכבא","bt":"תרכז","b":"רב בקרדיף-תרנא, יוהנסבורג, רב ביהכנ\"ס בלונדון. חיבר \"תולדות בר כוכבא\", \"תולדות הלוח\", ועוד."},{"i":17814,"n":"וסרצוג, חיים הכהן מוילנא ולונד","k":"חיים לאמזער","b":"ש\"ץ בוילנא, לונדון. חיבר \"שירי המקדש\". בנו - ר דוד מלונדון."},{"i":17815,"n":"וסרצוג, חיים פיליפובר","f":"שמשון מוישטינץ","k":"בעל נשמת חיים","dt":"תרכה - ח אד\"א","dp":"וישטיניץ","b":"תלמיד ר שלמה זלמן פוזנר מקוהארי. רב בצ'נסטחוב, רייגרוד, פיליפובה, סארהיי, וישטיניץ על מקום ר משה בן אהרן. נהג בדרך משלו בפסקיו ונטה להתיר גם נגד דעת פוסקים אחרונים, התנגד לחסידות והיה מחלוקת כנגדו וכמה רבנים אף רצו להחרימו אבל יראו לפגוע בכבודו (בין מתנגדיו - ר יצחק איזיק חבר בעל בנין עולם, ואולי גם ר משה יצחק אביגדור מקובנא וסייני). עבר ממקום למקום בגלל אהבת האמת ולא נשא פני איש ונרדף בעיקר ע\"י החסידים. הניח חבורים בכת\"י. הסופר ט\"ף שפירא חיבר הקדמה לספרו. (אצל ליפמן - קובנא - תאריך פטירתו תרכה)."},{"i":17816,"n":"ועטש, יעקב מסערדאוהל","b":"רב בסערדאוהל, עזב בגלל מחלוקת (לפני תרטו), כנראה שעלה לארץ (כך בכת\"י של ר אהרן יהודה אקשטין מוויצען)."},{"i":17817,"n":"ועלי, אהרן מלבוב","f":"שמואל","dt":"תב - ל-ג כסלו","dp":"לבוב","b":"ר\"מ ודיין בלבוב."},{"i":17818,"n":"ועלי, זיגמונד מפרשבורג","b":"מיסד בי\"ס פרטי בגרמנית בפרשבורג-תקפה."},{"i":17819,"n":"ועלי, משה מאמשטרדם","b":"הרב הראשון לאשכנזים באמסטרדם"},{"i":17820,"n":"ועליש, שמואל מירושלים","dp":"ירושלים","b":"נכד המהר\"ל, מחכמי ירושלים-תקל, נשיא בירושלים. בנו - יהודה ליוואי ונכדו ר אהרן בעל \"בית אהרן\" מזכירו בספרו."},{"i":17821,"n":"ועלס, אברהם מארה\"ב","b":"מצאצאי ר רפאל מהמבורג. חתן ר מנשה יוסף גינצבורג מסמרגון וגיסו של ר איסר גינצבורג. תלמיד ישיבת וולוזין, וילנא קובנא, היגר לארה\"ב. סופר יהודי בניו יורק, עורך הירחון \"די צוקונפט\"."},{"i":17822,"n":"ועלשוס, אלעזר","f":"שלום הכהן","b":"רב,רופא,נסע לפולין,היה בקרמניץ"},{"i":17823,"n":"ועלשיר, אלעזר כץ מקרמניץ","b":"בנו הביא מתורתו ב\"ברכת טוב על התורה\". חיבר פירוש על התנ\"ך - בכת\"י."},{"i":17824,"n":"וענונו, בנימין","f":"שלמה","b":"מחכמי מרוקו-תרי\"א"},{"i":17825,"n":"וענונו, דוד ממראקש","dt":"תש","b":"מרבני מראקש, כתב ספרי תורה במראקש וקזבלנקה"},{"i":17826,"n":"וענונו, יצחק ממרוקו","f":"יעקב","b":"מחכמי מרוקו-תקפא."},{"i":17827,"n":"וענונו, שלמה ממרוקו","k":"בעל הלולא רבא","b":"רב במרוקו, ונסע לליוורנו להדפסת סדר הלימוד לליל לג בעומר בשם \"הלולא רבא\", ו\"תוספות רבנו פרץ\"."},{"i":17828,"n":"וענונו, שמעון ממרוקו","bt":"תרסה","bp":"מוגדור","dt":"תשן - יט כסלו","dp":"ירושלים","b":"מחכמי מרוקו, תלמיד ר דוד עטר במוגדור, עבר למכנאס, חתן ר מרדכי הלחמי. ר\"מ בספרו-מרוקו, ומתלמידיו ר דוד עובדיא, ר יהושע ממן , ר שמואל הרוש, ור יוס ממאן, ועוד. ר\"מ בישיבת ר ברוך טולדנו במכנאס ומתלמידיו במכנאס ר נסים טולדנו ראש ישיבה \"באר יעקב\", ר יעקב טולדנו ראש ישיבת \"חזון ברוך\" בצרפת, ועוד. דיין בסתאת-מרוקו, מראקש. היה מגדולי התורמים לישיבת \"איקס לה באן\" בצרפת, עלה לארץ. נפטר ללא ילדים."},{"i":17829,"n":"ועקנין, בכור יהודה מטבריה","b":"רב בטבריה-תרע בערך."},{"i":17830,"n":"ועקנין, דוד מטבריה ומרוקו","f":"יעקב","k":"בעל וידבר דוד","bt":"1840","bp":"דנמאת-מרוקו","dt":"תרנז - יז שבט","dp":"טבריה","b":"מחכמי דמנאת-מרוקו, עלה לארץ-תרלא והתישב בטבריה, דיין בטבריה-תרלה, אב\"ד, בשליחות בטריפולי ותוניס-תרמח, חיבר גם \"ילקוט דוד\" על המשניות. בניו: ר יעקב, ר שמעון, ר מאיר.","bk":[["וידבר דוד","שו\"ת - אחרונים"],["וידבר דוד – שו\"ת",""]]},{"i":17831,"n":"ועקנין, יעקב מדמנאת-מרוקו","b":"מחכמי דמנאת-מרוקו. בנו - ר דוד."},{"i":17832,"n":"ועקנין, יעקב מטבריה","f":"דוד","bt":"תרלד","b":"רב ודיין בטבריה-תרצו."},{"i":17833,"n":"ועקנין, יעקב מירושלים","dt":"תרנג - ו ניסן","b":"רב בירושלים, נזכר ב\"חלקת מחוקק\"."},{"i":17834,"n":"ועקנין, יצחק מדמנאת-מרוקו","b":"מחכמי דמנאת-מרוקו-תקצד."},{"i":17835,"n":"ועקנין, יצחק מפאס","f":"מסעוד","b":"מחכמי פאס - שנות ה-תק'."},{"i":17836,"n":"ועקנין, מאיר מטבריה","f":"דוד","k":"בעל ויאמר מאיר","bt":"תרמה","bp":"טבריה","dt":"תשלה - כט אדר","dp":"טבריה","b":"תלמיד ר אליהו חיים אבולעפיה מטבריה, ור דוד עבו מטבריה. רב ודיין בטבריה. בשליחות באירופה-תרע. רב ראשי באר\"ץ וסוריה-תרעד, חזר לטבריה-תרף וכיהן כרב הראשי. פרסם מאמרים ב\"כתר תורה\" - גרבה תרצח.","bk":[["ויאמר מאיר – שו\"ת",""],["ויאמר מאיר",""]]},{"i":17837,"n":"ועקנין, מסעוד מפאס","b":"רב בפאס- בשנות הת-תק. בנו ר יצחק מחכמי פאס."},{"i":17838,"n":"ועקנין, שמעון ממרוקו","f":"דוד","k":"בעל דורש סמוכים","b":"מחכמי מרוקו, עלה לארץ והתישב בטבריה. חיבר גם \"דבר השו\"ה\", ועוד."},{"i":17839,"n":"וערבלוב, אהרן","dt":"תשא","b":"רב ביאנישק"},{"i":17840,"n":"וערבש-אוירבך, אליעזר","f":"יעקב","b":"חתם-תטז על קיום חתימת בית דינו של בעל הש\"ך יחד עם ר יחיאל מיכל בן יצחק, חתם-תל על פסק דין."},{"i":17841,"n":"ופרינסקי, יחזקאל מטשעהרין","f":"בנימין אברהם יוסף אל","bt":"תרטז","bp":"טשרקס","b":"תלמיד ר משה נחום ירושלימסקי מקיעלץ המזכירו בספריו. רב בטשערין(=טשעהרין)-פלך קיוב-תרמו. נסמך מאת: ר מרדכי דב מהורנסטיפל, ר ישראל איזנשטין בעל \"עמודי אש\"."},{"i":17842,"n":"וצלר, יהודה","b":"רב בדורידבורג-שע\"ו"},{"i":17843,"n":"וצלר, ליב מפפד\"מ","k":"בעל מעשה תעתועים","b":"מחכמי פפד\"מ. חיבר בעילום שם ספר כנגד ר נתן אדלר ותלמידיו-תקן - לאחר שהוכרז חרם כנגדם."},{"i":17844,"n":"וצלר, מרדכי מגודנסבורג","bt":"תקסא","dt":"תרלט - כג טבת","b":"תלמיד ר משה טוביה זונטהיים מהאנאו ושימשו כ-10 שנים. אב\"ד אוגסבורג עד פטירתו. כתב הסמיכה מרבו נדפס ב\"אור פני משה\". פעל כנגד הריפורמים, מכתב ממנו כנגד מבטלי המילה בספרו של ר זלמן טריר."},{"i":17845,"n":"וקאר ן, יוסף מספרד","f":"אברהם","b":"פילוסוף מחכמי ספרד-שנות ה-ק', נזכר בספרי חכמי דורו. חיבר ספר בפילוסופיה וקבלה. חיבר שיר היחוד \"אספרה כל נפלאותיך..\"."},{"i":17846,"n":"וקאר ן, שמואל מספרד","dt":"ק (1340)","dp":"ספרד","b":"רופא מחכמי ספרד, ממונה על המטבעות אצל מלך קסטיליה אלפונסו ה-10, ורופא המלך - הציל את חיי המלכה ובנה דון פדרו. חיבר \"הרפואה הקסטילית המלכותית\", העלילו עליו שמעל בתפקידו, ושנתן עצות שגרמו למלחמה עם גרנדה ולפלישת מלך מרוקו לספרד (1332). הודח ממשרתו ונמסר לגונזלס מרטינס די אוביידו, שירש את משרתו. נהרג עק\"ה."},{"i":17847,"n":"וקס, אבא מקראקא","f":"שאול","k":"בעל בית אבא","bt":"תרנג","bp":"גלוגוב","dt":"תשג","b":"רב בירוסלב. חתן ר שמואל אהרן מילר מלאבובה ורב לצד חותנו. רב בפרושוביץ-תרפג, קראקא-תרפד שם עמד בראש ישיבה. רב בפרושוביץ-תרצה. נספה בשואה. חיבר \"בית אבא\" קראקא תרפב. \"ברכת שלמה\" קראקא תרפח, \"דגל הרבנים\" - וארשא תרפו, \"יגדיל תורה\" - פראגא-וארשא תרפז."},{"i":17848,"n":"וקס, אלעזר מקאליש","b":"רב בקאליש. תשובה ממנו לאדמור מסוכטשוב-תרכח - ב\"הפרדס\" פיעטרקוב-שיקגו תרעג-תרפז."},{"i":17849,"n":"וקס, אשר אלתר ממיקולייב","f":"בנימין ממיקולייב","bt":"תרכא","b":"נכד-אבי אמו ר יחיאל מיכל מזלוטשוב. רב במיקולייב(=ניקולייב)-פודוליה-תרסו על מקום אביו וזקנו. נסמך מאת: ר שואל מחאטין, ר משה מחמלניק, ר יצחק רחמן משאהן(=טופאפאליע)."},{"i":17850,"n":"וקס, בנימין ממיקולייב","f":"שמחה מנטשל ממיקולייב","b":"חתן ר יחיאל מיכל מזלוטשוב. רב במיקולייב(=ניקולייב)-תרך על מקום אביו, ובנו ר אשר אלתר על מקומו אחריו."},{"i":17851,"n":"וקס, זאב וולף","dt":"תרפח","b":"חסיד בלז בעל אחוזות. חתן ר יוסף יוסקא לאם."},{"i":17852,"n":"וקס, חיים אלעזר מקאליש","k":"בעל נפש חיה","r":"אב\"ד קאליש, טארינגראד, ופיעטרקוב","bt":"תקפב","dt":"תרמט - ל סיון","b":"חתן ר ישראל יהושע מקוטנא בעל \"ישועות ישראל\". מגדולי חכמי דורו, רב בטרניגרד-תרא, קאליש-תרכ, פיעטרקוב-תרמד. חיבר מאמרים ב\"הבאר\" - זאמושץ-וארשא תרפד, \"בית מאיר\" - אוסטרובצה - פיעטרקוב - תרצא, \"כרם בית שמואל\" - פיעטרקוב תרצג, \"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, מתורתו ב\"כרם בית שמואל\" - פיעטרקוב תרצא, \"כרמנו\" - אלכסנדר-לודז תרצג, \"כתר תורה\" - אושפיצין תרצט, \"קובץ דרושים\" - פיעטרקוב תרפג.","bk":[["נפש חיה - שו\"ת וחידושים על הש\"ס ועל התורה",""],["שם ושארית לנפש חיה - שו\"ת וחידושים",""]]},{"i":17853,"n":"וקס, יהושע הניך מדזיקוב","b":"מחכמי דזיקוב, תשובה אליו \"מאה שערים\"."},{"i":17854,"n":"וקס, משה","dt":"תרנז - לפני","b":"תשובה אליו מרבו רא\"מ שטיינברג, ב\"מחזה אברהם\"."},{"i":17855,"n":"וקס, שמחה מנטשיל ממיקולייב","b":"רב במיקולייב-תקץ, ובנו ר בנימין על מקומו אחריו."},{"i":17856,"n":"וקסברג, מנחם נחום מידליטש","dt":"תש..","b":"רב בידליטש, קראקא. חתן ר משואל פיהרר מקראס. נספה בשואה."},{"i":17857,"n":"וקסברגר, דוד מפאמא","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":17858,"n":"וקסיר, אריה ליבש הכהן מדאשיב","f":"מנשה","k":"בעל מלבושי כהונה","bt":"תרכ","bp":"קאמינקא-פודוליה","b":"רב בחרישקיפקה-ליד טולטשין, דאשיב-פלך קיוב-תרמה. נסמך מאת: ר משה נחום ירושלימסקי, ר דוד מבאלטא. חיבר \"מלבושי כהונה\", \"קשת גבורים\"."},{"i":17859,"n":"וקסלר, אברהם משוואבך","dt":"תריב","b":"אב\"ד שוואבאך(=שוואבך). פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז. נספד ב\"לקוטי חבר בן חיים\"."},{"i":17860,"n":"וקסלר, אלימלך","b":"פרסם מאמרים ב\"בית המדרש\" - קראקא תרמח."},{"i":17861,"n":"וקסלר, אפרים שלמה מוארנוב","dt":"תרעא","b":"רב במ' קיוועשד, וארנוב"},{"i":17862,"n":"וקסלר, ישראל מנחם מנדל מטרנוב","b":"נגיד בטרנוב. חתן ר יהושע השל פרנקל-תאומים. וחתן ר זכריה מנדל הלוי אברדם מטרנוב."},{"i":17863,"n":"וקסלר, ישראל מנחם מנדל מטרנוב","f":"משה","bt":"תרכד","dt":"תרפו","b":"מחכמי טרנוב. חתן ר יחיאל מאיר טננבאום מברנוב."},{"i":17864,"n":"וקסלר, מאיר מטרנוב","f":"בנימין זאב וולף","b":"מחכמי טרנוב. נספה בשואה. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח."},{"i":17865,"n":"וקסלר, מנחם מנדל מקראקא","f":"יצחק","bt":"תרמא","bp":"זווירציה","b":"תלמיד האבני נזר. חתן ר פישל בונם מזגירז ועבר לשם. מלמד בישיבות, ר\"מ בישיבת \"בית מאיר\" בקראקא. מתלמידיו ה\"שם משמואל\". נספה בשואה."},{"i":17866,"n":"וקסלר, משה מארה\"ב","k":"בעל משה ידבר","b":"רב בניו יורק-תרסב. פרסם מאמרים ב\"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג."},{"i":17867,"n":"וקסלר, משה מטרנוב","f":"ישראל מנחם מנדל","k":"בעל ברכת משה","bt":"תרו","dt":"תרסב","b":"נגיד מחכמי טרנוב ובעל חסד. חתן הנגיד ר בנימין זאב לעזער. עבר לארה\"ב. חיבר \"ברכת משה\" נ\"י תרסב."},{"i":17868,"n":"וקסלר, פנחס משה אלחנן חיים מנ'","f":"שלמה משוואבאך","k":"בעל דבר אזהרה לישראל","bt":"תרג","bp":"שוואבך","dt":"תרנד - כז סיון","dp":"העכברג","b":"תלמיד הכת\"ס, וזקנו ר מנדל רוזנבוים מצעל, ודודו ר אברהם וקסלר משוואבך. חתן דודו ר רפאל רוזנבוים מצעל. רב בשוואבך-תרכו, העכברג-תרמז. ?? לא באוצר ??"},{"i":17869,"n":"וקסלר, שלמה מירושלים","f":"פנחס משה אלחנן חיים","bt":"תרכו - אחרי","b":"בנו של הרב מהעכברג(=היכבערג) בעל \"דבר אזהרה לישראל\". עלה לירושלים, וכיהן כראש ישיבת ברסלב. מקורב למהרי\"ל דיסקין."},{"i":17870,"n":"וקסלר, שמואל מטרנוב","f":"ברוך משה","bt":"תרצא","bp":"טרנוב","b":"ניצל מהשואה. הגיע לאנטורפן ועבר לארה\"ב. חתן ר משה הכהן אנגלנדר. ההדיר ספר דודו \"אמרי כהן\" לר יחיאל מיכל הכהן הולנדר מטרנוב."},{"i":17871,"n":"וקסמן, אשר אנשיל מגליציה","dt":"תשה","b":"עלה מגליציה לצפת ולימד בישיבת אמשטרדם. בנו ר שמואל - מהדיר ספרי קדמונים."},{"i":17872,"n":"וקסמן, זאב וולף מנחם מאושפצין","f":"אברהם","k":"בעל אמרי זאב","bt":"תרן","dt":"תשב","b":"מחכמי אושפיצין. חתן ר משה אליעזר פוזנר. נספה בשואה. חיבר \"אמרי זאב\" פיעטרקוב תרצז. ?? לא באוצר ??"},{"i":17873,"n":"וקסמן, חיים פנחס מבריגל","b":"מחכמי בריגל. תשובה אליו \"דובב מישרים\"-תרצא."},{"i":17874,"n":"וקסמן, יצחק מאיר מקראקא","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":17875,"n":"וקסמן, מאיר מארה\"ב","f":"מרדכי","k":"בעל דוד דוד ומחנכיו","b":"מורה לתלמוד בביהמ\"ד לתורה בשיקגו-תרפז."},{"i":17876,"n":"וקסמן, משה צבי","f":"חיים","b":"מחסידי בובוב בניו יורק, תלמיד טשבין. תשובה אליו ב\"דובב מישרים\"-תשכב. חתן ר משה סנדר לעזער מיורדנוב."},{"i":17877,"n":"וקסמן, ניסן מארה\"ב","f":"ראובן","bt":"תרסז","bp":"סטרבין-פלך סלוצק","b":"תלמיד ישיבת סלוצק, סמילוביץ, סלובודקה, מיר וישיבת רבי יצחק אלחנן בניו יורק. נסמך מאת: רא\"י פינקל ממיר, ר אברהם צבי הירש קאמאי, ר שמעון שקופ. חתן ר אברהם נחמן שורץ מבולטימור. רב בלייקווד-תרצב. פרסם מאמרים בעברית, אידיש ואנגלית. חבר אגודת הרבנים באמריקה."},{"i":17878,"n":"וקסמן, צדיק צבי","dt":"תרעד - בערך","b":"רב בגליציה, ממקורבי האדמור מדזיקוב. רב בהולשיץ-תרמה, רעדים, ריגליץ, אולינוב."},{"i":17879,"n":"וקסמן, ראובן","b":"חתן ר אלחנן פרייל, וגיסם של ר יהושע יוסף בעל \"אגלי טל\", ור אלעזר בעל \"המאור\". בנו - ר ניסן מלייקווד."},{"i":17880,"n":"וקסמן, שמואל מצפת","f":"אשר אנשל","dt":"תשלב","b":"תלמיד ישיבות טבריה וירושלים וביניהם ישיבת תורת חיים. סחר בספרים עתיקים. יסד מכון חכמת ישראל והדפיס ספרים קדמונים. נסע לארה\"ב-תרצט."},{"i":17881,"n":"וראנק (פרנק), זכריה מנדל מקושט","f":"אהרן","dt":"שח - לפני","b":"ראש העדה האשכנזית בקושטא, היה בין המגורשים ממדינת באוואריה בשנת רל, בניו ר דוד ור משה. מוזכר בשות ר אליהו מזרחי על אודות נישואי קראית לכהן, וחתם זכריה בן אהרן איש ירושלים. יתכן שהוא מוזכר בשות מהרי בירב סימן מד. עלה לירושלים וחי תקופה מסוימת גם בצפת."},{"i":17882,"n":"ורבווסקי, נחום מרדכי","f":"יהודה ליב","bt":"תרלח","dt":"תשג","b":"רבה האחרון של אוקמיאן-פלך קובנא-תרסז."},{"i":17883,"n":"ורבורג, וולף מאלטונא","b":"פו\"מ באלטונא-תר."},{"i":17884,"n":"ורבורג, זיגמונד שמעון מהמבורג","b":"חתן הגביר יהושע השל רוזנברג, גיסו של הברון נפתלי הירץ גינצבורג."},{"i":17885,"n":"ורבורג, זלמן מברלין","b":"מראשי הקהילה בברלין-תקד, חתם על כתב ההסכם עם ר דוד פרנקל הראב\"ד בברלין."},{"i":17886,"n":"ורבורג, יעקב שמואל מאלטונא","f":"לוי יוסף","dt":"תכח","dp":"אלטונא","b":"ראש משפחת ורבורג באלטונא."},{"i":17887,"n":"ורבורג, שמואל","b":"רב בגעלנהויזן ומדינת מערהולץ-תקנ\"ד"},{"i":17888,"n":"ורבלוב, אלעזר מפנזה","bt":"תרף - בערך","bp":"וילנא","dt":"תשמז - יב תמוז","b":"עבר עם משפחתו לטלז. תלמיד ישיבת טלז, קעלם אצל ר דניאל מובשוביץ. ניצל כמעט יחידי בזמן השואה והגיע לעיר פנזה ברוסיה, וכל ימיו עסק בתורה (תחת השלטון הקומוניסטי - בעיר כמעט ללא יהודים), לימד תורה בסתר במוסקבה. הניח חדושים בכת\"י. אביו שהיה בעל בית פשוט עזר ל\"חפץ חיים\" לאסוף כסף לישיבה בזמן מלחה\"ע ה-I, ועל כך ברכו החפץ חיים שיהיו בניו תלמידי חכמים - ואכן כל חמשת בניו היו בני תורה מופלגים."},{"i":17889,"n":"ורדאי, יוסף מאנקונא","dt":"שיו - ז תמז","dp":"אנקונא","b":"אחד מ-24 הרוגי אנקונא על פי עדות ר שלמה חזן מאנקונא. קינה לזכרם מאת ר אברהם דוד חי."},{"i":17890,"n":"ורדנבורג, יוסף מאמשטרדם","b":"דומ\"צ באמשטרדם-תרע."},{"i":17891,"n":"ורדניים, מנחם","dt":"נח","b":"מגדולי חכמי צרפת"},{"i":17892,"n":"ורהפטיג, אליהו מסעלץ","f":"בצלאל","b":"גביר מחכמי סעלץ בזמן כהונתו של הגדול ממינסק. חתנו - ר מאיר הלפרין בעל \"הגדול ממינסק\"."},{"i":17893,"n":"ורהפטיג, דוד מחורסטקוב","b":"ממשתתפי \"אהל מועד\"-תרנט."},{"i":17894,"n":"ורהפטיג, זרח","b":"מראשי המפד\"ל, שר בממשלה."},{"i":17895,"n":"ורהפטיג, חנוך מחורוסטקוב","b":"ממשתתפי \"אהל מועד\"-תרנט."},{"i":17896,"n":"ורהפטיג, ירוחם אשר","k":"בעל דברי ירוחם","bt":"תרלג","dt":"תשכו - ה תשרי","b":"חתן ר יעקב זרח פינשטיין מניעזין. ר\"מ בנוברדוק בוארשא, עלה לירושלים-תרצג. פרסם מאמרים ב\"בית שמואל\" - וארשא תרצו, \"שמוש חכמים\" - בני ברק תשז, \"תפארת ציון\" - בני ברק תשב. חדושים וסוגיות. ר' ירוחם אשר וארהפטיג, מחו\"ר ירושלים. נדפס תרצ\"א. נפטר תשכ\"ו. חיבר גם: עולת ירוחם, שלמי ירוחם, אמרי ירוחם ועוד.","bk":[["שלמי ירוחם","מפרשי רמב\"ם"],["דברי ירוחם [על שו\"ע]",""],["דברי ירוחם","שו\"ע-סוגיות הש\"ס"]]},{"i":17897,"n":"ורובל, בן ציון מבלז","f":"דוד אלימלך","bt":"תרלב","bp":"ישיניצה","dt":"תרפט","b":"חתן הנגיד ר יוסף טויבה. רב בבלז ומקורב לאדמורי בלז. ר\"מ בקראקא בישיבת \"בית מאיר\". רבי אהרן מבלז הספידו ואמר \"נפטר הרבי שלי\"."},{"i":17898,"n":"ורובל, דוד אלימלך מישיניצה","f":"פנחס","bt":"תר","dt":"תרלט","b":"ראב\"ד ושיניצה. חתן ר אברהם גלר אב\"ד קריפטש."},{"i":17899,"n":"ורזבלוסבסקי, מאיר מליטא","f":"בנימין דב","bt":"תרמא","bp":"שאקי","dt":"תשא-ג","dp":"קרוק","b":"תלמידי ישיבת וולוזין. רב בשימאנצי-ליד קופישוק-תרפה, דווידובקה-ליד רזיצ'ה, ספיזישוק, קרוק-מחוז שאוולי. הו\"ל \"בית יצחק\" לר יצחק איזיק חבר, עם הערות משלו. נספה בשואה."},{"i":17900,"n":"ורטהיים","f":"נפתלי צבי וורטהיים","b":"רב בוורטהיים-תפ\"ז"},{"i":17901,"n":"ורטהיים, אהרן מבענדר ארה\"ב","f":"יוסף מבענדר","k":"בעל הלכות והליכות בח","dt":"תשמט","b":"בן האדמור מבענדר. רב בארה\"ב."},{"i":17902,"n":"ורטהיים, אריה ליב","k":"אדמור מבענדר","b":"מייסד שושלת בנדרי,רב בשנת-תק\"ע"},{"i":17903,"n":"ורטהיים, אריה ליב מבענדר=בינדע","f":"שמעון שלמה מסאווראן","bt":"תקלב","dt":"תריד - ג תמוז","b":"מצאצאי השר ר שמשון ורטהימר מוינה - ומכאן מקור שמו \"ורטהיים\". תלמיד גיסו ר שלום מפרוהוביטש, ור ברוך ממזבוז, ותלמיד אחיו ר משה צבי מסאווראן. חתן ר אברהם מקוריסטשוב, ובזיוו\"ש חתן ר יהודה מאיר משפיטובקא (קוריץ). ממפיצי החסידות בבסרביה-רומניה. מתורתו בספר אחיו \"לקוטי שושנים השלם\". מתולדותיו ב\"צבי לצדיק\"."},{"i":17904,"n":"ורטהיים, דוד מוינה","f":"יוסף יוזל","bt":"תק","bp":"וינה","b":"גביר בוינה, שתדלן ועסק בפדיון שבויים."},{"i":17905,"n":"ורטהיים, וילהלם","bt":"1813","dt":"1861","b":"רופא ומדען וחוקר טבע, עבר לפאריס. חיבר מאמרים במדע."},{"i":17906,"n":"ורטהיים, זכריה מפפד\"מ","f":"יצחק איצק","dt":"תקסט - כד אלול","dp":"פפד\"מ","b":"מראשי קהילת פפד\"מ. חתם על ביטול החרם כנגד ר נתן אדלר-תקס."},{"i":17907,"n":"ורטהיים, יוסף מבענדר(=בנדרי)","f":"שמעון שלמה","k":"אדמור מבענדר","bt":"תרמב","bp":"בנדרי","dt":"תשו - כג אד\"ב","b":"חתן דודו ר אליעזר מראדויל-אוסטילא (זלוטושוב). מו\"ץ בבענדר, רב באוסטילא(=אסטילוה)-ווהלין, אוסטראה, הרובישוב. ניצל מהשואה, ואחריה עלה לארץ-תשו והקים בית מדרש. היה האחרון בשושלת בנדר, בניו - ר אהרן רב בארה\"ב בעל \"הלכות והליכות בחסידות\". חתנו ר שמעון אפרתי בן האדמור ר יקותיאל מחוליוב."},{"i":17908,"n":"ורטהיים, יוסף משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":17909,"n":"ורטהיים, יצחק","f":"אריה ליב וורטהיים","b":"רב בבנדרי-תר\"ל"},{"i":17910,"n":"ורטהיים, יצחק מבענדר","f":"שמעון שלמה ב","k":"אדמור מבענדר","dt":"תרעא - ו סיון","b":"חתן ר יוסף מראדויל (זלוטשוב). חיבר \"באר הגולה\", \"באר רחובות - שומר מצוה\", ועוד."},{"i":17911,"n":"ורטהיים, מנחם מנדל משטמפן","dt":"תקצג - כו שבט","dp":"שטמפן","b":"חתן ר פיבל ברסלוי משטמפן. מחכמי שטמפן, חתם-תקסט עם ראשי הקהלה, חתם-תקעו על כתב רבנות ר מרדכי בנט."},{"i":17912,"n":"ורטהיים, שמעון שלמה מבענדר ב","f":"אריה ליב מבענדר","k":"אדמור מבענדר","bt":"תקסה","dt":"תרכד - כ אד\"ב","b":"חתן ר חיים משה מסטפין. תלמיד דודו ר משה צבי מסאווראן. מתורתו ב\"אור השמש\" - בכת\"י."},{"i":17913,"n":"ורטהיים, שמעון שלמה מבענדר ג","f":"יצחק מבענדר","k":"אדמור מבענדר","bt":"תרכה","dt":"תרפה - יח שבט","b":"רב בואדמו\"ר בבענדר(=בנדרי). חתן ר חיים מברזנא (סטפין). ביקר בארץ. רבם של החסידים בבסרביה. השיב תשובות רבות. - בכת\"י. פרסם מאמרים ב\"היונה\" - אודסה תרסז, \"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס. בנו - ר יוסף מאסטוילה."},{"i":17914,"n":"ורטהיימר, אביגדור מברסלוי ואלט","dp":"אלטונא","b":"מחכמי ברסלוי, אלטונא. בנו - ר עקיבא מאלטונא."},{"i":17915,"n":"ורטהיימר, יוסף","f":"שלמה","bt":"תקס","dt":"תרמז - כח אדר","dp":"וינה","b":"חתן הגביר אולמן מוינה, מראשי הקהלה בוינה. מלומד ומומחה בחינוך, חיבר ספרים ומאמרים בנושאי חינוך, תרגם ספר חינוך מאנגלית לגרמנית \"איבער פריהציטינגע ערציהונג..\" וינה 1828, וספרו נתקבל במערכת החינוך בפרוסיה ומדינות נוספות."},{"i":17916,"n":"ורטהיימר, יוסף יוזל מוינה","f":"שמשון מוינה","dt":"תקכב - טז כסלו","dp":"וינה","b":"גביר מחכמי וינה, המשיך בדרכי אביו ועסק הרבה בצדקה וחסד."},{"i":17917,"n":"ורטהיימר, יוסף מורמייזא","f":"יצחק מוורמייזא","dt":"תעג - ד אייר","b":"שר,עשיר,עסקן לכלל ישראל בוורמייזא"},{"i":17918,"n":"ורטהיימר, יעקב מפרשבורג","f":"אריה יהודה ליב","bt":"תקצו","bp":"פעזינג","dt":"תרלה - ח תמוז","dp":"ירושלים","b":"תלמיד הכת\"ס, ור ישראל דוד יפה-מרגליות מפעזינד, ור אברהם שאג מקוברסדורף. חתן ר זאב קלמן משאפא ועבר לשם. מחכמי פרשבורג. עלה לירושלים-תרלב. בנו ר שלמה אהרן בעל \"שאלת שלמה\" - מגלה הגניזה בקהיר."},{"i":17919,"n":"ורטהיימר, יצחק","b":"רב בוורטהיים-תק\"ע"},{"i":17920,"n":"ורטהיימר, ישראל יעקב וישניצא","b":"רב בוישניצא."},{"i":17921,"n":"ורטהיימר, מנשה מגורליץ","b":"רב בגורליץ לפני מלחמת העולם הראשונה."},{"i":17922,"n":"ורטהיימר, עקיבא מברסלוי ואלטונ","f":"אביגדור","bp":"ברסלוי","dt":"תקצח - כא אייר","b":"בזיוו\"ש חתן ר יצחק לייטרדורף. רב בליבק-תקסו, מייסלינגן, דיין באלטונא-תקעו, רב מדינת שלזויג-הולשטין-תקפג. רב באלטונא-תקפג על מקום ר מנדל הירש-פרנקפורטר-זקנו של רש\"ר הירש - והיה הרב הראשון של אלטונא לאחר היפרדות קהלות אה\"ו. הסכים על \"רמוני פרץ\", אהל ישכר\", מחזורים אלטונא, \"הרכסים לבקעה\". בניו - ר יעקב, אברהם הירש, ר מאיר אשר מאנגליה, ר משה. חתניו - ר יצחק פרידמן, יוסף מיכל."},{"i":17923,"n":"ורטהיימר, שלמה אהרן מירושלים","f":"יעקב","k":"בעל גנזי ירושלים","bt":"תרכז","bp":"פעזינג-ליד פרשבורג","dt":"תרצה","dp":"ירושלים","b":"מחכמי ירושלים, עלה עם הוריו בגיל שש. לאחר שנתייתם גדל אצל ר טוביה גדליה פריינד. חתן ר נתנאל הלוי מוארשא. ראש ישיבת \"אור המאיר\"-כולל אונגרן. עסק ברכישה והוצאה לאור של כתבי ראשונים ובהם מהגניזה בקהיר. חיבר \"גנזי ירושלים\" ירושלים תרנו, \"דרכה של תורה\", ועוד. פרסם מאמרים ב\"המאסף\", \"תורה מציון\", \"אור תורה\" - ירושלים תרנז, \"הדביר\" - ירושלים תרעט, \"היהודי\" - נ\"י תרצו, \"מגד ירחים\" - סיגט תרנח,\"המאסף\" - ירושלים תרנו, \"שערי ציון\" - ירושלים תרפא, \"תורה מציון\" - ירושלים תרנה-תרסה. (לפי - תולדות יהודי פרשבורג - היה תלמיד השב\"ס ועלה לירושלים מאוחר יותר).","bk":[["שאלת שלמה [שו\"ת]",""]]},{"i":17924,"n":"ורטהיימר, שמשון מוינה","f":"יוסף","k":"השר שמשון וורטהיימר","bt":"תיט","dt":"תפד - יז אב","b":"גביר, ראש חכמי דורו, שר המלוכה ושתדלן גדול - הוכר כמייצג עניני היהדות אצל הקיסר בוינה, רב בוינה ומדינת הונגריה. חתניו: ר משה קן מפפד\"מ, ר זליגמן יהודה בן ישכר בר הכהן מהמבורג. בנו - ר יוסף יוזל מוינה."},{"i":17925,"n":"ורטמן, חיים יעקב","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":17926,"n":"ורטמן, יעקב","f":"אברהם","bt":"תקנה","dt":"תרלב","dp":"צפת","b":"חתנו של ר רפאל מברשד, ולימים רבה של קהילת טרנובקה. בשנת תרכו עלה לצפת. השאיר כתבים רבים בחסידות."},{"i":17927,"n":"ורטמן, יעקב מטרנובקא","f":"אברהם מבוסיבקא","b":"חתן ר רפאל מברשיד. עלה לארץ בסוף ימיו והשתקע בצפת."},{"i":17928,"n":"ורטמן-קוזניצר, משה מירושלים","f":"חיים","k":"משה קאזניצר","dt":"תרלד - ל ניסן","dp":"חברון או ירושלים","b":"עלה בשנת תרך מקוזניץ, רב בירושלים. התגורר בחברון וציוה בצוואתו את ביתו לראשון מצאצאיו שיעלה לארץ ישראל. חיבר \"דברי תורה\" ורשה תרט, \"אהבת ישראל\", צדה לדרך\", ועוד.","bk":[["אהבת ישראל",""],["דברי תורה",""],["ספר החיים",""],["קדושת הארץ",""],["רוממות נשמת ישראל",""]]},{"i":17929,"n":"ורטר, יצחק איצק מווארט","dt":"תקנח","b":"רב בווארט, מחכמי ביהמ\"ד של ר יחיאל ואליך בהמבורג-תקלז."},{"i":17930,"n":"ורידבורג, משה הלוי מפפד\"מ","f":"מאיר","dt":"תכב - ג אב","dp":"פפד\"מ","b":"פרנס בפפד\"מ."},{"i":17931,"n":"ורמברנד, אברהם יוסף מזלישטשיק","b":"מחכמי זלישטשיק."},{"i":17932,"n":"ורמברנד, מאיר מזלישטשיק","b":"מחכמי זלישטשיק-תרנד."},{"i":17933,"n":"ורמייזא, יצחק אהרן ממיץ","f":"יוסף יוזל","b":"רב במנהיים-תנ\"ה,מדינת עלזאס,מיץ-תע\"ד"},{"i":17934,"n":"ורמייזא, ישעיה ממיץ","b":"גביר מחכמי מיץ."},{"i":17935,"n":"ורמייזא, ליב","b":"מגדולי אשכנז"},{"i":17936,"n":"ורמן, אברהם דוד - הנכד","f":"ישראל אריה ליב מבוצא","b":"נכד ה\"דעת קדושים\". חתן ר יעקב יצחק מזבאריז."},{"i":17937,"n":"ורמן, דוד משה מבוסק","bt":"תריח","bp":"בוסק","b":"מחכמי למברג. חתן ר יהושע מיזלס מטופרוב."},{"i":17938,"n":"ורמן, יהודה מפעסט","f":"ישראל","k":"בעל מערכת ההעתקות","bt":"תקנג","bp":"פעסט","dt":"תרכט","b":"תלמיד ר שמואל פלקנפלד מפשוורסק. התגורר אצל חותנו בירוסלב, עבר למישקולץ ובודפסט. עסק בחינוך. רבה של קרסטור(=קרסטיר)-תקמו. רב בפעסט-תקנו. חיבר \"מערכת ההעתקות\" אפען תקצא. (היה מחלקות עם רצ\"ה חריף מאובן - אודות גט בבודפשט)."},{"i":17939,"n":"ורמן, יוסף דוד מגרוסורדין","f":"ישראל (או יהודה)","dt":"תריב - ז אדר","b":"רב בווישניצא(=ויזניץ), ראב\"ד בגרוסורדין-תקצח. נספד ב\"חבר בן חיים\". (לפי מורשת הונגריה נפטר - תקצט)."},{"i":17940,"n":"ורמן, יעקב יצחק מיאסי","f":"משלם פיבוש","bt":"תרן","bp":"יאסי","dt":"תשלב","b":"ניצל מהשואה ועלה לתל אביב. חתן ר ישכר שאול טייכמן. ההדיר כמה מספרי זקנו הדעת קדושים."},{"i":17941,"n":"ורמן, יצחק מבוצאץ","f":"ישראל אריה ליב","bt":"תקץ","dt":"תרס","b":"סייע בהדפסת ספרי זקנו ה\"דעת קדשים\"."},{"i":17942,"n":"ורמן, ישראל אריה ליב מבוצאץ","f":"אברהם דוד-דעת קדושים","bt":"תקן","dt":"תרי","b":"רב ודיין בבוצאץ ופוסק בדיני ממונות. חתן ר ישעיה שור מיאסי. לא נהג אדמורות. היה במחלוקת עם המשכילים בעירו וסבל מהם. בנו ר אברהם דוד-חתן ר יעקב יצחק מזבאריז."},{"i":17943,"n":"ורמן, ישראל מבאריש","f":"יונה אהרן הלוי","dt":"תשב","b":"רבה של באריש-תרס. חתן ר חיים ברוך הוכברג. נספה בשואה."},{"i":17944,"n":"ורמן, ישראל מבודפשט","f":"שלמה","bt":"תקטו","bp":"אויבן ישן","dt":"תקפו","dp":"בודפשט","b":"תלמיד ר מאיר ברבי בפרשבורג, ר זרח אידליץ בפרג. רב בבודרוג-קרסטור-תקל, בודפשט-תקנט - וחיבר את תקנון הקהילה ותחתיו התפתחה הקהילה והקימה את מוסדותיה. נזכר אצל החת\"ס. לזכרו \"אבל ישראל\" מאת פ. וייל, \"אבל כבד\" לר משה מינץ מאויבן. בניו: ר יהודה מפעסט, ר יוסף דוד מויזניץ וגרוסורדין."},{"i":17945,"n":"ורמן, משה יוסף","f":"אברהם דוד-דעת קדושים","dt":"תריח - י כסלו","dp":"טבריה","b":"עלה לארץ."},{"i":17946,"n":"ורמן, משה ליב מבוטשאן","dt":"תרמה","b":"ראש הקהל בבוטשאן. פרסם ב\"המגיד\" ועוד."},{"i":17947,"n":"ורמן, משלם פיבוש מיאסי","f":"יעקב יצחק מזבאריז","k":"אדמור מפולטישאן","bt":"תריד","dt":"תשז - יז חשון","b":"אדמור בפולטושאן על מקום אביו. עבר ליאסי ושימש אדמור. ניצל מהשואה. חתן ר לוי יצחק מניגרשט. בנו ר יעקב יצחק מתל אביב."},{"i":17948,"n":"ורמן, נחום מפודהייץ","f":"ישראל","bt":"תרנה","bp":"פודהייץ","dt":"תשכא","b":"עסקן בצורטקוב. בעל תואר דוקטור מהאוניברסיטה. חתן אליעזר שיפטן. רב באילזה (עלס) - שלזיה. מלמד בביהמד\"ר בברסלוי-תרצד. עלה לארץ-תרצט. חיבר בגרמנית \"השקאת סוטה בזמן הבית\" ברסלוי תרצג, \"תנאי ואסמכתא במשפט העברי\" ברסלוי תרצז."},{"i":17949,"n":"ורמן, צבי","b":"נכד ר אברהם דוד ורמן מבוצאץ. חתנו - ר יקותיאל מחוליוב."},{"i":17950,"n":"ורמן, שמשון מבאקוי","f":"יעקב יצחק מזבאריז","k":"אדמור מבאקוי","b":"נינו של ה\"דעת קדושים\". אדמור בבאקוי-מולדובה."},{"i":17951,"n":"ורמן-השל, יוסף יהושע מבוצאץ","f":"יצחק מקונסטנטין","k":"אדמור מבוצאץ","b":"אחיינו של ר שמואל-אבי ר אברהם יהושע השל מאפטא. חתן ר אברהם דוד ורמן-בעל \"דעת קדושים\". אדמור בבוצאץ על מקום חותנו."},{"i":17952,"n":"ורמן-השל, יעקב יצחק מזבריז","f":"יוסף יהושע השל מבוצץ","k":"אדמור מפרימישלן","bt":"תקץ","dt":"תרמה - יב שבט","dp":"יאסי","b":"חתן ר יוסף יוסקא גוטסמן מלשקוביץ(שושלת זבאריז)-חתן ר מאיר מפרמישלן. אב\"ד זבריז על מקום זקנו ר משולם פיבוש הלר. עבר לפולטושאן וכיהן שם כאדמור מפרימישלן, עבר ליאס."},{"i":17953,"n":"ורמס, אהרן מורמיזא","b":"מגדולי חכמי דורו בוורמז-ת\"ע"},{"i":17954,"n":"ורמס, אהרן ממיץ","k":"בעל מאורי אור","bt":"תקיד","dt":"תקצו - טו אייר","b":"תלמיד בעל שאגת אריה. דיין בעלזאס, מיץ, ראש ישיבה במיץ. חיבר \"מאורי אור\". חבר הסנהדרין של נפוליאון-תקסז."},{"i":17955,"n":"ורמס, אנשיל מאיר (אשר)","f":"וולף","k":"בעל סייג לתורה","bp":"פפד\"מ","dt":"תקכט - א אד\"ב","dp":"פפד\"מ","b":"מחכמי פפד\"מ. רב רופא ומדקדק. חיבר \"סייג לתורה\" - פפד\"מ תקכו, ונדפס ע\"י בנו - הד\"ר שמעון וולף, והיה מחלוקת בנוגע לספר לאחר שר אנשל האשים את ר יוסף הילבורן העתיק מכתב היד בספרו \"מבין חידות\", ועל כך כתב ר יוסף הילברון \"מריבת קדש\"."},{"i":17956,"n":"ורמס, גבריאל מפפד\"מ","b":"פרנס מראשי קהילת פפד\"מ, ומבין 12 מחברי תקנות הקהילה-תקיג. בזמן המחלוקת בין מחנה קולפא ומחנה קן."},{"i":17957,"n":"ורמס, יצחק זעקל מפולדא","f":"שלמה זלמן מפולדא","dt":"תקסז - כד כסלו","b":"חתן ר נתן אדלר (בן דודו של ר נתן מפרנקפורט). רב בפולדא-תקסז על מקום אביו. חתנו - ר יצחק דב במברגר מוירצבורג."},{"i":17958,"n":"ורמס, מאיר מפפד\"מ","b":"מראשי קהילת פפד\"מ, ומבין 12 מחברי תקנות הקהילה-תקיג."},{"i":17959,"n":"ורמס, נתן מפרידברג","b":"חתן ר שמואל דידלסהיים מפפד\"מ. רב בפרידברג-שעז, ואז פנו אליו בשאלה מקהילת פפד\"מ - שבאותו הזמן החלה להשתקם אחרי גירוש-שעד ולא היה להם רב."},{"i":17960,"n":"ורמס, שלמה זלמן מפולדא","dt":"תקלט - יח אב","b":"רב בשטטלנגספלד, גלנהוזן, פולדא ובנו ר יצחק זעקל על מקומו אחריו. ממשפחת ר זעקל ורמסר-הבעל שם ממיכלשטט."},{"i":17961,"n":"ורמס, שמואל","f":"שלמה זלמן","dt":"תרה - אחרי","b":"רב בנשטטן, לנג\"ש וולבך - עד פרישתו ב-תרה,"},{"i":17962,"n":"ורמסר, יעקב","b":"אין פרטים. אולי ממשפחת הבעל שם ממיכלשטט."},{"i":17963,"n":"ורמסר, יצחק איזיק זעקל ליב","k":"הבעל שם טוב ממיכלשטט","bt":"תקכח","dt":"תרח - ג תשרי","b":"איש מופת,התנזר מכל תענוג, מנהיים-תק\"ע,רב במיכלשטט וערפעלדען-תקפ\"ב"},{"i":17964,"n":"ורניק, יחיאל מיכל","f":"משלם","k":"הו\"ל יריעות שלמה","b":"הו\"ל \"יריעות שלמה\" לתורה עם הוספות ממנו."},{"i":17965,"n":"ורניקובסקי, יהודה מסלונים","k":"בעל פני יהודה","bt":"תקפב","dt":"תרסא - ד אדר","b":"מרביץ תורה,ר\"מ בסלונים-תרכ\"א"},{"i":17966,"n":"ורניקובסקי, יצחק מניו יורק","f":"אברהם מרדכי","bt":"תרלז","bp":"סלונים","dt":"תשד - ב אב","b":"בעצת ד\"ר פוזננסקי מוארשא פנה ללמוד בהילדברג אצל הפרופ' שפירא. חתן הסופרת מרים לימאן. היגר לניו יורק-1903. פרסם מאמרים ב\"המליץ\", \"הצפירה\", ועוד."},{"i":17967,"n":"ורניקובסקי, שבתי","dt":"תשג","b":"מרביץ תורה בלומזא"},{"i":17968,"n":"ורנק, דוד מטרעברק - הזקן","b":"רב בטרעברק בהסכמת ר ישראל מברונא."},{"i":17969,"n":"ורנק, דוד מפליונא-תורכיה וצפת","f":"זכריה ורנק אשכנזי","dt":"של","dp":"צפת","b":"נכד ר דוד ורנק מטרעברק (בזמן ר ישראל מברונא). מחכמי פליונא-ליד סופיה, נירנברג-רנח, לאחר הגירוש עלה עם אביו לצפת. מרביץ תורה בירושלים-ש', הסכים על פס\"ד של ר יוסף קארו יחד עם הרדב\"ז, נזכר ב\"אבקת רוכל\", ובשו\"ת אהע\"ז, בהלכות יבום וחליצה מביא תשובה בדין יבמה שישבו שם לדין וביניהם ר דוד. בשנת שה חתם על הסכמת הנגיד ר יצחק שולל לענין פטור תלמידי חכמים ממס, נזכר בשו\"ת מהר\"י בירב ובשות מהרי\"ט. לפי רוזניס היה אחיו של ר זכריה ולא בנו."},{"i":17970,"n":"ורנק, זכריה אשכנזי מפליבנא","f":"דוד או מנטבל","b":"מחכמי פליונא(=פליבנה)-ליד סופיה-רן-ש', עלה לירושלים, דיין בקהלת האשכנזים בצפת-רפ (עם ר יהודה אורי הלוי ור יוסף למרוזו). אחיו - ר דוד שעלה לצפת. נזכר אצל ר יוסף קארו ב\"אבקת רוכל\". בנו - ר משה מפליבנא וירושלים."},{"i":17971,"n":"ורנק, מנחם מנדל","b":"רב בפוזנא, ומובא בתשובות ר שלום שכנא, בשנת רצט היה רב בריסק, ועלה לירושלים."},{"i":17972,"n":"ורנק, משה מירושלים ופליבנא","f":"זכריה ורנק אשכנזי","k":"מהר\"ל מנטבל ורנק","b":"רב בפליבנא(=פליונה), אב\"ד ניקופול-רפג עד רצו, עלה לצפת או לירושלים עם אביו. מרביץ תורה בירושלים-שנת ש'. נזכר אצל החיד\"א בשם \"משה ירוק\" (והוא שבוש של ורנק). אחיו - ר דוד מצפת."},{"i":17973,"n":"ורנר, אברהם אבא מליטא ולונדון","f":"יעקב מטלז","bt":"תקצז","bp":"טלז","dt":"תרעב - י טבת","dp":"לונדון","b":"רב בואגר, דיין בטלז אצל ר יוסף רוזין, רב בהלסינקי(=הלסינגפורס) ורב ראשי בפינלנד-תרמ, רב קהל \"מחזיקי הדת\" בלונדון-תרנא. פעיל בתנועה הציונית ואף כיהן כציר בקונגרס, והיה בקשר עם הרצל."},{"i":17974,"n":"ורנר, אברהם מצפת","f":"אשר זאב מארה\"ב וטברי","b":"מחכמי צפת-תש..."},{"i":17975,"n":"ורנר, אליקים גצל","b":"פרסם מאמרים ב\"אור תורה\" - לבוב תרפו."},{"i":17976,"n":"ורנר, אשר זאב מארה\"ב","f":"שמחה בונם","bt":"תרנד","dt":"תשיח - ז שבט","b":"רב בפטרסון-ניו ג'רזי-ארה\"ב-תרעד, טבריה-תרצד. בנו - ר אברהם מצפת. סייע לגיסו ר פנחס מנחם מינצברג בהדפסת ספרו מרגניתא דר מאיר."},{"i":17977,"n":"ורנר, ברוך משיקגו","f":"אברהם אבא","k":"בעל מקור ברוך","bt":"תריט","bp":"קובנה","dt":"תרף","dp":"ראשון לציון","b":"היה רב בשיקגו, עלה לארץ והיה רב במזכרת בתיה, חיבר ספר \"מקור ברוך\" ירושלים תרסד ועוד. החל לחבר קונקורדנציה תלמודית אלא שהרב קוסובסקי הקדימו והציג בשער ספרו זכרון לרבי ברוך. התיישב בראשון לציון. ?? לא באוצר ??"},{"i":17978,"n":"ורנר, דוד מירושלים","f":"שמחה בונם","bt":"תרסג","bp":"ירושלים","b":"נכד ר יהודה ליב מסלונים. תלמיד ישיבות ירושלים \"תורת חיים\", \"עץ חיים\", \"מאה שערים\", ישיבת רידב\"ז ו\"מרכז הרב\", תלמיד מובהק של מוהרי\"ל דיסקין, ורי\"ג הורביץ. נסמך מאת: ר אברהם יעקב בורוכוב, ר משה קליערס, ר יעקב משה חרלפ, רי\"ג הורביץ, \"ר\"ז אפשטין, ר שמעון וינוגרד, רמ\"א עמיאל. חתן ר אברהם צבי מרגליות מגלוסקא. היגר לארה\"ב-תרפו ויסד את ישיבת \"בית אב\" עם חבריו ר אברהם אהרן יודלביץ, ור\"ש לוין, מנהל ישיבת \"כנסת ישראל\"-תרפו, רב בדזורוי סיטי, פרובידנס, ניו פורט. פרסם מאמרים ב\"מוריה\" - ירושלים תשג."},{"i":17979,"n":"ורנר, יעקב מטלז","b":"רב בטלז-ת\"ר"},{"i":17980,"n":"ורנר, משה הכהן ממינכן","bt":"תרטז","bp":"רוגוזין-פלך פוזנא","b":"תלמיד ישיבת פוזנא, ביהמ\"ד לרבנים בברסלוי, בעל תואר ד\"ר. רב בדנציג-תרן, מינכן-תרנו על מקום ר יוסף פערלס. חיבר מאמר \"על אודות תקנות הגאונים\", על ר אברהם בן הרמב\"ם, ועוד."},{"i":17981,"n":"ורנר, שמואל ברוך מתל אביב","b":"אב\"ד תל אביב. פרסם מאמרים ב\"מוריה\" - ירושלים תשג."},{"i":17982,"n":"ורנר, שמחה בונם מירושלים","f":"משה מנדל","bt":"תרכז","dt":"תרצו","dp":"ירושלים","b":"מחכמי ירושלים, עלה בילדותו עם אביו, הקים את שכונת \"בתי ורנר\" בירושלים."},{"i":17983,"n":"ורעשנא, ישראל מליסא וועלין","f":"משה","bp":"פראגא-ליד וארשא","dt":"תקף - כט טבת","b":"ראב\"ד בראויטש-ליד ליסא-תקן, נתבקש לכהן כדיין בפרידלנד אצל ר עקיבא איגר ולבקשתו (היו בידידות רבה במשך עשרות שנים ור עקיבא הסכים לממן חלק משכרו) אך לא הגיע לשם, דיין בליסא - אצל בעל ה\"נתיבות\" וגם אצל ר יעקב בעל \"החוות דעת\", רב בווילען-(=וועלין)תקעו ובנו ר אברהם מקאבלין על מקומו אחריו (ובין החותמים על כתב הרבנות של ר ישראל - גם ר משה בנו של ר עקיבא איגר). בניו גם: ר משה-רב בלובלינץ וליסא, ור שאול-רב בטומשוב."},{"i":17984,"n":"ורפל, צבי הירש ממיקוליניץ","f":"משה","dp":"ניו יורק","b":"רב במיקוליניץ, עבר לניו יורק."},{"i":17985,"n":"ורצברגר, יוסף מאיר מווישאוה","f":"יצחק מבורשה","dt":"תרפח","b":"גביר מחכמי אונטר-ווישווה, ונחשב לאדמור מקומי."},{"i":17986,"n":"ורצברגר, יצחק מבורשא","dt":"תרסג -כג-ד ניסן","dp":"בורשא","b":"חסיד ויזניץ בבורשה, וכיהן כרב בבורשה בהוראת האדמור ר מנחם מנדל בעל \"צמח צדיק\" (כנראה בזמן המחלוקת בדבר רב העיר ר יעקב צבי ולדמן - עיין ערכו). תושבי המקום נהגו בו כאדמור והקימו \"אוהל\" על קברו. פרסם מאמרים ב\"דגל התורה\" - אויבר-וישווה תרפח (אחר פטירתו?)."},{"i":17987,"n":"ורצברגר, יצחק מדעש","f":"אליעזר מווישיווה","bt":"תקץ","bp":"אויבר-ווישיווה","dt":"תרפב - כח שבט","dp":"דעש","b":"תלמיד ר שמואל שמעלקא קליין מסעליש, ור מנחם א\"ש מאונגוואר בהיותו בחוסט. חתן ר משה שטיין אב\"ד ערדא-סענזשארץ. שו\"ב בכפר קוזורואר-ליד דעש, דיין בדעש-תרמה אצל ר משה פאנט וכן סייע לר משה בכתיבה."},{"i":17988,"n":"ורצברגר, ישראל מבויאן ובוזאו","f":"[אליעזר שוחט]","k":"בעל זכרון יהושע-תרעב","bt":"[תרי]","bp":"אויבר-ווישיווה","dt":"תרפט","dp":"וזאו-מולדובה","b":"שו\"ב בראחוב-מארמרוש-תרלט, בויאן-תרמא, דיין בבוזאו-מולדבה כ-50 שנה. קרא לספרו ע\"ש בנו יהושע."},{"i":17989,"n":"ורצברגר, מ' דוד יצחק מטעטש","dt":"תשג","b":"רב בטעטש"},{"i":17990,"n":"ורצברגר, מרדכי מנאסוד","b":"רב בנאסוד-תר\"נ"},{"i":17991,"n":"ורצברגר, משה מארשווא","dt":"תשד","b":"דומ\"צ בארשווא"},{"i":17992,"n":"ורצל, ברוך מזלין","f":"אלעזר מסטריזוב","b":"רב בזלין-תרמט."},{"i":17993,"n":"ורצקי, אליהו הכהן מפיעטרקוב","f":"מנחם בנימין","bt":"תריט","b":"רב בפיעטרקוב הקטן-פלך וארשא-תרנה."},{"i":17994,"n":"ורצקי, יצחק מלובלין","b":"שו\"ב בלובלין. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא, \"כרם בית שמואל\" - פיעטרקוב תרצא."},{"i":17995,"n":"ורצקנד, בנימין זאב מקרלסבורג","b":"רב בקרלסבורג על מקום ר יוחנן-תקכא בערך. חתם על תקנה בפנקס הקהל יחד עם הפרנס ר חיים בן בנימין זאב מטירנוי."},{"i":17996,"n":"ורקר, מרדכי יצחק מדומברובה","b":"רב בדומברובה. הדב\"ח כתב עליו למהר\"י הכהן - כר\"ש."},{"i":17997,"n":"ורשאנו - משפחה","b":"משפחה במזרח - מקורה בעיר וארשא."},{"i":17998,"n":"ורשאנו, אברהם מרדכי משלוניקי","dt":"תש..","b":"מחכמי שלוניקי. נספה בשואה."},{"i":17999,"n":"ורשאנו, אברהם משלוניקי","b":"רב הכולל בשלוניקי-תקצב בזמן ר משה ברכה."},{"i":18000,"n":"ורשאנו, חיים יעקב","k":"בעל יגל יעקב","b":"חיבר \"יגל יעקב\" דרשות"},{"i":18001,"n":"ורשאנו, יוסף משלוניקי","dt":"תקא","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":18002,"n":"ורשאנו, יעקב משלוניקי","dt":"תקכב","dp":"שלוניקי","b":"מחכמי שלוניקי. נפטר במגפה-תקכב."},{"i":18003,"n":"ורשאנו, יעקב משלוניקי","f":"יוסף","k":"בעל יעקב חבל","b":"מחכמי שלוניקי-שנות התק', חיבר דרשות על התורה בשם \"יעקב חבל\"-תקלב. אחיו ר עובדיה בעל \"חזון עובדיה\" על פרקי אבות."},{"i":18004,"n":"ורשאנו, עובדיה משלוניקי","f":"יוסף","k":"בעל חזון עובדיה","b":"רב בשלוניקי. אחיו של ר יעקב בעל \"יעקב חבל\". חיבר ביאור על פרקי אבות בשם \"חזון עובדיה\"-תקל."},{"i":18005,"n":"ורשביאק, מאיר הכהן מליטומירסק","f":"יעקב אליעזר","bt":"תרלב","dt":"תשג","b":"חתן ר פנחס אליהו מייזלש. רב בליטומירסק-פלך פיעטרקוב-תרנא, מנקטוב(=מאנקטוב, מאקוטוב, מונקוטוב)-תרפ. מעורכי \"קובץ דרושים\" - פיעטרקוב תרפג, \"שערי תורה\" - וארשא תרסג."},{"i":18006,"n":"ורשביאק, מנחם מנדל","f":"נחום ישראל מליפנא","bt":"תרלד","bp":"ליפנא-פולין","dt":"תרף - יח ניסן","b":"בן האדמור מליפנא. חתן הגביר ר משלם הברפלד מוארשא. נהרג עק\"ה."},{"i":18007,"n":"ורשביאק, נחום ישראל מליפנא","f":"אברהם מליפנא","k":"אדמור מליפנא","b":"תלמיד ר מנחם מנדל מקוצק, בעל חדושי הרי\"ם ור חנוך הניך מאלכסנדר. אדמור-תרל בליפנא אחר פטירת בעל חדושי הרי\"ם, ונסע כאדמור לשפת אמת מגור."},{"i":18008,"n":"ורשבסקי, אברהם","dt":"תשא","b":"רב בראדין"},{"i":18009,"n":"ורשבסקי, משה מהאצילע","f":"נח אשר זליג","bt":"תרח","b":"רב בהאצילע-פלך חרסון-תרלח."},{"i":18010,"n":"ורשבסקי, נתן נטע מבורזנין","b":"פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא."},{"i":18011,"n":"ורשבסקי, שמעון מצנסטחוב","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":18012,"n":"ורשובר, שלמה טבל מבוטושאן","f":"נח","k":"אדמור מבוטושאן","b":"רב בקרעניץ והיה האדמור מבוטושאן. חתן רא\"ל ברוינפלד."}];
